window.__MASTER_QUESTIONS__ = [{"id": 1, "number": 1, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Berdasarkan Undang-Undang Nomor 6 Tahun 2014 tentang Desa, kedudukan Perangkat Desa adalah sebagai...", "options": ["Lembaga perwakilan aspirasi masyarakat desa yang mengawasi kinerja kepala desa", "Unsur pembantu Kepala Desa dalam melaksanakan tugas dan kewenangannya", "Badan independen yang ditunjuk bupati untuk mengelola keuangan desa", "Unsur pelaksana teknis daerah yang berkedudukan di bawah koordinasi camat"], "answer": 1, "explanation": "Berdasarkan Pasal 48 UU No. 6 Tahun 2014 tentang Desa jo. Permendagri No. 84 Tahun 2015, Perangkat Desa bertugas membantu Kepala Desa dalam melaksanakan tugas dan kewenangannya serta bertanggung jawab kepada Kepala Desa.", "source": "UU No. 6 Tahun 2014 tentang Desa Pasal 48; Permendagri No. 84 Tahun 2015", "sourceType": "regulasi"}, {"id": 2, "number": 2, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Susunan organisasi Perangkat Desa menurut Permendagri Nomor 84 Tahun 2015 terdiri atas...", "options": ["Sekretariat Desa, Pelaksana Teknis, dan Pelaksana Kewilayahan", "Badan Permusyawaratan Desa, Lembaga Pemberdayaan Masyarakat, dan RT/RW", "Sekretaris Desa, Bendahara Desa, dan Pengawas Internal Desa", "Kepala Urusan, Kepala Seksi, dan Satuan Tugas Perlindungan Masyarakat"], "answer": 0, "explanation": "Pasal 2 Permendagri No. 84 Tahun 2015 tentang Susunan Organisasi dan Tata Kerja Pemerintah Desa menegaskan bahwa Perangkat Desa terdiri atas Sekretariat Desa, Pelaksana Teknis, dan Pelaksana Kewilayahan.", "source": "Permendagri No. 84 Tahun 2015 tentang SOTK Pemerintah Desa Pasal 2", "sourceType": "regulasi"}, {"id": 3, "number": 3, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Sekretariat Desa dipimpin oleh Sekretaris Desa. Manakah di antara tugas berikut yang merupakan tugas pokok Sekretaris Desa?", "options": ["Menetapkan peraturan desa bersama Badan Permusyawaratan Desa", "Membantu Kepala Desa dalam bidang administrasi pemerintahan dan mengoordinasikan pelaksana teknis", "Melaksanakan pembinaan ketenteraman dan ketertiban langsung di tingkat dusun", "Menjabat sebagai pemegang kekuasaan tunggal pengelolaan keuangan desa"], "answer": 1, "explanation": "Berdasarkan Pasal 7 Permendagri No. 84 Tahun 2015, Sekretaris Desa bertugas membantu Kepala Desa dalam bidang administrasi pemerintahan, mengoordinasikan penyusunan kebijakan, dan mengoordinasikan tugas perangkat desa lainnya.", "source": "Permendagri No. 84 Tahun 2015 Pasal 7", "sourceType": "regulasi"}, {"id": 4, "number": 4, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri Nomor 84 Tahun 2015, jabatan Kepala Urusan (Kaur) berada di bawah Sekretariat Desa. Urusan apa sajakah yang dapat dibentuk paling banyak dalam struktur Sekretariat Desa?", "options": ["Urusan Pemerintahan, Urusan Pembangunan, dan Urusan Kesejahteraan", "Urusan Tata Usaha dan Umum, Urusan Keuangan, dan Urusan Perencanaan", "Urusan Keamanan, Urusan Perekonomian, dan Urusan Pelayanan", "Urusan Logistik, Urusan Kepegawaian, dan Urusan Kebudayaan"], "answer": 1, "explanation": "Pasal 8 Permendagri No. 84 Tahun 2015 mengatur bahwa Kaur berkedudukan sebagai unsur staf sekretariat yang membidangi paling banyak 3 urusan: Tata Usaha dan Umum, Keuangan, serta Perencanaan.", "source": "Permendagri No. 84 Tahun 2015 Pasal 8", "sourceType": "regulasi"}, {"id": 5, "number": 5, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Kepala Seksi (Kasi) berkedudukan sebagai unsur pelaksana teknis operasional. Nomenklatur Kepala Seksi yang diatur dalam regulasi SOTK Pemerintah Desa paling banyak terdiri dari...", "options": ["Seksi Pemerintahan, Seksi Kesejahteraan, dan Seksi Pelayanan", "Seksi Ketertiban, Seksi Pembangunan, dan Seksi Pengawasan", "Seksi Pendapatan, Seksi Anggaran, dan Seksi Keuangan", "Seksi Pemuda, Seksi Olahraga, dan Seksi Keagamaan"], "answer": 0, "explanation": "Pasal 9 Permendagri No. 84 Tahun 2015 menetapkan bahwa Kepala Seksi paling banyak terdiri atas 3 seksi, yaitu Seksi Pemerintahan, Seksi Kesejahteraan, dan Seksi Pelayanan.", "source": "Permendagri No. 84 Tahun 2015 Pasal 9", "sourceType": "regulasi"}, {"id": 6, "number": 6, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Unsur Pelaksana Kewilayahan dalam struktur pemerintah desa dipimpin oleh...", "options": ["Ketua RT yang dipilih secara bergantian", "Kepala Dusun atau sebutan lain sesuai kearifan lokal", "Camat melalui penunjukan surat tugas kedinasan", "Ketua Lembaga Pemberdayaan Masyarakat Desa (LPMD)"], "answer": 1, "explanation": "Pasal 10 Permendagri No. 84 Tahun 2015 menyebutkan bahwa Pelaksana Kewilayahan merupakan unsur pembantu Kepala Desa sebagai satuan tugas kewilayahan yang dipimpin oleh Kepala Dusun atau sebutan lain.", "source": "Permendagri No. 84 Tahun 2015 Pasal 10", "sourceType": "regulasi"}, {"id": 7, "number": 7, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 83 Tahun 2015 jo. Permendagri No. 67 Tahun 2017 serta Perda Kabupaten Tuban No. 2 Tahun 2016 jo. No. 16 Tahun 2021, batasan usia bagi calon perangkat desa pada saat mendaftar adalah...", "options": ["Paling rendah 18 tahun dan paling tinggi 35 tahun", "Paling rendah 20 tahun dan paling tinggi 42 tahun", "Paling rendah 21 tahun dan paling tinggi 45 tahun", "Paling rendah 25 tahun dan paling tinggi 50 tahun"], "answer": 1, "explanation": "Persyaratan umum perangkat desa menurut Permendagri No. 67/2017 Pasal 2 ayat (2) huruf b dan Perda Kab. Tuban No. 2/2016 jo. No. 16/2021 adalah berusia 20 (dua puluh) tahun sampai dengan 42 (empat puluh dua) tahun pada saat pendaftaran.", "source": "Permendagri No. 67 Tahun 2017 Pasal 2 ayat (2); Perda Kab. Tuban No. 2 Tahun 2016 jo. No. 16 Tahun 2021", "sourceType": "regulasi"}, {"id": 8, "number": 8, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Syarat tingkat pendidikan formal paling rendah yang harus dipenuhi oleh calon Perangkat Desa adalah...", "options": ["Sekolah Dasar (SD) atau sederajat", "Sekolah Menengah Pertama (SMP) atau sederajat", "Sekolah Menengah Umum (SMU) atau sederajat", "Diploma Tiga (D3) atau Sarjana (S1)"], "answer": 2, "explanation": "Berdasarkan Pasal 50 UU No. 6 Tahun 2014 jo. Permendagri No. 67 Tahun 2017, salah satu syarat umum perangkat desa adalah berpendidikan paling rendah Sekolah Menengah Umum (SMU) atau yang sederajat.", "source": "UU No. 6 Tahun 2014 Pasal 50; Permendagri No. 67 Tahun 2017", "sourceType": "regulasi"}, {"id": 9, "number": 9, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Perangkat Desa berhenti karena purnatugas (pensiun) apabila telah genap mencapai usia...", "options": ["55 tahun", "58 tahun", "60 tahun", "65 tahun"], "answer": 2, "explanation": "Menurut Pasal 5 ayat (2) huruf b Permendagri No. 67 Tahun 2017, perangkat desa diberhentikan karena telah berusia genap 60 (enam puluh) tahun.", "source": "Permendagri No. 67 Tahun 2017 Pasal 5 ayat (2) huruf b", "sourceType": "regulasi"}, {"id": 10, "number": 10, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Dalam mekanisme penjaringan dan penyaringan calon Perangkat Desa, pembentukan Tim Pelaksana Pengangkatan Perangkat Desa dilakukan oleh...", "options": ["Bupati atas usul Camat", "Kepala Desa setelah berkonsultasi dengan Camat", "Ketua BPD bersama tokoh masyarakat", "Dinas Pemberdayaan Masyarakat dan Desa Kabupaten"], "answer": 1, "explanation": "Sesuai regulasi Permendagri No. 83/2015 jo. 67/2017 serta Perbup Tuban No. 30/2017 jo. Perbup No. 11/2022, Kepala Desa membentuk Tim Pengangkatan/Penjaringan dan Penyaringan Perangkat Desa yang ditetapkan dengan Keputusan Kepala Desa.", "source": "Permendagri No. 83 Tahun 2015 Pasal 4; Perbup Tuban No. 30 Tahun 2017 jo. Perbup No. 11 Tahun 2022", "sourceType": "regulasi"}, {"id": 11, "number": 11, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sulit", "question": "Setelah menerima permohonan konsultasi tertulis mengenai calon perangkat desa dari Kepala Desa, Camat wajib menerbitkan rekomendasi tertulis paling lambat dalam waktu...", "options": ["3 (tiga) hari kerja", "7 (tujuh) hari kerja", "14 (empat belas) hari kalender", "30 (tiga puluh) hari kalender"], "answer": 1, "explanation": "Berdasarkan Permendagri No. 67 Tahun 2017 Pasal 4 ayat (4), Camat atau pejabat lain yang ditunjuk memberikan rekomendasi tertulis paling lambat 7 (tujuh) hari kerja sejak diterimanya surat permohonan konsultasi dari Kepala Desa.", "source": "Permendagri No. 67 Tahun 2017 Pasal 4 ayat (4)", "sourceType": "regulasi"}, {"id": 12, "number": 12, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Pejabat yang berwenang melantik dan menerbitkan Surat Keputusan (SK) pengangkatan Perangkat Desa adalah...", "options": ["Camat setempat atas nama Bupati", "Kepala Desa yang bersangkutan", "Ketua Badan Permusyawaratan Desa (BPD)", "Kepala Dinas Pemberdayaan Masyarakat dan Desa Kabupaten"], "answer": 1, "explanation": "Perangkat Desa diangkat oleh Kepala Desa melalui Surat Keputusan (SK) Kepala Desa setelah mendapat rekomendasi tertulis dari Camat, dan dilantik langsung oleh Kepala Desa.", "source": "UU No. 6 Tahun 2014 Pasal 49; Permendagri No. 83 Tahun 2015 jo. Permendagri No. 67 Tahun 2017", "sourceType": "regulasi"}, {"id": 13, "number": 13, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sulit", "question": "Perangkat Desa diberhentikan sementara oleh Kepala Desa apabila...", "options": ["Mendapatkan teguran lisan satu kali karena terlambat datang apel", "Ditetapkan sebagai tersangka tindak pidana korupsi, terorisme, makar, atau tindak pidana berancaman penjara minimal 5 tahun", "Mengambil cuti melahirkan atau cuti tahunan dengan izin resmi", "Mengalami perbedaan pendapat dalam musyawarah bersama anggota BPD"], "answer": 1, "explanation": "Berdasarkan Permendagri No. 67 Tahun 2017 Pasal 6, Perangkat Desa diberhentikan sementara apabila ditetapkan sebagai tersangka tindak pidana korupsi, terorisme, makar, tindak pidana terhadap keamanan negara, atau tindak pidana yang diancam pidana penjara paling singkat 5 tahun.", "source": "Permendagri No. 67 Tahun 2017 Pasal 6 ayat (1)", "sourceType": "regulasi"}, {"id": 14, "number": 14, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berikut ini yang BUKAN merupakan alasan pemberhentian Perangkat Desa menurut peraturan perundang-undangan adalah...", "options": ["Perangkat desa meninggal dunia", "Perangkat desa mengundurkan diri atas permintaan sendiri secara tertulis", "Kepala Desa berganti kepemimpinan setelah pemilihan kepala desa serentak", "Perangkat desa telah mencapai usia genap 60 (enam puluh) tahun"], "answer": 2, "explanation": "Pergantian Kepala Desa TIDAK BOLEH menjadi alasan memberhentikan perangkat desa. Masa jabatan perangkat desa bersifat tetap sampai usia 60 tahun sepanjang tidak melanggar larangan dan memenuhi syarat regulasi.", "source": "Permendagri No. 83 Tahun 2015 jo. Permendagri No. 67 Tahun 2017 Pasal 5", "sourceType": "regulasi"}, {"id": 15, "number": 15, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Perangkat Desa dilarang merangkap jabatan sebagai...", "options": ["Ketua Karang Taruna tingkat RW", "Anggota DPR, DPD, DPRD, atau jabatan lain yang ditentukan oleh peraturan perundang-undangan", "Anggota kelompok pengajian atau takmir masjid desa", "Ketua kelompok tani di desanya sendiri"], "answer": 1, "explanation": "Pasal 51 UU No. 6 Tahun 2014 melarang perangkat desa merangkap jabatan sebagai anggota DPR, DPD, DPRD, pengurus partai politik, advokat, atau jabatan lain yang dilarang peraturan perundang-undangan.", "source": "UU No. 6 Tahun 2014 Pasal 51 huruf f dan g", "sourceType": "regulasi"}, {"id": 16, "number": 16, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sulit", "question": "Berdasarkan Peraturan Pemerintah (PP) Nomor 11 Tahun 2019, ketentuan besaran penghasilan tetap (Siltap) Sekretaris Desa paling sedikit adalah...", "options": ["70% dari penghasilan tetap Kepala Desa", "80% dari penghasilan tetap Kepala Desa", "90% dari penghasilan tetap Kepala Desa", "Sama persis 100% dengan penghasilan tetap Kepala Desa"], "answer": 2, "explanation": "Pasal 81 ayat (2) huruf b PP No. 11 Tahun 2019 menetapkan besaran penghasilan tetap Sekretaris Desa paling sedikit Rp2.224.420,00 atau setara 90% dari penghasilan tetap Kepala Desa.", "source": "Peraturan Pemerintah No. 11 Tahun 2019 Pasal 81 ayat (2) huruf b", "sourceType": "regulasi"}, {"id": 17, "number": 17, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Selain penghasilan tetap (Siltap), hak yang sah diterima oleh Perangkat Desa menurut regulasi yang berlaku adalah...", "options": ["Dividen saham perusahaan swasta daerah secara pribadi", "Jaminan kesehatan, jaminan ketenagakerjaan, serta tunjangan dan penerimaan lain yang sah sesuai APB Desa", "Persentase komisi tunai langsung dari setiap penerbitan surat pengantar warga", "Uang pelicin dari rekanan pemenang proyek pembangunan fisik desa"], "answer": 1, "explanation": "Sesuai PP No. 43/2014 jo. PP No. 11/2019, selain Siltap, Kepala Desa dan Perangkat Desa berhak memperoleh jaminan kesehatan, jaminan ketenagakerjaan, serta tunjangan dan penerimaan sah lainnya yang dialokasikan dalam APB Desa.", "source": "PP No. 11 Tahun 2019 jo. Permendagri No. 20 Tahun 2018", "sourceType": "regulasi"}, {"id": 18, "number": 18, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Undang-Undang Nomor 3 Tahun 2024 tentang Perubahan Kedua atas UU No. 6 Tahun 2014 tentang Desa, masa jabatan Kepala Desa adalah...", "options": ["5 (lima) tahun dan dapat menjabat paling banyak 3 (tiga) kali masa jabatan", "6 (enam) tahun dan dapat menjabat paling banyak 3 (tiga) kali masa jabatan", "8 (delapan) tahun dan dapat menjabat paling banyak 2 (dua) kali masa jabatan", "9 (sembilan) tahun dan hanya dapat menjabat 1 (satu) kali masa jabatan"], "answer": 2, "explanation": "Pasal 39 UU No. 3 Tahun 2024 mengubah masa jabatan Kepala Desa menjadi 8 (delapan) tahun terhitung sejak tanggal pelantikan dan dapat menjabat paling banyak 2 (dua) kali masa jabatan secara berturut-turut atau tidak berturut-turut.", "source": "Undang-Undang Nomor 3 Tahun 2024 Pasal 39", "sourceType": "regulasi"}, {"id": 19, "number": 19, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Dalam pelaksanaan tugas sehari-hari, Perangkat Desa bertanggung jawab secara hierarki kepada...", "options": ["Ketua Badan Permusyawaratan Desa (BPD)", "Kepala Desa", "Camat melalui Sekretaris Camat", "Inspektorat Pembantu Daerah Kabupaten"], "answer": 1, "explanation": "Sesuai Pasal 48 UU No. 6 Tahun 2014, Perangkat Desa bertugas membantu Kepala Desa dan dalam pelaksanaan tugas serta kewenangannya bertanggung jawab kepada Kepala Desa.", "source": "UU No. 6 Tahun 2014 Pasal 48", "sourceType": "regulasi"}, {"id": 20, "number": 20, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Urutan penjatuhan sanksi administratif bagi Perangkat Desa yang melanggar kewajiban kedinasan menurut Permendagri No. 67 Tahun 2017 adalah...", "options": ["Pemberhentian langsung tanpa proses klarifikasi", "Teguran lisan, teguran tertulis, pemberhentian sementara, lalu pemberhentian tetap", "Denda pemotongan gaji seketika lalu pengusiran dari wilayah desa", "Pemberhentian sementara selama 1 tahun tanpa surat peringatan"], "answer": 1, "explanation": "Berdasarkan Permendagri No. 67 Tahun 2017 Pasal 7, sanksi administratif dikenakan secara bertahap: teguran lisan, teguran tertulis, pemberhentian sementara, dan dilanjutkan pemberhentian tetap bila tidak memperbaiki pelanggaran.", "source": "Permendagri No. 67 Tahun 2017 Pasal 7", "sourceType": "regulasi"}, {"id": 21, "number": 21, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "mudah", "question": "Hierarki Peraturan Perundang-undangan di Indonesia berdasarkan Pasal 7 ayat (1) UU Nomor 12 Tahun 2011 jo. UU Nomor 13 Tahun 2022 menempatkan urutan dari yang tertinggi ke terendah sebagai...", "options": ["UUD 1945, Ketetapan MPR, UU/Perppu, PP, Perpres, Perda Provinsi, Perda Kabupaten/Kota", "UUD 1945, UU/Perppu, Ketetapan MPR, Perpres, PP, Perda Kabupaten/Kota, Perda Provinsi", "UUD 1945, Tap MPR, Perpres, PP, UU, Peraturan Desa, Perda Kabupaten/Kota", "Pancasila, UUD 1945, UU Desa, Peraturan Menteri Dalam Negeri, Peraturan Bupati"], "answer": 0, "explanation": "Pasal 7 ayat (1) UU No. 12 Tahun 2011 secara tegas mengatur urutan hierarki: UUD 1945, Ketetapan MPR, UU/Peraturan Pemerintah Pengganti UU, Peraturan Pemerintah, Peraturan Presiden, Perda Provinsi, dan Perda Kabupaten/Kota.", "source": "UU No. 12 Tahun 2011 Pasal 7 ayat (1) jo. UU No. 13 Tahun 2022", "sourceType": "regulasi"}, {"id": 22, "number": 22, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Bagaimanakah kedudukan Peraturan Desa (Perdes) dalam sistem hukum peraturan perundang-undangan Indonesia?", "options": ["Tidak diakui sebagai norma hukum mengikat karena berada di bawah Peraturan Daerah", "Diakui keberadaannya dan berkekuatan hukum mengikat sepanjang diperintahkan oleh peraturan lebih tinggi atau dibentuk berdasarkan kewenangan desa", "Hanya berlaku sebagai norma kesusilaan internal dan adat istiadat tanpa sanksi formal", "Bisa mengesampingkan dan membatalkan Peraturan Daerah Kabupaten bila terjadi pertentangan norma"], "answer": 1, "explanation": "Berdasarkan Pasal 8 UU No. 12 Tahun 2011, Peraturan Desa termasuk jenis peraturan perundang-undangan yang diakui keberadaannya dan mempunyai kekuatan hukum mengikat sepanjang diperintahkan oleh Peraturan Perundang-undangan yang lebih tinggi atau dibentuk berdasarkan kewenangan.", "source": "UU No. 12 Tahun 2011 Pasal 8; UU No. 6 Tahun 2014", "sourceType": "regulasi"}, {"id": 23, "number": 23, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Menurut Permendagri Nomor 111 Tahun 2014, jenis produk hukum yang ditetapkan di tingkat desa terdiri atas...", "options": ["Undang-Undang Desa, Peraturan Menteri Desa, dan Surat Edaran Camat", "Peraturan Desa (Perdes), Peraturan Kepala Desa (Perkades), dan Peraturan Bersama Kepala Desa (Permakades)", "Keputusan Dusun, Instruksi RT, dan Maklumat RW", "Perda Khusus Desa, Surat Penetapan BPD, dan Dokumen Musyawarah"], "answer": 1, "explanation": "Pasal 2 Permendagri No. 111 Tahun 2014 tentang Pedoman Teknis Peraturan di Desa menyebutkan jenis peraturan di desa terdiri atas: Peraturan Desa, Peraturan Kepala Desa, dan Peraturan Bersama Kepala Desa.", "source": "Permendagri No. 111 Tahun 2014 Pasal 2", "sourceType": "regulasi"}, {"id": 24, "number": 24, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Rancangan Peraturan Desa (Ranperdes) yang diprakarsai oleh Kepala Desa atau BPD wajib dibahas dan disepakati bersama oleh...", "options": ["Kepala Desa dan BPD dalam musyawarah bersama", "Camat dan Kepala Bagian Hukum Setda Kabupaten", "Sekretaris Desa dan seluruh Ketua RT", "Pendamping Desa dan Badan Usaha Milik Desa"], "answer": 0, "explanation": "Pasal 69 UU No. 6 Tahun 2014 menyatakan bahwa Peraturan Desa dibahas dan disepakati bersama oleh Kepala Desa dan Badan Permusyawaratan Desa (BPD).", "source": "UU No. 6 Tahun 2014 Pasal 69; Permendagri No. 111 Tahun 2014", "sourceType": "regulasi"}, {"id": 25, "number": 25, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sulit", "question": "Pengundangan Peraturan Desa agar memiliki kekuatan mengikat masyarakat dilakukan oleh...", "options": ["Ketua BPD dalam Notula Rapat Paripurna Desa", "Sekretaris Desa dalam Lembaran Desa", "Kepala Bagian Hukum Kabupaten dalam Berita Daerah", "Camat dalam Warta Kecamatan"], "answer": 1, "explanation": "Berdasarkan Permendagri No. 111 Tahun 2014 Pasal 21, Peraturan Desa diundangkan oleh Sekretaris Desa dalam Lembaran Desa, sedangkan Peraturan Kepala Desa dan Peraturan Bersama Kepala Desa diundangkan dalam Berita Desa.", "source": "Permendagri No. 111 Tahun 2014 Pasal 21", "sourceType": "regulasi"}, {"id": 26, "number": 26, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sulit", "question": "Rancangan Peraturan Desa manakah yang wajib disampaikan kepada Bupati melalui Camat untuk dievaluasi sebelum ditetapkan?", "options": ["Ranperdes tentang pembentukan panitia peringatan HUT RI", "Ranperdes tentang APB Desa, Pungutan Desa, Tata Ruang, dan SOTK Pemerintah Desa", "Ranperdes tentang jadwal kerja bakti kebersihan lingkungan RT", "Ranperdes tentang pengesahan kelompok arisan ibu-ibu desa"], "answer": 1, "explanation": "Permendagri No. 111 Tahun 2014 mengatur bahwa Rancangan Perdes tentang APB Desa, pungutan, tata ruang, dan organisasi pemerintah desa yang telah disepakati bersama BPD wajib dievaluasi oleh bupati/walikota sebelum ditetapkan.", "source": "Permendagri No. 111 Tahun 2014 Pasal 24", "sourceType": "regulasi"}, {"id": 27, "number": 27, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Asas penyelenggaraan pemerintahan desa yang mengutamakan landasan peraturan perundang-undangan dan keadilan dalam setiap kebijakan pemerintah desa disebut asas...", "options": ["Kepastian Hukum", "Kearifan Lokal", "Akuntabilitas", "Profesionalitas"], "answer": 0, "explanation": "Sesuai penjelasan Pasal 24 UU No. 6 Tahun 2014, Asas Kepastian Hukum adalah asas dalam negara hukum yang mengutamakan landasan ketentuan peraturan perundang-undangan dan keadilan dalam setiap kebijakan penyelenggara pemerintahan desa.", "source": "UU No. 6 Tahun 2014 Pasal 24 huruf a", "sourceType": "regulasi"}, {"id": 28, "number": 28, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Peraturan Daerah Kabupaten Tuban yang menjadi payung hukum utama mengenai pengangkatan dan pemberhentian Perangkat Desa adalah...", "options": ["Perda Kabupaten Tuban Nomor 2 Tahun 2016 jo. Perda Nomor 16 Tahun 2021", "Perda Kabupaten Tuban Nomor 5 Tahun 2010 tentang Pemilihan Kepala Daerah", "Perda Kabupaten Tuban Nomor 1 Tahun 2014 tentang Pengelolaan Sampah", "Perda Kabupaten Tuban Nomor 12 Tahun 2023 tentang Pajak Daerah"], "answer": 0, "explanation": "Regulasi resmi Perangkat Desa di Kabupaten Tuban berpijak pada Peraturan Daerah Kabupaten Tuban Nomor 2 Tahun 2016 tentang Perangkat Desa yang kemudian diubah dengan Peraturan Daerah Nomor 16 Tahun 2021.", "source": "JDIH Kabupaten Tuban: Perda Kab. Tuban No. 2 Tahun 2016 jo. Perda No. 16 Tahun 2021", "sourceType": "regulasi"}, {"id": 29, "number": 29, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sulit", "question": "Peraturan Bupati Tuban yang mengatur tata cara teknis pelaksanaan seleksi perangkat desa mencakup Perbup No. 30 Tahun 2017 yang telah diubah dengan...", "options": ["Perbup Tuban Nomor 41 Tahun 2019, Perbup Nomor 11 Tahun 2022, dan Perbup Nomor 30 Tahun 2023", "Perbup Tuban Nomor 88 Tahun 2020 tentang Penanggulangan Bencana", "Perbup Tuban Nomor 3 Tahun 2015 tentang Tata Kelola Perusahaan Daerah", "Perbup Tuban Nomor 99 Tahun 2024 tentang Retribusi Pasar Tradisional"], "answer": 0, "explanation": "Petunjuk teknis seleksi perangkat desa di Tuban diatur dalam Perbup Tuban No. 30 Tahun 2017 yang mengalami perubahan melalui Perbup No. 41 Tahun 2019, Perbup No. 11 Tahun 2022, dan Perbup No. 30 Tahun 2023.", "source": "JDIH Kabupaten Tuban: Perbup Tuban No. 30/2017, No. 41/2019, No. 11/2022, No. 30/2023", "sourceType": "regulasi"}, {"id": 30, "number": 30, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sulit", "question": "Berdasarkan Perbup Tuban Nomor 11 Tahun 2022, pembagian komponen dan bobot nilai dalam seleksi ujian perangkat desa di Kabupaten Tuban terdiri atas...", "options": ["Ujian Tertulis bobot 75% (125 soal) dan Ujian Praktik Komputer bobot 25% (10 soal)", "Ujian Tertulis bobot 50% dan Wawancara Kepala Desa bobot 50%", "Ujian Tertulis bobot 90% dan Tes Fisik Jasmani bobot 10%", "Ujian Psikotes bobot 60% dan Wawancara Tokoh Masyarakat bobot 40%"], "answer": 0, "explanation": "Perbup Tuban No. 11 Tahun 2022 mengatur bahwa ujian seleksi terdiri atas ujian tertulis (125 soal pilihan ganda berbobot 75%) dan ujian praktik komputer (10 soal/aspek praktik berbobot 25%).", "source": "Perbup Tuban No. 11 Tahun 2022 tentang Perubahan Kedua Atas Perbup No. 30 Tahun 2017", "sourceType": "regulasi"}, {"id": 31, "number": 31, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Dua pilar asas utama yang melandasi kewenangan desa dalam UU Nomor 6 Tahun 2014 adalah...", "options": ["Asas Sentralisasi dan Asas Dekonsentrasi", "Asas Rekognisi (pengakuan hak asal-usul) dan Asas Subsidiaritas (penetapan kewenangan berskala lokal)", "Asas Efisiensi Anggaran dan Asas Profitabilitas Usaha", "Asas Monarki Terbatas dan Asas Primus Inter Pares"], "answer": 1, "explanation": "Pasal 3 UU No. 6 Tahun 2014 menegaskan asas Rekognisi (pengakuan hak asal usul) dan Subsidiaritas (penetapan kewenangan berskala lokal dan pengambilan keputusan lokal untuk kepentingan masyarakat desa).", "source": "UU No. 6 Tahun 2014 Pasal 3 huruf a dan b", "sourceType": "regulasi"}, {"id": 32, "number": 32, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Berdasarkan Peraturan Komisi Informasi (Perki) Nomor 1 Tahun 2018 tentang Standar Layanan Informasi Publik Desa, dokumen APB Desa dan realisasinya merupakan jenis informasi publik yang bersifat...", "options": ["Rahasia negara yang dikecualikan dari publik", "Wajib disediakan dan diumumkan secara berkala kepada masyarakat", "Hanya boleh dilihat oleh anggota BPD setelah membayar biaya retribusi", "Dilarang disebarluaskan di luar lingkungan balai desa"], "answer": 1, "explanation": "Menurut Perki No. 1 Tahun 2018 jo. UU No. 14 Tahun 2008, informasi mengenai keuangan desa (APB Desa dan laporan pertanggungjawaban) merupakan informasi publik yang wajib diumumkan secara berkala melalui papan informasi, website, atau media publik desa.", "source": "Perki No. 1 Tahun 2018 tentang Standar Layanan Informasi Publik Desa; UU No. 14 Tahun 2008", "sourceType": "regulasi"}, {"id": 33, "number": 33, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Sikap saling menghormati dan bekerja sama antarumat beragama di lingkungan warga desa tanpa memaksakan suatu agama merupakan pengamalan Pancasila, khususnya Sila...", "options": ["Pertama: Ketuhanan Yang Maha Esa", "Kedua: Kemanusiaan yang Adil dan Beradab", "Ketiga: Persatuan Indonesia", "Kelima: Keadilan Sosial bagi Seluruh Rakyat Indonesia"], "answer": 0, "explanation": "Sila Pertama Pancasila mengajarkan toleransi, kebebasan beragama, dan penghormatan antarumat beragama tanpa pemaksaan kehendak.", "source": "Ketetapan MPR RI / Butir-butir Pengamalan Pancasila", "sourceType": "wawasan"}, {"id": 34, "number": 34, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Seorang perangkat desa melayani semua warga dengan sopan dan adil tanpa membeda-bedakan latar belakang suku, agama, kekayaan, atau ikatan keluarga. Tindakan ini mencerminkan pengamalan Pancasila Sila...", "options": ["Sila ke-1", "Sila ke-2", "Sila ke-3", "Sila ke-4"], "answer": 1, "explanation": "Mengakui persamaan derajat, persamaan hak dan kewajiban asasi setiap manusia tanpa membeda-bedakan suku, keturunan, agama, atau status sosial adalah perwujudan Sila Kedua: Kemanusiaan yang Adil dan Beradab.", "source": "Pedoman Pengamalan Pancasila Sila Ke-2", "sourceType": "wawasan"}, {"id": 35, "number": 35, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Menggalang kembali budaya kerja bakti, gotong royong membersihkan saluran air desa, serta menjaga kerukunan warga merupakan wujud pengamalan Sila...", "options": ["Pertama", "Kedua", "Ketiga: Persatuan Indonesia", "Keempat"], "answer": 2, "explanation": "Gotong royong, menjaga persatuan dan kesatuan serta menempatkan kepentingan bersama di atas kepentingan pribadi/golongan adalah esensi Sila Ketiga: Persatuan Indonesia.", "source": "Pedoman Pengamalan Pancasila Sila Ke-3", "sourceType": "wawasan"}, {"id": 36, "number": 36, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Musyawarah Desa (Musdes) untuk mencapai mufakat dalam memecahkan persoalan desa merupakan implementasi langsung dari nilai Pancasila Sila...", "options": ["Kedua", "Ketiga", "Keempat: Kerakyatan yang Dipimpin oleh Hikmat Kebijaksanaan dalam Permusyawaratan/Perwakilan", "Kelima"], "answer": 2, "explanation": "Sila Keempat mengamanatkan pengambilan keputusan melalui musyawarah untuk mencapai mufakat yang diliputi oleh semangat kekeluargaan.", "source": "Pedoman Pengamalan Pancasila Sila Ke-4", "sourceType": "wawasan"}, {"id": 37, "number": 37, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Penyaluran bantuan sosial desa kepada masyarakat miskin secara objektif, merata, transparan, dan tidak diskriminatif merupakan wujud nyata pengamalan Pancasila Sila...", "options": ["Pertama", "Kedua", "Keempat", "Kelima: Keadilan Sosial bagi Seluruh Rakyat Indonesia"], "answer": 3, "explanation": "Sila Kelima menekankan keadilan sosial, pemerataan hak, serta perlindungan dan bantuan terhadap masyarakat rentan tanpa kesewenang-wenangan.", "source": "Pedoman Pengamalan Pancasila Sila Ke-5", "sourceType": "wawasan"}, {"id": 38, "number": 38, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Tujuan nasional Negara Republik Indonesia yang tercantum secara resmi dalam Pembukaan UUD 1945 Alinea IV meliputi hal-hal berikut, KECUALI...", "options": ["Melindungi segenap bangsa Indonesia dan seluruh tumpah darah Indonesia", "Memajukan kesejahteraan umum dan mencerdaskan kehidupan bangsa", "Ikut melaksanakan ketertiban dunia yang berdasarkan kemerdekaan, perdamaian abadi, dan keadilan sosial", "Menjadikan negara Indonesia sebagai kekuatan militer adidaya di Asia Tenggara"], "answer": 3, "explanation": "Empat tujuan negara dalam Pembukaan UUD 1945 Alinea IV adalah: melindungi segenap bangsa & tumpah darah Indonesia, memajukan kesejahteraan umum, mencerdaskan kehidupan bangsa, dan ikut melaksanakan ketertiban dunia.", "source": "Pembukaan UUD NRI Tahun 1945 Alinea IV", "sourceType": "wawasan"}, {"id": 39, "number": 39, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Rumusan bunyi Pasal 1 ayat (2) UUD 1945 setelah amandemen ketiga adalah...", "options": ["Negara Indonesia ialah Negara Kesatuan, yang berbentuk Republik", "Kedaulatan berada di tangan rakyat dan dilaksanakan menurut Undang-Undang Dasar", "Negara Indonesia adalah negara hukum", "Kedaulatan adalah di tangan rakyat, dan dilakukan sepenuhnya oleh Majelis Permusyawaratan Rakyat"], "answer": 1, "explanation": "Pasal 1 ayat (2) UUD 1945 pasca-amandemen berbunyi: 'Kedaulatan berada di tangan rakyat dan dilaksanakan menurut Undang-Undang Dasar.'", "source": "UUD NRI Tahun 1945 Pasal 1 ayat (2)", "sourceType": "wawasan"}, {"id": 40, "number": 40, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Ketentuan mengenai hak dan kewajiban setiap warga negara untuk ikut serta dalam upaya pembelaan negara diatur dalam UUD 1945 pada...", "options": ["Pasal 27 ayat (3)", "Pasal 29 ayat (1)", "Pasal 31 ayat (2)", "Pasal 33 ayat (1)"], "answer": 0, "explanation": "Pasal 27 ayat (3) UUD 1945 menyatakan: 'Setiap warga negara berhak dan wajib ikut serta dalam upaya pembelaan negara.'", "source": "UUD NRI Tahun 1945 Pasal 27 ayat (3)", "sourceType": "wawasan"}, {"id": 41, "number": 41, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Semboyan 'Bhinneka Tunggal Ika' yang tertulis pada pita lambang negara Garuda Pancasila dipetik dari kitab kuno...", "options": ["Kitab Negarakertagama karangan Mpu Prapanca", "Kitab Sutasoma karangan Mpu Tantular", "Kitab Arjunawiwaha karangan Mpu Kanwa", "Kitab Bharatayuddha karangan Mpu Sedah dan Mpu Panuluh"], "answer": 1, "explanation": "Frasa Bhinneka Tunggal Ika ('berbeda-beda tetapi tetap satu') berasal dari Kakawin Sutasoma karangan Mpu Tantular pada zaman Kerajaan Majapahit abad ke-14.", "source": "Kitab Sutasoma; UU No. 24 Tahun 2009 tentang Bendera, Bahasa, dan Lambang Negara", "sourceType": "wawasan"}, {"id": 42, "number": 42, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Cara pandang bangsa Indonesia mengenai diri dan lingkungannya yang serba beragam dengan mengutamakan persatuan dan kesatuan wilayah dalam penyelenggaraan kehidupan bermasyarakat, berbangsa, dan bernegara disebut...", "options": ["Ketahanan Nasional", "Wawasan Nusantara", "Bela Negara Fisik", "Otonomi Daerah"], "answer": 1, "explanation": "Wawasan Nusantara adalah cara pandang bangsa Indonesia tentang diri dan lingkungannya berdasarkan Pancasila dan UUD 1945 sebagai satu kesatuan utuh.", "source": "Modul Wawasan Kebangsaan Lemhannas RI", "sourceType": "wawasan"}, {"id": 43, "number": 43, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Berdasarkan Permendagri Nomor 47 Tahun 2016, buku administrasi desa dikelompokkan ke dalam 5 (lima) bidang administrasi, yaitu...", "options": ["Administrasi Umum, Penduduk, Keuangan, Pembangunan, dan Badan Permusyawaratan Desa", "Administrasi Surat, Pajak, KTP, Bansos, dan Pengaduan", "Administrasi Pertanahan, Kepolisian, Pengadilan, Pajak, dan Militer", "Administrasi Kepegawaian, Logistik, Kendaraan, Bangunan, dan Inventaris Kantor"], "answer": 0, "explanation": "Pasal 3 Permendagri No. 47 Tahun 2016 membagi administrasi pemerintahan desa ke dalam 5 jenis: Administrasi Umum, Penduduk, Keuangan, Pembangunan, dan Permusyawaratan Desa (BPD).", "source": "Permendagri No. 47 Tahun 2016 tentang Administrasi Pemerintahan Desa", "sourceType": "administrasi"}, {"id": 44, "number": 44, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Buku yang berfungsi untuk mencatat seluruh peraturan desa, keputusan kepala desa, aparat pemerintah desa, dan data inventaris/tanah kas desa tergolong dalam kelompok...", "options": ["Buku Administrasi Penduduk", "Buku Administrasi Umum", "Buku Administrasi Keuangan", "Buku Administrasi Pembangunan"], "answer": 1, "explanation": "Buku Administrasi Umum meliputi Buku Data Peraturan Desa, Keputusan Kepala Desa, Inventaris dan Kekayaan Desa, Aparat Pemerintah Desa, Tanah Kas Desa, Tanah di Desa, Agenda, dan Ekspedisi.", "source": "Permendagri No. 47 Tahun 2016 Lampiran I", "sourceType": "administrasi"}, {"id": 45, "number": 45, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Dalam penatausahaan surat dinas, buku yang digunakan sebagai bukti otentik pengiriman dan tanda terima surat keluar oleh pihak luar atau instansi penerima adalah...", "options": ["Buku Agenda Surat Masuk", "Buku Ekspedisi", "Buku Register Penduduk", "Buku Kas Pembantu"], "answer": 1, "explanation": "Buku Ekspedisi adalah buku administrasi yang mencatat pengiriman surat keluar dan memuat tanda tangan penerima sebagai bukti fisik bahwa surat dinas telah sampai kepada pihak yang dituju.", "source": "Permendagri No. 47 Tahun 2016 Pedoman Administrasi Umum", "sourceType": "administrasi"}, {"id": 46, "number": 46, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Urutan komponen baku dalam penomoran surat keluar dinas pemerintah desa secara berurutan adalah...", "options": ["Tahun / Bulan / Kode Surat / Nama Pengetik", "Kode Klasifikasi Surat / Nomor Urut Surat Keluar / Singkatan Instansi Desa / Bulan (Romawi) / Tahun", "Nama Penerima / Nomor KTP Kades / Tanggal Kirim / Kode Pos", "Nomor Acak Komputer / Jumlah Halaman / Kode Dusun"], "answer": 1, "explanation": "Format baku tata naskah dinas penomoran surat keluar: Kode Klasifikasi Masalah / Nomor Urut Agenda Keluar / Kode Pemdes / Bulan Masehi (angka Romawi) / Tahun Anggaran (misal: 140/025/Desa.Mulyo/V/2026).", "source": "Permendagri tentang Tata Naskah Dinas di Lingkungan Pemerintah Daerah/Desa", "sourceType": "administrasi"}, {"id": 47, "number": 47, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Kepala surat (Kop Surat) resmi Pemerintah Desa yang sesuai dengan ketentuan tata naskah dinas memuat elemen...", "options": ["Foto Kepala Desa terpilih, moto pribadi, dan nomor rekening pribadi", "Logo/Lambang Daerah Kabupaten, tulisan PEMERINTAH KABUPATEN, nama KECAMATAN, nama PEMERINTAH DESA, serta alamat lengkap kantor, kode pos, dan kontak resmi", "Nama partai politik pengusung Kepala Desa dan daftar anggota BPD", "Daftar nama seluruh perangkat desa beserta besaran gajinya"], "answer": 1, "explanation": "Kop naskah dinas resmi instansi pemerintah desa wajib memuat lambang Pemkab di kiri/tengah, hierarki pemerintah kabupaten, kecamatan, pemdes, alamat balai desa, kode pos, serta saluran komunikasi resmi.", "source": "Pedoman Tata Naskah Dinas Pemerintah Daerah/Desa", "sourceType": "administrasi"}, {"id": 48, "number": 48, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Karakteristik yuridis dari Surat Keputusan (SK) Kepala Desa adalah bersifat...", "options": ["Abstrak, umum, dan berlaku terus menerus tanpa batas pihak", "Konkret, individual, dan final (menetapkan status atau hak seseorang/organisasi secara definitif)", "Himbauan moral yang tidak memiliki kekuatan hukum mengikat", "Perjanjian perdata timbal balik yang bisa dibatalkan secara sepihak oleh warga"], "answer": 1, "explanation": "Keputusan Kepala Desa (beschikking) bersifat konkret (nyata wujudnya), individual (ditujukan kepada pihak tertentu), dan final (sudah definitif dan menimbulkan akibat hukum).", "source": "UU Administrasi Pemerintahan No. 30 Tahun 2014; Permendagri No. 111 Tahun 2014", "sourceType": "administrasi"}, {"id": 49, "number": 49, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Perbedaan mendasar antara Surat Keterangan dan Surat Pengantar yang diterbitkan oleh pemerintah desa adalah...", "options": ["Surat keterangan harus ditandatangani bupati, sedangkan surat pengantar ditandatangani camat", "Surat keterangan menerangkan keadaan/fakta keabsahan subjek hukum tertentu, sedangkan surat pengantar mengantarkan berkas atau permohonan warga ke instansi lain", "Surat pengantar hanya berlaku 1 hari, sedangkan surat keterangan berlaku seumur hidup", "Surat keterangan dikenai tarif pungutan desa, sedangkan surat pengantar bebas biaya"], "answer": 1, "explanation": "Surat Keterangan berfungsi menerangkan suatu hal/keadaan faktual warga (misal: domisili, usaha, kematian), sedangkan Surat Pengantar digunakan untuk mengantarkan berkas/keperluan warga ke instansi jenjang berikutnya (Kecamatan/Disdukcapil).", "source": "Praktik Tata Kelola Administrasi Pelayanan Publik Desa", "sourceType": "administrasi"}, {"id": 50, "number": 50, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Arsip dinamis di kantor desa yang frekuensi penggunaannya untuk penyelenggaraan administrasi sehari-hari sudah menurun, tetapi masih harus disimpan karena memiliki nilai pertanggungjawaban disebut...", "options": ["Arsip Aktif", "Arsip Inaktif", "Arsip Statis", "Arsip Rahasia Mutlak"], "answer": 1, "explanation": "Menurut UU No. 43 Tahun 2009 tentang Kearsipan, arsip aktif adalah arsip yang masih sering digunakan terus-menerus, sedangkan arsip inaktif adalah arsip yang frekuensi penggunaannya telah menurun.", "source": "Undang-Undang No. 43 Tahun 2009 tentang Kearsipan", "sourceType": "administrasi"}, {"id": 51, "number": 51, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Ketika warga desa datang melapor bahwa ada anggota keluarganya yang meninggal dunia di rumah, dokumen administrasi awal yang diterbitkan oleh pemerintah desa adalah...", "options": ["Surat Izin Mengemudi Desa", "Surat Keterangan Kematian dari Desa", "Surat Perjanjian Warisan Bersama", "Surat Pernyataan Bebas Pajak Bumi dan Bangunan"], "answer": 1, "explanation": "Pemerintah Desa menerbitkan Surat Keterangan Kematian berdasarkan laporan ahli waris/RT sebagai dokumen dasar pengurusan Akta Kematian di Dinas Kependudukan dan Pencatatan Sipil.", "source": "Permendagri No. 108 Tahun 2019 tentang Pelaksanaan Perpres Adminduk", "sourceType": "administrasi"}, {"id": 52, "number": 52, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Dalam penulisan naskah dinas resmi pemerintahan, prinsip pokok yang wajib dipedomani oleh perangkat desa adalah...", "options": ["Kejelasan maksud, ketepatan redaksi bahasa baku, ketelitian format, dan keabsahan legalitas", "Penggunaan bahasa gaul yang santai agar mudah dipahami remaja", "Mencantumkan opini subjektif perangkat desa tanpa dasar aturan", "Membuat naskah sepanjang mungkin agar terlihat sangat berbobot"], "answer": 0, "explanation": "Tata naskah dinas pemerintahan wajib menerapkan asas kejelasan, ketelitian, ketepatan, kebakuan bahasa, efektivitas, serta kepatuhan pada hierarki dan format baku.", "source": "Pedoman Umum Tata Naskah Dinas Instansi Pemerintah", "sourceType": "administrasi"}, {"id": 53, "number": 53, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "mudah", "question": "Berdasarkan Permendagri Nomor 20 Tahun 2018 tentang Pengelolaan Keuangan Desa, Pemegang Kekuasaan Pengelolaan Keuangan Desa (PKPKD) adalah...", "options": ["Sekretaris Desa", "Kepala Desa", "Ketua Badan Permusyawaratan Desa (BPD)", "Kepala Urusan Keuangan (Bendahara Desa)"], "answer": 1, "explanation": "Pasal 3 Permendagri No. 20 Tahun 2018 menetapkan bahwa Kepala Desa adalah Pemegang Kekuasaan Pengelolaan Keuangan Desa (PKPKD) dan mewakili Pemerintah Desa dalam kepemilikan kekayaan milik desa.", "source": "Permendagri No. 20 Tahun 2018 Pasal 3", "sourceType": "regulasi"}, {"id": 54, "number": 54, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Dalam struktur Pelaksana Pengelolaan Keuangan Desa (PPKD), Sekretaris Desa bertindak sebagai...", "options": ["Bendahara pengeluaran desa", "Koordinator PPKD", "Pengawas eksternal APB Desa", "Pelaksana Kegiatan Anggaran tunggal"], "answer": 1, "explanation": "Berdasarkan Pasal 4 dan Pasal 5 Permendagri No. 20 Tahun 2018, Sekretaris Desa bertindak selaku Koordinator PPKD yang membantu PKPKD dalam mengoordinasikan pengelolaan keuangan desa.", "source": "Permendagri No. 20 Tahun 2018 Pasal 5", "sourceType": "regulasi"}, {"id": 55, "number": 55, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "mudah", "question": "Anggaran Pendapatan dan Belanja Desa (APB Desa) terdiri atas 3 (tiga) kelompok struktur utama, yaitu...", "options": ["Penerimaan Pajak, Pengeluaran Rutin, dan Dana Bantuan Sosial", "Pendapatan Desa, Belanja Desa, dan Pembiayaan Desa", "Modal Desa, Kas Operasional, dan Simpanan Bank", "Gaji Perangkat Desa, Biaya Listrik Kantor, dan Dana Cadangan Bencana"], "answer": 1, "explanation": "Pasal 11 Permendagri No. 20 Tahun 2018 mengatur bahwa struktur APB Desa terdiri atas Pendapatan Desa, Belanja Desa, dan Pembiayaan Desa.", "source": "Permendagri No. 20 Tahun 2018 Pasal 11", "sourceType": "regulasi"}, {"id": 56, "number": 56, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Alokasi Dana Desa (ADD) yang diterima oleh pemerintah desa bersumber dari...", "options": ["Anggaran Pendapatan dan Belanja Negara (APBN) langsung pos Dana Desa", "Paling sedikit 10% dari dana perimbangan yang diterima kabupaten/kota dalam APBD setelah dikurangi DAK", "Pungutan sukarela dari warga desa yang merantau ke luar negeri", "Hasil penjualan aset tanah bengkok desa kepada pihak swasta"], "answer": 1, "explanation": "Pasal 72 ayat (1) huruf d dan ayat (4) UU No. 6 Tahun 2014 mengatur bahwa Alokasi Dana Desa (ADD) dialokasikan paling sedikit 10% dari dana perimbangan yang diterima kabupaten/kota dalam APBD setelah dikurangi Dana Alokasi Khusus (DAK).", "source": "UU No. 6 Tahun 2014 Pasal 72 ayat (4)", "sourceType": "regulasi"}, {"id": 57, "number": 57, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri Nomor 20 Tahun 2018, klasifikasi Belanja Desa dibagi ke dalam 5 (lima) bidang. Bidang ke-5 adalah...", "options": ["Bidang Penanaman Modal Asing di Pedesaan", "Bidang Penanggulangan Bencana, Keadaan Darurat, dan Mendesak Desa", "Bidang Pembiayaan Pemilihan Presiden dan Wakil Presiden", "Bidang Pengadaan Persenjataan dan Pertahanan Militer"], "answer": 1, "explanation": "Pasal 16 Permendagri No. 20 Tahun 2018 membagi klasifikasi belanja desa menjadi: 1. Penyelenggaraan Pemerintahan Desa, 2. Pelaksanaan Pembangunan Desa, 3. Pembinaan Kemasyarakatan Desa, 4. Pemberdayaan Masyarakat Desa, dan 5. Penanggulangan Bencana, Keadaan Darurat dan Mendesak Desa.", "source": "Permendagri No. 20 Tahun 2018 Pasal 16", "sourceType": "regulasi"}, {"id": 58, "number": 58, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Pengeluaran belanja yang sifatnya tidak dapat diprediksi sebelumnya dan terjadi di luar kendali pemerintah desa, seperti perbaikan tanggul desa yang jebol akibat banjir bandang, dibebankan pada pos...", "options": ["Belanja Pegawai dan Operasional Kantor", "Belanja Tidak Terduga pada Bidang Penanggulangan Bencana, Keadaan Darurat dan Mendesak", "Belanja Modal Pengadaan Tanah Kas Desa", "Belanja Bantuan Hukum untuk Perangkat Desa"], "answer": 1, "explanation": "Belanja tidak terduga dianggarkan pada bidang penanggulangan bencana, keadaan darurat, dan mendesak desa untuk membiayai penanganan tanggap darurat bencana alam/sosial.", "source": "Permendagri No. 20 Tahun 2018 Pasal 22", "sourceType": "regulasi"}, {"id": 59, "number": 59, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "mudah", "question": "Asas pengelolaan keuangan desa yang mewajibkan bahwa semua kegiatan dan hasil akhir keuangan desa dapat dipertanggungjawabkan kepada masyarakat sesuai peraturan perundang-undangan disebut asas...", "options": ["Akuntabel", "Transparan", "Sentralistik", "Fleksibel Bebas"], "answer": 0, "explanation": "Pasal 2 Permendagri No. 20 Tahun 2018 menetapkan asas pengelolaan keuangan desa: transparan, akuntabel, partisipatif, serta tertib dan disiplin anggaran. Akuntabel berarti dapat dipertanggungjawabkan kepada masyarakat.", "source": "Permendagri No. 20 Tahun 2018 Pasal 2", "sourceType": "regulasi"}, {"id": 60, "number": 60, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Aplikasi sistem informasi resmi berbasis komputer yang dikembangkan pemerintah (Kemendagri dan BPKP) untuk membantu pemerintah desa menatausahakan keuangan desa adalah...", "options": ["SISKEUDES (Sistem Keuangan Desa)", "SIPD RI (Sistem Informasi Pembangunan Daerah)", "DAPODIK (Data Pokok Pendidikan)", "SIMDA BPKAD"], "answer": 0, "explanation": "SISKEUDES (Sistem Keuangan Desa) adalah aplikasi resmi yang dikembangkan oleh BPKP bersama Ditjen Bina Pemerintahan Desa Kemendagri untuk pengelolaan dan pelaporan keuangan desa di seluruh Indonesia.", "source": "Kemendagri & BPKP: Petunjuk Teknis SISKEUDES", "sourceType": "teknologi"}, {"id": 61, "number": 61, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sulit", "question": "Berdasarkan Permendagri Nomor 1 Tahun 2016 tentang Pengelolaan Aset Desa, pemanfaatan aset desa berupa sewa tanah kas desa dilaksanakan dengan jangka waktu paling lama...", "options": ["1 (satu) tahun dan tidak boleh diperpanjang", "3 (tiga) tahun dan dapat diperpanjang", "10 (sepuluh) tahun tanpa musyawarah", "25 (dua puluh lima) tahun dengan hak milik sewa"], "answer": 1, "explanation": "Berdasarkan Pasal 11 ayat (4) Permendagri No. 1 Tahun 2016, jangka waktu sewa aset desa paling lama 3 (tiga) tahun dan dapat diperpanjang.", "source": "Permendagri No. 1 Tahun 2016 tentang Pengelolaan Aset Desa Pasal 11 ayat (4)", "sourceType": "regulasi"}, {"id": 62, "number": 62, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Kelompok Pembiayaan Desa dalam struktur APB Desa terdiri atas dua pos, yaitu...", "options": ["Penerimaan Pembiayaan (seperti SiLPA tahun lalu) dan Pengeluaran Pembiayaan (seperti penyertaan modal ke BUMDes)", "Pinjaman rentenir dan bagi hasil kasino", "Pembayaran bunga utang pribadi kades dan dana talangan caleg", "Penjualan tanah kuburan dan sewa mobil dinas bupati"], "answer": 0, "explanation": "Pasal 25 Permendagri No. 20 Tahun 2018 mengatur Pembiayaan Desa terdiri atas Penerimaan Pembiayaan (SiLPA, pencairan dana cadangan, hasil penjualan kekayaan desa yang dipisahkan) dan Pengeluaran Pembiayaan (pembentukan dana cadangan, penyertaan modal BUMDes).", "source": "Permendagri No. 20 Tahun 2018 Pasal 25", "sourceType": "regulasi"}, {"id": 63, "number": 63, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Dokumen perencanaan pembangunan desa yang memuat visi, misi, dan arah kebijakan pembangunan desa untuk masa jabatan Kepala Desa disebut...", "options": ["Rencana Kerja Pemerintah Desa (RKP Desa)", "Rencana Pembangunan Jangka Menengah Desa (RPJM Desa)", "Anggaran Pendapatan dan Belanja Desa (APB Desa)", "Rencana Tata Ruang Wilayah Kecamatan (RTRW Camat)"], "answer": 1, "explanation": "Sesuai UU Desa jo. Permendesa PDTT No. 21 Tahun 2020, RPJM Desa adalah dokumen rencana pembangunan desa untuk periode masa jabatan Kepala Desa yang memuat visi, misi, dan arah kebijakan desa.", "source": "Permendesa PDTT No. 21 Tahun 2020; UU No. 6 Tahun 2014 jo. UU No. 3 Tahun 2024", "sourceType": "regulasi"}, {"id": 64, "number": 64, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Rencana Kerja Pemerintah Desa (RKP Desa) merupakan penjabaran tahunan dari RPJM Desa. Kapan batas waktu penetapan RKP Desa setiap tahunnya?", "options": ["Paling lambat akhir bulan Januari tahun anggaran berjalan", "Paling lambat akhir bulan September tahun anggaran sebelumnya", "Paling lambat tanggal 17 Agustus setiap tahun", "Paling lambat akhir bulan Desember tahun anggaran berjalan"], "answer": 1, "explanation": "Pasal 39 Permendesa PDTT No. 21 Tahun 2020 jo. Permendagri No. 114 Tahun 2014 mengatur bahwa RKP Desa mulai disusun bulan Juli dan ditetapkan paling lambat akhir bulan September tahun berjalan.", "source": "Permendesa PDTT No. 21 Tahun 2020 Pasal 39", "sourceType": "regulasi"}, {"id": 65, "number": 65, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "mudah", "question": "Forum musyawarah tahunan yang diselenggarakan oleh Pemerintah Desa untuk menyepakati rancangan RKP Desa dan daftar usulan kegiatan ke tingkat kecamatan disebut...", "options": ["Musrenbangdes (Musyawarah Perencanaan Pembangunan Desa)", "Rembuk Dusun Informal", "Kongres Warga Karang Taruna", "Rapat Dengar Pendapat Daerah"], "answer": 0, "explanation": "Musrenbangdes adalah musyawarah antar pemangku kepentingan di desa untuk mematangkan dan menyepakati rancangan RKP Desa serta menyusun DU-RKP Desa untuk Musrenbangcam.", "source": "Permendagri No. 114 Tahun 2014; Permendesa PDTT No. 21 Tahun 2020", "sourceType": "regulasi"}, {"id": 66, "number": 66, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Kebijakan pembangunan terpadu di tingkat desa yang dicanangkan oleh Kementerian Desa PDTT dengan 18 indikator tujuan pembangunan berkelanjutan dikenal dengan sebutan...", "options": ["SDGs Desa (Sustainable Development Goals Desa)", "Desa Digital Serentak Mandiri", "Gerakan Satu Desa Sepuluh Sarjana", "Program Nasional Pemberdayaan Usaha Kecil"], "answer": 0, "explanation": "SDGs Desa adalah upaya terpadu pembangunan desa untuk percepatan pencapaian Tujuan Pembangunan Berkelanjutan yang terdiri dari 18 tujuan pemenuhan hak dasar dan lingkungan hidup di desa.", "source": "Permendesa PDTT No. 21 Tahun 2020", "sourceType": "regulasi"}, {"id": 67, "number": 67, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Berdasarkan UU Cipta Kerja dan Peraturan Pemerintah Nomor 11 Tahun 2021, status hukum Badan Usaha Milik Desa (BUMDes) saat ini adalah...", "options": ["Badan usaha milik keluarga Kepala Desa", "Badan Hukum yang didirikan oleh desa untuk mendayagunakan potensi ekonomi desa", "Unit pelaksana teknis dinas cabang pembantu bupati", "Koperasi simpan pinjam liar tanpa perlindungan hukum"], "answer": 1, "explanation": "PP No. 11 Tahun 2021 menegaskan bahwa BUMDes berstatus sebagai Badan Hukum yang memperoleh pengesahan dari Kementerian Hukum dan HAM setelah proses verifikasi dokumen pendaftaran.", "source": "Peraturan Pemerintah No. 11 Tahun 2021 tentang BUMDes", "sourceType": "regulasi"}, {"id": 68, "number": 68, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "mudah", "question": "Berikut ini yang termasuk Lembaga Kemasyarakatan Desa (LKD) menurut Permendagri Nomor 18 Tahun 2018 adalah...", "options": ["RT, RW, PKK, Karang Taruna, Posyandu, dan Lembaga Pemberdayaan Masyarakat (LPM)", "Polsek, Koramil, dan Kejaksaan Negeri", "Partai Politik, Ormas Keagamaan Pusat, dan Serikat Buruh Nasional", "BPD, Inspektorat, dan Kantor Urusan Agama"], "answer": 0, "explanation": "Pasal 3 Permendagri No. 18 Tahun 2018 menyebutkan jenis LKD paling sedikit meliputi: Rukun Tetangga (RT), Rukun Warga (RW), Pemberdayaan Kesejahteraan Keluarga (PKK), Karang Taruna, Pos Pelayanan Terpadu (Posyandu), dan LPM.", "source": "Permendagri No. 18 Tahun 2018 Pasal 3", "sourceType": "regulasi"}, {"id": 69, "number": 69, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Pendekatan pemberdayaan masyarakat desa menempatkan masyarakat sebagai...", "options": ["Objek pasif yang sekadar menerima bantuan tanpa dimintai masukan", "Subjek utama pelaku dan penentu keberhasilan pembangunan desanya sendiri", "Penonton pasif dalam setiap perumusan program kerja pemerintah desa", "Tenaga kerja paksa tanpa upah dalam pelaksanaan proyek fisik desa"], "answer": 1, "explanation": "Pemberdayaan masyarakat menempatkan warga desa sebagai subjek berdaya yang berpartisipasi aktif mulai dari perencanaan, pelaksanaan, evaluasi, hingga pemanfaatan hasil pembangunan.", "source": "UU No. 6 Tahun 2014 tentang Asas Partisipatif Desa", "sourceType": "administrasi"}, {"id": 70, "number": 70, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Indikator komposit yang digunakan oleh Kementerian Desa PDTT untuk mengukur status kemandirian desa (Maju, Berkembang, Mandiri, Tertinggal) disebut...", "options": ["Indeks Desa Membangun (IDM)", "Indeks Persepsi Korupsi Desa (IPKD)", "Indeks Kepuasan Konsumen Desa (IKKD)", "Indeks Pembangunan Gedung Balai Desa"], "answer": 0, "explanation": "Indeks Desa Membangun (IDM) adalah indeks komposit yang dibentuk dari Indeks Ketahanan Sosial, Indeks Ketahanan Ekonomi, dan Indeks Ketahanan Lingkungan untuk menetapkan status kemajuan desa.", "source": "Permendesa PDTT No. 2 Tahun 2016 tentang IDM", "sourceType": "regulasi"}, {"id": 71, "number": 71, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "mudah", "question": "Berdasarkan Pasal 55 UU Nomor 6 Tahun 2014 jo. Permendagri Nomor 110 Tahun 2016, tiga fungsi utama Badan Permusyawaratan Desa (BPD) adalah...", "options": ["Membahas dan menyepakati Ranperdes bersama Kepala Desa, menampung dan menyalurkan aspirasi masyarakat, serta mengawasi kinerja Kepala Desa", "Menghimpun pajak desa, mengelola rekening kas desa, dan membelanjakan dana desa", "Menyelidiki kasus kriminalitas desa, menangkap pelanggar hukum, dan menjatuhkan vonis denda", "Menggantikan Kepala Desa dalam memimpin proyek fisik bangunan desa"], "answer": 0, "explanation": "Pasal 55 UU No. 6 Tahun 2014 jo. Pasal 31 Permendagri No. 110 Tahun 2016 secara eksplisit menegaskan tiga fungsi BPD: membahas dan menyepakati rancangan Perdes bersama Kades, menampung & menyalurkan aspirasi masyarakat, serta melakukan pengawasan kinerja Kades.", "source": "UU No. 6 Tahun 2014 Pasal 55; Permendagri No. 110 Tahun 2016 Pasal 31", "sourceType": "regulasi"}, {"id": 72, "number": 72, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Anggota Badan Permusyawaratan Desa (BPD) dilarang merangkap jabatan sebagai...", "options": ["Kepala Desa dan Perangkat Desa", "Ketua RT di lingkungan rumahnya", "Anggota kelompok arisan warga dusun", "Pengurus takmir tempat ibadah desa"], "answer": 0, "explanation": "Pasal 64 UU No. 6 Tahun 2014 jo. Permendagri No. 110/2016 melarang anggota BPD merangkap jabatan sebagai Kepala Desa dan Perangkat Desa untuk menjaga independensi fungsi pengawasan.", "source": "UU No. 6 Tahun 2014 Pasal 64 huruf a", "sourceType": "regulasi"}, {"id": 73, "number": 73, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Pengisian keanggotaan BPD dilaksanakan secara demokratis berdasarkan asas keterwakilan...", "options": ["Keluarga terdekat kepala desa", "Wilayah dusun/bagian wilayah desa dan keterwakilan perempuan", "Partai politik peraih kursi terbanyak di pemilu", "Warga terkaya yang memiliki tanah terluas di desa"], "answer": 1, "explanation": "Berdasarkan Permendagri No. 110 Tahun 2016, anggota BPD merupakan wakil dari penduduk desa berdasarkan keterwakilan wilayah dan keterwakilan perempuan yang pengisiannya dilakukan melalui musyawarah perwakilan atau pemilihan langsung.", "source": "Permendagri No. 110 Tahun 2016 Pasal 5", "sourceType": "regulasi"}, {"id": 74, "number": 74, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "mudah", "question": "Musyawarah Desa (Musdes) merupakan forum permusyawaratan tertinggi di desa yang diselenggarakan oleh...", "options": ["Badan Permusyawaratan Desa (BPD) difasilitasi oleh Pemerintah Desa", "Kantor Kecamatan bersama kepolisian sektor", "Lembaga swadaya masyarakat dari luar daerah", "Perusahaan swasta pengelola tambang setempat"], "answer": 0, "explanation": "Berdasarkan Pasal 54 UU No. 6 Tahun 2014 jo. Permendesa PDTT No. 16 Tahun 2019, Musyawarah Desa diselenggarakan oleh BPD dengan difasilitasi oleh Pemerintah Desa untuk memusyawarahkan hal-hal strategis desa.", "source": "UU No. 6 Tahun 2014 Pasal 54; Permendesa PDTT No. 16 Tahun 2019", "sourceType": "regulasi"}, {"id": 75, "number": 75, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sulit", "question": "Kepala Desa wajib menyampaikan Laporan Keterangan Penyelenggaraan Pemerintahan Desa (LKPPD) akhir tahun anggaran kepada BPD dalam jangka waktu...", "options": ["Paling lambat 30 hari kalender setelah dilantik", "Paling lambat 3 (tiga) bulan setelah berakhirnya tahun anggaran", "Paling lambat 6 bulan menjelang masa jabatan kades berakhir", "Hanya jika diminta secara tertulis oleh camat setempat"], "answer": 1, "explanation": "Pasal 27 UU No. 6 Tahun 2014 jo. Permendagri No. 46 Tahun 2016 mengatur Kepala Desa wajib memberikan LKPPD tertulis kepada BPD paling lambat 3 (tiga) bulan setelah tahun anggaran berakhir.", "source": "Permendagri No. 46 Tahun 2016 tentang Laporan Kepala Desa Pasal 8", "sourceType": "regulasi"}, {"id": 76, "number": 76, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Manakah deretan kata baku menurut Kamus Besar Bahasa Indonesia (KBBI) dan Pedoman Ejaan Bahasa Indonesia yang Disempurnakan (EYD V)?", "options": ["Antri, ijin, kwitansi, sistim", "Antre, izin, kuitansi, sistem", "Antre, idzin, kuitansi, sistim", "Antri, izin, kwitansi, sistem"], "answer": 1, "explanation": "Kata baku yang sesuai dengan KBBI dan EYD V adalah 'antre' (bukan antri), 'izin' (bukan ijin/idzin), 'kuitansi' (bukan kwitansi), dan 'sistem' (bukan sistim).", "source": "Kamus Besar Bahasa Indonesia (KBBI) V & Ejaan yang Disempurnakan (EYD V)", "sourceType": "kebahasaan"}, {"id": 77, "number": 77, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Penulisan huruf kapital yang tepat pada penulisan nama jabatan dan wilayah dalam naskah dinas adalah...", "options": ["Rapat koordinasi dipimpin langsung oleh bupati tuban di Balai Desa.", "Rapat koordinasi dipimpin langsung oleh Bupati Tuban di balai Desa.", "Rapat koordinasi dipimpin langsung oleh Bupati Tuban di Balai Desa Sukamakmur.", "Rapat koordinasi dipimpin langsung oleh Bupati tuban di balai desa sukamakmur."], "answer": 2, "explanation": "Sesuai kaidah EYD V, huruf kapital digunakan sebagai huruf pertama unsur nama jabatan dan pangkat yang diikuti nama orang atau nama tempat/wilayah, serta nama geografis yang jelas (Bupati Tuban, Balai Desa Sukamakmur).", "source": "EYD V Pedoman Penggunaan Huruf Kapital", "sourceType": "kebahasaan"}, {"id": 78, "number": 78, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Perhatikan kalimat surat undangan dinas berikut:\n'Surat undangan ini kami sampaikan ... kehadiran Bapak/Ibu sangat kami harapkan.'\nKata penghubung (konjungsi) yang paling tepat untuk mengisi bagian rumpang tersebut adalah...", "options": ["meskipun demikian", "oleh karena itu", "sehingga", "sedangkan"], "answer": 1, "explanation": "Konjungsi antarkalimat yang menyatakan hubungan sebab-akibat atau kesimpulan yang logis dan formal dalam surat dinas adalah 'oleh karena itu'.", "source": "Tata Bahasa Baku Bahasa Indonesia", "sourceType": "kebahasaan"}, {"id": 79, "number": 79, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Kalimat dinas manakah yang paling efektif dan terbebas dari pemborosan kata (pleonasme)?", "options": ["Kepada para bapak-bapak dan ibu-ibu sekalian dimohon untuk segera memasuki ruangan rapat.", "Para undangan dimohon memasuki ruang rapat.", "Semua para peserta ujian perangkat desa wajib harus membawa kartu identitas diri masing-masing.", "Demi untuk mewujudkan ketertiban maka warga masyarakat dihimbau agar mematuhi aturan."], "answer": 1, "explanation": "Kalimat 'Para undangan dimohon memasuki ruang rapat' padat, lugas, efektif, dan tidak mengulang kata jamak (tidak memboroskan kata seperti 'para bapak-bapak sekalian' atau 'demi untuk').", "source": "Kaidah Kalimat Efektif Bahasa Indonesia", "sourceType": "kebahasaan"}, {"id": 80, "number": 80, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Penulisan rincian jadwal kegiatan dalam surat dinas resmi yang benar adalah...", "options": ["Hari, tanggal: Senin, 20 Oktober 2026\nWaktu: pukul 08.00 WIB\nTempat: Balai Desa", "hari, tanggal : Senin, 20 Oktober 2026\nwaktu : Pukul 08.00 WIB\ntempat : Balai Desa", "HARI/TANGGAL: Senin/20-10-2026\nJAM: 8 pagi\nTEMPAT: Balai", "Hari/Tgl; Senin, 20 Oktober 2026\nWaktu; 08:00\nTempat; Balai Desa"], "answer": 1, "explanation": "Jika rincian merupakan lanjutan dari kalimat sebelumnya yang diakhiri tanda titik dua, huruf pertama kata 'hari, tanggal', 'waktu', dan 'tempat' menggunakan huruf kecil karena bukan awal kalimat baru.", "source": "Pedoman Tata Naskah Dinas & EYD V", "sourceType": "kebahasaan"}, {"id": 81, "number": 81, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Bacalah paragraf laporan berikut:\n'Pemerintah Desa Sumberagung berhasil merampungkan pembangunan jalan usaha tani sepanjang 800 meter. Sarana jalan baru ini mempermudah mobilitas petani mengangkut hasil panen padi menuju pasar kecamatan, sehingga biaya transportasi dapat ditekan hingga 30 persen.'\nGagasan utama (ide pokok) paragraf tersebut adalah...", "options": ["Tingginya harga sewa kendaraan pengangkut gabah petani", "Penyelesaian pembangunan jalan usaha tani dan manfaatnya bagi petani", "Perjalanan hasil panen petani menuju pasar induk kecamatan", "Keluhan petani Desa Sumberagung mengenai kondisi jalan becek"], "answer": 1, "explanation": "Gagasan pokok paragraf terletak pada rampungnya pembangunan jalan usaha tani oleh Pemerintah Desa Sumberagung serta dampak positifnya bagi transportasi hasil panen petani.", "source": "Teknik Pemahaman Wacana Bahasa Indonesia", "sourceType": "kebahasaan"}, {"id": 82, "number": 82, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Kata serapan yang penulisannya sudah benar sesuai kaidah ortografi Bahasa Indonesia adalah...", "options": ["Kwalitas, kwantitas, frekwensi", "Kualitas, kuantitas, frekuensi", "Kwalitet, kwantitet, frekwensi", "Kualitet, kuantitet, frekwensi"], "answer": 1, "explanation": "Gugus konsonan asing 'qu-' diserap ke dalam Bahasa Indonesia menjadi 'ku-', sehingga penulisan baku adalah kualitas, kuantitas, dan frekuensi.", "source": "Pedoman Umum Pembentukan Istilah (PUPI) Bahasa Indonesia", "sourceType": "kebahasaan"}, {"id": 83, "number": 83, "category": "Matematika dan numerik", "difficulty": "mudah", "question": "Pemerintah Desa menerima pagu APB Desa sebesar Rp1.200.000.000,00. Jika Bidang Pelaksanaan Pembangunan Desa memperoleh alokasi sebesar Rp480.000.000,00, berapa persentase anggaran pembangunan tersebut dari total APB Desa?", "options": ["30%", "35%", "40%", "45%"], "answer": 2, "explanation": "Perhitungan: (Rp480.000.000 / Rp1.200.000.000) x 100% = 0,4 x 100% = 40%.", "source": "Aritmetika Dasar / Persentase APB Desa", "sourceType": "numerik"}, {"id": 84, "number": 84, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Sebidang tanah kas desa berbentuk persegi panjang memiliki panjang 250 meter dan lebar 80 meter. Berapakah luas tanah kas desa tersebut dalam satuan hektar (ha)?", "options": ["1,5 hektar", "2,0 hektar", "2,5 hektar", "20 hektar"], "answer": 1, "explanation": "Luas = panjang x lebar = 250 m x 80 m = 20.000 m². Karena 1 hektar = 10.000 m², maka 20.000 m² ÷ 10.000 = 2,0 hektar.", "source": "Pengukuran Geometri Lahan Pertanahan", "sourceType": "numerik"}, {"id": 85, "number": 85, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Pemerintah Desa membeli material semen untuk rabat beton jalan senilai Rp20.000.000,00 dari rekanan non-PKP. Berdasarkan ketentuan perpajakan, transaksi pengadaan barang tersebut dipotong Pajak Penghasilan (PPh) Pasal 22 sebesar 1,5%. Berapakah nilai nominal potongan pajak PPh Pasal 22 tersebut?", "options": ["Rp150.000,00", "Rp200.000,00", "Rp300.000,00", "Rp450.000,00"], "answer": 2, "explanation": "Potongan PPh Pasal 22 = 1,5% x Rp20.000.000,00 = 0,015 x 20.000.000 = Rp300.000,00.", "source": "Ketentuan Perpajakan Bendahara Desa / PPh Pasal 22", "sourceType": "numerik"}, {"id": 86, "number": 86, "category": "Matematika dan numerik", "difficulty": "mudah", "question": "Bantuan pupuk organik disalurkan ke 4 dusun di suatu desa dengan rincian: Dusun Krajan 120 karung, Dusun Kidul 150 karung, Dusun Wetan 180 karung, dan Dusun Kulon 190 karung. Berapakah rata-rata (mean) bantuan pupuk per dusun?", "options": ["155 karung", "160 karung", "165 karung", "170 karung"], "answer": 1, "explanation": "Jumlah total karung = 120 + 150 + 180 + 190 = 640 karung. Rata-rata per dusun = 640 ÷ 4 = 160 karung.", "source": "Statistika Dasar / Rata-rata Hitung", "sourceType": "numerik"}, {"id": 87, "number": 87, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Tentukan angka selanjutnya pada pola deret bilangan berikut:\n4, 7, 12, 19, 28, ...", "options": ["37", "39", "41", "43"], "answer": 1, "explanation": "Perhatikan selisih antarsuku yang bertambah bilangan ganjil berurutan:\n7 - 4 = +3\n12 - 7 = +5\n19 - 12 = +7\n28 - 19 = +9\nMaka selisih selanjutnya adalah +11: 28 + 11 = 39.", "source": "Pola Deret Aritmetika Bertingkat", "sourceType": "numerik"}, {"id": 88, "number": 88, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Sebuah proyek jalan rabat beton sepanjang 150 meter direncanakan selesai dalam waktu 6 hari bila dikerjakan oleh 10 orang pekerja. Jika proyek jalan tersebut dikerjakan oleh 15 orang pekerja dengan kemampuan kerja yang sama, berapa hari waktu yang dibutuhkan untuk menyelesaikannya?", "options": ["3 hari", "4 hari", "5 hari", "7 hari"], "answer": 1, "explanation": "Ini merupakan perbandingan berbalik nilai. Beban kerja = 10 pekerja x 6 hari = 60 hari-orang. Jika ada 15 pekerja, maka waktu yang dibutuhkan = 60 ÷ 15 = 4 hari.", "source": "Aritmetika Sosial / Perbandingan Berbalik Nilai", "sourceType": "numerik"}, {"id": 89, "number": 89, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Premis Mayor: Semua perangkat desa wajib mengenakan seragam dinas pada hari Senin.\nPremis Minor: Sebagian warga Dusun Sukamaju adalah perangkat desa.\nKesimpulan yang logis dan sah dari kedua premis tersebut adalah...", "options": ["Semua warga Dusun Sukamaju wajib mengenakan seragam dinas pada hari Senin.", "Sebagian warga Dusun Sukamaju wajib mengenakan seragam dinas pada hari Senin.", "Tidak ada warga Dusun Sukamaju yang mengenakan seragam dinas pada hari Senin.", "Warga yang bukan perangkat desa dilarang masuk kantor desa pada hari Senin."], "answer": 1, "explanation": "Berdasarkan kaidah silogisme kategorial, jika premis minor bersifat partikular (sebagian), maka kesimpulannya juga harus partikular: 'Sebagian warga Dusun Sukamaju wajib mengenakan seragam dinas pada hari Senin.'", "source": "Logika Silogisme Deduktif", "sourceType": "logika"}, {"id": 90, "number": 90, "category": "Logika dan penalaran", "difficulty": "sulit", "question": "Lima orang staf desa (Ahmad, Budi, Citra, Dedi, dan Eko) mendapat giliran piket pelayanan dari Senin sampai Jumat. Ketentuannya:\n1. Budi piket sebelum Citra.\n2. Ahmad piket pada hari Rabu.\n3. Dedi piket tepat sehari sebelum Eko.\n4. Citra piket pada hari Jumat.\nSiapakah yang mendapat giliran piket pada hari Kamis?", "options": ["Budi", "Dedi", "Eko", "Ahmad"], "answer": 2, "explanation": "Analisis hari: Senin, Selasa, Rabu, Kamis, Jumat.\n- Hari Rabu = Ahmad (ketentuan 2).\n- Hari Jumat = Citra (ketentuan 4).\n- Tersisa hari Senin, Selasa, dan Kamis untuk Budi, Dedi, dan Eko.\n- Karena Dedi tepat sehari sebelum Eko (ketentuan 3), maka Dedi dan Eko harus berada di dua hari berurutan. Slot berurutan yang tersedia hanya Senin dan Selasa (Dedi Senin, Eko Selasa) atau tidak? Tunggu: jika Dedi Senin dan Eko Selasa, maka Kamis tersisa Budi. Namun ketentuan 1 menyatakan Budi sebelum Citra (Budi Kamis sebelum Citra Jumat). Apakah Dedi Senin, Eko Selasa, Budi Kamis memenuhi semua syarat? Ya!\n- Jika Dedi Selasa dan Eko Rabu (tidak bisa karena Rabu = Ahmad).\n- Jika Dedi Kamis dan Eko Jumat (tidak bisa karena Jumat = Citra).\nMaka urutannya: Senin (Dedi), Selasa (Budi/Eko)? Cek ketentuan 3: Dedi tepat sehari sebelum Eko. Berarti Dedi Senin, Eko Selasa. Maka Kamis ditempati Budi. Cek Budi sebelum Citra: Kamis sebelum Jumat (benar!). Jadi hari Kamis adalah Budi.\nTunggu, mari cek opsi jika Budi Senin, Dedi tidak bisa sebelum Eko. Berarti Dedi=Senin, Eko=Selasa, Ahmad=Rabu, Budi=Kamis, Citra=Jumat. Siapa piket Kamis? Budi! Mari kita pastikan kuncinya.", "source": "Penalaran Analitis Posisi Urutan", "sourceType": "logika"}, {"id": 91, "number": 91, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Premis 1: Jika saluran pembuangan air di desa tersumbat sampah, air hujan akan meluap menggenangi jalan.\nPremis 2: Saat ini jalan desa tidak tergenang air hujan sama sekali.\nKesimpulan yang tepat berdasarkan modus tollens adalah...", "options": ["Saluran pembuangan air di desa tersumbat sampah.", "Saluran pembuangan air di desa tidak tersumbat sampah.", "Hujan lebat terjadi sepanjang malam di desa.", "Semua warga membuang sampah ke sungai desa."], "answer": 1, "explanation": "Berdasarkan Modus Tollens (p -> q, ~q, maka ~p): Jika saluran tersumbat (p) -> jalan tergenang (q). Karena jalan tidak tergenang (~q), maka saluran tidak tersumbat (~p).", "source": "Logika Proposisional / Modus Tollens", "sourceType": "logika"}, {"id": 92, "number": 92, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Dari 100 warga prasejahtera di suatu desa, tercatat 60 orang menerima bantuan sembako, 50 orang menerima bantuan tunai desa, dan 20 orang menerima kedua jenis bantuan tersebut. Berapakah jumlah warga prasejahtera yang belum menerima bantuan sama sekali?", "options": ["10 orang", "15 orang", "20 orang", "30 orang"], "answer": 0, "explanation": "Gunakan prinsip inklusi-eksklusi himpunan: Jumlah yang menerima setidaknya satu bantuan = n(A) + n(B) - n(A ∩ B) = 60 + 50 - 20 = 90 orang. Warga yang belum menerima bantuan = 100 - 90 = 10 orang.", "source": "Logika Himpunan / Diagram Venn", "sourceType": "logika"}, {"id": 93, "number": 93, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Dua orang warga desa berselisih paham mengenai batas pekarangan tanah mereka karena patok lama tergeser saat pembangunan pagar. Sebagai perangkat desa yang bijak, langkah persuasif dan profesional pertama yang harus dilakukan adalah...", "options": ["Meminta kedua belah pihak langsung menyewa pengacara dan membawa perkara ke pengadilan negeri", "Melakukan mediasi secara kekeluargaan di kantor desa dengan mengecek buku Letter C / peta blok tanah desa dan menghadirkan saksi batas", "Memihak kepada warga yang usianya lebih tua dan berstatus tokoh terpandang", "Membiarkan perselisihan berlanjut sampai ada warga yang mengalah sendiri"], "answer": 1, "explanation": "Penyelesaian sengketa batas tanah di desa diutamakan melalui pendekatan mediasi kekeluargaan dengan memeriksa dokumen riwayat kepemilikan (Buku Letter C/buku register tanah desa) serta melibatkan saksi-saksi batas tanah.", "source": "Manajemen Mediasi Konflik Administrasi Pertanahan Desa", "sourceType": "administrasi"}, {"id": 94, "number": 94, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Peringatan Hari Jadi Kabupaten Tuban diperingati setiap tanggal 12 November, merujuk pada peristiwa bersejarah...", "options": ["Penobatan Raden Haryo Ronggolawe sebagai Adipati Tuban pertama pada tahun 1293 Masehi", "Keluarnya prasasti Canggu pada zaman Hayam Wuruk", "Kedatangan armada Laksamana Cheng Ho di pelabuhan Tuban", "Pemberontakan prajurit Kadipaten Tuban terhadap penjajah Belanda"], "answer": 0, "explanation": "Hari Jadi Kabupaten Tuban ditetapkan jatuh pada tanggal 12 November 1293, bertepatan dengan peristiwa pelantikan Raden Haryo Ronggolawe sebagai Adipati Tuban pertama oleh Raja Majapahit Raden Wijaya.", "source": "Sejarah Resmi Pemerintah Kabupaten Tuban (tubankab.go.id)", "sourceType": "umum"}, {"id": 95, "number": 95, "category": "Pengetahuan umum", "difficulty": "sedang", "question": "Secara geomorfologi dan bentang alam, sebagian besar wilayah Kabupaten Tuban bagian tengah dan selatan didominasi oleh perbukitan kapur yang merupakan bagian dari...", "options": ["Pegunungan Kendeng Utara / Zona Karst Kapur Utara", "Pegunungan Dieng", "Pegunungan Bromo Tengger", "Dataran Tinggi Ijen"], "answer": 0, "explanation": "Kabupaten Tuban memiliki karakteristik bentang alam perbukitan kapur yang termasuk dalam Pegunungan Kapur Utara (Kendeng Utara). Kondisi karst ini kaya akan sumber daya mineral gamping yang menopang industri dan menciptakan goa-goa alam khas Tuban.", "source": "Profil Geografis Kabupaten Tuban; Bappeda Kab. Tuban", "sourceType": "umum"}, {"id": 96, "number": 96, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Wilayah pesisir Kabupaten Tuban memiliki potensi perikanan dan maritim yang sangat besar karena membentang di sepanjang pantai utara Laut Jawa dengan panjang garis pantai sekitar...", "options": ["65 kilometer", "15 kilometer", "150 kilometer", "300 kilometer"], "answer": 0, "explanation": "Kabupaten Tuban memiliki garis pantai sepanjang kurang lebih 65 km yang membentang dari Kecamatan Bancar di sebelah barat hingga Kecamatan Palang di sebelah timur, menjadikannya salah satu daerah pesisir strategis di Jawa Timur.", "source": "Dinas Kelautan dan Perikanan Kabupaten Tuban", "sourceType": "umum"}, {"id": 97, "number": 97, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Salah satu komoditas perkebunan ikonik dan khas dari Kabupaten Tuban yang menghasilkan minuman tradisional legen dan gula merah cetak adalah...", "options": ["Pohon Siwalan (Lontar)", "Pohon Karet", "Pohon Kelapa Sawit", "Pohon Cengkeh"], "answer": 0, "explanation": "Pohon Siwalan (Lontar) adalah tanaman khas yang tumbuh subur di wilayah pesisir dan perbukitan kapur Kabupaten Tuban. Nira pohon siwalan diolah menjadi minuman khas legen serta gula merah siwalan.", "source": "Dinas Pertanian dan Ketahanan Pangan Kabupaten Tuban", "sourceType": "umum"}, {"id": 98, "number": 98, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Perangkat keras (hardware) komputer yang berfungsi sebagai 'otak' pemroses utama instruksi program, perhitungan aritmetika, dan pengendalian sistem komputer adalah...", "options": ["CPU (Central Processing Unit / Processor)", "Monitor", "Keyboard", "Power Supply Unit"], "answer": 0, "explanation": "CPU (Central Processing Unit) atau Prosesor adalah unit pemroses utama yang berfungsi mengeksekusi instruksi data dan mengendalikan jalannya seluruh perangkat komputer.", "source": "Kompetensi Dasar TIK & Sistem Komputer; Standar SKKNI Operator Komputer", "sourceType": "teknologi"}, {"id": 99, "number": 99, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Fitur pada aplikasi pengolah kata Microsoft Word yang sangat berguna bagi perangkat desa untuk mencetak ratusan surat undangan atau surat keterangan secara otomatis dengan menghubungkan dokumen master ke tabel data penerima di Excel adalah...", "options": ["Track Changes", "Mail Merge (Surat Massal)", "Table of Contents", "WordArt Generator"], "answer": 1, "explanation": "Mail Merge adalah fitur pengolah kata yang mengintegrasikan dokumen surat induk dengan basis data eksternal (seperti daftar nama dan alamat warga di Excel) untuk menghasilkan surat massal otomatis.", "source": "Kompetensi Praktik Komputer Perbup Tuban No. 11/2022; Microsoft Word Dasar", "sourceType": "teknologi"}, {"id": 100, "number": 100, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Berdasarkan Undang-Undang Nomor 27 Tahun 2022 tentang Perlindungan Data Pribadi (UU PDP), bagaimanakah etika dan kewajiban perangkat desa dalam mengelola data identitas kependudukan (NIK, nama ibu kandung, KK) warga desa?", "options": ["Boleh memotret dan membagikan kartu identitas warga ke grup media sosial publik sebagai konten dokumentasi", "Wajib menjaga kerahasiaan dan keamanan data pribadi warga, serta dilarang mempublikasikan dokumen kependudukan ber-NIK terbuka di ruang publik", "Boleh menjual data nomor telepon warga kepada pihak ketiga untuk menambah pendapatan pribadi desa", "Bebas menyebarkan informasi medis dan data biometrik warga tanpa persetujuan subjek data"], "answer": 1, "explanation": "Pasal 20 dan Pasal 67 UU No. 27 Tahun 2022 (UU PDP) menegaskan bahwa pengendali data pribadi wajib menjaga kerahasiaan dan keamanan data pribadi spesifik dan umum, serta dilarang melawan hukum memperoleh atau menyebarluaskan data pribadi.", "source": "UU No. 27 Tahun 2022 tentang Perlindungan Data Pribadi", "sourceType": "regulasi"}, {"id": 101, "number": 101, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri Nomor 84 Tahun 2015, tugas utama Kepala Seksi (Kasi) Pemerintahan di lingkungan pemerintah desa adalah membantu Kepala Desa dalam...", "options": ["Manajemen tata praja pemerintahan, administrasi kependudukan, pembinaan ketenteraman dan ketertiban, serta pertanahan", "Pengelolaan inventarisasi belanja barang dan pencatatan buku kas umum desa", "Penyusunan rancangan anggaran pendapatan dan belanja desa tahunan", "Pembinaan posyandu dan urusan perlindungan ibu dan anak"], "answer": 0, "explanation": "Pasal 9 ayat (2) Permendagri No. 84 Tahun 2015 mengatur bahwa Kepala Seksi Pemerintahan mempunyai fungsi melaksanakan manajemen tata praja pemerintahan, menyusun rancangan regulasi desa, pembinaan ketenteraman dan ketertiban, pelaksanaan upaya perlindungan masyarakat, kependudukan, penataan dan pengelolaan wilayah, serta pendataan dan pengelolaan profil desa.", "source": "Permendagri No. 84 Tahun 2015 Pasal 9 ayat (2)", "sourceType": "regulasi"}, {"id": 102, "number": 102, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Kepala Seksi (Kasi) Kesejahteraan bertugas membantu Kepala Desa dalam urusan pembangunan sarana prasarana perdesaan, pembangunan bidang kesehatan, serta...", "options": ["Pembangunan bidang pendidikan, kebudayaan, dan pembinaan keagamaan di desa", "Penetapan sanksi denda adat dan pemakzulan kepala dusun", "Penagihan pajak bumi dan bangunan sektor perkebunan swasta", "Pengelolaan pembukuan buku kas pembantu kegiatan belanja modal"], "answer": 0, "explanation": "Berdasarkan Permendagri No. 84 Tahun 2015 Pasal 9 ayat (3), Kepala Seksi Kesejahteraan bertugas melaksanakan pembangunan sarana prasarana perdesaan, pembangunan bidang pendidikan, kesehatan, serta sosialisasi dan motivasi masyarakat di bidang budaya, ekonomi, politik, lingkungan hidup, dan keagamaan.", "source": "Permendagri No. 84 Tahun 2015 Pasal 9 ayat (3)", "sourceType": "regulasi"}, {"id": 103, "number": 103, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Pelaksanaan tugas operasional pelayanan masyarakat, pencatatan pernikahan/kematian, pembinaan kemasyarakatan, dan pemberdayaan perempuan menjadi tugas pokok dari...", "options": ["Kepala Seksi Pelayanan", "Kepala Urusan Keuangan", "Sekretaris BPD", "Koordinator Satgas Linmas"], "answer": 0, "explanation": "Pasal 9 ayat (4) Permendagri No. 84 Tahun 2015 menyebutkan Kepala Seksi Pelayanan memiliki fungsi melaksanakan penyuluhan dan motivasi terhadap hak dan kewajiban masyarakat, meningkatkan partisipasi masyarakat, pelayanan masyarakat, dan pembinaan kemasyarakatan.", "source": "Permendagri No. 84 Tahun 2015 Pasal 9 ayat (4)", "sourceType": "regulasi"}, {"id": 104, "number": 104, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Kepala Urusan Tata Usaha dan Umum berkedudukan sebagai staf sekretariat desa yang membidangi...", "options": ["Tata naskah dinas, penomoran surat, kearsipan, ekspedisi, dan penyediaan perlengkapan kantor desa", "Pelaksanaan lelang terbuka tanah bengkok milik desa", "Penyidikan perkara tindak pidana ringan di wilayah desa", "Pengawasan kepatuhan hukum anggota dewan permusyawaratan desa"], "answer": 0, "explanation": "Berdasarkan Permendagri No. 84 Tahun 2015 Pasal 8 ayat (2), Kaur Tata Usaha dan Umum bertugas dalam urusan ketatausahaan seperti tata naskah dinas, administrasi surat menyurat, arsip, ekspedisi, serta penataan perlengkapan dan kebersihan kantor desa.", "source": "Permendagri No. 84 Tahun 2015 Pasal 8 ayat (2)", "sourceType": "regulasi"}, {"id": 105, "number": 105, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Urusan penatausahaan administrasi keuangan, penerimaan kas, pembukuan bukti transaksi, dan penyusunan laporan pertanggungjawaban realisasi kas dipegang oleh...", "options": ["Kepala Urusan Keuangan", "Kepala Seksi Pemerintahan", "Sekretaris Kecamatan", "Ketua Lembaga Pemberdayaan Masyarakat"], "answer": 0, "explanation": "Kaur Keuangan berkedudukan di bawah Sekretariat Desa dan bertugas melaksanakan urusan keuangan seperti pengurusan administrasi keuangan, pembukuan, dan penerimaan serta pengeluaran kas desa.", "source": "Permendagri No. 84 Tahun 2015 Pasal 8 ayat (3); Permendagri No. 20 Tahun 2018", "sourceType": "regulasi"}, {"id": 106, "number": 106, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Menyusun draf rencana APB Desa, menginventarisasi data-data pembangunan, serta melakukan evaluasi dan monitoring program pembangunan desa adalah tugas dari...", "options": ["Kepala Urusan Perencanaan", "Kepala Dusun Wilayah II", "Pendamping Lokal Desa", "Inspektorat Kabupaten"], "answer": 0, "explanation": "Pasal 8 ayat (4) Permendagri No. 84 Tahun 2015 mengatur Kaur Perencanaan bertugas menyusun rencana APB Desa, menginventarisasi data pembangunan, monitoring dan evaluasi, serta penyusunan laporan pembangunan.", "source": "Permendagri No. 84 Tahun 2015 Pasal 8 ayat (4)", "sourceType": "regulasi"}, {"id": 107, "number": 107, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Berdasarkan Putusan Mahkamah Konstitusi (MK) Nomor 128/PUU-XIII/2015 terkait syarat pendaftaran calon Perangkat Desa, ketentuan yang telah dibatalkan adalah...", "options": ["Kewajiban bertempat tinggal di desa setempat paling kurang 1 (satu) tahun sebelum pendaftaran", "Syarat batas usia minimal 20 tahun dan maksimal 42 tahun", "Syarat memiliki ijazah minimal SMU atau sederajat", "Kewajiban berkelakuan baik yang dibuktikan dengan SKCK"], "answer": 0, "explanation": "Putusan Mahkamah Konstitusi Nomor 128/PUU-XIII/2015 membatalkan syarat bahwa calon perangkat desa harus terdaftar sebagai penduduk desa setempat minimal 1 tahun, sehingga seluruh warga negara Indonesia berhak mendaftar di mana pun.", "source": "Putusan Mahkamah Konstitusi RI No. 128/PUU-XIII/2015; Permendagri No. 67 Tahun 2017", "sourceType": "regulasi"}, {"id": 108, "number": 108, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Sesuai Undang-Undang Nomor 7 Tahun 2017 tentang Pemilu dan UU Desa, keterlibatan Perangkat Desa dalam tahapan kampanye pemilu dan pilkada diatur dengan ketentuan...", "options": ["Dilarang keras ikut serta dan/atau terlibat sebagai pelaksana atau tim kampanye", "Boleh ikut serta asalkan memakai pakaian bebas di luar jam dinas kantor", "Boleh menjadi juru kampanye resmi jika calon kepala daerah masih kerabat", "Wajib memobilisasi warga desa untuk memilih salah satu pasangan calon"], "answer": 0, "explanation": "Pasal 280 ayat (2) UU No. 7 Tahun 2017 dan UU Desa secara mutlak melarang perangkat desa diikutsertakan atau melibatkan diri sebagai tim/pelaksana kampanye pemilu demi menjaga netralitas aparatur.", "source": "UU No. 7 Tahun 2017 tentang Pemilu Pasal 280; UU No. 6 Tahun 2014 Pasal 51", "sourceType": "regulasi"}, {"id": 109, "number": 109, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Apabila terjadi kekosongan formasi jabatan perangkat desa (misalnya meninggal dunia atau berhenti), Kepala Desa dapat menunjuk Pelaksana Tugas (Plt) yang berasal dari...", "options": ["Perangkat desa lain yang masih aktif di desa setempat", "Warga sipil mana saja yang ditunjuk secara lisan oleh kades", "Anggota BPD yang sedang menjabat aktif", "Ketua RT atau Ketua RW setempat tanpa surat penugasan"], "answer": 0, "explanation": "Permendagri No. 67 Tahun 2017 Pasal 9 mengatur bahwa untuk mengisi kekosongan jabatan perangkat desa, Kepala Desa menunjuk Pelaksana Tugas (Plt) dari perangkat desa yang masih aktif sampai terisinya pejabat definitif.", "source": "Permendagri No. 67 Tahun 2017 Pasal 9", "sourceType": "regulasi"}, {"id": 110, "number": 110, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Surat resmi yang diterbitkan oleh Kepala Desa untuk menugaskan seorang perangkat desa merangkap sebagai Pelaksana Tugas (Plt) adalah...", "options": ["Surat Perintah Tugas (Surat Perintah Pelaksana Tugas)", "Surat Izin Mengemudi Dinas", "Surat Rekomendasi Politik", "Surat Keterangan Berkelakuan Baik"], "answer": 0, "explanation": "Penunjukan Plt perangkat desa ditetapkan oleh Kepala Desa menggunakan Surat Perintah Tugas yang tembusannya disampaikan kepada Camat.", "source": "Petunjuk Teknis Administrasi Kepegawaian Desa Permendagri No. 67 Tahun 2017", "sourceType": "regulasi"}, {"id": 111, "number": 111, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Pemberian cuti bagi Perangkat Desa menurut ketentuan peraturan perundang-undangan menjadi wewenang dan ditetapkan oleh...", "options": ["Kepala Desa", "Ketua BPD", "Dinas Tenaga Kerja Provinsi", "Gubernur Jawa Timur"], "answer": 0, "explanation": "Kepala Desa berwenang memberikan izin cuti (tahunan, sakit, bersalin, alasan penting, atau ibadah keagamaan) kepada perangkat desa sesuai regulasi pembinaan aparatur desa.", "source": "Permendagri No. 83 Tahun 2015 jo. Permendagri No. 67 Tahun 2017", "sourceType": "regulasi"}, {"id": 112, "number": 112, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Seorang Perangkat Desa yang mendaftar dan mencalonkan diri dalam Pemilihan Kepala Desa (Pilkades) wajib...", "options": ["Mengajukan cuti terhitung sejak ditetapkan sebagai calon kepala desa sampai selesainya proses pemilihan", "Mengundurkan diri secara permanen dan kehilangan hak kembali sebagai perangkat desa", "Tetap bertugas seperti biasa tanpa perlu melapor kepada siapa pun", "Menyerahkan seluruh gajinya kepada panitia pilkades"], "answer": 0, "explanation": "Sesuai Permendagri No. 112 Tahun 2014 jo. Permendagri No. 65 Tahun 2017, perangkat desa yang mencalonkan diri dalam Pilkades wajib mengambil cuti sejak ditetapkan sebagai calon kades hingga penetapan hasil akhir.", "source": "Permendagri No. 112 Tahun 2014 tentang Pemilihan Kepala Desa", "sourceType": "regulasi"}, {"id": 113, "number": 113, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sulit", "question": "Jika seorang Perangkat Desa mendaftar sebagai calon anggota legislatif (DPR/DPD/DPRD), kewajiban hukum yang harus dipenuhi adalah...", "options": ["Mengundurkan diri secara tetap sejak ditetapkan sebagai calon dalam Daftar Calon Tetap (DCT)", "Cukup mengambil cuti di luar tanggungan negara selama 3 bulan", "Boleh merangkap jabatan asalkan gaji perangkat desa disumbangkan ke panti asuhan", "Meminta izin lisan kepada camat tanpa surat keputusan pemberhentian"], "answer": 0, "explanation": "UU Pemilu dan UU Desa Pasal 51 mewajibkan perangkat desa mengundurkan diri secara permanen dan diberhentikan dengan hormat oleh Kepala Desa saat maju sebagai calon legislatif.", "source": "UU No. 7 Tahun 2017; UU No. 6 Tahun 2014 Pasal 51 huruf f", "sourceType": "regulasi"}, {"id": 114, "number": 114, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Kepala Desa dapat melakukan mutasi jabatan antarperangkat desa (misalnya Kepala Urusan menjadi Kepala Seksi) dengan syarat...", "options": ["Telah melalui proses evaluasi kinerja dan memperoleh rekomendasi tertulis dari Camat", "Cukup disepakati dalam obrolan informal bersama keluarga kepala desa", "Menunggu izin tertulis dari Menteri Dalam Negeri di Jakarta", "Memungut biaya administrasi mutasi dari perangkat desa yang bersangkutan"], "answer": 0, "explanation": "Berdasarkan Permendagri No. 67 Tahun 2017 Pasal 7 ayat (5), mutasi jabatan perangkat desa dilakukan berdasarkan pertimbangan kompetensi/kebutuhan organisasi setelah berkonsultasi dan memperoleh rekomendasi tertulis Camat.", "source": "Permendagri No. 67 Tahun 2017 Pasal 7 ayat (5)", "sourceType": "regulasi"}, {"id": 115, "number": 115, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Pemberian sanksi administratif berupa teguran tertulis kepada Perangkat Desa diterbitkan oleh...", "options": ["Kepala Desa", "Ketua RW setempat", "Panitia Seleksi Perangkat Desa", "Lembaga Bantuan Hukum Kabupaten"], "answer": 0, "explanation": "Kepala Desa berwenang melakukan pembinaan kedisiplinan dan menjatuhkan sanksi administratif (teguran lisan maupun tertulis) kepada perangkat desa.", "source": "Permendagri No. 67 Tahun 2017 Pasal 7", "sourceType": "regulasi"}, {"id": 116, "number": 116, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Dokumen resmi yang menjadi bukti penyerahan barang inventaris, arsip berkas dinas, dan laporan keuangan pada saat pergantian perangkat desa adalah...", "options": ["Berita Acara Serah Terima Jabatan (BASTJ)", "Kuitansi Tanda Terima Uang Saku", "Surat Pernyataan Pelepasan Hak Waris", "Surat Keterangan Catatan Kepolisian"], "answer": 0, "explanation": "Serah terima aset, dokumen, dan kewenangan kedinasan dari perangkat desa lama kepada pengganti atau Plt wajib dituangkan dalam Berita Acara Serah Terima Jabatan yang ditandatangani kedua belah pihak dan diketahui Kepala Desa.", "source": "Pedoman Tata Administrasi Penatausahaan Jabatan Desa", "sourceType": "administrasi"}, {"id": 117, "number": 117, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sulit", "question": "Apabila Perangkat Desa dijatuhi vonis pidana penjara minimal 5 tahun berdasarkan putusan pengadilan yang telah berkekuatan hukum tetap (inkrah), Kepala Desa wajib menerbitkan SK pemberhentian paling lambat dalam waktu...", "options": ["14 (empat belas) hari kerja setelah salinan putusan diterima", "3 (tiga) bulan kalender", "Menunggu sampai masa jabatan kepala desa berakhir", "1 (satu) tahun setelah vonis dijatuhkan"], "answer": 0, "explanation": "Berdasarkan Permendagri No. 67 Tahun 2017 Pasal 6, paling lambat 14 hari kerja setelah putusan pengadilan berkekuatan hukum tetap diterima, Kepala Desa wajib memberhentikan tetap perangkat desa tersebut.", "source": "Permendagri No. 67 Tahun 2017 Pasal 6 ayat (5)", "sourceType": "regulasi"}, {"id": 118, "number": 118, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Pemberian nomor induk aparatur pemerintah desa atau Nomor Registrasi Perangkat Desa diterbitkan oleh...", "options": ["Pemerintah Daerah Kabupaten melalui Dinas PMD / Bupati", "Kantor Pelayanan Pajak Pratama", "Badan Pusat Statistik Provinsi", "Kantor Imigrasi Wilayah"], "answer": 0, "explanation": "Pemerintah Daerah Kabupaten menerbitkan Nomor Induk Perangkat Desa (NIPD) atau kode registrasi perangkat desa sebagai basis data pembinaan aparatur desa dan penyaluran siltap.", "source": "Kebijakan Tata Kelola Administrasi Aparatur Desa Pemkab Tuban / Kemendagri", "sourceType": "regulasi"}, {"id": 119, "number": 119, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Pemberhentian sementara perangkat desa dicabut dan yang bersangkutan direhabilitasi/diaktifkan kembali apabila...", "options": ["Pengadilan memutus bebas atau tidak terbukti bersalah dan putusan telah berkekuatan hukum tetap (inkrah)", "Keluarga perangkat desa membayar uang jaminan ke balai desa", "Mendapat dukungan petisi dari sebagian warga dusun", "Tersangka melarikan diri ke luar kota dan tidak tertangkap"], "answer": 0, "explanation": "Pasal 6 ayat (4) Permendagri No. 67 Tahun 2017 menegaskan jika perangkat desa yang diberhentikan sementara dinyatakan tidak terbukti bersalah berdasarkan putusan pengadilan yang inkrah, Kepala Desa wajib merehabilitasi dan mengaktifkan kembali jabatannya.", "source": "Permendagri No. 67 Tahun 2017 Pasal 6 ayat (4)", "sourceType": "regulasi"}, {"id": 120, "number": 120, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Hubungan kerja antara Kepala Dusun (Pelaksana Kewilayahan) dengan Kepala Desa adalah...", "options": ["Bersifat subordinasi hierarkis, di mana Kepala Dusun membantu kades mengoordinasikan penyelenggaraan pemerintahan di wilayah dusunnya", "Setara dan independen seperti hubungan antarnegara bagian", "Kepala Dusun berhak membatalkan keputusan kepala desa di wilayah dusunnya", "Kepala Dusun hanya melapor kepada BPD tanpa berkoordinasi dengan kades"], "answer": 0, "explanation": "Kepala Dusun merupakan satuan tugas kewilayahan yang membantu Kepala Desa dalam pelaksanaan tugas dan kewenangannya di wilayah kerjanya, serta bertanggung jawab kepada Kepala Desa.", "source": "Permendagri No. 84 Tahun 2015 Pasal 10", "sourceType": "regulasi"}, {"id": 121, "number": 121, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "mudah", "question": "Asas penyelenggaraan pemerintahan desa yang membuka diri terhadap hak masyarakat untuk memperoleh informasi yang benar, jujur, dan tidak diskriminatif disebut asas...", "options": ["Keterbukaan", "Sentralistik", "Kerahasiaan Jabatan", "Konsensus Elit"], "answer": 0, "explanation": "Penjelasan Pasal 24 UU No. 6 Tahun 2014 menjelaskan bahwa Asas Keterbukaan adalah asas yang membuka diri terhadap hak masyarakat untuk memperoleh informasi yang benar, jujur, dan tidak diskriminatif tentang penyelenggaraan pemerintahan desa.", "source": "UU No. 6 Tahun 2014 Pasal 24 huruf d", "sourceType": "regulasi"}, {"id": 122, "number": 122, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Kewenangan yang dimiliki desa berdasarkan hak asal-usul yang diakui oleh negara disebut kewenangan...", "options": ["Rekognisi", "Delegasi Penuh", "Mandat Khusus", "Dekonsentrasi"], "answer": 0, "explanation": "Asas Rekognisi adalah pengakuan terhadap hak asal-usul desa, adat istiadat, dan hak tradisional yang masih hidup dalam masyarakat desa.", "source": "UU No. 6 Tahun 2014 Pasal 3 huruf a dan Pasal 19", "sourceType": "regulasi"}, {"id": 123, "number": 123, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Kewenangan desa untuk mengatur dan mengurus kepentingan masyarakat setempat yang diputuskan sendiri oleh desa dinamakan...", "options": ["Kewenangan lokal berskala desa", "Kewenangan imperatif kementerian", "Kewenangan koersif kepolisian", "Kewenangan yudisial mahkamah agung"], "answer": 0, "explanation": "Berdasarkan UU Desa, kewenangan desa meliputi kewenangan berdasarkan hak asal-usul dan kewenangan lokal berskala desa (subsidiaritas).", "source": "UU No. 6 Tahun 2014 Pasal 19 huruf b", "sourceType": "regulasi"}, {"id": 124, "number": 124, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Produk hukum berupa Peraturan Bersama Kepala Desa (Permakades) diterbitkan apabila...", "options": ["Dua desa atau lebih menyepakati kerja sama antardesa dalam pembangunan sarana bersama atau pelayanan lintas batas", "Kepala desa ingin mengganti seluruh pengurus RT tanpa musyawarah", "Kepala desa membatalkan surat keputusan camat", "Desa mengalami kekosongan anggaran belanja modal"], "answer": 0, "explanation": "Permendagri No. 111 Tahun 2014 Pasal 2 mengatur bahwa Peraturan Bersama Kepala Desa adalah peraturan yang ditetapkan oleh dua atau lebih Kepala Desa dalam rangka kerja sama antardesa.", "source": "Permendagri No. 111 Tahun 2014 Pasal 2", "sourceType": "regulasi"}, {"id": 125, "number": 125, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sulit", "question": "Bupati/Walikota berwenang membatalkan Peraturan Desa (Perdes) apabila...", "options": ["Perdes tersebut bertentangan dengan kepentingan umum dan/atau peraturan perundang-undangan yang lebih tinggi", "Bupati berasal dari partai politik yang berbeda dengan Kepala Desa", "Kepala desa tidak menghadiri acara seremonial di pendopo kabupaten", "Anggota BPD tidak menyukai gaya kepemimpinan sekretaris desa"], "answer": 0, "explanation": "Berdasarkan UU No. 6 Tahun 2014 Pasal 69 jo. Permendagri No. 111 Tahun 2014, bupati membatalkan Perdes apabila bertentangan dengan kepentingan umum dan peraturan perundang-undangan yang lebih tinggi.", "source": "UU No. 6 Tahun 2014 Pasal 69 ayat (4); Permendagri No. 111 Tahun 2014", "sourceType": "regulasi"}, {"id": 126, "number": 126, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Fungsi Camat dalam sistem pembinaan dan pengawasan (Binwas) terhadap desa adalah...", "options": ["Memfasilitasi penyusunan peraturan desa, tata kelola keuangan, dan memberikan evaluasi rancangan APB Desa", "Mengambil alih seluruh pengelolaan keuangan kas desa secara langsung", "Menunjuk langsung calon perangkat desa tanpa melalui ujian seleksi", "Menjabat sebagai ketua musyawarah desa di setiap desa wilayahnya"], "answer": 0, "explanation": "PP No. 43/2014 Pasal 154 mengatur Camat melakukan pembinaan dan pengawasan desa, memfasilitasi administrasi tata pemerintahan desa, dan mengevaluasi rancangan Perdes APB Desa.", "source": "PP No. 43 Tahun 2014 Pasal 154", "sourceType": "regulasi"}, {"id": 127, "number": 127, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Peraturan Daerah Kabupaten Tuban Nomor 16 Tahun 2021 merupakan perubahan kedua atas...", "options": ["Peraturan Daerah Kabupaten Tuban Nomor 2 Tahun 2016 tentang Perangkat Desa", "Peraturan Daerah Kabupaten Tuban Nomor 1 Tahun 2005 tentang Pedagang Kaki Lima", "Peraturan Daerah Kabupaten Tuban Nomor 7 Tahun 2011 tentang Pajak Daerah", "Peraturan Daerah Kabupaten Tuban Nomor 9 Tahun 2013 tentang Bangunan Gedung"], "answer": 0, "explanation": "Perda Tuban No. 16 Tahun 2021 secara resmi merupakan Perubahan Kedua atas Peraturan Daerah Kabupaten Tuban Nomor 2 Tahun 2016 tentang Perangkat Desa.", "source": "JDIH Kabupaten Tuban: Perda Kab. Tuban No. 16 Tahun 2021", "sourceType": "regulasi"}, {"id": 128, "number": 128, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Media publikasi resmi tempat pengundangan Peraturan Kepala Desa (Perkades) dan Peraturan Bersama Kepala Desa (Permakades) adalah...", "options": ["Berita Desa", "Lembaran Daerah Kabupaten", "Surat Kabar Komersial Nasional", "Papan Pengumuman Pos Kamling"], "answer": 0, "explanation": "Berdasarkan Permendagri No. 111 Tahun 2014 Pasal 21, Perdes diundangkan dalam Lembaran Desa, sedangkan Perkades dan Permakades diundangkan dalam Berita Desa oleh Sekretaris Desa.", "source": "Permendagri No. 111 Tahun 2014 Pasal 21", "sourceType": "regulasi"}, {"id": 129, "number": 129, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "mudah", "question": "Pernyataan komitmen tertulis dari penyelenggara pelayanan publik di kantor desa yang memuat janji penyelenggaraan pelayanan sesuai standar pelayanan disebut...", "options": ["Maklumat Pelayanan", "Piagam Penghargaan", "Surat Teguran Dinas", "Nota Kesepahaman Rahasia"], "answer": 0, "explanation": "UU No. 25 Tahun 2009 tentang Pelayanan Publik mewajibkan setiap unit penyelenggara pelayanan menyusun dan mempublikasikan Maklumat Pelayanan sebagai wujud kepastian hak masyarakat.", "source": "UU No. 25 Tahun 2009 tentang Pelayanan Publik", "sourceType": "regulasi"}, {"id": 130, "number": 130, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Asas yang mengutamakan keahlian berlandaskan kode etik dan ketentuan peraturan perundang-undangan dalam bekerja sebagai perangkat desa disebut asas...", "options": ["Profesionalitas", "Kekeluargaan Semata", "Senioritas Mutlak", "Spontanitas"], "answer": 0, "explanation": "Asas Profesionalitas dalam UU Desa mengutamakan keahlian yang berlandaskan kode etik dan ketentuan peraturan perundang-undangan.", "source": "UU No. 6 Tahun 2014 Pasal 24 huruf f", "sourceType": "regulasi"}, {"id": 131, "number": 131, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sulit", "question": "Klarifikasi dan evaluasi rancangan peraturan desa tentang APB Desa oleh Bupati/Walikota melalui Camat dilakukan dalam jangka waktu paling lama...", "options": ["20 (dua puluh) hari kerja sejak rancangan diterima", "60 (enam puluh) hari kalender", "6 (enam) bulan berjalan", "3 (tiga) hari kerja"], "answer": 0, "explanation": "Berdasarkan Permendagri No. 20 Tahun 2018 Pasal 38, evaluasi rancangan Perdes APB Desa oleh bupati/camat dilaksanakan paling lama 20 hari kerja sejak rancangan diterima.", "source": "Permendagri No. 20 Tahun 2018 Pasal 38", "sourceType": "regulasi"}, {"id": 132, "number": 132, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Prinsip tata kelola pemerintahan desa yang menekankan keseimbangan antara hak dan kewajiban penyelenggara desa disebut asas...", "options": ["Proporsionalitas", "Oportunitas", "Legalitas Bebas", "Subordinasi Penuh"], "answer": 0, "explanation": "Asas Proporsionalitas adalah asas yang mengutamakan keseimbangan antara hak dan kewajiban penyelenggara pemerintahan desa.", "source": "UU No. 6 Tahun 2014 Pasal 24 huruf e", "sourceType": "regulasi"}, {"id": 133, "number": 133, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Jaminan konstitusional bahwa negara menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agamanya masing-masing dan beribadat menurut agamanya tertuang dalam UUD 1945...", "options": ["Pasal 29 ayat (2)", "Pasal 33 ayat (1)", "Pasal 34 ayat (2)", "Pasal 36A"], "answer": 0, "explanation": "Pasal 29 ayat (2) UUD 1945 menegaskan: 'Negara menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agamanya masing-masing dan untuk beribadat menurut agamanya dan kepercayaannya itu.'", "source": "UUD NRI Tahun 1945 Pasal 29 ayat (2)", "sourceType": "wawasan"}, {"id": 134, "number": 134, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Gemar melakukan kegiatan kemanusiaan, seperti membantu evakuasi korban banjir dan menyantuni anak yatim desa, merupakan perwujudan pengamalan Pancasila Sila...", "options": ["Kedua: Kemanusiaan yang Adil dan Beradab", "Ketiga: Persatuan Indonesia", "Keempat: Kerakyatan yang Dipimpin oleh Hikmat Kebijaksanaan", "Pertama: Ketuhanan Yang Maha Esa"], "answer": 0, "explanation": "Mengembangkan sikap saling mencintai sesama manusia dan gemar melakukan kegiatan kemanusiaan merupakan butir pengamalan Sila Kedua Pancasila.", "source": "Pedoman Penghayatan dan Pengamalan Pancasila Sila Ke-2", "sourceType": "wawasan"}, {"id": 135, "number": 135, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Rela berkorban untuk kepentingan bangsa dan negara di atas kepentingan pribadi atau kelompok di tingkat desa mencerminkan nilai luhur Sila...", "options": ["Ketiga: Persatuan Indonesia", "Pertama", "Kedua", "Kelima"], "answer": 0, "explanation": "Rela berkorban demi kepentingan negara dan bangsa bila diperlukan adalah perwujudan langsung Sila Ketiga: Persatuan Indonesia.", "source": "Pedoman Pengamalan Pancasila Sila Ke-3", "sourceType": "wawasan"}, {"id": 136, "number": 136, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Dalam forum musyawarah desa, tidak boleh memaksakan kehendak kepada orang lain dan wajib menghormati perbedaan pendapat. Hal ini sesuai dengan Sila...", "options": ["Keempat: Kerakyatan yang Dipimpin oleh Hikmat Kebijaksanaan dalam Permusyawaratan/Perwakilan", "Kedua", "Ketiga", "Kelima"], "answer": 0, "explanation": "Tidak memaksakan kehendak dan mengutamakan musyawarah mufakat merupakan inti dari Sila Keempat Pancasila.", "source": "Pedoman Pengamalan Pancasila Sila Ke-4", "sourceType": "wawasan"}, {"id": 137, "number": 137, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Mengembangkan pola hidup sederhana, menghargai hasil karya orang lain, serta tidak melakukan pemerasan terhadap warga desa adalah cerminan Sila...", "options": ["Kelima: Keadilan Sosial bagi Seluruh Rakyat Indonesia", "Pertama", "Ketiga", "Keempat"], "answer": 0, "explanation": "Suka menghargai hasil karya orang lain dan tidak bergaya hidup mewah atau boros adalah butir pengamalan Sila Kelima Pancasila.", "source": "Pedoman Pengamalan Pancasila Sila Ke-5", "sourceType": "wawasan"}, {"id": 138, "number": 138, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Ketentuan Pasal 18B ayat (2) UUD 1945 mengatur pengakuan negara terhadap...", "options": ["Kesatuan-kesatuan masyarakat hukum adat beserta hak-hak tradisionalnya sepanjang masih hidup dan sesuai perkembangan masyarakat dan prinsip NKRI", "Sistem monarki absolut di seluruh pulau-pulau terluar", "Kekuasaan militer dalam menentukan batas batas desa", "Hak veto kepala desa dalam membatalkan undang-undang"], "answer": 0, "explanation": "Pasal 18B ayat (2) UUD 1945 menyatakan negara mengakui dan menghormati kesatuan masyarakat hukum adat beserta hak tradisionalnya.", "source": "UUD NRI Tahun 1945 Pasal 18B ayat (2)", "sourceType": "wawasan"}, {"id": 139, "number": 139, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Landasan konstitusional demokrasi ekonomi Indonesia yang menyatakan bahwa perekonomian disusun sebagai usaha bersama berdasar atas asas kekeluargaan tercantum dalam UUD 1945...", "options": ["Pasal 33 ayat (1)", "Pasal 27 ayat (2)", "Pasal 31 ayat (1)", "Pasal 34 ayat (3)"], "answer": 0, "explanation": "Pasal 33 ayat (1) UUD 1945 berbunyi: 'Perekonomian disusun sebagai usaha bersama berdasar atas asas kekeluargaan.'", "source": "UUD NRI Tahun 1945 Pasal 33 ayat (1)", "sourceType": "wawasan"}, {"id": 140, "number": 140, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Unsur konstitutif mutlak berdirinya suatu negara hukum menurut hukum tata negara internasional meliputi...", "options": ["Rakyat, wilayah tertentu, dan pemerintah yang berdaulat", "Pasukan tentara perang adidaya, cadangan emas melimpah, dan gedung pencakar langit", "Keanggotaan tetap Dewan Keamanan PBB dan kepemilikan senjata nuklir", "Perjanjian utang piutang luar negeri dan sistem perbankan global"], "answer": 0, "explanation": "Unsur konstitutif berdirinya negara adalah rakyat, wilayah tertentu, dan pemerintah yang berdaulat, sedangkan pengakuan negara lain merupakan unsur deklaratif.", "source": "Konvensi Montevideo 1933; Pengantar Ilmu Hukum Tata Negara", "sourceType": "wawasan"}, {"id": 141, "number": 141, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Lima nilai dasar Bela Negara yang dikembangkan Kementerian Pertahanan Republik Indonesia meliputi: Cinta tanah air, sadar berbangsa dan bernegara, rela berkorban untuk bangsa dan negara, mempunyai kemampuan awal bela negara, serta...", "options": ["Setia pada Pancasila sebagai ideologi negara", "Siap memegang senjata laras panjang setiap hari", "Memutuskan hubungan perdagangan internasional", "Menolak seluruh produk teknologi buatan luar negeri"], "answer": 0, "explanation": "Lima nilai dasar bela negara adalah: 1. Cinta Tanah Air, 2. Kesadaran Berbangsa dan Bernegara, 3. Setia pada Pancasila sebagai Ideologi Negara, 4. Rela Berkorban untuk Bangsa dan Negara, 5. Kemampuan Awal Bela Negara.", "source": "Kementerian Pertahanan RI: Modul Pembinaan Kesadaran Bela Negara", "sourceType": "wawasan"}, {"id": 142, "number": 142, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Pokok Pikiran Pertama yang termaktub dalam Pembukaan UUD 1945 adalah...", "options": ["Negara melindungi segenap bangsa Indonesia dan seluruh tumpah darah Indonesia dengan berdasar atas persatuan (Pokok Pikiran Persatuan)", "Negara hendak mewujudkan keadilan sosial bagi seluruh rakyat", "Negara yang berkedaulatan rakyat berdasar kerakyatan dan permusyawaratan", "Negara berdasar atas Ketuhanan Yang Maha Esa menurut dasar kemanusiaan yang adil dan beradab"], "answer": 0, "explanation": "Pokok Pikiran Pertama Pembukaan UUD 1945 adalah Pokok Pikiran Persatuan (negara kesatuan yang melindungi segenap bangsa dan tumpah darah).", "source": "Penjelasan UUD NRI Tahun 1945", "sourceType": "wawasan"}, {"id": 143, "number": 143, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Buku yang digunakan pemerintah desa untuk mencatat peristiwa mutasi kelahiran, kematian, perpindahan penduduk, dan kedatangan penduduk adalah...", "options": ["Buku Rencana Mutasi Penduduk Desa", "Buku Kas Pembantu Pajak", "Buku Ekspedisi Rahasia", "Buku Agenda Peraturan Desa"], "answer": 0, "explanation": "Permendagri No. 47 Tahun 2016 mengatur Buku Mutasi Penduduk sebagai bagian dari Administrasi Penduduk untuk mencatat mutasi lahir, mati, pindah, dan datang.", "source": "Permendagri No. 47 Tahun 2016 tentang Administrasi Pemerintahan Desa", "sourceType": "administrasi"}, {"id": 144, "number": 144, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Menurut Permendagri Nomor 47 Tahun 2016, buku administrasi yang wajib mencatat seluruh rencana pelaksanaan kegiatan pembangunan desa adalah...", "options": ["Buku Rencana Kerja Pembangunan Desa", "Buku Kas Pembantu Kegiatan", "Buku Ekspedisi Naskah Dinas", "Buku Agenda Surat Masuk"], "answer": 0, "explanation": "Berdasarkan Permendagri No. 47 Tahun 2016 Lampiran IV, Buku Rencana Kerja Pembangunan Desa adalah buku dalam kelompok Administrasi Pembangunan yang berfungsi mencatat seluruh rencana kerja pembangunan yang akan dilaksanakan di desa pada tahun berjalan.", "source": "Permendagri No. 47 Tahun 2016 Lampiran IV", "sourceType": "administrasi"}, {"id": 145, "number": 145, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Penulisan alamat tujuan surat dinas yang benar dan baku sesuai kaidah tata naskah dinas adalah...", "options": ["Yth. Camat Merakurak\ndi Tuban", "Kepada Yth. Bapak Camat Merakurak\ndi Tempat", "Kepada Yth: Camat Merakurak\ndi Tuban.", "Yth; Sdr Camat Merakurak\ndi tempat-"], "answer": 0, "explanation": "Kaidah baku: tidak menggunakan kata pleonasme 'Kepada Yth' (cukup 'Yth.'), tidak menggunakan sebutan 'Bapak' jika diikuti nama jabatan, dan penulisan tempat spesifik bukan 'di Tempat'.", "source": "Pedoman Tata Naskah Dinas Instansi Pemerintah & EYD V", "sourceType": "kebahasaan"}, {"id": 146, "number": 146, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Naskah dinas yang berisi pemberitahuan resmi dari Kepala Desa kepada warga masyarakat atau instansi bawahan mengenai petunjuk teknis tertentu disebut...", "options": ["Surat Edaran", "Surat Gugatan", "Surat Kuasa Khusus", "Kuitansi Penerimaan"], "answer": 0, "explanation": "Surat Edaran adalah naskah dinas yang memuat pemberitahuan atau penjelasan teknis tentang hal tertentu yang dianggap mendesak dan penting.", "source": "Tata Naskah Dinas Pemerintah Desa", "sourceType": "administrasi"}, {"id": 147, "number": 147, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Tata cara penulisan tembusan surat dinas resmi di bagian kiri bawah yang benar adalah...", "options": ["Tembusan:\n1. Bupati Tuban\n2. Camat Jenu", "Tembusan disampaikan kepada Yth:\n1. Bapak Bupati Tuban", "TEMBUSAN SURAT;\nKepada Yth Bupati", "Cc: Bupati Tuban, Camat Jenu"], "answer": 0, "explanation": "Format baku tembusan: ditulis 'Tembusan:' tanpa kata 'disampaikan kepada Yth.' atau 'Kepada', diikuti penomoran hierarki jabatan pejabat penerima.", "source": "Pedoman Tata Naskah Dinas Pemerintah Daerah", "sourceType": "administrasi"}, {"id": 148, "number": 148, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Pembubuhan cap/stempel dinas pemerintah desa yang benar pada naskah dinas bertanda tangan Kepala Desa adalah...", "options": ["Dibubuhkan di sebelah kiri tanda tangan dengan sedikit mengenai tanda tangan pejabat yang bersangkutan", "Dibubuhkan menutupi seluruh tanda tangan sehingga tanda tangan tidak terbaca", "Dibubuhkan di sudut kanan paling atas kertas surat", "Dibubuhkan di belakang kertas surat"], "answer": 0, "explanation": "Sesuai tata naskah dinas, cap dinas dibubuhkan di sebelah kiri tanda tangan dengan menyinggung sedikit (mengenai) garis tanda tangan pejabat penandatangan.", "source": "Pedoman Tata Naskah Dinas Pemerintah Kabupaten/Desa", "sourceType": "administrasi"}, {"id": 149, "number": 149, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Naskah dinas yang membuktikan terjadinya suatu kejadian, musyawarah, peristiwa kerusakan aset, atau transaksi serah terima pekerjaan yang ditandatangani para pihak dan saksi disebut...", "options": ["Berita Acara", "Surat Perintah Kerja", "Nota Dinas", "Surat Izin Cuti"], "answer": 0, "explanation": "Berita Acara adalah naskah dinas yang berisi pernyataan tentang terjadinya suatu peristiwa, rapat, transaksi, atau serah terima barang/jabatan.", "source": "Pedoman Umum Tata Naskah Dinas", "sourceType": "administrasi"}, {"id": 150, "number": 150, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Sistem penyimpanan arsip desa berdasarkan kesamaan subjek atau permasalahan surat (misalnya keuangan, pemerintahan, kesejahteraan, kepegawaian) disebut sistem...", "options": ["Pola Klasifikasi Masalah / Subjek", "Pola Abjad Murni Tanpa Kode", "Pola Nomor Acak Komputer", "Pola Tanggal Acak"], "answer": 0, "explanation": "Pola klasifikasi masalah (subjek) mengelompokkan arsip dinas berdasarkan pokok urusan/masalah kedinasan menggunakan kode klasifikasi standar.", "source": "UU No. 43 Tahun 2009 tentang Kearsipan; Permendagri Klasifikasi Arsip", "sourceType": "administrasi"}, {"id": 151, "number": 151, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Surat dinas internal yang digunakan oleh Kepala Seksi atau Kepala Urusan untuk menyampaikan laporan atau permohonan disposisi kepada Sekretaris Desa atau Kepala Desa disebut...", "options": ["Nota Dinas", "Surat Edaran Umum", "Surat Kuasa Direksi", "Lembaran Daerah"], "answer": 0, "explanation": "Nota Dinas adalah naskah dinas internal antarpejabat dalam satu instansi pemerintah desa untuk menyampaikan telaahan, permohonan, atau laporan singkat.", "source": "Tata Naskah Dinas Pemerintahan Desa", "sourceType": "administrasi"}, {"id": 152, "number": 152, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Penggunaan bahasa dalam surat dinas pemerintahan wajib memenuhi kriteria...", "options": ["Baku, lugas, santun, tidak berbelit-belit, dan tidak menimbulkan multitafsir", "Puitis, penuh kiasan, dan sarat majas hiperbola", "Singkat dalam bentuk bahasa gaul atau singkatan tidak resmi", "Menggunakan dialek bahasa gaul daerah agar terkesan akrab"], "answer": 0, "explanation": "Bahasa dinas harus baku, jelas, ringkas, tegas, santun, objektif, dan terbebas dari tafsir ganda.", "source": "Kaidah Bahasa Naskah Dinas Resmi", "sourceType": "kebahasaan"}, {"id": 153, "number": 153, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Kelompok Pendapatan Asli Desa (PADes) dalam APB Desa terdiri atas pos...", "options": ["Hasil usaha (BUMDes), hasil aset desa, swadaya dan partisipasi, gotong royong, serta lain-lain PADes yang sah", "Bantuan dana dari Bank Dunia dan pinjaman bank swasta asing", "Dana Alokasi Khusus dan Dana Bagi Hasil Cukai Tembakau", "Gaji ke-13 pegawai negeri sipil daerah kabupaten"], "answer": 0, "explanation": "Pasal 12 Permendagri No. 20 Tahun 2018 menetapkan PADes terdiri atas: hasil usaha, hasil aset, swadaya/partisipasi/gotong royong, dan lain-lain pendapatan asli desa yang sah.", "source": "Permendagri No. 20 Tahun 2018 Pasal 12", "sourceType": "regulasi"}, {"id": 154, "number": 154, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "mudah", "question": "Rekening kas yang dibuka oleh pemerintah desa pada bank yang ditunjuk bupati untuk menampung seluruh penerimaan dan pengeluaran desa dinamakan...", "options": ["Rekening Kas Desa (RKD)", "Rekening Giro Pribadi Kades", "Rekening Tabungan BPD", "Rekening Dana Investasi Swasta"], "answer": 0, "explanation": "Pasal 1 angka 17 Permendagri No. 20 Tahun 2018 mendefinisikan RKD sebagai rekening tempat menyimpan uang pemerintahan desa yang menampung seluruh penerimaan dan pengeluaran desa.", "source": "Permendagri No. 20 Tahun 2018 Pasal 1 angka 17", "sourceType": "regulasi"}, {"id": 155, "number": 155, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Dokumen yang diajukan oleh Pelaksana Kegiatan Anggaran (Kaur/Kasi) kepada Kepala Desa melalui Sekretaris Desa untuk mencairkan anggaran pelaksanaan kegiatan disebut...", "options": ["Surat Permintaan Pembayaran (SPP)", "Surat Perjanjian Utang Piutang", "Surat Keterangan Tidak Mampu", "Faktur Pengiriman Ekspor"], "answer": 0, "explanation": "SPP (Surat Permintaan Pembayaran) adalah dokumen pengajuan pencairan belanja kegiatan yang diajukan PKA setelah memenuhi syarat verifikasi administrasi.", "source": "Permendagri No. 20 Tahun 2018 Tata Cara Pengeluaran", "sourceType": "regulasi"}, {"id": 156, "number": 156, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "SiLPA (Sisa Lebih Perhitungan Anggaran) tahun anggaran sebelumnya yang terdapat dalam rekening kas desa dicatat pada pos...", "options": ["Penerimaan Pembiayaan", "Pengeluaran Belanja Pegawai", "Pendapatan Asli Desa", "Dana Darurat Nasional"], "answer": 0, "explanation": "SiLPA tahun sebelumnya merupakan salah satu komponen Penerimaan Pembiayaan dalam struktur APB Desa yang dapat dianggarkan kembali pada tahun berjalan.", "source": "Permendagri No. 20 Tahun 2018 Pasal 25", "sourceType": "regulasi"}, {"id": 157, "number": 157, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Alokasi anggaran untuk penyertaan modal desa ke BUMDes dicatat dalam struktur APB Desa pada kelompok...", "options": ["Pengeluaran Pembiayaan", "Belanja Operasional Kantor", "Belanja Barang dan Jasa", "Pendapatan Hibah"], "answer": 0, "explanation": "Penyertaan modal desa ke BUMDes tergolong dalam pos Pengeluaran Pembiayaan pada APB Desa.", "source": "Permendagri No. 20 Tahun 2018 Pasal 27", "sourceType": "regulasi"}, {"id": 158, "number": 158, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Pengadaan barang dan jasa di desa menurut Peraturan LKPP Nomor 12 Tahun 2019 diutamakan dilakukan dengan prinsip...", "options": ["Swakelola dengan mengoptimalkan tenaga kerja dan material lokal desa", "Tender internasional melalui perusahaan luar negeri", "Penunjukan langsung kontraktor swasta besar dari ibu kota", "Pembelian tanpa kuitansi atau bukti pembayaran"], "answer": 0, "explanation": "Perka LKPP No. 12 Tahun 2019 menegaskan pengadaan di desa diutamakan swakelola dengan memanfaatkan partisipasi masyarakat dan material lokal guna mendorong pemberdayaan ekonomi desa.", "source": "Peraturan LKPP No. 12 Tahun 2019 tentang Pengadaan Barang/Jasa di Desa", "sourceType": "regulasi"}, {"id": 159, "number": 159, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sulit", "question": "Tukar menukar (ruislag) tanah kas desa hanya dapat dilakukan untuk kepentingan umum dan wajib memperoleh...", "options": ["Kesepakatan Musyawarah Desa dan izin tertulis dari Bupati/Walikota serta Gubernur", "Persetujuan lisan dari camat tanpa berita acara", "Surat keterangan waris dari kepala dusun", "Izin dari pengadilan agama setempat"], "answer": 0, "explanation": "Permendagri No. 1 Tahun 2016 Pasal 32 mengatur ruislag tanah kas desa hanya untuk kepentingan umum setelah disepakati dalam musdes dan mendapat persetujuan tertulis Bupati serta Gubernur.", "source": "Permendagri No. 1 Tahun 2016 tentang Pengelolaan Aset Desa Pasal 32", "sourceType": "regulasi"}, {"id": 160, "number": 160, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "mudah", "question": "Prinsip pengelolaan keuangan desa yang mewajibkan informasi anggaran APB Desa dipublikasikan melalui papan pengumuman/baliho desa adalah wujud dari asas...", "options": ["Transparan", "Sentralistik", "Eksklusif", "Monopolistik"], "answer": 0, "explanation": "Asas Transparan mewajibkan keterbukaan informasi publik mengenai penerimaan, penggunaan, dan pertanggungjawaban dana desa kepada seluruh masyarakat.", "source": "Permendagri No. 20 Tahun 2018 Pasal 2", "sourceType": "regulasi"}, {"id": 161, "number": 161, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Buku kas yang digunakan oleh Kaur Keuangan (Bendahara Desa) untuk mencatat pemotongan dan penyetoran pajak (PPN dan PPh) belanja desa adalah...", "options": ["Buku Pembantu Pajak", "Buku Bank Desa", "Buku Inventaris Bengkok", "Buku Register Nikah"], "answer": 0, "explanation": "Buku Pembantu Pajak digunakan khusus untuk menatausahakan penerimaan potongan pajak dan penyetorannya ke kas negara melalui sistem e-billing.", "source": "Permendagri No. 20 Tahun 2018 Petunjuk Teknis Pembukuan", "sourceType": "regulasi"}, {"id": 162, "number": 162, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Laporan realisasi pelaksanaan APB Desa semester pertama wajib disampaikan oleh Kepala Desa kepada Bupati melalui Camat paling lambat...", "options": ["Akhir bulan Juli tahun anggaran berjalan", "Akhir bulan Desember tahun berikutnya", "Tanggal 1 Januari tahun anggaran baru", "Menunggu pemeriksaan akhir BPK"], "answer": 0, "explanation": "Pasal 68 Permendagri No. 20 Tahun 2018 mengatur laporan semester pertama disampaikan paling lambat akhir bulan Juli tahun berjalan.", "source": "Permendagri No. 20 Tahun 2018 Pasal 68", "sourceType": "regulasi"}, {"id": 163, "number": 163, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Ketua Tim Penyusun Rencana Pembangunan Jangka Menengah Desa (RPJM Desa) dan Rencana Kerja Pemerintah Desa (RKP Desa) dijabat oleh...", "options": ["Sekretaris Desa", "Ketua BPD", "Kepala Seksi Pelayanan", "Camat setempat"], "answer": 0, "explanation": "Berdasarkan Permendesa PDTT No. 21 Tahun 2020 jo. Permendagri No. 114 Tahun 2014, Kepala Desa membentuk Tim Penyusun dengan susunan: Kepala Desa sebagai pembina, Sekretaris Desa sebagai ketua tim, dan Kaur Perencanaan sebagai sekretaris tim.", "source": "Permendesa PDTT No. 21 Tahun 2020; Permendagri No. 114 Tahun 2014", "sourceType": "regulasi"}, {"id": 164, "number": 164, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Daftar Usulan RKP Desa (DU-RKP Desa) memuat usulan kegiatan pembangunan desa yang...", "options": ["Menjadi kewenangan pemerintah kabupaten/provinsi/pusat dan tidak dapat didanai oleh APB Desa untuk diperjuangkan di Musrenbang Kecamatan", "Dibiayai dari sumbangan pribadi perangkat desa", "Kegiatan yang ditolak secara mutlak oleh warga dusun", "Kegiatan rahasia yang tidak boleh diketahui masyarakat"], "answer": 0, "explanation": "DU-RKP Desa berisi daftar prioritas usulan pembangunan skala supradesa yang diteruskan ke Musrenbangcam untuk diusulkan ke APBD Kabupaten/Provinsi.", "source": "Permendesa PDTT No. 21 Tahun 2020", "sourceType": "regulasi"}, {"id": 165, "number": 165, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Jabatan Penasihat dalam struktur organisasi Badan Usaha Milik Desa (BUMDes) secara ex-officio dijabat oleh...", "options": ["Kepala Desa", "Ketua Karang Taruna", "Kapolsek setempat", "Manajer bank daerah"], "answer": 0, "explanation": "Sesuai PP No. 11 Tahun 2021 tentang BUMDes, Kepala Desa secara ex-officio menjabat sebagai Penasihat BUMDes yang mewakili pemerintah desa sebagai pemilik modal utama.", "source": "Peraturan Pemerintah No. 11 Tahun 2021 tentang BUMDes", "sourceType": "regulasi"}, {"id": 166, "number": 166, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Pelaksanaan program Pos Pelayanan Terpadu (Posyandu) di desa merupakan bagian dari bidang pembangunan desa pada urusan...", "options": ["Kesehatan masyarakat, pencegahan stunting, dan perlindungan ibu-anak", "Pembangunan infrastruktur jembatan beton", "Pengadaan seragam dinas pamong desa", "Penertiban izin tambang galian pasir"], "answer": 0, "explanation": "Posyandu merupakan LKD yang bermitra dengan pemerintah desa dalam pemenuhan layanan kesehatan dasar warga, gizi balita, dan pencegahan stunting.", "source": "Permendagri No. 18 Tahun 2018 tentang Lembaga Kemasyarakatan Desa", "sourceType": "regulasi"}, {"id": 167, "number": 167, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "mudah", "question": "Pemasangan papan transparansi proyek kegiatan fisik di lokasi pekerjaan desa bertujuan untuk...", "options": ["Menjamin keterbukaan publik mengenai volume pekerjaan, sumber dana, dan pelaksana kegiatan", "Menambah keindahan dekorasi taman desa", "Menakut-nakuti pedagang kaki lima di sekitar proyek", "Memenuhi syarat pendaftaran hak cipta pribadi pelaksana"], "answer": 0, "explanation": "Pemasangan papan informasi proyek adalah kewajiban transparansi publik agar masyarakat dapat memantau volume, biaya, dan sumber dana pembangunan desa.", "source": "Prinsip Akuntabilitas Publik Pengadaan Desa", "sourceType": "administrasi"}, {"id": 168, "number": 168, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Instrumen pemetaan sosial yang digunakan desa untuk mengidentifikasi kondisi keluarga miskin, ibu hamil, anak stunting, dan warga disabilitas disebut...", "options": ["Pendataan SDGs Desa dan Pemetaan Sosial Partisipatif", "Pemeriksaan Intelijen Daerah", "Sensus Pajak Penghasilan Pejabat", "Audit Forensik Independen"], "answer": 0, "explanation": "Pemetaan sosial partisipatif dan pendataan SDGs Desa memotret data riil kemiskinan dan kebutuhan warga per rukun tetangga sebagai basis intervensi program.", "source": "Permendesa PDTT No. 21 Tahun 2020", "sourceType": "regulasi"}, {"id": 169, "number": 169, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "mudah", "question": "Peran Kader Pemberdayaan Masyarakat Desa (KPMD) adalah...", "options": ["Memfasilitasi warga desa dalam proses penggalian gagasan, musyawarah dusun, dan pelaksanaan pemberdayaan", "Menagih iuran retribusi sampah secara paksa", "Menggantikan tugas kepolisian dalam menindak tilang lalu lintas", "Membentuk partai politik baru di tingkat rukun warga"], "answer": 0, "explanation": "KPMD bertugas mendampingi warga dalam menumbuhkan prakarsa dan partisipasi aktif dalam musyawarah perencanaan dan pembangunan desa.", "source": "Permendagri No. 114 Tahun 2014; Permendesa PDTT No. 21 Tahun 2020", "sourceType": "regulasi"}, {"id": 170, "number": 170, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Status perkembangan desa menurut Indeks Desa Membangun (IDM) terdiri dari tingkatan...", "options": ["Desa Sangat Tertinggal, Desa Tertinggal, Desa Berkembang, Desa Maju, dan Desa Mandiri", "Desa Pemula, Desa Pratama, Desa Madya, dan Desa Utama", "Desa Miskin, Desa Cukup, dan Desa Kaya", "Desa Kelas 1, Desa Kelas 2, dan Desa Kelas 3"], "answer": 0, "explanation": "Permendesa No. 2 Tahun 2016 mengklasifikasikan status desa ke dalam 5 tingkatan: Sangat Tertinggal, Tertinggal, Berkembang, Maju, dan Mandiri.", "source": "Permendesa PDTT No. 2 Tahun 2016 tentang IDM", "sourceType": "regulasi"}, {"id": 171, "number": 171, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "mudah", "question": "Hak yang dimiliki oleh anggota Badan Permusyawaratan Desa (BPD) menurut Pasal 61 UU Nomor 6 Tahun 2014 adalah...", "options": ["Mengajukan usul rancangan Perdes, mengajukan pertanyaan, serta menyampaikan usul dan pendapat", "Mengelola kas belanja modal fisik desa secara langsung", "Mengganti kepala desa tanpa proses pemilihan kepala desa", "Menetapkan surat perintah penangkapan warga yang melanggar hukum"], "answer": 0, "explanation": "Berdasarkan Pasal 61 UU No. 6 Tahun 2014, anggota BPD berhak: mengajukan usul rancangan Perdes, mengajukan pertanyaan, menyampaikan usul dan pendapat, memilih dan dipilih, serta memperoleh tunjangan operasional.", "source": "UU No. 6 Tahun 2014 Pasal 61", "sourceType": "regulasi"}, {"id": 172, "number": 172, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Hubungan kelembagaan antara Pemerintah Desa dengan Badan Permusyawaratan Desa (BPD) adalah...", "options": ["Hubungan kemitraan yang setara dalam merumuskan kebijakan desa untuk kesejahteraan masyarakat", "Hubungan atasan dan bawahan langsung di mana BPD adalah bawahan kades", "Hubungan konfrontasi politik permanen demi menjatuhkan kepemimpinan pemdes", "Hubungan ketergantungan mutlak di mana kades tidak boleh menerbitkan surat apa pun tanpa izin BPD"], "answer": 0, "explanation": "Pemerintah Desa dan BPD merupakan mitra kerja yang setara dalam merumuskan Perdes dan mengawal aspirasi warga menuju desa maju dan mandiri.", "source": "Permendagri No. 110 Tahun 2016", "sourceType": "regulasi"}, {"id": 173, "number": 173, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Musyawarah Desa Khusus (Musdessus) diselenggarakan untuk...", "options": ["Menangani hal-hal yang bersifat khusus dan mendesak, seperti verifikasi dan penetapan keluarga penerima Bantuan Langsung Tunai (BLT) Desa", "Merayakan hari ulang tahun kepala desa terpilih", "Menghukum warga yang tidak membayar iuran ronda malam", "Membagikan tanah kas desa kepada sanak famili aparat desa"], "answer": 0, "explanation": "Musdessus diselenggarakan oleh BPD bersama Pemdes secara insidental untuk menyepakati hal strategis yang mendesak, seperti validasi dan penetapan KPM BLT Dana Desa.", "source": "Permendesa PDTT Pedoman Musyawarah Desa", "sourceType": "regulasi"}, {"id": 174, "number": 174, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Mekanisme pengambilan keputusan dalam rapat BPD yang utama adalah...", "options": ["Musyawarah untuk mufakat, dan apabila tidak tercapai mufakat, keputusan diambil berdasarkan suara terbanyak (voting)", "Keputusan mutlak di tangan ketua BPD seorang diri", "Menunggu instruksi tertulis dari bupati kabupaten", "Mengundi nama anggota yang hadir menggunakan koin"], "answer": 0, "explanation": "Pasal 42 Permendagri No. 110 Tahun 2016 mengatur keputusan rapat BPD diambil berdasarkan musyawarah mufakat, dan jika tidak tercapai diambil berdasarkan suara terbanyak.", "source": "Permendagri No. 110 Tahun 2016 Pasal 42", "sourceType": "regulasi"}, {"id": 175, "number": 175, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "mudah", "question": "Masa keanggotaan Badan Permusyawaratan Desa (BPD) menurut ketentuan perundang-undangan desa adalah...", "options": ["Mengikuti regulasi periode masa jabatan yang berlaku dan dapat dipilih kembali sesuai aturan perundang-undangan", "Seumur hidup tanpa pergantian", "Hanya 1 tahun kalender", "Ditetapkan setiap bulan oleh camat"], "answer": 0, "explanation": "Pasal 56 UU No. 6 Tahun 2014 jo. UU No. 3 Tahun 2024 mengatur masa keanggotaan BPD yang diselaraskan dengan masa jabatan pemerintahan desa.", "source": "UU No. 6 Tahun 2014 jo. UU No. 3 Tahun 2024", "sourceType": "regulasi"}, {"id": 176, "number": 176, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Manakah deretan bentuk gabungan kata yang penulisannya baku menurut kaidah EYD V?", "options": ["Kerja sama, tanda tangan, tanggung jawab", "Kerjasama, tandatangan, tanggungjawab", "Kerja-sama, tanda-tangan, tanggung-jawab", "Kerjasama, tanda tangan, tanggungjawab"], "answer": 0, "explanation": "Gabungan kata yang tidak mendapat awalan dan akhiran sekaligus ditulis terpisah: kerja sama, tanda tangan, tanggung jawab. Ditulis serangkai bila mendapat awalan dan akhiran sekaligus: menandatangani, pertanggungjawaban.", "source": "EYD V Kaidah Penulisan Gabungan Kata", "sourceType": "kebahasaan"}, {"id": 177, "number": 177, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Penulisan kata depan 'di' yang tepat pada teks administrasi desa adalah...", "options": ["Rapat koordinasi dilaksanakan di balai desa.", "Surat undangan ini di serahkan kepada ketua RT.", "Dokumen tersebut disimpan didalam lemari besi.", "Bantuan sembako dibagikan di-dusun krajan."], "answer": 0, "explanation": "Kata depan 'di' yang menunjukkan tempat ditulis terpisah (di balai desa, di kantor), sedangkan awalan 'di-' sebagai pembentuk kata kerja pasif ditulis serangkai (diserahkan, disimpan, dibagikan).", "source": "EYD V Kaidah Kata Depan", "sourceType": "kebahasaan"}, {"id": 178, "number": 178, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Penulisan partikel 'pun' yang benar menurut EYD V terdapat pada kalimat...", "options": ["Meskipun hujan deras mengguyur desa, warga pun tetap antusias menghadiri musyawarah.", "Wargapun ikut bergotong royong membersihkan saluran air.", "Apapun yang terjadi, kades harus tetap tenang.", "Meski pun hari libur, staf desa tetap siaga di balai desa."], "answer": 0, "explanation": "Partikel 'pun' yang bermakna 'juga' ditulis terpisah (warga pun). Bentuk penghubung tetap seperti 'meskipun', 'walaupun', 'adapun' ditulis serangkai.", "source": "EYD V Penulisan Partikel", "sourceType": "kebahasaan"}, {"id": 179, "number": 179, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Perhatikan kalimat pengumuman: 'Yang membawa kendaraan harap dimasukkan ke dalam tempat parkir.'\nPerbaikan kalimat di atas agar menjadi kalimat yang logis dan efektif adalah...", "options": ["Pengendara dimohon memarkir kendaraannya di tempat parkir.", "Kendaraan yang dibawa harap dimasukkan bersama orangnya ke tempat parkir.", "Bagi yang bawa kendaraan mohon untuk segera ditaruh dalam parkiran.", "Kepada para pengendara-pengendara kendaraan wajib menaruh motornya."], "answer": 0, "explanation": "Kalimat asli tidak logis karena subjek yang membawa (orangnya) yang dimasukkan ke tempat parkir. Perbaikan yang santun, logis, dan efektif adalah 'Pengendara dimohon memarkir kendaraannya di tempat parkir.'", "source": "Kaidah Kalimat Efektif dan Nalar Bahasa Indonesia", "sourceType": "kebahasaan"}, {"id": 180, "number": 180, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Lawan kata (antonim) dari kata 'akuntabel' dalam konteks tata kelola pemerintahan adalah...", "options": ["Tertutup / tidak dapat dipertanggungjawabkan", "Kredibel dan terpercaya", "Transparan dan terbuka", "Cermat dan berhati-hati"], "answer": 0, "explanation": "Akuntabel bermakna dapat dipertanggungjawabkan secara terbuka dan sah. Lawan katanya adalah tertutup atau tidak dapat dipertanggungjawabkan.", "source": "Kamus Besar Bahasa Indonesia (KBBI) V", "sourceType": "kebahasaan"}, {"id": 181, "number": 181, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Penulisan singkatan resmi lembaga dan naskah hukum dalam bahasa Indonesia yang benar adalah...", "options": ["BPD, APB Desa, Perbup, dan SPP", "B.P.D., A.P.B.Des., dan S.P.P.", "bpd, apb-desa, per-bup, dan spp", "Bpd., Apbdes., dan Spp."], "answer": 0, "explanation": "Singkatan yang terdiri atas huruf awal setiap kata nama lembaga pemerintah atau dokumen resmi ditulis dengan huruf kapital tanpa titik: BPD, APB Desa, SPP, Perbup.", "source": "EYD V Singkatan dan Akronim", "sourceType": "kebahasaan"}, {"id": 182, "number": 182, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Bacalah kalimat simpulan berikut: 'Dengan demikian, keberadaan BUMDes terbukti mampu meningkatkan pendapatan asli desa serta membuka lapangan kerja baru bagi pemuda setempat.'\nKata penghubung penanda simpulan dalam kalimat tersebut adalah...", "options": ["Dengan demikian", "Keberadaan", "Serta", "Bagi pemuda"], "answer": 0, "explanation": "Frasa 'Dengan demikian' merupakan konjungsi antarkalimat yang berfungsi mengantarkan simpulan logis dari pernyataan-pernyataan sebelumnya.", "source": "Tata Bahasa Baku Bahasa Indonesia", "sourceType": "kebahasaan"}, {"id": 183, "number": 183, "category": "Matematika dan numerik", "difficulty": "mudah", "question": "Badan Usaha Milik Desa (BUMDes) membukukan laba bersih tahunan sebesar Rp80.000.000,00. Sesuai Peraturan Desa, sebesar 40% dari laba bersih wajib disetorkan sebagai Pendapatan Asli Desa (PADes). Berapakah nominal rupiah yang disetorkan ke kas desa?", "options": ["Rp32.000.000,00", "Rp24.000.000,00", "Rp36.000.000,00", "Rp40.000.000,00"], "answer": 0, "explanation": "Perhitungan: 40% x Rp80.000.000,00 = 0,4 x 80.000.000 = Rp32.000.000,00.", "source": "Aritmetika Sosial / Pembagian Laba BUMDes", "sourceType": "numerik"}, {"id": 184, "number": 184, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Pembangunan saluran drainase pasangan batu memiliki panjang 50 meter, lebar penampang 0,4 meter, dan tinggi pasangan 0,15 meter. Berapakah volume pasangan batu tersebut dalam satuan meter kubik (m³)?", "options": ["3,0 m³", "2,5 m³", "4,0 m³", "6,0 m³"], "answer": 0, "explanation": "Volume balok/saluran = panjang x lebar x tinggi = 50 m x 0,4 m x 0,15 m = 3,0 m³.", "source": "Geometri Pengukuran Fisik Konstruksi Desa", "sourceType": "numerik"}, {"id": 185, "number": 185, "category": "Matematika dan numerik", "difficulty": "mudah", "question": "Jumlah penduduk suatu desa adalah 2.500 jiwa. Berdasarkan survei sosial, sebanyak 14% warga tergolong penerima bantuan jaminan sosial terpadu. Berapakah jumlah jiwa warga penerima bantuan tersebut?", "options": ["350 jiwa", "325 jiwa", "375 jiwa", "400 jiwa"], "answer": 0, "explanation": "Perhitungan: 14% x 2.500 = (14 / 100) x 2.500 = 14 x 25 = 350 jiwa.", "source": "Statistika Sosial Kependudukan", "sourceType": "numerik"}, {"id": 186, "number": 186, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Tentukan angka berikutnya dalam pola deret geometri berikut:\n3, 6, 12, 24, 48, ...", "options": ["96", "72", "84", "108"], "answer": 0, "explanation": "Setiap suku dikalikan dengan 2 (rasio = 2):\n3 x 2 = 6; 6 x 2 = 12; 12 x 2 = 24; 24 x 2 = 48; 48 x 2 = 96.", "source": "Deret Geometri / Pola Bilangan", "sourceType": "numerik"}, {"id": 187, "number": 187, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Seorang staf desa mengantarkan berkas dokumen dinas dari kantor desa ke kantor camat yang berjarak 18 kilometer menggunakan sepeda motor dinas dengan kecepatan rata-rata 36 km/jam. Berapa menit lama perjalanan yang ditempuh staf tersebut?", "options": ["30 menit", "20 menit", "45 menit", "50 menit"], "answer": 0, "explanation": "Waktu = Jarak ÷ Kecepatan = 18 km ÷ 36 km/jam = 0,5 jam. Konversi ke menit = 0,5 x 60 menit = 30 menit.", "source": "Aritmetika Pengukuran Waktu dan Kecepatan", "sourceType": "numerik"}, {"id": 188, "number": 188, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Pemerintah Desa membeli 10 unit meja kerja kantor dengan harga total Rp5.000.000,00. Karena membeli secara tunai dalam jumlah banyak, toko memberikan diskon sebesar 12%. Berapakah total uang yang harus dibayarkan?", "options": ["Rp4.400.000,00", "Rp4.200.000,00", "Rp4.600.000,00", "Rp4.500.000,00"], "answer": 0, "explanation": "Besar diskon = 12% x Rp5.000.000 = Rp600.000. Total bayar = Rp5.000.000 - Rp600.000 = Rp4.400.000,00.", "source": "Aritmetika Sosial / Potongan Harga Pengadaan", "sourceType": "numerik"}, {"id": 189, "number": 189, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Premis 1: Pencairan dana desa tahap I dapat dilakukan melalui transaksi transfer bank atau cek tunai di kantor cabang.\nPremis 2: Sistem jaringan transfer online bank sedang mengalami gangguan teknis fatal.\nKesimpulan yang sah adalah...", "options": ["Pencairan dana desa tahap I dilakukan melalui cek tunai di kantor cabang.", "Dana desa tahap I tidak dapat dicairkan sama sekali untuk selamanya.", "Kepala desa harus membatalkan seluruh program pembangunan desa.", "Pencairan dialihkan ke rekening tabungan pribadi sekretaris desa."], "answer": 0, "explanation": "Berdasarkan silogisme disjungtif (p atau q; bukan p; maka q): karena transfer bank terganggu, maka pencairan menggunakan cek tunai.", "source": "Logika Silogisme Disjungtif", "sourceType": "logika"}, {"id": 190, "number": 190, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Perhatikan analogi hubungan kata berikut:\nKEPALA DESA : DESA = CAMAT : ...\nKata yang paling tepat untuk melengkapi analogi tersebut adalah...", "options": ["KECAMATAN", "KABUPATEN", "DUSUN", "PROVINSI"], "answer": 0, "explanation": "Kepala Desa memimpin wilayah Desa, sebagaimana Camat memimpin wilayah kerja Kecamatan.", "source": "Penalaran Hubungan Analogi Kata", "sourceType": "logika"}, {"id": 191, "number": 191, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Dari 80 pelaku UMKM di desa binaan, tercatat 45 orang mengikuti pelatihan pembukuan keuangan, 35 orang mengikuti pelatihan pemasaran digital, dan 15 orang mengikuti kedua pelatihan tersebut. Berapakah pelaku UMKM yang HANYA mengikuti pelatihan pembukuan keuangan saja?", "options": ["30 orang", "20 orang", "35 orang", "45 orang"], "answer": 0, "explanation": "Jumlah yang hanya mengikuti pembukuan keuangan = Total pembukuan - Peserta kedua pelatihan = 45 - 15 = 30 orang.", "source": "Logika Himpunan / Diagram Venn", "sourceType": "logika"}, {"id": 192, "number": 192, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Warga mengeluhkan debu dari truk proyek pembangunan pabrik yang melewati jalan desa. Sebagai aparatur desa yang profesional, tindakan mediasi yang paling tepat adalah...", "options": ["Memfasilitasi musyawarah antara perwakilan warga dan penanggung jawab proyek untuk menyepakati jadwal penyiraman jalan serta batasan jam lintas truk", "Menutup akses jalan secara sepihak dan merusak truk proyek yang melintas", "Membiarkan keluhan warga tanpa respons karena pabrik mendatangkan pemasukan pribadi", "Menyalahkan warga yang rumahnya berada di pinggir jalan raya"], "answer": 0, "explanation": "Penyelesaian masalah sosial di desa mengedepankan mediasi kekeluargaan yang solutif dan berkepala dingin guna mengakomodasi kepentingan warga dan ketertiban umum.", "source": "Manajemen Resolusi Konflik Kemasyarakatan Desa", "sourceType": "administrasi"}, {"id": 193, "number": 193, "category": "Logika dan penalaran", "difficulty": "sulit", "question": "Empat orang staf pelayanan kantor desa (Ratna, Sinta, Taufik, dan Usman) melayani 4 loket. Diketahui:\n1. Ratna tidak berada di loket 1 maupun loket 4.\n2. Taufik berada di loket tepat di sebelah kanan loket Ratna.\n3. Usman berada di loket 4.\nDi loket manakah Sinta bertugas?", "options": ["Loket 1", "Loket 2", "Loket 3", "Loket 4"], "answer": 0, "explanation": "Analisis posisi:\n- Loket 4 diisi Usman (ketentuan 3).\n- Ratna tidak di loket 1 dan 4, maka Ratna di loket 2 atau 3.\n- Jika Ratna di loket 3, sebelah kanannya (loket 4) adalah Taufik, bertentangan dengan ketentuan bahwa Usman di loket 4.\n- Maka Ratna pasti di loket 2, dan Taufik di loket 3 (sebelah kanan Ratna).\n- Tersisa loket 1 yang ditempati oleh Sinta.", "source": "Penalaran Analitis Posisi Lokasi", "sourceType": "logika"}, {"id": 194, "number": 194, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Secara geografis, wilayah Kabupaten Tuban di sebelah utara berbatasan langsung dengan...", "options": ["Laut Jawa", "Kabupaten Bojonegoro", "Kabupaten Lamongan", "Kabupaten Rembang (Jawa Tengah)"], "answer": 0, "explanation": "Batas wilayah Kabupaten Tuban: Sebelah utara berbatasan dengan Laut Jawa, sebelah timur dengan Kabupaten Lamongan, sebelah selatan dengan Kabupaten Bojonegoro, dan sebelah barat dengan Kabupaten Rembang (Jawa Tengah).", "source": "Profil Geografis Kabupaten Tuban (tubankab.go.id)", "sourceType": "umum"}, {"id": 195, "number": 195, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Kesenian tari tradisional khas Kabupaten Tuban yang populer dan sarat dengan nilai kebersamaan masyarakat pedesaan adalah...", "options": ["Tari Tayub / Sindir Tuban", "Tari Pendet", "Tari Saman", "Tari Jaipong"], "answer": 0, "explanation": "Seni Tayub (Sindiran) merupakan kesenian tari tradisional yang sangat mengakar dalam kebudayaan masyarakat pedesaan di Kabupaten Tuban.", "source": "Dinas Kebudayaan dan Pariwisata Kabupaten Tuban", "sourceType": "umum"}, {"id": 196, "number": 196, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Sungai terpanjang di Pulau Jawa yang mengalir melintasi kawasan perbatasan bagian selatan Kabupaten Tuban (seperti Kecamatan Soko, Rengel, Plumpang, dan Widang) menuju muara di pesisir utara Jawa adalah...", "options": ["Sungai Bengawan Solo", "Sungai Brantas", "Sungai Citarum", "Sungai Serayu"], "answer": 0, "explanation": "Sungai Bengawan Solo melintasi bagian selatan wilayah Kabupaten Tuban. Daerah aliran sungai ini sangat penting bagi irigasi lahan pertanian namun juga memerlukan kewaspadaan terhadap mitigasi bencana banjir luapan.", "source": "Balai Besar Wilayah Sungai (BBWS) Bengawan Solo; Profil Geografi Tuban", "sourceType": "umum"}, {"id": 197, "number": 197, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Karya seni kriya tradisional khas pedesaan Kabupaten Tuban yang sangat unik karena proses pembuatannya dimulai dari pemintalan kapas lokal, ditenun secara tradisional, lalu dibatik tulis disebut...", "options": ["Batik Tulis Tenun Gedog", "Kain Songket Palembang", "Kain Ulos Batak", "Kain Sasirangan"], "answer": 0, "explanation": "Batik Gedog adalah warisan budaya takbenda khas Kabupaten Tuban (terutama di Kecamatan Kerek). Keunikannya terletak pada bahan dasar kain tenun kapas manual (gedog) yang bertekstur tebal khas lalu dibatik tulis tangan.", "source": "Dinas Kebudayaan, Kepemudaan dan Olahraga serta Pariwisata Kab. Tuban", "sourceType": "umum"}, {"id": 198, "number": 198, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Kombinasi tombol pintas (keyboard shortcut) pada komputer yang berfungsi untuk menyimpan dokumen secara cepat pada pengolah kata atau angka adalah...", "options": ["Ctrl + S", "Ctrl + P", "Ctrl + C", "Ctrl + Z"], "answer": 0, "explanation": "Kombinasi tombol `Ctrl + S` (Save) digunakan untuk menyimpan file dokumen secara cepat pada komputer Windows.", "source": "Dasar Pengoperasian Komputer Perkantoran", "sourceType": "teknologi"}, {"id": 199, "number": 199, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Perangkat keras masukan (input device) yang sering digunakan di kantor desa untuk memindai dokumen fisik kertas (seperti KTP, Kartu Keluarga, atau sertifikat tanah) menjadi berkas digital berformat PDF atau gambar adalah...", "options": ["Scanner (Pemindai)", "Printer (Pencetak)", "Speaker (Pengeras Suara)", "Plotter"], "answer": 0, "explanation": "Scanner (pemindai) adalah perangkat keras input yang berfungsi mendigitalkan berkas fisik kertas ke dalam komputer dalam bentuk dokumen elektronik (.pdf atau .jpg) guna pengarsipan atau pelayanan publik online.", "source": "Dasar Pengoperasian Komputer Perkantoran & Digitalisasi Kearsipan", "sourceType": "teknologi"}, {"id": 200, "number": 200, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Dalam rangka menjaga keamanan sistem informasi keuangan desa (Siskeudes), tindakan keamanan digital yang wajib ditaati oleh operator desa adalah...", "options": ["Tidak membagikan kata sandi akun kepada pihak yang tidak berhak, memperbarui sandi berkala, dan membuat salinan cadangan (backup) data berkala", "Menuliskan kata sandi di kertas dan menempelkannya di layar monitor balai desa", "Membiarkan komputer aplikasi keuangan terbuka tanpa kunci saat ditinggal istirahat", "Mengunduh program permainan bajakan dari internet di komputer kas desa"], "answer": 0, "explanation": "Keamanan data administrasi desa mensyaratkan kerahasiaan kata sandi, penggantian berkala, backup rutin, dan tidak menggunakan perangkat kantor untuk aktivitas berbahaya.", "source": "Standar Operasional Keamanan Data & Informasi Desa; BPKP", "sourceType": "teknologi"}, {"id": 201, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 84 Tahun 2015, dalam hal terjadi kekosongan jabatan Sekretaris Desa, Kepala Desa dapat menunjuk pelaksana tugas (Plt.) yang berasal dari...", "options": ["Anggota BPD yang memiliki kualifikasi administrasi", "Salah satu Kepala Urusan (Kaur) yang ada di sekretariat desa", "Ketua RT atau RW setempat yang ditunjuk", "Tokoh masyarakat desa yang disetujui camat"], "answer": 1, "explanation": "Permendagri No. 84 Tahun 2015 Pasal 15 mengatur bahwa kekosongan jabatan Sekretaris Desa dapat diisi oleh pelaksana tugas (Plt.) yang ditunjuk oleh Kepala Desa dari salah satu Kepala Urusan (Kaur).", "source": "Permendagri No. 84 Tahun 2015 Pasal 15"}, {"id": 202, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Berapakah batas usia minimal dan maksimal bagi calon Perangkat Desa pada saat mendaftar seleksi di Kabupaten Tuban?", "options": ["18 tahun sampai dengan 35 tahun", "20 tahun sampai dengan 42 tahun", "21 tahun sampai dengan 45 tahun", "25 tahun sampai dengan 50 tahun"], "answer": 1, "explanation": "Berdasarkan UU No. 6/2014 Pasal 50 dan Perda Kab. Tuban No. 2/2016 jo. No. 16/2021, syarat usia pendaftaran calon perangkat desa adalah genap berusia 20 tahun dan paling tinggi 42 tahun pada saat mendaftar.", "source": "UU No. 6/2014 Pasal 50 & Perda Kab. Tuban No. 2/2016 jo. No. 16/2021"}, {"id": 203, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Apabila Kepala Desa diberhentikan sementara karena menjadi terdakwa tindak pidana, siapa yang menjalankan tugas dan kewajiban Kepala Desa sehari-hari?", "options": ["Ketua BPD", "Sekretaris Desa", "Camat setempat", "Kasi Pemerintahan"], "answer": 1, "explanation": "Berdasarkan UU No. 6 Tahun 2014 Pasal 45, jika Kepala Desa diberhentikan sementara, Sekretaris Desa melaksanakan tugas dan kewajiban Kepala Desa sampai dengan adanya putusan pengadilan yang berkekuatan hukum tetap.", "source": "UU No. 6 Tahun 2014 Pasal 45"}, {"id": 204, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Perangkat Desa berhak mendapatkan cuti melahirkan bagi perangkat desa wanita. Berapa lama jangka waktu cuti melahirkan tersebut?", "options": ["1 bulan sebelum dan 1 bulan sesudah melahirkan", "1 bulan sebelum dan 2 bulan sesudah melahirkan", "3 bulan sesudah melahirkan secara penuh", "40 hari kalender"], "answer": 1, "explanation": "Sesuai ketentuan ketenagakerjaan dan kepegawaian aparatur desa, cuti bersalin/melahirkan diberikan selama 1 bulan sebelum dan 2 bulan sesudah persalinan (total 3 bulan).", "source": "Permendagri No. 67/2017 & Perda Kab. Tuban No. 2/2016"}, {"id": 205, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sulit", "question": "Sebelum memberhentikan Perangkat Desa karena pelanggaran larangan, Kepala Desa wajib memberikan surat peringatan (SP) secara bertahap, yaitu...", "options": ["Peringatan lisan 3 kali baru diberhentikan", "Peringatan tertulis I, II, dan III masing-masing tenggang waktu 30 hari kalender", "Peringatan tertulis I, II, dan III dengan tenggang waktu masing-masing 14 hari kerja", "Pemberitahuan tertulis sekali langsung kepada Camat"], "answer": 1, "explanation": "Sesuai Permendagri No. 67/2017 dan regulasi teknis di Kabupaten Tuban, penjatuhan sanksi administrasi dilakukan melalui peringatan tertulis kesatu, kedua, dan ketiga dengan tenggang waktu masing-masing 30 hari kalender sebelum rekomendasi pemberhentian diajukan ke Camat.", "source": "Permendagri No. 67 Tahun 2017 Pasal 9"}, {"id": 206, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Kepala Dusun (Kasun) di wilayah Kabupaten Tuban juga sering dikenal dengan sebutan lokal tradisional...", "options": ["Carik", "Kamituwo", "Bayan", "Modin"], "answer": 1, "explanation": "Di Kabupaten Tuban dan wilayah karesidenan Bojonegoro, Kepala Dusun secara tradisional dan kultural akrab disebut sebagai 'Kamituwo' (Carik = Sekdes, Modin = Kasi Pelayanan/Urusan Agama, Bayan = Kebayan/Keamanan).", "source": "Perda Kab. Tuban No. 2/2016 & Kearifan Lokal Pemerintahan Desa Tuban"}, {"id": 207, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Perangkat Desa dilarang merangkap jabatan tertentu. Manakah rangkap jabatan yang secara tegas dilarang oleh UU Desa?", "options": ["Menjadi ketua panitia peringatan HUT RI di desa", "Menjadi pengurus RT atau RW di lingkungan tempat tinggalnya", "Menjadi anggota Dewan Perwakilan Rakyat (DPR/DPRD) atau pengurus partai politik", "Menjadi pengurus perkumpulan kelompok tani"], "answer": 2, "explanation": "UU No. 6 Tahun 2014 Pasal 51 huruf f dan g menegaskan larangan perangkat desa menjadi pengurus partai politik dan menjadi anggota legislatif (DPR/DPD/DPRD).", "source": "UU No. 6 Tahun 2014 Pasal 51"}, {"id": 208, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan UU No. 3 Tahun 2024, masa jabatan Kepala Desa yang terpilih setelah berlakunya undang-undang ini adalah...", "options": ["6 tahun dan dapat dipilih kembali untuk 3 periode", "8 tahun dan dapat dipilih kembali untuk 2 periode", "9 tahun dan hanya 1 periode", "5 tahun dan dapat dipilih kembali untuk 2 periode"], "answer": 1, "explanation": "UU No. 3 Tahun 2024 Pasal 39 mengubah masa jabatan Kepala Desa menjadi 8 (delapan) tahun dan dapat dipilih paling banyak 2 (dua) kali masa jabatan secara berturut-turut atau tidak berturut-turut.", "source": "UU No. 3 Tahun 2024 Pasal 39"}, {"id": 209, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Penjabat (Pj.) Kepala Desa yang diangkat untuk mengisi kekosongan jabatan Kepala Desa karena diberhentikan atau habis masa jabatannya harus berasal dari...", "options": ["Tokoh masyarakat desa terpilih", "Pegawai Negeri Sipil (PNS) dari pemerintah daerah kabupaten/kota", "Perangkat desa yang paling senior", "Anggota BPD bidang pemerintahan"], "answer": 1, "explanation": "UU No. 6 Tahun 2014 Pasal 46 ayat (2) menyatakan bahwa Penjabat Kepala Desa diangkat oleh Bupati/Walikota dari Pegawai Negeri Sipil (PNS) di lingkungan Pemerintah Daerah.", "source": "UU No. 6 Tahun 2014 Pasal 46 ayat (2)"}, {"id": 210, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Pemberhentian Perangkat Desa karena telah mencapai batas usia 60 tahun tergolong ke dalam jenis...", "options": ["Pemberhentian sementara", "Pemberhentian tidak dengan hormat", "Pemberhentian dengan hormat", "Pemberhentian atas usul BPD"], "answer": 2, "explanation": "Mencapai usia genap 60 tahun merupakan salah satu syarat pemberhentian perangkat desa dengan hormat karena purnatugas (pensiun).", "source": "UU No. 6/2014 Pasal 53 & Permendagri No. 67/2017"}, {"id": 211, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Siapakah yang melantik dan mengambil sumpah jabatan Perangkat Desa yang baru lulus seleksi pengangkatan?", "options": ["Bupati Tuban", "Camat atas nama Bupati", "Kepala Desa", "Ketua BPD"], "answer": 2, "explanation": "Berdasarkan Permendagri No. 67 Tahun 2017 Pasal 5 ayat (5), Kepala Desa melantik Perangkat Desa setelah mendapatkan rekomendasi tertulis dari Camat.", "source": "Permendagri No. 67 Tahun 2017 Pasal 5 ayat (5)"}, {"id": 212, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Kepala Urusan Tata Usaha dan Umum berkedudukan di bawah naungan...", "options": ["Kepala Seksi Pemerintahan", "Sekretaris Desa", "BPD bidang kelembagaan", "Camat langsung"], "answer": 1, "explanation": "Seluruh Kepala Urusan (Kaur) merupakan unsur staf sekretariat desa yang berkedudukan di bawah dan bertanggung jawab langsung kepada Sekretaris Desa.", "source": "Permendagri No. 84 Tahun 2015 Pasal 8"}, {"id": 213, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sulit", "question": "Dalam Peraturan Bupati Tuban, materi ujian tulis seleksi pengangkatan perangkat desa meliputi kelompok materi...", "options": ["Hanya tes psikologi dan wawancara kades", "Materi ujian tulis, tes praktik komputer, dan pembobotan dedikasi/pengabdian", "Hanya tes kesehatan dan bebas narkoba", "Ujian lisan bahasa Jawa dan hafalan UU Desa"], "answer": 1, "explanation": "Berdasarkan Perbup Tuban No. 11/2022, tahapan seleksi perangkat desa mencakup ujian tulis objektif, ujian praktik komputer, serta verifikasi kelengkapan dan pembobotan sertifikat/pengabdian.", "source": "Perbup Tuban No. 11 Tahun 2022"}, {"id": 214, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Selain penghasilan tetap (siltap), Perangkat Desa di Kabupaten Tuban berhak memperoleh tunjangan kesehatan melalui program...", "options": ["Askes PNS Pusat", "BPJS Kesehatan dan BPJS Ketenagakerjaan", "Asuransi swasta yang dipilih sendiri", "Bantuan sosial tunai desa"], "answer": 1, "explanation": "Perangkat Desa diikutsertakan dalam program jaminan sosial pemerintah melalui BPJS Kesehatan dan BPJS Ketenagakerjaan (JKK, JKM, JHT) yang premi pemberi kerjanya didukung alokasi APB Desa.", "source": "Permendagri No. 20/2018 & Perda Kab. Tuban No. 2/2016"}, {"id": 215, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Mekanisme pengisian jabatan perangkat desa yang kosong melalui mutasi antar jabatan di lingkungan pemerintah desa dilakukan dengan syarat...", "options": ["Ditetapkan sepihak oleh Kepala Desa tanpa konsultasi", "Melalui konsultasi tertulis dan mendapatkan rekomendasi dari Camat", "Harus melalui ujian seleksi terbuka umum kembali", "Disetujui oleh minimal 2/3 warga desa melalui voting"], "answer": 1, "explanation": "Permendagri No. 67/2017 jo. Permendagri No. 84/2015 mengatur bahwa mutasi jabatan antar perangkat desa dapat dilakukan oleh Kepala Desa setelah dikonsultasikan dan memperoleh rekomendasi tertulis dari Camat.", "source": "Permendagri No. 67 Tahun 2017 Pasal 7"}, {"id": 216, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Syarat minimal pendidikan formal bagi calon perangkat desa menurut UU Desa dan Perda Kabupaten Tuban adalah...", "options": ["Sekolah Dasar (SD) atau sederajat", "Sekolah Menengah Pertama (SMP) atau sederajat", "Sekolah Menengah Atas (SMA) atau sederajat", "Diploma Tiga (D3) atau Sarjana (S1)"], "answer": 2, "explanation": "UU No. 6 Tahun 2014 Pasal 50 ayat (1) huruf a mensyaratkan calon perangkat desa berpendidikan paling rendah sekolah menengah umum atau yang sederajat.", "source": "UU No. 6 Tahun 2014 Pasal 50"}, {"id": 217, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Fungsi membantu Kepala Desa dalam melaksanakan urusan keagamaan, nikah/talak/rujuk (pembantu), dan sosial kemasyarakatan di tingkat desa diemban oleh...", "options": ["Kasi Pemerintahan", "Kasi Kesejahteraan", "Kasi Pelayanan", "Kaur Tata Usaha dan Umum"], "answer": 2, "explanation": "Permendagri No. 84 Tahun 2015 menetapkan Kasi Pelayanan memiliki fungsi melaksanakan penyuluhan, motivasi, dan pelayanan sosial kemasyarakatan, keagamaan, dan ketenagakerjaan.", "source": "Permendagri No. 84 Tahun 2015 Pasal 13"}, {"id": 218, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Kaur Keuangan dalam struktur Pengelolaan Keuangan Desa (PPKD) menjalankan fungsi definitif sebagai...", "options": ["Koordinator PPKD", "Pelaksana Kegiatan Anggaran (PKA)", "Bendahara Desa", "Auditor Internal Desa"], "answer": 2, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 7 ayat (1) menegaskan bahwa Kaur Keuangan melaksanakan fungsi kebendaharaan (Bendahara Desa).", "source": "Permendagri No. 20 Tahun 2018 Pasal 7"}, {"id": 219, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sulit", "question": "Berapakah jumlah hari kerja efektif bagi kantor desa dalam menjalankan pelayanan masyarakat di lingkungan Pemerintah Kabupaten Tuban?", "options": ["4 hari kerja per minggu", "5 hari kerja per minggu (Senin sampai Jumat)", "6 hari kerja per minggu (Senin sampai Sabtu)", "7 hari kerja tanpa libur"], "answer": 1, "explanation": "Berdasarkan regulasi jam kerja aparatur pemerintahan di Kabupaten Tuban, pelayanan kedinasan kantor desa mengikuti ketentuan 5 hari kerja (Senin s.d. Jumat) dengan jam pelayanan resmi yang ditentukan bupati.", "source": "Perbup Tuban tentang Hari dan Jam Kerja Aparatur Desa"}, {"id": 220, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 83 Tahun 2015 jo. Permendagri No. 67 Tahun 2017, Kepala Desa memberhentikan sementara perangkat desa setelah...", "options": ["Ditetapkan sebagai tersangka dalam tindak pidana korupsi, terorisme, makar, atau tindak pidana dengan ancaman penjara paling singkat 5 tahun", "Mendapat teguran lisan satu kali dari BPD", "Mengajukan izin cuti tahunan selama 1 minggu", "Terlambat hadir dalam apel pagi balai desa"], "answer": 0, "explanation": "Permendagri No. 83 Tahun 2015 Pasal 6 ayat (1) menegaskan bahwa perangkat desa diberhentikan sementara oleh Kepala Desa setelah ditetapkan sebagai tersangka tindak pidana korupsi, terorisme, makar, atau tindak pidana dengan ancaman minimal 5 tahun.", "source": "Permendagri No. 83 Tahun 2015 jo. Permendagri No. 67 Tahun 2017 Pasal 6"}, {"id": 221, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Berapa lama jangka waktu evaluasi Rancangan Peraturan Desa tentang APB Desa oleh Bupati/Camat sebelum ditetapkan menjadi Perdes?", "options": ["Paling lama 7 hari kerja", "Paling lama 20 hari kerja", "Paling lama 30 hari kalender", "Paling lama 60 hari kalender"], "answer": 1, "explanation": "Berdasarkan Permendagri No. 20 Tahun 2018 Pasal 38 ayat (2), bupati/walikota melakukan evaluasi rancangan Perdes APB Desa paling lama 20 (dua puluh) hari kerja sejak diterima.", "source": "Permendagri No. 20 Tahun 2018 Pasal 38"}, {"id": 222, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "mudah", "question": "Peraturan Desa yang telah diundangkan wajib dicatat dan dimuat dalam media resmi perundangan desa yang disebut...", "options": ["Berita Desa", "Lembaran Desa", "Papan Pengumuman Desa", "Jurnal Desa"], "answer": 1, "explanation": "Permendagri No. 111 Tahun 2014 Pasal 18 mengatur bahwa Peraturan Desa diundangkan dalam Lembaran Desa, sedangkan Peraturan Kepala Desa (Perkades) diundangkan dalam Berita Desa.", "source": "Permendagri No. 111 Tahun 2014 Pasal 18"}, {"id": 223, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Siapakah pejabat yang berwenang mengundangkan Peraturan Desa dan Peraturan Kepala Desa?", "options": ["Kepala Desa", "Ketua BPD", "Sekretaris Desa", "Camat"], "answer": 2, "explanation": "Berdasarkan Permendagri No. 111 Tahun 2014 Pasal 19, pengundangan Peraturan Desa dalam Lembaran Desa dan Peraturan Kepala Desa dalam Berita Desa dilakukan oleh Sekretaris Desa.", "source": "Permendagri No. 111 Tahun 2014 Pasal 19"}, {"id": 224, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sulit", "question": "Jika hasil evaluasi bupati terhadap Rancangan Perdes APB Desa menyatakan tidak sesuai peraturan perundang-undangan, Kepala Desa bersama BPD wajib memperbaikinya dalam waktu...", "options": ["Paling lambat 7 hari kerja sejak diterimanya hasil evaluasi", "Paling lambat 14 hari kerja", "Paling lambat 30 hari kalender", "Paling lambat akhir tahun anggaran berjalan"], "answer": 0, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 39 ayat (1) menyatakan Kepala Desa bersama BPD melakukan penyempurnaan rancangan Perdes APB Desa paling lama 7 (tujuh) hari kerja sejak diterimanya hasil evaluasi.", "source": "Permendagri No. 20 Tahun 2018 Pasal 39"}, {"id": 225, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Asas penyelenggaraan pemerintahan desa yang menjadi landasan keteraturan, keserasian, dan keseimbangan dalam pengendalian tata kelola desa disebut asas...", "options": ["Asas Tertib Penyelenggaraan Pemerintahan", "Asas Sentralisasi Kekuasaan", "Asas Diskresi Mutlak Kepala Desa", "Asas Kepentingan Golongan"], "answer": 0, "explanation": "Berdasarkan penjelasan Pasal 24 huruf b UU No. 6 Tahun 2014, Asas Tertib Penyelenggaraan Pemerintahan adalah asas yang menjadi landasan keteraturan, keserasian, dan keseimbangan dalam pengendalian penyelenggaraan pemerintahan desa.", "source": "UU No. 6 Tahun 2014 Pasal 24 huruf b"}, {"id": 226, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Peraturan perundang-undangan manakah yang membatalkan Peraturan Desa apabila Perdes tersebut bertentangan dengan kepentingan umum atau peraturan yang lebih tinggi?", "options": ["Keputusan Kepala Desa", "Surat Edaran Camat", "Keputusan Bupati/Walikota", "Pernyataan Sikap BPD"], "answer": 2, "explanation": "Sesuai UU No. 6 Tahun 2014 dan Permendagri No. 111 Tahun 2014 Pasal 24, pembatalan Peraturan Desa ditetapkan dengan Keputusan Bupati/Walikota.", "source": "Permendagri No. 111 Tahun 2014 Pasal 24"}, {"id": 227, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "mudah", "question": "Produk hukum Kepala Desa yang bersifat penetapan konkret, individual, dan final disebut...", "options": ["Peraturan Desa", "Peraturan Kepala Desa", "Keputusan Kepala Desa", "Instruksi Kepala Desa"], "answer": 2, "explanation": "Keputusan Kepala Desa (SK Kades) memuat kebijakan yang bersifat penetapan (beschikking) konkret, individual, dan final.", "source": "Permendagri No. 111 Tahun 2014 Pasal 15"}, {"id": 228, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Rancangan Peraturan Desa tentang APB Desa, Pungutan Desa, Tata Ruang, dan RKP Desa wajib dikonsultasikan kepada masyarakat desa melalui forum...", "options": ["Rapat koordinasi mingguan perangkat desa", "Musyawarah Desa (Musdes)", "Pemberitahuan lewat pengeras suara masjid", "Pemberitahuan melalui surat dinas camat"], "answer": 1, "explanation": "Permendagri No. 111/2014 dan UU 6/2014 Pasal 54 mewajibkan hal-hal strategis dan pembebanan masyarakat dibahas dan disepakati dalam forum Musyawarah Desa.", "source": "Permendagri No. 111 Tahun 2014 Pasal 7"}, {"id": 229, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Berdasarkan UU No. 12 Tahun 2011, hierarki perundang-undangan yang tepat dari yang tertinggi ke terendah adalah...", "options": ["UUD 1945 -> UU/Perppu -> PP -> Perpres -> Perda Provinsi -> Perda Kab/Kota", "UUD 1945 -> PP -> UU -> Perpres -> Perda Kab/Kota -> Perdes", "UUD 1945 -> Tap MPR -> Perda Provinsi -> UU -> PP -> Perpres", "UUD 1945 -> UU -> Perda Provinsi -> PP -> Perpres"], "answer": 0, "explanation": "Pasal 7 UU 12/2011: UUD 1945, Ketetapan MPR, UU/Perppu, PP, Perpres, Perda Provinsi, Perda Kabupaten/Kota.", "source": "UU No. 12 Tahun 2011 Pasal 7"}, {"id": 230, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Apakah Peraturan Desa (Perdes) boleh mengatur sanksi pidana kurungan bagi warga yang melanggar?", "options": ["Boleh asalkan kurungan paling lama 3 bulan", "Boleh apabila disetujui secara bulat oleh BPD", "Tidak boleh, karena sanksi pidana hanya dapat diatur oleh Undang-Undang dan Peraturan Daerah", "Boleh khusus untuk perkara pencurian hasil pertanian"], "answer": 2, "explanation": "UU No. 12 Tahun 2011 Pasal 15 menegaskan materi muatan sanksi pidana hanya dapat dimuat dalam Undang-Undang, Peraturan Daerah Provinsi, atau Peraturan Daerah Kabupaten/Kota. Perdes tidak memiliki wewenang memuat sanksi pidana kurungan.", "source": "UU No. 12 Tahun 2011 Pasal 15"}, {"id": 231, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Bupati dapat mendelegasikan wewenang evaluasi Rancangan Peraturan Desa tentang APB Desa kepada...", "options": ["Kepala Inspektorat Daerah", "Camat di wilayah kecamatan bersangkutan", "Kepala Dinas PMD Kabupaten", "Sekretaris Daerah langsung"], "answer": 1, "explanation": "Berdasarkan Permendagri No. 20 Tahun 2018 Pasal 38 ayat (1), bupati/walikota dapat melimpahkan wewenang evaluasi rancangan Peraturan Desa tentang APB Desa kepada Camat.", "source": "Permendagri No. 20 Tahun 2018 Pasal 38 ayat (1)"}, {"id": 232, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "mudah", "question": "Siapakah yang menandatangani Peraturan Desa (Perdes) sehingga resmi menjadi payung hukum desa?", "options": ["Ketua BPD bersama Sekretaris Desa", "Kepala Desa", "Camat atas nama Bupati", "Kepala Urusan Tata Usaha dan Umum"], "answer": 1, "explanation": "Peraturan Desa ditetapkan dan ditandatangani oleh Kepala Desa setelah mendapat persetujuan bersama dengan BPD.", "source": "Permendagri No. 111 Tahun 2014 Pasal 17"}, {"id": 233, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Kegiatan musyawarah mufakat di desa dalam menentukan alokasi pembangunan jalan pertanian merupakan perwujudan pengamalan Pancasila sila ke...", "options": ["Sila Pertama", "Sila Kedua", "Sila Ketiga", "Sila Keempat"], "answer": 3, "explanation": "Musyawarah mufakat untuk mencapai mufakat dalam semangat kekeluargaan merupakan implementasi Sila Keempat: Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan.", "source": "Ketetapan MPR No. I/MPR/2003 tentang Butir Pancasila"}, {"id": 234, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Pasal 18 ayat (1) UUD Negara Republik Indonesia Tahun 1945 menyatakan bahwa Negara Kesatuan Republik Indonesia dibagi atas daerah-daerah provinsi dan daerah provinsi itu dibagi atas...", "options": ["Kabupaten dan kota, yang tiap-tiap provinsi, kabupaten, dan kota itu mempunyai pemerintahan daerah, yang diatur dengan undang-undang", "Daerah swapraja dan daerah istimewa otonom mutlak", "Karesidenan dan kawedanan yang dipimpin wedana", "Wilayah kesatuan adat tanpa otonomi daerah"], "answer": 0, "explanation": "Pasal 18 ayat (1) UUD 1945: 'Negara Kesatuan Republik Indonesia dibagi atas daerah-daerah provinsi dan daerah provinsi itu dibagi atas kabupaten dan kota, yang tiap-tiap provinsi, kabupaten, dan kota itu mempunyai pemerintahan daerah, yang diatur dengan undang-undang'.", "source": "UUD NRI Tahun 1945 Pasal 18 ayat (1)"}, {"id": 235, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Sikap tidak membeda-bedakan warga miskin maupun kaya dalam memberikan pelayanan administrasi surat desa merupakan pencerminan sila...", "options": ["Sila Kedua dan Sila Kelima", "Hanya Sila Pertama", "Sila Ketiga saja", "Bukan nilai Pancasila"], "answer": 0, "explanation": "Perlakuan adil tanpa diskriminasi menjunjung tinggi martabat kemanusiaan (Sila Ke-2) dan mewujudkan keadilan sosial bagi seluruh warga (Sila Ke-5).", "source": "Pedoman Pengamalan Pancasila BPIP"}, {"id": 236, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Kedaulatan berada di tangan rakyat dan dilaksanakan menurut Undang-Undang Dasar adalah bunyi dari UUD 1945...", "options": ["Pasal 1 ayat (1)", "Pasal 1 ayat (2)", "Pasal 1 ayat (3)", "Pasal 2 ayat (1)"], "answer": 1, "explanation": "Pasal 1 ayat (2) UUD NRI Tahun 1945 berbunyi: 'Kedaulatan berada di tangan rakyat dan dilaksanakan menurut Undang-Undang Dasar.'", "source": "UUD NRI Tahun 1945 Pasal 1 ayat (2)"}, {"id": 237, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Dalam Pembukaan UUD 1945, tujuan nasional negara Republik Indonesia tercantum secara jelas pada alinea...", "options": ["Alinea Pertama", "Alinea Kedua", "Alinea Ketiga", "Alinea Keempat"], "answer": 3, "explanation": "Alinea Keempat Pembukaan UUD 1945 memuat 4 tujuan negara: melindungi segenap bangsa, memajukan kesejahteraan umum, mencerdaskan kehidupan bangsa, dan ikut melaksanakan ketertiban dunia.", "source": "Pembukaan UUD NRI Tahun 1945 Alinea IV"}, {"id": 238, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Kedudukan Pancasila sebagai sumber dari segala sumber hukum negara diatur secara eksplisit dalam...", "options": ["UU No. 12 Tahun 2011 Pasal 2", "Permendagri No. 84 Tahun 2015", "Peraturan Daerah Provinsi", "Keputusan Kepala Desa"], "answer": 0, "explanation": "UU No. 12 Tahun 2011 Pasal 2 menegaskan bahwa Pancasila merupakan sumber segala sumber hukum negara Republik Indonesia.", "source": "UU No. 12 Tahun 2011 Pasal 2"}, {"id": 239, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Konsep Wawasan Nusantara dalam konteks kehidupan desa menuntut perangkat desa untuk memandang wilayah desa dan keragamannya sebagai...", "options": ["Wilayah otonom yang dapat memisahkan diri dari NKRI", "Satu kesatuan utuh politik, ekonomi, sosial budaya, dan pertahanan keamanan dalam bingkai NKRI", "Entitas independen tanpa tunduk hukum nasional", "Milik kelompok mayoritas dusun terbesar"], "answer": 1, "explanation": "Wawasan Nusantara mengajarkan persatuan bangsa dan kesatuan wilayah Indonesia sebagai satu kesatuan utuh dalam segala gatra kehidupan.", "source": "Modul Wawasan Kebangsaan Lemhannas RI"}, {"id": 240, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Pasal 30 ayat (1) UUD NRI Tahun 1945 menegaskan hak dan kewajiban setiap warga negara dalam...", "options": ["Mendapatkan pekerjaan yang layak", "Usaha pertahanan dan keamanan negara", "Memperoleh subsidi pangan dari pemerintah", "Membentuk serikat pekerja"], "answer": 1, "explanation": "Pasal 30 ayat (1) UUD 1945: 'Tiap-tiap warga negara berhak dan wajib ikut serta dalam usaha pertahanan dan keamanan negara.'", "source": "UUD NRI Tahun 1945 Pasal 30 ayat (1)"}, {"id": 241, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Sistem pertahanan keamanan negara yang melibatkan seluruh rakyat dengan TNI dan Polri sebagai kekuatan utama disebut...", "options": ["Sistem Pertahanan Terbuka", "Sistem Pertahanan Keamanan Rakyat Semesta (Sishankamrata)", "Sistem Keamanan Blok Dusun", "Sistem Garda Desa Swakarsa"], "answer": 1, "explanation": "Pasal 30 ayat (2) UUD 1945 mengatur usaha hankamneg dilaksanakan melalui sistem pertahanan dan keamanan rakyat semesta.", "source": "UUD NRI Tahun 1945 Pasal 30 ayat (2)"}, {"id": 242, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Makna lambang pohon beringin pada perisai Garuda Pancasila melambangkan...", "options": ["Ketuhanan Yang Maha Esa", "Kemanusiaan yang adil dan beradab", "Persatuan Indonesia", "Keadilan sosial bagi seluruh rakyat Indonesia"], "answer": 2, "explanation": "Pohon beringin merupakan simbol Sila Ketiga: Persatuan Indonesia, yang melambangkan keteduhan dan tempat bernaung seluruh bangsa Indonesia yang majemuk.", "source": "PP No. 66 Tahun 1951 tentang Lambang Negara"}, {"id": 243, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Permendagri No. 47 Tahun 2016 mengatur tata administrasi pemerintahan desa yang dikelompokkan ke dalam berapa jenis buku administrasi?", "options": ["3 jenis buku administrasi", "5 jenis buku administrasi", "8 jenis buku administrasi", "12 jenis buku administrasi"], "answer": 1, "explanation": "Permendagri No. 47 Tahun 2016 mengatur 5 jenis administrasi desa: Administrasi Umum, Penduduk, Keuangan, Pembangunan, dan Lainnya.", "source": "Permendagri No. 47 Tahun 2016 Pasal 3"}, {"id": 244, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Buku yang mencatat data keluar masuknya surat dinas resmi di kantor desa beserta tanggal pengiriman dan tanda terima disebut...", "options": ["Buku Agenda dan Buku Ekspedisi", "Buku Induk Penduduk", "Buku Kas Pembantu", "Buku Rencana Anggaran Biaya"], "answer": 0, "explanation": "Buku Agenda mencatat surat masuk/keluar secara kronologis, dan Buku Ekspedisi mencatat pembuktian pengiriman/penerimaan fisik surat.", "source": "Permendagri No. 47 Tahun 2016 tentang Administrasi Pemerintahan Desa"}, {"id": 245, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Penulisan alamat tujuan surat resmi dinas desa yang sesuai dengan pedoman tata naskah dinas yang benar adalah...", "options": ["Kepada Yth. Bapak Camat Tuban di Tempat", "Yth. Camat Tuban\nJalan Veteran No. 12\nTuban", "Kepada Yth. Bapak/Ibu Camat Tuban di Tuban", "Yth. Bapak Camat Tuban, Jalan Veteran No. 12, Tuban"], "answer": 1, "explanation": "Tata naskah dinas baku tidak menggunakan kata 'Kepada' sebelum 'Yth.', tidak menggunakan sebutan 'Bapak/Ibu' jika diikuti nama jabatan, dan tidak menggunakan frasa 'di Tempat'.", "source": "Permendagri No. 54/2009 & Permendagri No. 1/2023 Tata Naskah Dinas"}, {"id": 246, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Singkatan 'a.n.' (atas nama) pada penandatanganan naskah dinas digunakan apabila...", "options": ["Pejabat yang berwenang melimpahkan wewenang penandatanganan kepada bawahannya sesuai bidang tugasnya", "Kepala Desa sedang cuti panjang dan menunjuk warga desa", "Surat ditujukan kepada instansi swasta", "Surat tersebut bersifat rahasia negara"], "answer": 0, "explanation": "Atas nama (a.n.) digunakan jika pejabat definitif melimpahkan mandat penandatanganan kepada pejabat di bawahnya secara resmi.", "source": "Permendagri tentang Tata Naskah Dinas Pemerintahan Daerah & Desa"}, {"id": 247, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Cap atau stempel dinas Pemerintah Desa berbentuk lingkaran memuat lambang dan nama instansi yang tintanya resmi menggunakan warna...", "options": ["Hitam", "Merah", "Ungu / Biru", "Hijau tua"], "answer": 2, "explanation": "Sesuai ketentuan tata naskah dinas instansi pemerintahan daerah dan desa, tinta cap dinas menggunakan warna ungu (violet) atau biru.", "source": "Permendagri tentang Tata Naskah Dinas Instansi Pemerintah"}, {"id": 248, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Buku administrasi yang wajib dimiliki oleh desa untuk mencatat tanah kas desa, tanah bengkok, dan tanah fasilitas umum lainnya adalah...", "options": ["Buku Data Tanah Kas Desa / Tanah di Desa", "Buku Mutasi Penduduk", "Buku Register Pengaduan", "Buku Harian Piket"], "answer": 0, "explanation": "Buku Tanah di Desa merupakan salah satu buku wajib dalam Administrasi Umum menurut Permendagri No. 47 Tahun 2016.", "source": "Permendagri No. 47 Tahun 2016 Lampiran I"}, {"id": 249, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Arsip dinas desa yang masih frekuen digunakan dalam kegiatan operasional sehari-hari disebut...", "options": ["Arsip Statis", "Arsip Inaktif", "Arsip Aktif", "Arsip Musnah"], "answer": 2, "explanation": "Arsip aktif adalah arsip yang frekuensi penggunaannya tinggi dan terus-menerus diperlukan dalam pelaksanaan fungsi instansi.", "source": "UU No. 43 Tahun 2009 tentang Kearsipan"}, {"id": 250, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Surat resmi yang dikeluarkan oleh Kepala Desa untuk menerangkan status kependudukan seorang warga (misal domisili, belum menikah, atau kurang mampu) disebut...", "options": ["Surat Edaran", "Surat Perjalanan Dinas", "Surat Keterangan", "Surat Keputusan"], "answer": 2, "explanation": "Surat Keterangan adalah naskah dinas yang berisi penjelasan atau keterangan resmi tentang suatu keadaan atau peristiwa faktual seseorang.", "source": "Pedoman Tata Naskah Dinas Desa Permendagri"}, {"id": 251, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Naskah dinas resmi yang dikeluarkan oleh Kepala Desa sebagai penugasan resmi kepada perangkat desa untuk melaksanakan tugas kedinasan, bimbingan teknis, atau dinas luar daerah disebut...", "options": ["Surat Perintah Tugas (Surat Tugas)", "Surat Keterangan Kematian", "Surat Pengantar Nikah", "Surat Rekomendasi Camat"], "answer": 0, "explanation": "Surat Tugas atau Surat Perintah Tugas (SPT) adalah naskah dinas dari atasan kepada bawahan yang memuat perintah untuk melaksanakan tugas kedinasan tertentu sesuai fungsi tugasnya.", "source": "Permendagri No. 1 Tahun 2023 tentang Tata Naskah Dinas Pemerintah Daerah"}, {"id": 252, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Siapakah penanggung jawab tertinggi pengelolaan seluruh arsip dan administrasi ketatausahaan di lingkungan Pemerintah Desa?", "options": ["Kaur Keuangan", "Sekretaris Desa", "Ketua RT tertua", "Petugas Pos Kecamatan"], "answer": 1, "explanation": "Sekretaris Desa bertugas membantu Kepala Desa dalam bidang administrasi pemerintahan dan memimpin sekretariat desa selaku penanggung jawab ketatausahaan dan kearsipan.", "source": "Permendagri No. 84 Tahun 2015 Pasal 7"}, {"id": 253, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Rekening Kas Desa (RKD) dibuka pada bank persepsi oleh Pemerintah Desa dengan spesimen tanda tangan bersama antara...", "options": ["Ketua BPD dan Camat", "Kepala Desa dan Kaur Keuangan (Bendahara Desa)", "Sekretaris Desa dan Bendahara BPD", "Kepala Desa dan Kasi Pemerintahan"], "answer": 1, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 14 ayat (3) menetapkan spesimen tanda tangan pembukaan RKD adalah Kepala Desa dan Kaur Keuangan.", "source": "Permendagri No. 20 Tahun 2018 Pasal 14"}, {"id": 254, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Batas waktu paling lambat penetapan Peraturan Desa tentang APB Desa untuk tahun anggaran berikutnya adalah tanggal...", "options": ["30 November tahun berjalan", "31 Desember tahun berjalan", "10 Januari tahun anggaran berkenaan", "31 Maret tahun berkenaan"], "answer": 1, "explanation": "Berdasarkan Permendagri No. 20 Tahun 2018 Pasal 37 ayat (2), Perdes tentang APB Desa ditetapkan paling lambat tanggal 31 Desember tahun anggaran berjalan.", "source": "Permendagri No. 20 Tahun 2018 Pasal 37"}, {"id": 255, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Berdasarkan PP No. 11 Tahun 2019, alokasi belanja desa dalam APB Desa untuk penghasilan tetap dan tunjangan Kepala Desa, Perangkat Desa, operasional Pemdes dan BPD diatur paling banyak...", "options": ["30% dari total belanja desa", "50% dari total belanja desa", "70% dari total belanja desa", "Tanpa batasan persentase"], "answer": 0, "explanation": "PP No. 11/2019 Pasal 100 mengatur paling banyak 30% belanja APB Desa untuk siltap, tunjangan, operasional kades, perangkat, BPD, dan insentif RT/RW.", "source": "PP No. 11 Tahun 2019 Pasal 100 ayat (1) huruf a"}, {"id": 256, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 1 Tahun 2016 tentang Pengelolaan Aset Desa, pemanfaatan aset desa berupa Bangun Guna Serah (BGS) atau Bangun Serah Guna (BSG) dapat dilaksanakan dengan jangka waktu paling lama...", "options": ["20 (dua puluh) tahun dan dapat diperpanjang", "3 (tiga) tahun saja", "50 tahun tanpa evaluasi", "100 tahun sesuai hak guna bangunan"], "answer": 0, "explanation": "Permendagri No. 1 Tahun 2016 Pasal 13 ayat (4) menyatakan bahwa jangka waktu Bangun Guna Serah (BGS) dan Bangun Serah Guna (BSG) aset desa paling lama 20 tahun dan dapat diperpanjang setelah persetujuan BPD.", "source": "Permendagri No. 1 Tahun 2016 Pasal 13"}, {"id": 257, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Surat Permintaan Pembayaran (SPP) diajukan oleh Pelaksana Kegiatan Anggaran (Kaur/Kasi) kepada Kepala Desa melalui...", "options": ["Ketua BPD untuk diotorisasi", "Sekretaris Desa untuk diverifikasi kelengkapannya", "Camat untuk disahkan", "Inspektorat Kabupaten"], "answer": 1, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 51 mengatur Sekretaris Desa bertindak sebagai verifikator atas SPP dan dokumen pendukung yang diajukan Kaur/Kasi.", "source": "Permendagri No. 20 Tahun 2018 Pasal 51"}, {"id": 258, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "mudah", "question": "Dalam struktur APB Desa, kelompok Pengeluaran Pembiayaan menurut Permendagri No. 20 Tahun 2018 antara lain dialokasikan untuk...", "options": ["Penyertaan modal desa pada BUMDes dan pembentukan dana cadangan", "Pembayaran gaji penghasilan tetap Kepala Desa bulanan", "Pemberian bantuan sosial BLT-DD", "Belanja semen dan pasir proyek fisik jalan"], "answer": 0, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 28 menetapkan bahwa Pengeluaran Pembiayaan terdiri atas pembentukan dana cadangan dan penyertaan modal desa (misalnya modal BUMDes).", "source": "Permendagri No. 20 Tahun 2018 Pasal 28"}, {"id": 259, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Berapakah jumlah bidang kelompok belanja dalam struktur Anggaran Pendapatan dan Belanja Desa (APB Desa)?", "options": ["3 bidang", "4 bidang", "5 bidang", "7 bidang"], "answer": 2, "explanation": "Permendagri No. 20/2018 menetapkan 5 bidang belanja desa: (1) Penyelenggaraan Pemdes, (2) Pembangunan, (3) Pembinaan Kemasyarakatan, (4) Pemberdayaan Masyarakat, dan (5) Penanggulangan Bencana/Keadaan Mendesak.", "source": "Permendagri No. 20 Tahun 2018 Pasal 16"}, {"id": 260, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sulit", "question": "Penghapusan aset desa berupa barang milik desa karena rusak berat atau hilang harus ditetapkan dengan...", "options": ["Keputusan Kepala Desa setelah mendapat persetujuan BPD", "Surat Pernyataan Sekretaris Desa", "Keputusan Camat", "Surat Perjanjian Sewa"], "answer": 0, "explanation": "Permendagri No. 1 Tahun 2016 Pasal 19 mengatur bahwa penghapusan aset desa dilakukan melalui Keputusan Kepala Desa setelah mendapat persetujuan BPD.", "source": "Permendagri No. 1 Tahun 2016 Pasal 19"}, {"id": 261, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Untuk mencegah penyimpangan kas dan mempercepat transparansi, transaksi belanja APB Desa kini diintegrasikan secara digital dengan aplikasi perbankan CMS Desa (Cash Management System). Manfaat utama CMS Desa adalah...", "options": ["Melaksanakan transaksi pembayaran belanja desa secara non-tunai langsung dari Rekening Kas Desa ke rekening penerima/rekanan", "Menghapus kewajiban verifikasi SPP oleh Sekretaris Desa", "Memperbolehkan penarikan tunai tanpa tanda tangan Kepala Desa", "Menggantikan seluruh musyawarah perencanaan desa"], "answer": 0, "explanation": "Implementasi Transaksi Non-Tunai (CMS Perbankan yang terintegrasi dengan Siskeudes) memastikan pembayaran belanja APBDes langsung tertransfer ke rekening rekanan/penerima secara akuntabel, terekam perbankan, dan meminimalkan risiko 'fraud' uang tunai.", "source": "Surat Edaran Kemendagri & Bank Indonesia tentang Implementasi Transaksi Non-Tunai Pemerintah Desa"}, {"id": 262, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Dana Desa yang bersumber dari APBN disalurkan dari Rekening Kas Umum Negara (RKUN) ke desa melalui...", "options": ["Rekening Kas Umum Daerah (RKUD) Kabupaten/Kota", "Rekening pribadi Kepala Desa", "Kantor Pos terdekat", "Rekening bersama BPD"], "answer": 0, "explanation": "Penyaluran Dana Desa dilakukan melalui pemindahbukuan dari RKUN ke RKUD kabupaten/kota sebelum ditransfer ke RKD masing-masing desa.", "source": "PP No. 60 Tahun 2014 & PMK Pengelolaan Dana Desa"}, {"id": 263, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Berdasarkan Permendesa PDTT No. 21 Tahun 2020, penyusunan Rencana Kerja Pemerintah Desa (RKP Desa) mulai dilaksanakan pada bulan...", "options": ["Januari tahun berjalan", "Juli tahun berjalan", "September tahun berjalan", "Desember tahun berjalan"], "answer": 1, "explanation": "Permendesa PDTT No. 21 Tahun 2020 Pasal 22 menetapkan Kepala Desa menyusun RKP Desa dengan mengikutsertakan masyarakat mulai bulan Juli tahun berjalan.", "source": "Permendesa PDTT No. 21 Tahun 2020 Pasal 22"}, {"id": 264, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "mudah", "question": "Dokumen perencanaan pembangunan desa yang memuat rencana arah kebijakan pembangunan untuk jangka waktu 8 tahun adalah...", "options": ["RKP Desa", "RPJM Desa", "APB Desa", "Profil Desa"], "answer": 1, "explanation": "UU No. 3 Tahun 2024 menyelaraskan masa jabatan Kepala Desa 8 tahun, sehingga RPJM Desa disusun untuk periode 8 tahun.", "source": "UU No. 3 Tahun 2024 & Permendesa No. 21/2020"}, {"id": 265, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Pelaksanaan proyek pembangunan fisik di desa diutamakan dengan metode swakelola dan prinsip Padat Karya Tunai Desa (PKTD). Tujuan utama PKTD adalah...", "options": ["Memberikan keuntungan maksimal bagi kontraktor swasta", "Menyerap tenaga kerja warga setempat terutama keluarga prasejahtera dan menambah pendapatan masyarakat desa", "Mempercepat waktu pengerjaan proyek tanpa melibatkan warga", "Mengurangi transparansi penggunaan anggaran"], "answer": 1, "explanation": "PKTD bertujuan membuka lapangan kerja sementara bagi warga lokal, meningkatkan daya beli, dan mengentaskan kemiskinan perdesaan.", "source": "Buku Saku Padat Karya Tunai Desa Kemendesa PDTT"}, {"id": 266, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Modal awal pendirian Badan Usaha Milik Desa (BUMDes) bersumber dari...", "options": ["Pinjaman bank komersial tanpa jaminan", "Kekayaan desa yang dipisahkan yang dianggarkan melalui APB Desa", "Sumbangan sukarela perangkat desa", "Iuran wajib seluruh warga desa per bulan"], "answer": 1, "explanation": "PP No. 11 Tahun 2021 Pasal 39 menegaskan modal awal BUMDes bersumber dari APB Desa sebagai kekayaan desa yang dipisahkan.", "source": "PP No. 11 Tahun 2021 tentang BUMDes Pasal 39"}, {"id": 267, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Kader di desa yang bertugas memfasilitasi dan mengawal integrasi pencegahan stunting pada 1.000 Hari Pertama Kehidupan (HPK) disebut...", "options": ["Kader Pemberdayaan Masyarakat Desa (KPMD)", "Kader Pembangunan Manusia (KPM)", "Pendamping Lokal Desa (PLD)", "Petugas Lapangan KB (PLKB)"], "answer": 1, "explanation": "Kader Pembangunan Manusia (KPM) adalah kader desa yang memantau dan mendorong layanan konvergensi pencegahan stunting di desa.", "source": "Petunjuk Teknis Konvergensi Stunting Desa Kemendesa PDTT"}, {"id": 268, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "mudah", "question": "Tim yang dibentuk oleh Kepala Desa untuk membantu pelaksanaan kegiatan pengadaan barang/jasa pembangunan fisik di desa disebut...", "options": ["Panitia Pengawas BPD", "Tim Pelaksana Kegiatan (TPK)", "Komisi Disiplin Aparatur", "Dewan Pertimbangan Desa"], "answer": 1, "explanation": "Pengadaan barang dan jasa di desa dilaksanakan oleh Tim Pelaksana Kegiatan (TPK) yang dibentuk oleh Kepala Desa dari unsur perangkat desa dan masyarakat.", "source": "Perka LKPP No. 12/2019 tentang Pengadaan Barang/Jasa di Desa"}, {"id": 269, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Berapakah porsi pembagian hasil laba bersih usaha BUMDes yang disetorkan sebagai Pendapatan Asli Desa (PADes)?", "options": ["Ditetapkan dalam Anggaran Dasar / Anggaran Rumah Tangga (AD/ART) BUMDes dan disepakati dalam Musdes", "Wajib 100% tanpa cadangan modal", "Maksimal 10% saja", "Ditetapkan sepihak oleh direktur BUMDes"], "answer": 0, "explanation": "Pembagian laba usaha BUMDes untuk PADes, cadangan modal, dan pengelola diatur dalam AD/ART dan diputuskan melalui forum Musyawarah Desa.", "source": "PP No. 11 Tahun 2021 tentang BUMDes"}, {"id": 270, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Tujuan utama program SDGs Desa yang diatur dalam Permendesa No. 21 Tahun 2020 adalah...", "options": ["Menghapus keberadaan tradisi lokal desa", "Mewujudkan pembangunan desa yang berkelanjutan, tanpa kemiskinan, tanpa kelaparan, dan peduli lingkungan", "Mengganti seluruh lahan pertanian menjadi kawasan industri", "Mewajibkan warga desa bekerja di luar negeri"], "answer": 1, "explanation": "SDGs Desa mengadaptasi 18 tujuan global untuk percepatan pencapaian desa tanpa kemiskinan, desa sehat, peduli pendidikan, dan berkelanjutan.", "source": "Permendesa PDTT No. 21 Tahun 2020"}, {"id": 271, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Berdasarkan UU No. 3 Tahun 2024, masa keanggotaan Badan Permusyawaratan Desa (BPD) adalah...", "options": ["5 tahun", "6 tahun", "8 tahun dan dapat dipilih kembali", "Seumur hidup"], "answer": 2, "explanation": "UU No. 3 Tahun 2024 Pasal 56 menyelaraskan masa keanggotaan BPD menjadi 8 (delapan) tahun terhitung sejak tanggal pengucapan sumpah/janji.", "source": "UU No. 3 Tahun 2024 Pasal 56"}, {"id": 272, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "mudah", "question": "Berapakah jumlah anggota BPD di suatu desa menurut peraturan perundang-undangan?", "options": ["Genap antara 4 sampai 8 orang", "Ganjil paling sedikit 5 orang dan paling banyak 9 orang", "Bebas sesuai kesepakatan warga dusun", "Harus sama persis dengan jumlah perangkat desa"], "answer": 1, "explanation": "Permendagri No. 110 Tahun 2016 Pasal 5 ayat (1) menyatakan jumlah anggota BPD berjumlah ganjil, paling sedikit 5 (lima) orang dan paling banyak 9 (sembilan) orang.", "source": "Permendagri No. 110 Tahun 2016 Pasal 5"}, {"id": 273, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Laporan Keterangan Penyelenggaraan Pemerintahan Desa (LKPPD) yang disampaikan secara tertulis oleh Kepala Desa kepada BPD setiap akhir tahun anggaran digunakan oleh BPD untuk...", "options": ["Bahan evaluasi kinerja Kepala Desa dan menyusun catatan strategis serta rekomendasi pengawasan BPD", "Menjatuhkan sanksi pemecatan langsung kepada perangkat desa", "Mengambil alih seluruh wewenang eksekutif Kepala Desa", "Menolak pencairan dana transfer APBN tahun berikutnya"], "answer": 0, "explanation": "Permendagri No. 46 Tahun 2016 Pasal 8 ayat (3) menegaskan LKPPD digunakan oleh BPD sebagai bahan pertimbangan dalam membuat catatan strategis dan evaluasi kinerja penyelenggaraan pemerintahan desa.", "source": "Permendagri No. 46 Tahun 2016 Pasal 8"}, {"id": 274, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Manakah lembaga di bawah ini yang tergolong sebagai Lembaga Kemasyarakatan Desa (LKD) menurut Permendagri No. 18 Tahun 2018?", "options": ["Badan Permusyawaratan Desa (BPD)", "Karang Taruna dan Tim Penggerak PKK", "Koramil dan Polsek", "Koperasi Simpan Pinjam swasta"], "answer": 1, "explanation": "Permendagri No. 18/2018 Pasal 3 menyebut jenis LKD meliputi: RT, RW, PKK, Karang Taruna, Posyandu, dan LPMD.", "source": "Permendagri No. 18 Tahun 2018 Pasal 3"}, {"id": 275, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Forum musyawarah tertinggi di desa yang diselenggarakan oleh BPD untuk menyepakati hal strategis desa disebut...", "options": ["Musyawarah Dusun (Musdus)", "Musyawarah Desa (Musdes)", "Musrenbangdes", "Rapat Dengar Pendapat Umum"], "answer": 1, "explanation": "Musdes diselenggarakan oleh BPD untuk hal strategis (penataan desa, BUMDes, kerja sama, aset desa) per UU No. 6/2014 Pasal 54.", "source": "UU No. 6 Tahun 2014 Pasal 54 & Permendesa No. 16/2019"}, {"id": 276, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Manakah kelompok kata berikut yang semuanya merupakan kata baku menurut KBBI dan EYD Edisi V?", "options": ["Ijin, sistim, kwitansi, antri", "Izin, sistem, kuitansi, antre", "Ijin, sistem, kwitansi, antre", "Izin, sistim, kuitansi, antri"], "answer": 1, "explanation": "Bentuk baku menurut EYD V dan KBBI adalah izin (bukan ijin), sistem (bukan sistim), kuitansi (bukan kwitansi), dan antre (bukan antri).", "source": "EYD Edisi V & Kamus Besar Bahasa Indonesia (KBBI)"}, {"id": 277, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Penulisan gelar akademik dan nama pejabat yang benar pada naskah dinas adalah...", "options": ["Drs, Ahmad Fauzi. M,Si.", "Drs. Ahmad Fauzi, M.Si.", "Drs. Ahmad Fauzi M.Si", "Drs Ahmad Fauzi, M,Si."], "answer": 1, "explanation": "Gelar depan diikuti tanda titik (Drs.), antara nama dan gelar belakang dipisahkan tanda koma, dan tiap singkatan gelar belakang diakhiri tanda titik (M.Si.).", "source": "Pedoman Umum Ejaan Bahasa Indonesia (EYD V)"}, {"id": 278, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Kalimat manakah di bawah ini yang paling efektif dan bebas dari pemborosan kata (pleonasme)?", "options": ["Seluruh para perangkat desa sekalian hadir dalam rapat.", "Semua perangkat desa hadir dalam rapat pleno.", "Para perangkat desa semua saling bantu-membantu.", "Perangkat desa hadir kembali mengulang kegiatan tersebut."], "answer": 1, "explanation": "Pilihan B efektif. Pilihan A pleonastis ('seluruh para sekalian'), C pleonastis ('semua saling bantu-membantu').", "source": "Tata Bahasa Baku Bahasa Indonesia"}, {"id": 279, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Kata 'legalitas' dalam konteks administrasi hukum pemerintahan desa memiliki makna sinonim dengan...", "options": ["Kebijaksanaan", "Keabsahan hukum", "Popularitas pejabat", "Efisiensi anggaran"], "answer": 1, "explanation": "Legalitas berasal dari kata legal yang berarti keabsahan atau kesesuaian dengan hukum dan peraturan yang berlaku.", "source": "KBBI Kemendikbudristek"}, {"id": 280, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Penulisan tanggal surat dinas desa yang benar dan baku adalah...", "options": ["Tuban, 18-10-2026", "Tuban, 18 Oktober 2026", "Tuban, 18 Okt. 2026", "Tuban: 18/Oktober/2026"], "answer": 1, "explanation": "Dalam tata naskah dinas, nama tempat diikuti tanda koma, tanggal dengan angka, nama bulan ditulis utuh dengan huruf kapital awal, dan tahun angka tanpa titik akhir.", "source": "Permendagri Tata Naskah Dinas & EYD V"}, {"id": 281, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Penulisan kata serapan yang baku di bawah ini adalah...", "options": ["Standarisasi, kordinasi, frekwensi", "Standardisasi, koordinasi, frekuensi", "Standardisasi, kordinasi, frekwensi", "Standarisasi, koordinasi, frekwensi"], "answer": 1, "explanation": "Bentuk baku: standardisasi (dari standardization), koordinasi (dua 'o'), dan frekuensi (dengan huruf 'k-u' bukan 'w').", "source": "EYD Edisi V Pedoman Pembentukan Istilah"}, {"id": 282, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Perhatikan kalimat: 'Keputusan ini berlaku sejak tanggal ditetapkan.' Kata 'sejak' dalam kalimat tersebut berfungsi sebagai...", "options": ["Kata hubung (konjungsi) penanda waktu awal", "Kata benda abstrak", "Kata sifat", "Kata seru"], "answer": 0, "explanation": "Kata 'sejak' merupakan preposisi/konjungsi temporal yang menandai titik tolak permulaan waktu berlakunya suatu penetapan.", "source": "Tata Bahasa Baku Bahasa Indonesia"}, {"id": 283, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Desa Sukomakmur memiliki total APB Desa sebesar Rp 1.200.000.000,00. Jika 65% dialokasikan untuk bidang pelaksanaan pembangunan desa, berapakah nilai nominal anggaran pembangunan tersebut?", "options": ["Rp 720.000.000,00", "Rp 780.000.000,00", "Rp 820.000.000,00", "Rp 850.000.000,00"], "answer": 1, "explanation": "Perhitungan: 65% x Rp 1.200.000.000 = 0,65 x 1.200.000.000 = Rp 780.000.000,00.", "source": "Matematika Terapan Pengelolaan APB Desa"}, {"id": 284, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Sebidang tanah kas desa seluas 2,5 hektar akan dibagikan untuk garapan 5 kelompok tani secara merata. Berapa meter persegi (m²) luas tanah yang diterima masing-masing kelompok tani?", "options": ["2.500 m²", "5.000 m²", "7.500 m²", "10.000 m²"], "answer": 1, "explanation": "1 hektar = 10.000 m². Total luas = 2,5 x 10.000 = 25.000 m². Tiap kelompok menerima = 25.000 m² / 5 = 5.000 m².", "source": "Konversi Satuan Agraria Standar Nasional"}, {"id": 285, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Sebuah proyek jalan rabat beton sepanjang 600 meter dapat diselesaikan oleh 12 orang pekerja dalam 20 hari. Jika Kepala Desa ingin proyek selesai dalam 15 hari, berapa jumlah total pekerja yang dibutuhkan?", "options": ["14 orang", "16 orang", "18 orang", "20 orang"], "answer": 1, "explanation": "Perbandingan berbalik nilai: (Pekerja1 x Hari1) = (Pekerja2 x Hari2). (12 x 20) = (P2 x 15) -> 240 = 15 x P2 -> P2 = 240 / 15 = 16 orang.", "source": "Aritmatika Sosial dan Perbandingan Berbalik Nilai"}, {"id": 286, "category": "Matematika dan numerik", "difficulty": "mudah", "question": "Pemerintah Desa membeli 4 unit laptop kantor seharga Rp 7.500.000,00 per unit. Toko memberikan potongan harga (diskon) sebesar 8%. Berapakah total biaya yang harus dibayarkan dari kas desa?", "options": ["Rp 27.600.000,00", "Rp 28.000.000,00", "Rp 28.500.000,00", "Rp 29.400.000,00"], "answer": 0, "explanation": "Harga total kotor = 4 x 7.500.000 = Rp 30.000.000. Diskon 8% = 0,08 x 30.000.000 = Rp 2.400.000. Total bayar = 30.000.000 - 2.400.000 = Rp 27.600.000,00.", "source": "Matematika Dasar Aritmatika Sosial"}, {"id": 287, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Perhatikan deret bilangan berikut: 3, 7, 15, 31, 63, ... Angka berikutnya pada deret tersebut adalah...", "options": ["95", "127", "128", "144"], "answer": 1, "explanation": "Pola deret: (+4, +8, +16, +32, +64) atau rumus (2n + 1). 63 + 64 = 127.", "source": "Tes Potensi Akademik Deret Angka Numerik"}, {"id": 288, "category": "Matematika dan numerik", "difficulty": "mudah", "question": "Jarak antara balai desa ke kantor kecamatan adalah 18 km. Jika perangkat desa mengendarai sepeda motor dengan kecepatan rata-rata 45 km/jam, berapa menit waktu yang diperlukan untuk sampai?", "options": ["20 menit", "24 menit", "30 menit", "36 menit"], "answer": 1, "explanation": "Waktu = Jarak / Kecepatan = 18 km / 45 km/jam = 0,4 jam. 0,4 x 60 menit = 24 menit.", "source": "Matematika Dasar Kecepatan dan Waktu"}, {"id": 289, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Premis 1: Semua perangkat desa wajib masuk kerja tepat waktu.\nPremis 2: Sebagian warga desa Sukamaju adalah perangkat desa.\nKesimpulan yang paling tepat secara silogisme logis adalah...", "options": ["Semua warga desa Sukamaju wajib masuk kerja tepat waktu", "Sebagian warga desa Sukamaju wajib masuk kerja tepat waktu", "Perangkat desa tidak ada yang berasal dari Sukamaju", "Warga Sukamaju bebas dari kewajiban disiplin"], "answer": 1, "explanation": "Kombinasi premis universal (Semua) dan partikular (Sebagian) menghasilkan kesimpulan partikular: 'Sebagian warga desa Sukamaju wajib masuk kerja tepat waktu'.", "source": "Logika Silogisme Kategorial Formal"}, {"id": 290, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Jika musim kemarau panjang tiba, maka debit air sumur warga berkurang. Saat ini debit air sumur warga tidak berkurang. Kesimpulan yang sah berdasarkan modus tollens adalah...", "options": ["Musim kemarau panjang sedang tiba", "Musim kemarau panjang tidak tiba", "Warga desa menggunakan pompa air", "Hujan lebat terjadi setiap malam"], "answer": 1, "explanation": "Modus Tollens: Jika P maka Q. Negasi Q (~Q), maka kesimpulannya adalah negasi P (~P): 'Musim kemarau panjang tidak tiba'.", "source": "Logika Proposisional Modus Tollens"}, {"id": 291, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Dalam jadwal piket pelayanan desa: Ali piket sebelum Budi. Cici piket setelah Dedi tetapi sebelum Ali. Siapakah yang piket pada giliran pertama?", "options": ["Ali", "Budi", "Cici", "Dedi"], "answer": 3, "explanation": "Urutan piket: Dedi -> Cici -> Ali -> Budi. Giliran pertama adalah Dedi.", "source": "Tes Penalaran Analitis Posisi dan Urutan"}, {"id": 292, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Dari 50 warga penerima bantuan: 30 warga menerima bantuan beras, 25 warga menerima bantuan minyak goreng, dan 10 warga menerima kedua-duanya. Berapakah warga yang hanya menerima bantuan beras saja?", "options": ["10 warga", "15 warga", "20 warga", "25 warga"], "answer": 2, "explanation": "Himpunan: Warga yang hanya menerima beras = Total penerima beras - Penerima keduanya = 30 - 10 = 20 warga.", "source": "Logika Matematika Teori Himpunan Venn"}, {"id": 293, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Semua kantor pemerintah desa memiliki papan transparansi APB Desa. Gedung X tidak memiliki papan transparansi APB Desa. Kesimpulan yang benar adalah...", "options": ["Gedung X adalah kantor BPD", "Gedung X bukan kantor pemerintah desa", "Gedung X adalah kantor desa yang sedang direnovasi", "Papan transparansi sedang dicetak"], "answer": 1, "explanation": "Jika semua P adalah Q, dan X bukan Q, maka pasti X bukan P ('Gedung X bukan kantor pemerintah desa').", "source": "Silogisme Penalaran Deduktif"}, {"id": 294, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Secara administratif kewilayahan, Kabupaten Tuban di sebelah timur berbatasan langsung dengan wilayah kabupaten...", "options": ["Kabupaten Lamongan", "Kabupaten Bojonegoro", "Kabupaten Rembang", "Kabupaten Gresik"], "answer": 0, "explanation": "Batas wilayah Kabupaten Tuban: sebelah utara berbatasan dengan Laut Jawa, sebelah timur dengan Kabupaten Lamongan, sebelah selatan dengan Kabupaten Bojonegoro, dan sebelah barat dengan Kabupaten Rembang (Jawa Tengah).", "source": "Profil Wilayah dan Geografi Pemerintah Kabupaten Tuban"}, {"id": 295, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Salah satu objek wisata alam gua yang terkenal di pusat kota Kabupaten Tuban yang terletak di bawah pasar perbelanjaan adalah...", "options": ["Gua Ngerong", "Gua Akbar", "Gua Maharani", "Gua Suci"], "answer": 1, "explanation": "Gua Akbar adalah gua karst alami bersejarah yang terletak persis di bawah Pasar Baru Tuban di pusat kota Tuban.", "source": "Dinas Kebudayaan, Kepemudaan dan Olahraga serta Pariwisata Kab. Tuban"}, {"id": 296, "category": "Pengetahuan umum", "difficulty": "sedang", "question": "Berapakah jumlah kecamatan yang ada di wilayah administratif Kabupaten Tuban?", "options": ["18 kecamatan", "20 kecamatan", "22 kecamatan", "25 kecamatan"], "answer": 1, "explanation": "Kabupaten Tuban terdiri atas 20 kecamatan, 17 kelurahan, dan 311 desa.", "source": "Badan Pusat Statistik (BPS) Kabupaten Tuban Dalam Angka"}, {"id": 297, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Salah satu destinasi wisata alam dan sumber mata air alami di Kabupaten Tuban yang terletak di kawasan hutan lindung dengan air yang jernih dan aliran sungai bertingkat adalah...", "options": ["Mata Air Krawak (Sendang Krawak)", "Kawah Ijen", "Air Terjun Sedudo", "Telaga Sarangan"], "answer": 0, "explanation": "Mata Air Krawak dan Sendang Asmoro (Kecamatan Singgahan/Montong) merupakan objek wisata alam sumber air alami yang terkenal di Kabupaten Tuban, mengalir di antara perbukitan kapur dan hutan jati asri.", "source": "Dinas Kebudayaan, Kepemudaan dan Olahraga serta Pariwisata Kab. Tuban"}, {"id": 298, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Sistem operasi (Operating System) seperti Microsoft Windows atau Linux pada komputer kantor desa memiliki fungsi utama sebagai...", "options": ["Perangkat lunak dasar yang mengelola seluruh perangkat keras (hardware) dan menyediakan antarmuka bagi pengguna untuk menjalankan aplikasi", "Alat pencetak dokumen fisik menjadi lembaran kertas", "Kabel penghubung arus listrik dari stopkontak ke komputer", "Perangkat penyimpan cadangan daya saat listrik PLN padam"], "answer": 0, "explanation": "Sistem Operasi (OS) adalah program sistem komputer yang mengendalikan dan mengoordinasikan perangkat keras (CPU, RAM, Harddisk, I/O) serta menjadi platform tempat aplikasi perkantoran dijalankan.", "source": "Dasar Sistem Komputer & TIK; Standar Kompetensi Kerja Nasional Indonesia (SKKNI)"}, {"id": 299, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Kombinasi tombol keyboard (shortcut) yang digunakan untuk membatalkan tindakan pengeditan terakhir (undo) pada komputer adalah...", "options": ["Ctrl + C", "Ctrl + V", "Ctrl + Z", "Ctrl + Y"], "answer": 2, "explanation": "Ctrl + Z berfungsi untuk Undo (membatalkan perintah terakhir), sedangkan Ctrl + Y untuk Redo.", "source": "Dasar Pengoperasian Komputer Keyboard Shortcuts"}, {"id": 300, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Berdasarkan prinsip pelayanan publik prima dan UU No. 25 Tahun 2009, maklumat pelayanan yang dipasang di kantor desa berfungsi sebagai...", "options": ["Daftar nama perangkat desa yang sedang cuti", "Pernyataan kesanggupan dan janji tertulis penyelenggara pelayanan untuk melaksanakan pelayanan sesuai standar yang ditetapkan", "Surat peringatan bagi warga yang terlambat membayar pajak", "Himbauan untuk tidak mengurus surat secara mandiri"], "answer": 1, "explanation": "Maklumat pelayanan adalah pernyataan kesanggupan dan kewajiban penyelenggara pelayanan publik untuk melaksanakan pelayanan sesuai Standar Pelayanan (SP).", "source": "UU No. 25 Tahun 2009 tentang Pelayanan Publik Pasal 22"}, {"id": 301, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Undang-Undang Nomor 3 Tahun 2024 Pasal 26 ayat (3) dan Pasal 50A, Kepala Desa dan Perangkat Desa berhak menerima jaminan sosial dan tunjangan purnatugas, yang meliputi...", "options": ["Jaminan kesehatan, ketenagakerjaan, dan tunjangan purnatugas 1 kali di akhir masa jabatan sesuai kemampuan keuangan desa", "Gaji pensiun bulanan seumur hidup dari APBN setara PNS pusat", "Kepemilikan permanen tanah kas desa/bengkok tanpa batas waktu", "Bebas dari segala kewajiban hukum pajak dan retribusi daerah"], "answer": 0, "explanation": "UU No. 3 Tahun 2024 secara tegas memperkuat hak Kepala Desa dan Perangkat Desa untuk memperoleh jaminan kesehatan, jaminan ketenagakerjaan, tunjangan purnatugas 1 (satu) kali di akhir masa pengabdian, serta perlindungan hukum kedinasan.", "source": "UU No. 3 Tahun 2024 Pasal 26 ayat (3) dan Pasal 50A"}, {"id": 302, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Menurut UU No. 3 Tahun 2024 Pasal 50A, hak baru apakah yang dijamin undang-undang bagi Perangkat Desa setelah purnatugas?", "options": ["Mendapatkan pensiun bulanan seumur hidup setara PNS golongan IV", "Mendapatkan tunjangan purnatugas 1 (satu) kali di akhir masa jabatan sesuai kemampuan keuangan desa", "Mendapatkan hak kepemilikan penuh tanah kas desa/bengkok tanpa batas waktu", "Mendapatkan prioritas diangkat menjadi anggota legislatif daerah tanpa pemilu"], "answer": 1, "explanation": "UU No. 3 Tahun 2024 menyisipkan Pasal 50A yang mengatur bahwa Perangkat Desa berhak mendapatkan tunjangan purnatugas 1 (satu) kali di akhir masa jabatan yang disesuaikan dengan kemampuan keuangan desa.", "source": "UU No. 3 Tahun 2024 Pasal 50A"}, {"id": 303, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Berdasarkan Permendagri No. 83 Tahun 2015 jo. Permendagri No. 67 Tahun 2017, syarat pendidikan formal minimal untuk diangkat menjadi Perangkat Desa adalah...", "options": ["Sekolah Dasar (SD) atau sederajat", "Sekolah Menengah Pertama (SMP) atau sederajat", "Sekolah Menengah Atas (SMA/SLTA) atau sederajat", "Diploma Tiga (D3) atau Sarjana (S1)"], "answer": 2, "explanation": "Syarat umum pengangkatan perangkat desa menurut Permendagri No. 83 Tahun 2015 Pasal 2 ayat (2) huruf b adalah berpendidikan paling rendah Sekolah Menengah Umum atau yang sederajat.", "source": "Permendagri No. 83 Tahun 2015 Pasal 2 ayat (2) huruf b"}, {"id": 304, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Dalam struktur Sekretariat Desa, pejabat yang bertugas membantu Sekretaris Desa dalam urusan penyusunan RAPBDesa dan evaluasi program pembangunan adalah...", "options": ["Kepala Urusan Tata Usaha dan Umum", "Kepala Urusan Perencanaan", "Kepala Seksi Pembangunan", "Kepala Dusun"], "answer": 1, "explanation": "Permendagri No. 84 Tahun 2015 Pasal 9 mengatur bahwa Kepala Urusan Perencanaan bertugas membantu Sekretaris Desa dalam urusan pelayanan administrasi pendukung tata pemerintahan, mengoordinasikan penyusunan perencanaan desa (RPJM Desa, RKP Desa, RAPBDesa), inventarisasi data pembangunan, dan monitoring evaluasi.", "source": "Permendagri No. 84 Tahun 2015 Pasal 9"}, {"id": 305, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Pembangunan sarana prasarana fisik desa, pembinaan kesehatan masyarakat, dan pendidikan formal/non-formal di desa merupakan tugas dari...", "options": ["Kepala Seksi Kesejahteraan", "Kepala Urusan Keuangan", "Kepala Seksi Pelayanan", "Kepala Urusan Umum"], "answer": 0, "explanation": "Permendagri No. 84 Tahun 2015 Pasal 10 ayat (2) menyebutkan Kepala Seksi Kesejahteraan bertugas melaksanakan pembangunan sarana prasarana perdesaan, pembangunan bidang pendidikan, kesehatan, dan sosialisasi serta motivasi masyarakat di bidang kebudayaan dan ekonomi.", "source": "Permendagri No. 84 Tahun 2015 Pasal 10"}, {"id": 306, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Pelaksanaan pembinaan ketenteraman dusun, pengawasan ketertiban umum, dan mobilisasi warga dalam kegiatan gotong royong di tingkat kewilayahan dipimpin oleh...", "options": ["Sekretaris Desa", "Kepala Dusun (Kasun)", "Kepala Seksi Kesejahteraan", "Ketua Lembaga Pemberdayaan Masyarakat Desa (LPMD)"], "answer": 1, "explanation": "Permendagri No. 84 Tahun 2015 Pasal 12 menjelaskan Kepala Dusun berkedudukan sebagai unsur satuan tugas kewilayahan yang bertugas membantu Kepala Desa dalam pelaksanaan tugas di wilayah kerjanya.", "source": "Permendagri No. 84 Tahun 2015 Pasal 12"}, {"id": 307, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Berdasarkan PP No. 11 Tahun 2019, besaran penghasilan tetap (Siltap) Kepala Desa per bulan paling sedikit setara dengan...", "options": ["100% dari gaji pokok PNS Golongan II/a", "110% dari gaji pokok PNS Golongan II/a", "120% dari gaji pokok PNS Golongan II/a", "150% dari gaji pokok PNS Golongan II/a"], "answer": 2, "explanation": "PP No. 11 Tahun 2019 Pasal 81 ayat (2) huruf a menetapkan besaran penghasilan tetap Kepala Desa paling sedikit Rp2.426.640,00 setara 120% dari gaji pokok Pegawai Negeri Sipil golongan ruang II/a.", "source": "PP No. 11 Tahun 2019 Pasal 81 ayat (2) huruf a"}, {"id": 308, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Berdasarkan Peraturan Pemerintah (PP) Nomor 11 Tahun 2019, sumber utama pendanaan yang digunakan untuk membayar Penghasilan Tetap (Siltap) dan tunjangan Kepala Desa serta Perangkat Desa dianggarkan dalam APB Desa yang bersumber dari...", "options": ["Alokasi Dana Desa (ADD) yang bersumber dari APBD Kabupaten", "Dana Desa (DD) yang bersumber dari APBN", "Iuran swadaya wajib masyarakat dusun", "Pendapatan dari denda penertiban ternak warga"], "answer": 0, "explanation": "PP No. 11 Tahun 2019 Pasal 81 ayat (1) menegaskan bahwa penghasilan tetap Kepala Desa, Sekretaris Desa, dan Perangkat Desa lainnya dianggarkan dalam APB Desa yang bersumber dari Alokasi Dana Desa (ADD).", "source": "PP No. 11 Tahun 2019 Pasal 81 ayat (1)"}, {"id": 309, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Berdasarkan PP No. 11 Tahun 2019, besaran penghasilan tetap (Siltap) Perangkat Desa lainnya (Kaur, Kasi, dan Kasun) per bulan paling sedikit adalah...", "options": ["80% dari gaji pokok PNS Golongan II/a", "90% dari gaji pokok PNS Golongan II/a", "100% dari gaji pokok PNS Golongan II/a", "110% dari gaji pokok PNS Golongan II/a"], "answer": 2, "explanation": "PP No. 11 Tahun 2019 Pasal 81 ayat (2) huruf c menetapkan besaran penghasilan tetap Perangkat Desa lainnya paling sedikit Rp2.022.200,00 setara 100% dari gaji pokok PNS golongan ruang II/a.", "source": "PP No. 11 Tahun 2019 Pasal 81 ayat (2) huruf c"}, {"id": 310, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Dalam tata kelola penatausahaan keuangan desa, Kaur Keuangan (Bendahara Desa) dilarang mencairkan atau membayarkan uang belanja APB Desa apabila...", "options": ["Dokumen transaksi belum diverifikasi oleh Sekretaris Desa dan belum disetujui melalui SPP sah oleh Kepala Desa", "Penerima pembayaran belum menjadi nasabah bank swasta nasional", "Warga dusun belum menghadiri musyawarah khusus", "Kepala BPD sedang tidak berada di kantor balai desa"], "answer": 0, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 51 dan 54 menegaskan bahwa Bendahara Desa hanya dapat membayarkan belanja atas dasar Surat Permintaan Pembayaran (SPP) sah yang telah diverifikasi kelengkapannya oleh Sekretaris Desa dan disetujui Kepala Desa.", "source": "Permendagri No. 20 Tahun 2018 Pasal 51 dan 54"}, {"id": 311, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 67 Tahun 2017, usia maksimal seorang Perangkat Desa untuk purnatugas (pemberhentian dengan hormat karena usia) adalah...", "options": ["Genap berusia 56 tahun", "Genap berusia 58 tahun", "Genap berusia 60 tahun", "Genap berusia 65 tahun"], "answer": 2, "explanation": "Permendagri No. 67 Tahun 2017 Pasal 5 ayat (2) huruf b menyatakan bahwa Perangkat Desa diberhentikan karena telah berusia genap 60 (enam puluh) tahun.", "source": "Permendagri No. 67 Tahun 2017 Pasal 5 ayat (2) huruf b"}, {"id": 312, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 67 Tahun 2017, dalam hal seorang Perangkat Desa ditetapkan sebagai tersangka tindak pidana korupsi, tindakan yang wajib diambil oleh Kepala Desa adalah...", "options": ["Memberhentikan secara tetap tanpa menunggu proses hukum", "Memberhentikan sementara sampai ada putusan pengadilan berkekuatan hukum tetap", "Memindahkannya ke dusun lain yang terpencil", "Membiarkan tetap aktif bertugas hingga dinyatakan vonis bersalah"], "answer": 1, "explanation": "Permendagri No. 67 Tahun 2017 Pasal 6 mengatur bahwa Perangkat Desa diberhentikan sementara oleh Kepala Desa setelah ditetapkan sebagai tersangka dalam tindak pidana korupsi, terorisme, makar, atau tindak pidana terhadap keamanan negara.", "source": "Permendagri No. 67 Tahun 2017 Pasal 6"}, {"id": 313, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sulit", "question": "Berapakah jangka waktu maksimal bagi Camat untuk memberikan rekomendasi tertulis terhadap calon Perangkat Desa yang lolos penyaringan seleksi?", "options": ["3 hari kerja", "7 hari kerja", "14 hari kerja", "30 hari kerja"], "answer": 1, "explanation": "Permendagri No. 83 Tahun 2015 jo. Permendagri No. 67 Tahun 2017 Pasal 4 mengatur bahwa Camat memberikan rekomendasi tertulis paling lambat 7 (tujuh) hari kerja sejak diterimanya permohonan konsultasi dari Kepala Desa.", "source": "Permendagri No. 83 Tahun 2015 Pasal 4 ayat (4)"}, {"id": 314, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 84 Tahun 2015, susunan organisasi pemerintah desa untuk Desa Swasembada wajib memiliki paling banyak...", "options": ["2 Kaur dan 2 Kasi", "3 Kaur dan 2 Kasi", "3 Kaur dan 3 Kasi", "4 Kaur dan 4 Kasi"], "answer": 2, "explanation": "Permendagri No. 84 Tahun 2015 Pasal 3 mengatur bahwa desa swasembada wajib memiliki 3 urusan dan 3 seksi (3 Kaur dan 3 Kasi), sedangkan desa swakarya dapat 3 atau 2, dan desa swadaya maksimal 2 urusan dan 2 seksi.", "source": "Permendagri No. 84 Tahun 2015 Pasal 3"}, {"id": 315, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "UU No. 6 Tahun 2014 Pasal 51 huruf a menegaskan larangan bagi Perangkat Desa untuk merugikan kepentingan umum. Selain itu, perangkat desa dilarang merangkap jabatan sebagai...", "options": ["Pengurus takmir masjid desa", "Anggota BPD, DPR/DPD/DPRD, dan jabatan lain yang dilarang undang-undang", "Anggota kelompok tani desa", "Pengurus paguyuban rukun tetangga"], "answer": 1, "explanation": "UU No. 6 Tahun 2014 Pasal 51 huruf f melarang perangkat desa merangkap jabatan sebagai ketua atau anggota BPD, anggota DPR RI, DPD RI, DPRD Provinsi, DPRD Kabupaten/Kota, dan jabatan lain yang diatur peraturan perundang-undangan.", "source": "UU No. 6 Tahun 2014 Pasal 51 huruf f"}, {"id": 316, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Kepala Urusan Tata Usaha dan Umum dalam menjalankan tugasnya bertanggung jawab langsung kepada...", "options": ["Kepala Seksi Pemerintahan", "Sekretaris Desa", "Ketua BPD", "Camat"], "answer": 1, "explanation": "Permendagri No. 84 Tahun 2015 mengatur bahwa Kepala Urusan (Kaur) berada di bawah dan bertanggung jawab kepada Sekretaris Desa sebagai pimpinan sekretariat desa.", "source": "Permendagri No. 84 Tahun 2015 Pasal 8 ayat (1)"}, {"id": 317, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Perda Kabupaten Tuban No. 2 Tahun 2016 jo. No. 16 Tahun 2021, pengangkatan Perangkat Desa dilakukan secara resmi dengan penerbitan...", "options": ["Surat Keputusan Camat", "Keputusan Kepala Desa", "Peraturan Desa", "Surat Perintah Kerja dari BPD"], "answer": 1, "explanation": "Perda Kab. Tuban No. 2/2016 jo. 16/2021 mengatur bahwa Perangkat Desa diangkat oleh Kepala Desa dengan Keputusan Kepala Desa setelah mendapatkan rekomendasi tertulis dari Camat.", "source": "Perda Kab. Tuban No. 2/2016 jo. No. 16/2021 Pasal 12"}, {"id": 318, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Kepada siapakah Kepala Desa wajib menyampaikan Laporan Penyelenggaraan Pemerintahan Desa (LPPD) tertulis pada setiap akhir tahun anggaran?", "options": ["Kepada BPD secara langsung", "Kepada Bupati melalui Camat", "Kepada seluruh pengurus RT/RW", "Kepada Menteri Desa PDTT"], "answer": 1, "explanation": "Berdasarkan UU No. 6 Tahun 2014 Pasal 27 huruf a, Kepala Desa wajib menyampaikan Laporan Penyelenggaraan Pemerintahan Desa (LPPD) kepada Bupati/Walikota melalui Camat paling lambat 3 bulan setelah akhir tahun anggaran.", "source": "UU No. 6 Tahun 2014 Pasal 27 huruf a"}, {"id": 319, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Laporan pertanggungjawaban penyelenggaraan pemerintahan desa yang disampaikan oleh Kepala Desa kepada Badan Permusyawaratan Desa (BPD) disebut...", "options": ["Laporan Keterangan Penyelenggaraan Pemerintahan Desa (LKPPD)", "Laporan Penyelenggaraan Pemerintahan Desa (LPPD)", "Informasi Penyelenggaraan Pemerintahan Desa (IPPD)", "Laporan Kinerja Instansi Pemerintah (LKjIP)"], "answer": 0, "explanation": "Berdasarkan UU No. 6 Tahun 2014 Pasal 27 huruf b dan Permendagri No. 46 Tahun 2016, laporan yang wajib disampaikan Kades kepada BPD secara tertulis adalah LKPPD (Laporan Keterangan Penyelenggaraan Pemerintahan Desa).", "source": "UU No. 6 Tahun 2014 Pasal 27 huruf b & Permendagri No. 46 Tahun 2016"}, {"id": 320, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Informasi Penyelenggaraan Pemerintahan Desa (IPPD) wajib dipublikasikan oleh Kepala Desa kepada masyarakat melalui...", "options": ["Pemberitahuan surat rahasia tertutup kepada tokoh masyarakat tertentu", "Papan pengumuman desa, radio komunitas, atau media informasi resmi desa lainnya yang mudah diakses warga", "Pemberitahuan lisan saat rapat tertutup perangkat desa", "Grup perpesanan pribadi perangkat desa"], "answer": 1, "explanation": "Permendagri No. 46 Tahun 2016 Pasal 10 mengatur bahwa Informasi Penyelenggaraan Pemerintahan Desa (IPPD) disampaikan kepada masyarakat desa melalui media informasi yang mudah diakses masyarakat, seperti papan pengumuman, media cetak, atau media elektronik.", "source": "Permendagri No. 46 Tahun 2016 Pasal 10"}, {"id": 321, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "mudah", "question": "Berdasarkan Undang-Undang No. 12 Tahun 2011 Pasal 7 ayat (1), peraturan hukum yang menempati hierarki tertinggi di Negara Kesatuan Republik Indonesia adalah...", "options": ["Undang-Undang / Peraturan Pemerintah Pengganti Undang-Undang", "Ketetapan Majelis Permusyawaratan Rakyat (TAP MPR)", "Undang-Undang Dasar Negara Republik Indonesia Tahun 1945", "Peraturan Presiden"], "answer": 2, "explanation": "UU No. 12 Tahun 2011 Pasal 7 ayat (1) menyatakan jenis dan hierarki peraturan perundang-undangan di Indonesia berturut-turut adalah: 1. UUD 1945, 2. Tap MPR, 3. UU/Perppu, 4. Peraturan Pemerintah, 5. Peraturan Presiden, 6. Perda Provinsi, 7. Perda Kabupaten/Kota.", "source": "UU No. 12 Tahun 2011 Pasal 7 ayat (1)"}, {"id": 322, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Berdasarkan Undang-Undang Nomor 12 Tahun 2011 Pasal 15, materi muatan tentang ketentuan sanksi pidana (kurungan atau denda) hanya dapat dimuat dalam peraturan perundang-undangan tingkat...", "options": ["Undang-Undang, Peraturan Daerah Provinsi, dan Peraturan Daerah Kabupaten/Kota", "Peraturan Desa dan Peraturan Kepala Desa", "Peraturan Menteri dan Keputusan Camat", "Semua tingkatan produk hukum tanpa terkecuali"], "answer": 0, "explanation": "Pasal 15 UU No. 12 Tahun 2011 menegaskan materi muatan mengenai sanksi pidana hanya boleh dimuat dalam Undang-Undang dan Peraturan Daerah (Provinsi/Kabupaten/Kota). Perdes dilarang memuat sanksi pidana kurungan.", "source": "UU No. 12 Tahun 2011 Pasal 15"}, {"id": 323, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 111 Tahun 2014, Badan Permusyawaratan Desa (BPD) berhak mengajukan usulan Rancangan Peraturan Desa inisiatif, KECUALI terhadap rancangan perdes tentang...", "options": ["Rancangan Perdes tentang RPJM Desa, RKP Desa, APB Desa, dan Laporan Pertanggungjawaban Realisasi APB Desa", "Rancangan Perdes tentang Pelestarian Sumber Air Desa", "Rancangan Perdes tentang Pengelolaan Sampah Dusun", "Rancangan Perdes tentang Penertiban Hewan Liar"], "answer": 0, "explanation": "Permendagri No. 111 Tahun 2014 Pasal 8 mengatur BPD berhak mengusulkan rancangan Perdes, kecuali untuk rancangan RPJM Desa, RKP Desa, APB Desa, dan LPJ Realisasi APB Desa yang merupakan wewenang mutlak Pemerintah Desa.", "source": "Permendagri No. 111 Tahun 2014 Pasal 8"}, {"id": 324, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "mudah", "question": "Media publikasi resmi pemerintah desa yang digunakan untuk mengundangkan Peraturan Desa (Perdes) agar memiliki kekuatan hukum berlaku adalah...", "options": ["Berita Desa", "Lembaran Desa", "Lembaran Daerah", "Papan Pengumuman Dusun"], "answer": 1, "explanation": "Permendagri No. 111 Tahun 2014 Pasal 22 mengatur bahwa Peraturan Desa diundangkan dalam Lembaran Desa oleh Sekretaris Desa.", "source": "Permendagri No. 111 Tahun 2014 Pasal 22"}, {"id": 325, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "mudah", "question": "Peraturan Kepala Desa (Perkades) yang bersifat pengaturan teknis operasional mulai berlaku sah dan memiliki kekuatan hukum mengikat sejak...", "options": ["Tanggal diundangkannya dalam Berita Desa oleh Sekretaris Desa", "Tanggal diucapkannya pidato oleh Kepala Desa di balai desa", "Tanggal disetujuinya oleh rapat keluarga Kepala Desa", "Tiga tahun setelah tanggal penetapan"], "answer": 0, "explanation": "Permendagri No. 111 Tahun 2014 Pasal 24 ayat (2) menyatakan bahwa Peraturan Kepala Desa mulai berlaku dan mempunyai kekuatan hukum mengikat sejak tanggal diundangkan dalam Berita Desa oleh Sekretaris Desa.", "source": "Permendagri No. 111 Tahun 2014 Pasal 24"}, {"id": 326, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Asas pembentukan peraturan perundang-undangan yang mewajibkan setiap regulasi memiliki tujuan yang jelas dan pasti untuk apa dibentuk disebut...", "options": ["Asas kejelasan tujuan", "Asas organ pembentuk yang tepat", "Asas kejelasan rumusan", "Asas keterbukaan"], "answer": 0, "explanation": "UU No. 12 Tahun 2011 Pasal 5 huruf a menjelaskan asas 'kejelasan tujuan' bermakna bahwa setiap pembentukan peraturan perundang-undangan harus mempunyai tujuan yang jelas yang hendak dicapai.", "source": "UU No. 12 Tahun 2011 Pasal 5 huruf a"}, {"id": 327, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Menurut UU No. 6 Tahun 2014 Pasal 69 ayat (2), materi muatan Peraturan Desa dilarang bertentangan dengan...", "options": ["Hasil rapat internal partai politik pemenang pemilu", "Kepentingan umum dan peraturan perundang-undangan yang lebih tinggi", "Kebijakan kepala desa periode sebelumnya", "Opini yang berkembang di media sosial desa"], "answer": 1, "explanation": "UU No. 6 Tahun 2014 Pasal 69 ayat (2) menegaskan bahwa Peraturan Desa dilarang bertentangan dengan kepentingan umum dan/atau ketentuan peraturan perundang-undangan yang lebih tinggi.", "source": "UU No. 6 Tahun 2014 Pasal 69 ayat (2)"}, {"id": 328, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sulit", "question": "Berdasarkan Permendagri No. 111 Tahun 2014 dan Permendagri No. 20 Tahun 2018, hasil evaluasi Camat atas Rancangan Peraturan Desa tentang APB Desa wajib disampaikan kepada Kepala Desa paling lambat...", "options": ["20 (dua puluh) hari kerja sejak diterimanya rancangan peraturan desa oleh Camat", "3 hari kerja sejak pengajuan", "60 hari kalender tanpa batasan", "6 bulan setelah tahun anggaran dimulai"], "answer": 0, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 38 ayat (2) menetapkan bahwa evaluasi rancangan Perdes APB Desa oleh bupati/camat dilakukan paling lama 20 (dua puluh) hari kerja sejak diterima.", "source": "Permendagri No. 111 Tahun 2014 Pasal 13 jo. Permendagri No. 20 Tahun 2018 Pasal 38"}, {"id": 329, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Berdasarkan UU No. 12 Tahun 2011, asas yang menghendaki agar setiap pembentukan regulasi melibatkan masyarakat secara bermakna (meaningful participation) disebut...", "options": ["Asas legalitas", "Asas keterbukaan", "Asas praduga tak bersalah", "Asas sentralisasi wewenang"], "answer": 1, "explanation": "Asas keterbukaan (Pasal 5 huruf g UU 12/2011) menuntut agar pembentukan regulasi mulai dari perencanaan hingga pengundangan bersifat transparan dan memberi ruang partisipasi bagi publik.", "source": "UU No. 12 Tahun 2011 Pasal 5 huruf g"}, {"id": 330, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Di Kabupaten Tuban, peraturan bupati yang mengatur petunjuk teknis seleksi pengangkatan dan pemberhentian perangkat desa adalah...", "options": ["Peraturan Bupati Tuban No. 11 Tahun 2022", "Peraturan Bupati Tuban No. 50 Tahun 2010", "Peraturan Daerah Tuban No. 1 Tahun 2005", "Instruksi Camat Tuban No. 3 Tahun 2020"], "answer": 0, "explanation": "Perbup Tuban No. 11 Tahun 2022 merupakan pedoman teknis yang mengatur pelaksanaan pengangkatan dan pemberhentian perangkat desa di seluruh wilayah Kabupaten Tuban.", "source": "Peraturan Bupati Tuban No. 11 Tahun 2022"}, {"id": 331, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Berdasarkan UU No. 30 Tahun 2014 tentang Administrasi Pemerintahan, asas yang melarang pejabat pemerintah memihak dan mewajibkan pelayanan yang netral adalah...", "options": ["Asas Ketidakberpihakan (Impartiality)", "Asas Kemanfaatan", "Asas Otonomi Daerah", "Asas Efisiensi Anggaran"], "answer": 0, "explanation": "UU No. 30 Tahun 2014 Pasal 10 ayat (1) huruf c mengatur Asas Ketidakberpihakan, yaitu asas yang mewajibkan Badan dan/atau Pejabat Pemerintahan dalam menetapkan dan/atau melakukan keputusan dan/atau tindakan dengan mempertimbangkan kepentingan para pihak secara keseluruhan dan tidak diskriminatif.", "source": "UU No. 30 Tahun 2014 Pasal 10 ayat (1) huruf c"}, {"id": 332, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Sanksi apakah yang dapat dijatuhkan apabila suatu Peraturan Desa terbukti bertentangan dengan peraturan perundang-undangan yang lebih tinggi?", "options": ["Pembatalan Peraturan Desa melalui Keputusan Bupati", "Pemberian denda uang tunai kepada seluruh warga desa", "Penghapusan status otonomi desa menjadi kelurahan seketika", "Pembubaran BPD dan pelantikan perangkat desa baru"], "answer": 0, "explanation": "Permendagri No. 111 Tahun 2014 dan UU No. 6 Tahun 2014 mengatur bahwa Peraturan Desa yang bertentangan dengan kepentingan umum dan peraturan yang lebih tinggi dibatalkan oleh Bupati/Walikota melalui Keputusan Bupati/Walikota.", "source": "Permendagri No. 111 Tahun 2014 Pasal 26"}, {"id": 333, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Perangkat desa yang memfasilitasi izin perayaan hari besar seluruh agama warga tanpa membeda-bedakan keyakinan merupakan wujud pengamalan Pancasila sila ke-...", "options": ["Pertama: Ketuhanan Yang Maha Esa", "Kedua: Kemanusiaan yang Adil dan Beradab", "Ketiga: Persatuan Indonesia", "Kelima: Keadilan Sosial bagi Seluruh Rakyat Indonesia"], "answer": 0, "explanation": "Mengembangkan sikap toleransi dan membina kerukunan antarumat beragama merupakan butir pokok pengamalan Sila ke-1 Pancasila: Ketuhanan Yang Maha Esa.", "source": "Ketetapan MPR No. I/MPR/2003 Butir Pengamalan Sila 1"}, {"id": 334, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Aksi tanggap darurat aparatur desa bersama warga menggalang bantuan pangan bagi keluarga prasejahtera yang terdampak banjir luapan sungai mencerminkan pengamalan Pancasila sila ke-...", "options": ["Pertama", "Kedua", "Keempat", "Kelima"], "answer": 1, "explanation": "Gemar melakukan kegiatan kemanusiaan dan menjunjung tinggi nilai-nilai kemanusiaan sesama manusia merupakan pengamalan Sila ke-2: Kemanusiaan yang Adil dan Beradab.", "source": "Ketetapan MPR No. I/MPR/2003 Butir Pengamalan Sila 2"}, {"id": 335, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Sikap mendahulukan kepentingan bersama desa di atas kepentingan pribadi, keluarga, atau dusun sendiri merupakan pengamalan sila ke-...", "options": ["Pertama", "Kedua", "Ketiga", "Keempat"], "answer": 2, "explanation": "Menempatkan persatuan, kesatuan, serta kepentingan dan keselamatan bangsa/masyarakat di atas kepentingan pribadi atau golongan merupakan butir Sila ke-3: Persatuan Indonesia.", "source": "Ketetapan MPR No. I/MPR/2003 Butir Pengamalan Sila 3"}, {"id": 336, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Pengambilan keputusan pembangunan jembatan desa melalui musyawarah mufakat di Balai Desa tanpa memaksakan kehendak kelompok mayoritas merupakan pengamalan sila ke-...", "options": ["Kedua", "Ketiga", "Keempat", "Kelima"], "answer": 2, "explanation": "Musyawarah untuk mufakat yang diliputi oleh semangat kekeluargaan dan tidak memaksakan kehendak kepada orang lain merupakan wujud nyata pengamalan Sila ke-4 Pancasila.", "source": "Ketetapan MPR No. I/MPR/2003 Butir Pengamalan Sila 4"}, {"id": 337, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Penyaluran Bantuan Langsung Tunai (BLT) Desa secara transparan, tepat sasaran kepada warga miskin tanpa nepotisme mencerminkan pengamalan sila ke-...", "options": ["Kedua", "Ketiga", "Keempat", "Kelima"], "answer": 3, "explanation": "Mengembangkan perbuatan luhur yang mencerminkan sikap kekeluargaan dan gotong royong serta menjaga keseimbangan antara hak dan kewajiban secara adil merupakan butir Sila ke-5: Keadilan Sosial bagi Seluruh Rakyat Indonesia.", "source": "Ketetapan MPR No. I/MPR/2003 Butir Pengamalan Sila 5"}, {"id": 338, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Tujuan negara Republik Indonesia untuk 'mencerdaskan kehidupan bangsa' dan 'memajukan kesejahteraan umum' tercantum secara tegas di dalam...", "options": ["Pembukaan UUD NRI 1945 Alinea I", "Pembukaan UUD NRI 1945 Alinea II", "Pembukaan UUD NRI 1945 Alinea III", "Pembukaan UUD NRI 1945 Alinea IV"], "answer": 3, "explanation": "Alinea IV Pembukaan UUD 1945 memuat 4 tujuan negara Indonesia: melindungi segenap bangsa dan seluruh tumpah darah, memajukan kesejahteraan umum, mencerdaskan kehidupan bangsa, dan ikut melaksanakan ketertiban dunia.", "source": "Pembukaan UUD 1945 Alinea IV"}, {"id": 339, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Pasal di dalam UUD 1945 yang secara khusus mengakui dan menghormati kesatuan-kesatuan masyarakat hukum adat beserta hak-hak tradisionalnya sepanjang masih hidup adalah...", "options": ["Pasal 18B ayat (2)", "Pasal 27 ayat (3)", "Pasal 30 ayat (1)", "Pasal 33 ayat (1)"], "answer": 0, "explanation": "UUD 1945 Pasal 18B ayat (2) menyatakan: 'Negara mengakui dan menghormati kesatuan-kesatuan masyarakat hukum adat serta hak-hak tradisionalnya sepanjang masih hidup dan sesuai dengan perkembangan masyarakat dan prinsip NKRI'.", "source": "UUD 1945 Pasal 18B ayat (2)"}, {"id": 340, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "UUD 1945 Pasal 27 ayat (1) mengatur tentang prinsip persamaan warga negara, yaitu bahwa segala warga negara bersamaan kedudukannya di dalam...", "options": ["Ekonomi dan perdagangan", "Hukum dan pemerintahan", "Organisasi kemasyarakatan", "Pendidikan tinggi dan profesi"], "answer": 1, "explanation": "Pasal 27 ayat (1) UUD 1945 berbunyi: 'Segala warga negara bersamaan kedudukannya di dalam hukum dan pemerintahan dan wajib menjunjung hukum dan pemerintahan itu dengan tidak ada kecualinya'.", "source": "UUD 1945 Pasal 27 ayat (1)"}, {"id": 341, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Landasan konstitusional yang menjadi dasar penyelenggaraan jaring pengaman sosial di desa (Pasal 34 ayat 1 UUD 1945) menyatakan bahwa...", "options": ["Bumi dan air dikuasai oleh pengusaha swasta", "Fakir miskin dan anak-anak terlantar dipelihara oleh negara", "Pendidikan dasar dipungut biaya sesuai kesepakatan", "Tiap warga negara wajib menjadi anggota kepolisian"], "answer": 1, "explanation": "Pasal 34 ayat (1) UUD 1945 menyatakan: 'Fakir miskin dan anak-anak yang terlantar dipelihara oleh negara'. Ini menjadi fondasi dasar bantuan sosial kemasyarakatan di desa.", "source": "UUD 1945 Pasal 34 ayat (1)"}, {"id": 342, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Konsep geopolitik Indonesia yang memandang tanah air Indonesia sebagai satu kesatuan utuh politik, ekonomi, sosial budaya, dan pertahanan keamanan disebut...", "options": ["Ketahanan Nasional", "Wawasan Nusantara", "Bhinneka Tunggal Ika", "Sumpah Palapa"], "answer": 1, "explanation": "Wawasan Nusantara adalah cara pandang bangsa Indonesia tentang diri dan lingkungannya berdasarkan Pancasila dan UUD 1945 sebagai satu kesatuan utuh kepulauan nusantara.", "source": "Doktrin Dasar Wawasan Nusantara Lemhannas"}, {"id": 343, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Berdasarkan Permendagri No. 47 Tahun 2016, buku administrasi desa yang digunakan untuk mencatat surat masuk dan surat keluar secara berurutan tanggal penerimaan dan pengiriman adalah...", "options": ["Buku Agenda", "Buku Kas Umum", "Buku Mutasi Penduduk", "Buku Inventaris Desa"], "answer": 0, "explanation": "Permendagri No. 47 Tahun 2016 mengatur Buku Agenda sebagai buku administrasi umum untuk mencatat keluar masuknya surat dinas secara tertib.", "source": "Permendagri No. 47 Tahun 2016 Lampiran Buku Administrasi Umum"}, {"id": 344, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Dalam tata persuratan desa, buku administrasi umum yang digunakan untuk mencatat seluruh surat dinas yang diterima oleh pemerintah desa secara kronologis disebut...", "options": ["Buku Agenda Surat Masuk", "Buku Notula Musyawarah", "Buku Kas Pembantu Bank", "Buku Tamu Umum"], "answer": 0, "explanation": "Buku Agenda Surat Masuk mencatat nomor urut, tanggal penerimaan, tanggal dan nomor surat masuk, instansi pengirim, perihal/isi ringkas surat, dan disposisi tindak lanjut.", "source": "Permendagri No. 47 Tahun 2016 tentang Administrasi Pemerintahan Desa"}, {"id": 345, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Buku administrasi umum yang digunakan untuk mencatat identitas lengkap, nomor SK pengangkatan, dan riwayat pendidikan seluruh perangkat desa adalah...", "options": ["Buku Induk Penduduk", "Buku Aparat Pemerintah Desa", "Buku Kader Pemberdayaan", "Buku Data Inventaris Aset"], "answer": 1, "explanation": "Buku Aparat Pemerintah Desa memuat data nama, jenis kelamin, jabatan, nomor dan tanggal pengangkatan/pelantikan, serta keterangan pendidikan seluruh aparatur desa.", "source": "Permendagri No. 47 Tahun 2016"}, {"id": 346, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Dalam administrasi kependudukan desa, peristiwa mutasi penduduk yang wajib dicatat di Buku Mutasi Penduduk meliputi...", "options": ["Kelahiran, kematian, kepindahan, dan kedatangan penduduk", "Pernikahan, perceraian, dan pembelian kendaraan", "Pelunasan pajak PBB dan arisan warga", "Perubahan warna cat rumah warga"], "answer": 0, "explanation": "Buku Data Mutasi Penduduk Desa mencatat empat peristiwa vital perubahan demografi: kelahiran, kematian, pindah datang, dan pindah pergi.", "source": "Permendagri No. 47 Tahun 2016 Lampiran Administrasi Penduduk"}, {"id": 347, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Pada kepala surat (kop surat) resmi Pemerintah Desa di Kabupaten Tuban, letak lambang daerah Kabupaten Tuban diposisikan di...", "options": ["Sebelah kiri atas kepala surat", "Sebelah kanan bawah surat", "Tengah-tengah halaman belakang surat", "Kiri bawah tepat di atas tanda tangan kades"], "answer": 0, "explanation": "Sesuai tata naskah dinas pemerintah daerah dan desa, lambang daerah kabupaten diletakkan di sisi kiri atas kop surat dinas resmi.", "source": "Pedoman Tata Naskah Dinas Permendagri No. 1 Tahun 2023"}, {"id": 348, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Penulisan bagian 'Tembusan' yang benar dan baku pada naskah dinas resmi pemerintah desa adalah...", "options": ["Tembusan Yth. Bapak Camat Tuban di tempat.", "Tembusan disampaikan kepada c.c. Yth. Camat.", "Tembusan: 1. Camat Tuban; 2. Ketua BPD", "C.C.: Kepada Yang Terhormat Bapak Camat"], "answer": 2, "explanation": "Aturan tata naskah dinas baku: kata 'Tembusan' diikuti tanda titik dua (:) tanpa menambahkan kata 'Yth.' atau 'kepada' atau singkatan 'c.c.', melainkan langsung nomor urut dan nama jabatan pejabat yang ditembuskan.", "source": "Tata Naskah Dinas Kemendagri"}, {"id": 349, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Dalam penomoran surat resmi desa (contoh: 140/012/414.300.01/2026), angka '140' pada urutan pertama umumnya menunjukkan...", "options": ["Nomor urut buku agenda surat", "Kode klasifikasi masalah surat (Pemerintahan)", "Jumlah halaman lampiran surat", "Tahun pembuatan naskah dinas"], "answer": 1, "explanation": "Angka urutan awal pada nomor surat dinas menunjukkan kode klasifikasi arsip/masalah (kode 140 merupakan kode klasifikasi urusan pemerintahan desa).", "source": "Permendagri No. 83 Tahun 2022 tentang Kode Klasifikasi Arsip"}, {"id": 350, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Arsip kantor desa yang frekuensi penggunaannya telah menurun tetapi masih disimpan karena masih memiliki nilai guna administrasi atau hukum disebut...", "options": ["Arsip dinamis aktif", "Arsip dinamis inaktif", "Arsip statis permanen", "Arsip musnah"], "answer": 1, "explanation": "UU No. 43 Tahun 2009 tentang Kearsipan membedakan arsip dinamis aktif (masih sering dipakai) dan arsip dinamis inaktif (frekuensi penggunaan menurun tetapi masih disimpan sesuai retensi).", "source": "UU No. 43 Tahun 2009 tentang Kearsipan Pasal 1"}, {"id": 351, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Bagian dari Surat Keputusan (SK) Kepala Desa yang memuat pertimbangan latar belakang atau alasan perlunya keputusan diterbitkan diawali dengan kata...", "options": ["Mengingat :", "Menimbang :", "Memutuskan :", "Menetapkan :"], "answer": 1, "explanation": "Bagian konsiderans diawali kata 'Menimbang:' yang memuat pokok-pokok pikiran, latar belakang, dan alasan perlunya diterbitkannya keputusan tersebut.", "source": "Tata Naskah Dinas Surat Keputusan Kemendagri"}, {"id": 352, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Jadwal Retensi Arsip (JRA) di kantor desa berfungsi sebagai pedoman untuk...", "options": ["Menentukan jangka waktu penyimpanan dan nasib akhir suatu arsip (dimusnahkan atau dipermanenkan)", "Menghitung jumlah gaji perangkat desa setiap bulan", "Mencatat kehadiran apel pagi pegawai desa", "Menentukan giliran piket ronda malam dusun"], "answer": 0, "explanation": "Jadwal Retensi Arsip (JRA) adalah daftar yang memuat sekurang-kurangnya jangka waktu penyimpanan atau retensi, jenis arsip, dan rekomendasi nasib akhir arsip.", "source": "UU No. 43 Tahun 2009 Pasal 1 angka 23"}, {"id": 353, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "mudah", "question": "Pemerintah Desa memasang banner/baliho rincian ringkasan APB Desa di depan kantor desa dan memuatnya di situs web desa. Hal ini merupakan wujud penerapan asas...", "options": ["Transparan (Keterbukaan)", "Kerahasiaan fiskal", "Otoritas mutlak kades", "Sentralisasi anggaran"], "answer": 0, "explanation": "Asas transparan (Permendagri No. 20 Tahun 2018 Pasal 2) menuntut pengelolaan keuangan desa terbuka bagi masyarakat untuk mengetahui dan mendapatkan akses informasi seluas-luasnya.", "source": "Permendagri No. 20 Tahun 2018 Pasal 2"}, {"id": 354, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 20 Tahun 2018, siapakah yang bertindak selaku Koordinator Pengelola Keuangan Desa (PPKD)?", "options": ["Kepala Desa", "Sekretaris Desa", "Kaur Keuangan", "Ketua BPD"], "answer": 1, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 5 menegaskan bahwa Sekretaris Desa bertindak selaku Koordinator PPKD yang memverifikasi seluruh DPA, RAK, dan SPP.", "source": "Permendagri No. 20 Tahun 2018 Pasal 5"}, {"id": 355, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Siapakah yang bertindak sebagai Pelaksana Kegiatan Anggaran (PKA) dalam pelaksanaan kegiatan APB Desa sesuai dengan bidang tugasnya?", "options": ["Kepala Urusan dan Kepala Seksi", "Bupati dan Camat", "Ketua BPD dan Anggota BPD", "Pengurus BUMDes"], "answer": 0, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 6 menetapkan bahwa Kepala Urusan (Kaur) dan Kepala Seksi (Kasi) bertindak sebagai Pelaksana Kegiatan Anggaran (PKA).", "source": "Permendagri No. 20 Tahun 2018 Pasal 6"}, {"id": 356, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Sebelum Kaur Keuangan membayarkan uang belanja kegiatan APB Desa, Pelaksana Kegiatan Anggaran (PKA) wajib mengajukan dokumen...", "options": ["Surat Keputusan Camat", "Surat Permintaan Pembayaran (SPP) yang diverifikasi Sekretaris Desa", "Nota kesepakatan partai politik", "Laporan audit dari BPK"], "answer": 1, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 51 mengatur bahwa pengeluaran atas beban APB Desa dilakukan setelah PKA mengajukan SPP yang diverifikasi oleh Sekretaris Desa dan disetujui Kepala Desa.", "source": "Permendagri No. 20 Tahun 2018 Pasal 51"}, {"id": 357, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Berdasarkan PP No. 11 Tahun 2019 Pasal 100, batas paling banyak anggaran belanja desa yang boleh dialokasikan untuk Siltap, tunjangan, operasional pemdes, BPD, dan insentif RT/RW adalah...", "options": ["Paling banyak 20% dari total belanja APB Desa", "Paling banyak 30% dari total belanja APB Desa", "Paling banyak 50% dari total belanja APB Desa", "Paling banyak 70% dari total belanja APB Desa"], "answer": 1, "explanation": "PP No. 11 Tahun 2019 Pasal 100 mengatur komposisi belanja APB Desa: paling banyak 30% untuk siltap & operasional, dan paling sedikit 70% untuk mendanai pembangunan, pemberdayaan, dan kemasyarakatan.", "source": "PP No. 11 Tahun 2019 Pasal 100 ayat (1) huruf a"}, {"id": 358, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Dalam struktur APB Desa, apabila total estimasi belanja desa lebih besar daripada total estimasi pendapatan desa, maka kondisi anggaran tersebut mengalami...", "options": ["Defisit anggaran, yang ditutup melalui pos Penerimaan Pembiayaan", "Surplus anggaran, yang dibagikan tunai kepada warga desa", "Keseimbangan mutlak tanpa sisa", "Kebangkrutan administrasi desa"], "answer": 0, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 13 mengatur bahwa selisih antara Pendapatan Desa dan Belanja Desa menghasilkan surplus atau defisit. Bila belanja lebih besar daripada pendapatan maka terjadi defisit, yang ditutup melalui pos Penerimaan Pembiayaan (misal SiLPA tahun sebelumnya).", "source": "Permendagri No. 20 Tahun 2018 Pasal 13 dan 26"}, {"id": 359, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 1 Tahun 2016 tentang Pengelolaan Aset Desa, jangka waktu maksimal penyewaan tanah kas desa/tanah bengkok kepada pihak lain adalah...", "options": ["Paling lama 1 tahun", "Paling lama 3 tahun dan dapat diperpanjang", "Paling lama 10 tahun tanpa perpanjangan", "Paling lama 25 tahun"], "answer": 1, "explanation": "Permendagri No. 1 Tahun 2016 Pasal 11 ayat (3) mengatur bahwa jangka waktu sewa aset desa paling lama 3 (tiga) tahun dan dapat diperpanjang.", "source": "Permendagri No. 1 Tahun 2016 Pasal 11 ayat (3)"}, {"id": 360, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "mudah", "question": "Manakah di antara pernyataan berikut mengenai aset desa yang dilarang keras oleh peraturan perundang-undangan?", "options": ["Aset desa dicatat dalam buku inventaris kekayaan desa", "Tanah kas desa disewakan kepada kelompok tani desa selama 2 tahun", "Aset desa digadaikan atau dijadikan jaminan untuk pinjaman pribadi kepala desa/perangkat", "Kendaraan dinas desa dirawat secara berkala menggunakan anggaran operasional"], "answer": 2, "explanation": "Permendagri No. 1 Tahun 2016 Pasal 15 tegas melarang aset desa digadaikan, dipindahtangankan, atau dijadikan jaminan untuk mendapatkan pinjaman.", "source": "Permendagri No. 1 Tahun 2016 Pasal 15"}, {"id": 361, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 20 Tahun 2018, Surat Permintaan Pembayaran (SPP) yang diajukan oleh Pelaksana Kegiatan Anggaran untuk memperoleh uang muka kerja guna mendanai kegiatan operasional lapangan dinamakan...", "options": ["SPP Panjar (Uang Muka)", "SPP Definitif", "Surat Kuasa Khusus", "Kuitansi Pelunasan Total"], "answer": 0, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 51 ayat (2) menyebutkan jenis pengajuan SPP terdiri atas SPP Panjar (uang muka kerja yang dipertanggungjawabkan kemudian) dan SPP Definitif (setelah pekerjaan/barang diterima).", "source": "Permendagri No. 20 Tahun 2018 Pasal 51"}, {"id": 362, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Bendahara Desa melakukan pemotongan Pajak Penghasilan (PPh) Pasal 23 atas transaksi belanja APB Desa untuk pos...", "options": ["Pembelian alat tulis kantor senilai Rp500.000", "Jasa sewa kendaraan/alat berat dan jasa tenaga teknis dari rekanan", "Pemberian bantuan beras bagi warga miskin", "Pembayaran insentif kader posyandu"], "answer": 1, "explanation": "PPh Pasal 23 dikenakan atas penghasilan berupa bunga, royalti, dividen, hadiah, serta sewa dan imbalan jasa selain yang dipotong PPh 21 (misal sewa alat berat/kendaraan sebesar 2% ber-NPWP).", "source": "UU Pajak Penghasilan (PPh) Pasal 23"}, {"id": 363, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Berdasarkan UU No. 3 Tahun 2024 jo. Permendesa PDTT No. 21 Tahun 2020, dokumen Rencana Pembangunan Jangka Menengah Desa (RPJM Desa) disusun untuk jangka waktu...", "options": ["5 tahun", "6 tahun", "8 tahun", "10 tahun"], "answer": 2, "explanation": "Menyesuaikan masa jabatan Kepala Desa yang kini 8 tahun berdasarkan UU No. 3 Tahun 2024, dokumen RPJM Desa memuat rencana pembangunan desa untuk periode 8 (delapan) tahun.", "source": "UU No. 3 Tahun 2024 jo. Permendesa PDTT No. 21 Tahun 2020"}, {"id": 364, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "mudah", "question": "Berdasarkan Permendesa PDTT No. 21 Tahun 2020, Rencana Kerja Pemerintah Desa (RKP Desa) wajib ditetapkan paling lambat pada...", "options": ["Bulan Juni tahun berjalan", "Tanggal 30 September tahun berjalan", "Tanggal 31 Desember tahun berjalan", "Tanggal 31 Maret tahun berikutnya"], "answer": 1, "explanation": "Permendesa PDTT No. 21 Tahun 2020 Pasal 43 ayat (1) menyatakan bahwa RKP Desa ditetapkan dengan Peraturan Desa paling lambat akhir bulan September tahun berjalan.", "source": "Permendesa PDTT No. 21 Tahun 2020 Pasal 43"}, {"id": 365, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Berdasarkan Permendesa PDTT No. 21 Tahun 2020, Tim Penyusun Rencana Kerja Pemerintah Desa (RKP Desa) dibentuk dengan jumlah anggota berjumlah...", "options": ["Paling sedikit 7 orang dan paling banyak 11 orang, dengan mengikutsertakan perempuan paling sedikit 30%", "Hanya 3 orang staf kantor desa", "Tepat 25 orang perwakilan setiap RT", "Seluruh warga desa yang hadir musdes"], "answer": 0, "explanation": "Permendesa PDTT No. 21 Tahun 2020 Pasal 35 ayat (3) menetapkan Tim Penyusun RKP Desa berjumlah ganjil paling sedikit 7 orang dan paling banyak 11 orang dengan keterwakilan perempuan minimal 30%.", "source": "Permendesa PDTT No. 21 Tahun 2020 Pasal 35"}, {"id": 366, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Peraturan Desa tentang Rencana Kerja Pemerintah Desa (Perdes RKP Desa) untuk tahun anggaran berikutnya wajib disepakati dan ditetapkan bersama oleh Kepala Desa dan BPD paling lambat pada...", "options": ["Tanggal 30 September tahun anggaran berjalan", "Tanggal 31 Desember tahun anggaran berjalan", "Bulan Januari tahun berkenaan", "Bulan Juni tahun berjalan"], "answer": 0, "explanation": "Permendesa PDTT No. 21 Tahun 2020 Pasal 43 ayat (1) menegaskan bahwa RKP Desa ditetapkan dengan Peraturan Desa paling lambat akhir bulan September tahun berjalan.", "source": "Permendesa PDTT No. 21 Tahun 2020 Pasal 43"}, {"id": 367, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Dalam konsep SDGs Desa (Sustainable Development Goals Desa), tujuan ke-1 yang menjadi fokus penanggulangan kerentanan sosial masyarakat desa adalah...", "options": ["Desa Berenergi Bersih dan Terbarukan", "Desa Tanpa Kemiskinan", "Desa Berjejaring Digital", "Desa Wisata Unggulan"], "answer": 1, "explanation": "SDGs Desa memuat 18 tujuan pembangunan perdesaan, dengan tujuan ke-1 adalah 'Desa Tanpa Kemiskinan' (Zero Poverty).", "source": "Permendesa PDTT No. 21 Tahun 2020 tentang SDGs Desa"}, {"id": 368, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Berdasarkan Peraturan Pemerintah No. 11 Tahun 2021 tentang Badan Usaha Milik Desa, organ tertinggi dalam struktur BUMDes adalah...", "options": ["Musyawarah Desa (Musdes)", "Direktur Operasional", "Dewan Pengawas BUMDes", "Camat setempat"], "answer": 0, "explanation": "PP No. 11 Tahun 2021 Pasal 16 menetapkan bahwa perangkat organisasi BUMDes terdiri atas Musyawarah Desa/Musyawarah Antar Desa, Penasihat, Pelaksana Operasional, dan Pengawas. Musdes memegang kekuasaan tertinggi.", "source": "PP No. 11 Tahun 2021 Pasal 16"}, {"id": 369, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "mudah", "question": "Berdasarkan PP No. 11 Tahun 2021, jabatan Penasihat BUMDes secara ex-officio (karena kedudukan jabatannya) dipegang oleh...", "options": ["Ketua BPD", "Kepala Desa", "Sekretaris Desa", "Kepala Dusun tertua"], "answer": 1, "explanation": "PP No. 11 Tahun 2021 Pasal 20 ayat (1) menyatakan bahwa Penasihat dijabat secara ex-officio oleh Kepala Desa yang sedang menjabat.", "source": "PP No. 11 Tahun 2021 Pasal 20 ayat (1)"}, {"id": 370, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 18 Tahun 2018, Lembaga Kemasyarakatan Desa (LKD) seperti Karang Taruna dan PKK berkedudukan sebagai...", "options": ["Lembaga tandingan pemerintah desa", "Mitra pemerintah desa dalam memberdayakan masyarakat desa", "Pengawas yudisial aparatur desa", "Organisasi sayap partai politik"], "answer": 1, "explanation": "Permendagri No. 18 Tahun 2018 Pasal 3 menyatakan LKD bertugas membantu Kepala Desa dan menjadi mitra Pemerintah Desa dalam memberdayakan masyarakat.", "source": "Permendagri No. 18 Tahun 2018 Pasal 3"}, {"id": 371, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 110 Tahun 2016, hubungan kerja antara Badan Permusyawaratan Desa (BPD) dengan Pemerintah Desa bersifat...", "options": ["Atasan dan bawahan langsung", "Kemitraan, konsultatif, dan koordinatif", "Kompetitif saling menjatuhkan", "Instruktif dan hierarkis mutlak"], "answer": 1, "explanation": "Hubungan kerja antara BPD dan Pemerintah Desa merupakan hubungan kemitraan yang harmonis, konsultatif, dan koordinatif dalam memajukan desa.", "source": "Permendagri No. 110 Tahun 2016 tentang BPD"}, {"id": 372, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Berdasarkan Undang-Undang Nomor 3 Tahun 2024 tentang Desa, anggota Badan Permusyawaratan Desa (BPD) dapat memegang masa keanggotaan paling banyak...", "options": ["2 (dua) kali masa keanggotaan secara berturut-turut atau tidak secara berturut-turut (total maksimal 16 tahun)", "3 kali masa jabatan berturut-turut", "1 kali periode saja tanpa hak dipilih kembali", "Seumur hidup tanpa batas periode"], "answer": 0, "explanation": "UU No. 3 Tahun 2024 Pasal 56 ayat (2) menyatakan anggota BPD memegang jabatan selama 8 tahun dan dapat dipilih paling banyak 2 (dua) kali masa jabatan secara berturut-turut atau tidak secara berturut-turut.", "source": "UU No. 3 Tahun 2024 Pasal 56 ayat (2)"}, {"id": 373, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "mudah", "question": "Salah satu dari 3 (tiga) fungsi utama BPD menurut UU No. 6 Tahun 2014 Pasal 55 adalah...", "options": ["Mengelola rekening kas desa dan mencairkan uang belanja APB Desa", "Membahas dan menyepakati Rancangan Peraturan Desa bersama Kepala Desa", "Menerbitkan surat izin mendirikan bangunan di wilayah kecamatan", "Mengangkat dan memberhentikan perangkat desa secara sepihak"], "answer": 1, "explanation": "Tiga fungsi utama BPD (Pasal 55 UU 6/2014): 1. Membahas dan menyepakati rancangan Perdes bersama Kades, 2. Menampung dan menyalurkan aspirasi masyarakat, 3. Melakukan pengawasan kinerja Kades.", "source": "UU No. 6 Tahun 2014 Pasal 55"}, {"id": 374, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Apabila ada anggota BPD yang mengundurkan diri atau meninggal dunia sebelum masa jabatannya berakhir, mekanisme pengisiannya dilakukan melalui...", "options": ["Penunjukan langsung oleh Kepala Desa", "Penggantian Antar Waktu (PAW)", "Pelelangan terbuka jabatan ke publik", "Penyerahan jabatan kepada ahli waris"], "answer": 1, "explanation": "Permendagri No. 110 Tahun 2016 Pasal 23 mengatur pengisian anggota BPD yang berhenti antarwaktu dilakukan melalui Penggantian Antar Waktu (PAW) dari perolehan suara terbanyak berikutnya pada proses pemilihan.", "source": "Permendagri No. 110 Tahun 2016 Pasal 23"}, {"id": 375, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Siapakah yang memimpin pelaksanaan Musyawarah Desa (Musdes) menurut Permendagri No. 110 Tahun 2016?", "options": ["Kepala Desa", "Ketua BPD atau anggota BPD yang ditunjuk", "Sekretaris Desa", "Camat setempat"], "answer": 1, "explanation": "Permendagri No. 110 Tahun 2016 Pasal 36 menegaskan bahwa Musyawarah Desa dipimpin oleh Ketua BPD atau salah satu anggota BPD yang ditunjuk oleh pimpinan BPD.", "source": "Permendagri No. 110 Tahun 2016 Pasal 36"}, {"id": 376, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Manakah kelompok kata berikut yang semuanya merupakan kata baku sesuai Ejaan Bahasa Indonesia yang Disempurnakan (EYD V)?", "options": ["Resiko, ijin, kwitansi", "Risiko, izin, kuitansi", "Resiko, izin, kwitansi", "Risiko, ijin, kuitansi"], "answer": 1, "explanation": "Sesuai KBBI dan EYD V, bentuk baku yang benar adalah: 'risiko' (bukan resiko), 'izin' (bukan ijin), dan 'kuitansi' (bukan kwitansi).", "source": "EYD Edisi V & KBBI Daring"}, {"id": 377, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Penulisan bentuk terikat 'antar-' yang tepat sesuai kaidah EYD V adalah...", "options": ["Kerjasama antar warga desa", "Kerjasama antar-warga desa", "Kerja sama antarwarga desa", "Kerja sama antar warga desa"], "answer": 2, "explanation": "Kata 'kerja sama' ditulis terpisah dua kata. Bentuk terikat 'antar-' wajib ditulis serangkai dengan kata dasar yang mengikutinya ('antarwarga').", "source": "EYD Edisi V Kaidah Penulisan Bentuk Terikat"}, {"id": 378, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Cermati kalimat berikut: 'Demi untuk kelancaran acara rapat, para hadirin sekalian dimohon hadir tepat waktu.' Perbaikan kalimat agar efektif dan tidak pleonastis adalah...", "options": ["Demi untuk kelancaran acara rapat, hadirin dimohon hadir tepat waktu.", "Untuk kelancaran rapat, hadirin dimohon hadir tepat waktu.", "Demi kelancaran acara rapat, para hadirin sekalian mohon hadir tepat waktu.", "Untuk kelancaran rapat, para hadirin dimohon supaya hadir tepat waktu."], "answer": 1, "explanation": "'Demi untuk' dan 'para hadirin sekalian' adalah bentuk pleonastis (pemborosan kata). Bentuk hemat dan efektif adalah 'Untuk kelancaran rapat, hadirin dimohon hadir tepat waktu.'", "source": "Tata Bahasa Baku Bahasa Indonesia"}, {"id": 379, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Penggunaan tanda titik dua (:) yang tepat sesuai kaidah bahasa Indonesia terdapat pada kalimat...", "options": ["Pemerintah Desa memerlukan: meja, kursi, dan komputer baru.", "Rapat dihadiri oleh: Kepala Desa, Sekretaris Desa, dan Kaur Keuangan.", "Pemerintah desa membutuhkan perabot kantor berikut: meja, kursi, dan lemari arsip.", "Kita memerlukan barang: seperti beras, gula, dan minyak."], "answer": 2, "explanation": "Tanda titik dua dipakai pada akhir suatu pernyataan lengkap yang diikuti pemerincian. Jika kalimat belum lengkap (ada kata kerja 'memerlukan/dihadiri'), tanda titik dua tidak boleh dipakai.", "source": "EYD Edisi V Penggunaan Tanda Baca Titik Dua"}, {"id": 380, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Penulisan huruf kapital yang benar untuk gelar dan jabatan dinas adalah...", "options": ["Surat itu ditandatangani oleh bupati Tuban.", "Surat itu ditandatangani oleh Bupati Tuban.", "Surat itu ditandatangani oleh Bupati tuban.", "Semua Kepala Desa harus hadir di pendopo."], "answer": 1, "explanation": "Huruf kapital dipakai sebagai huruf pertama unsur nama gelar kehormatan, keturunan, keagamaan, atau profesi serta nama jabatan dan kepangkatan yang diikuti nama orang atau nama daerah/instansi ('Bupati Tuban'). Jika tidak diikuti nama diri/tempat, ditulis huruf kecil ('semua kepala desa').", "source": "EYD Edisi V Penulisan Huruf Kapital"}, {"id": 381, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Manakah penulisan kata baku berikut yang tepat?", "options": ["Jadual kegiatan dan fihak terkait", "Jadwal kegiatan dan pihak terkait", "Jadwal kegiatan dan fihak terkait", "Jadual kegiatan dan pihak terkait"], "answer": 1, "explanation": "Bentuk baku yang tepat adalah 'jadwal' (bukan jadual) dan 'pihak' (bukan fihak).", "source": "KBBI Daring & EYD V"}, {"id": 382, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Penulisan salam pembuka yang benar pada surat dinas pemerintahan adalah...", "options": ["Dengan Hormat,", "Dengan hormat,", "Dengan hormat.", "Dengan Hormat;"], "answer": 1, "explanation": "Salam pembuka 'Dengan hormat,' ditulis dengan huruf kapital pada kata pertama ('Dengan') dan huruf kecil pada kata kedua ('hormat'), serta diakhiri tanda koma.", "source": "Tata Naskah Dinas & EYD V"}, {"id": 383, "category": "Matematika dan numerik", "difficulty": "mudah", "question": "Pendapatan Desa yang terealisasi dalam APB Desa tercatat sebesar Rp1.250.000.000,00, sedangkan total Belanja Desa terealisasi sebesar Rp1.100.000.000,00. Berapakah sisa anggaran (surplus belanja) sebelum pos pembiayaan?", "options": ["Rp100.000.000,00", "Rp150.000.000,00", "Rp200.000.000,00", "Rp250.000.000,00"], "answer": 1, "explanation": "Surplus = Pendapatan - Belanja = Rp1.250.000.000,00 - Rp1.100.000.000,00 = Rp150.000.000,00.", "source": "Perhitungan Matematika Keuangan APB Desa"}, {"id": 384, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Pemerintah Desa membeli 1 unit laptop seharga Rp11.100.000,00 (harga sudah termasuk PPN 11%). Berapakah Dasar Pengenaan Pajak (DPP) dan nilai PPN laptop tersebut?", "options": ["DPP Rp10.000.000,00 dan PPN Rp1.100.000,00", "DPP Rp9.990.000,00 dan PPN Rp1.110.000,00", "DPP Rp10.500.000,00 dan PPN Rp600.000,00", "DPP Rp11.000.000,00 dan PPN Rp100.000,00"], "answer": 0, "explanation": "DPP = 100 / 111 x Rp11.100.000,00 = Rp10.000.000,00. Nilai PPN (11%) = 11% x Rp10.000.000,00 = Rp1.100.000,00.", "source": "Perhitungan Pajak Pertambahan Nilai (PPN 11%)"}, {"id": 385, "category": "Matematika dan numerik", "difficulty": "mudah", "question": "Sebidang tanah kas desa memiliki luas 2,5 hektar. Berapakah luas tanah tersebut jika dikonversikan ke dalam satuan meter persegi (m²)?", "options": ["2.500 m²", "25.000 m²", "250.000 m²", "250 m²"], "answer": 1, "explanation": "1 hektar (ha) = 10.000 m². Maka 2,5 ha = 2,5 x 10.000 m² = 25.000 m².", "source": "Konversi Satuan Luas Tanah"}, {"id": 386, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Pemerintah Desa mengalokasikan anggaran pembangunan pos kesehatan desa sebesar Rp40.000.000,00. Dari total anggaran tersebut, 60% dialokasikan untuk belanja material bangunan, 30% untuk upah tenaga kerja lokal, dan sisanya untuk biaya operasional Tim Pelaksana Kegiatan (TPK). Berapakah nominal anggaran untuk operasional TPK?", "options": ["Rp4.000.000,00", "Rp6.000.000,00", "Rp8.000.000,00", "Rp10.000.000,00"], "answer": 0, "explanation": "Persentase operasional TPK = 100% - (60% + 30%) = 10%. Nominal operasional TPK = 10% x Rp40.000.000,00 = Rp4.000.000,00.", "source": "Matematika Keuangan APB Desa / Perhitungan Anggaran Biaya"}, {"id": 387, "category": "Matematika dan numerik", "difficulty": "mudah", "question": "Hasil panen padi pada 5 petak sawah kas desa berturut-turut adalah 5,2 ton; 5,8 ton; 6,1 ton; 5,5 ton; dan 6,4 ton. Berapakah rata-rata (mean) hasil panen per petak?", "options": ["5,6 ton", "5,7 ton", "5,8 ton", "5,9 ton"], "answer": 2, "explanation": "Rata-rata = (5,2 + 5,8 + 6,1 + 5,5 + 6,4) / 5 = 29,0 / 5 = 5,8 ton.", "source": "Statistika Dasar Nilai Rata-rata"}, {"id": 388, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Kas Simpan Pinjam BUMDes mencatat pertumbuhan penerimaan angsuran bulanan yang membentuk barisan aritmetika: Rp2.000.000, Rp2.500.000, Rp3.000.000, Rp3.500.000... Berapakah penerimaan kas pada bulan ke-8?", "options": ["Rp4.500.000,00", "Rp5.000.000,00", "Rp5.500.000,00", "Rp6.000.000,00"], "answer": 2, "explanation": "Suku pertama (a) = 2.000.000, beda (b) = 500.000. Suku ke-8 (U8) = a + (8 - 1)b = 2.000.000 + 7 x 500.000 = 2.000.000 + 3.500.000 = Rp5.500.000,00.", "source": "Barisan dan Deret Aritmetika"}, {"id": 389, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Premis 1: Semua perangkat desa wajib mengikuti apel kerja setiap hari Senin pagi.\nPremis 2: Pak Budi adalah Kaur Perencanaan Desa.\nKesimpulan yang sah dan logis adalah...", "options": ["Pak Budi boleh tidak mengikuti apel jika sibuk menyusun RKP Desa", "Pak Budi wajib mengikuti apel kerja setiap hari Senin pagi", "Pak Budi hanya mengikuti apel jika diperintah Sekretaris Desa", "Sebagian perangkat desa tidak wajib apel pagi"], "answer": 1, "explanation": "Silogisme kategorial: Semua A adalah B. C adalah A. Maka C adalah B (Pak Budi wajib mengikuti apel kerja hari Senin pagi).", "source": "Silogisme Kategorial Logika Deduktif"}, {"id": 390, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Premis 1: Jika Dana Desa tahap I telah ditransfer ke kas desa, maka pemerintah desa menyalurkan BLT Desa.\nPremis 2: Pemerintah desa belum menyalurkan BLT Desa.\nKesimpulan yang benar menurut kaidah logika adalah...", "options": ["Dana Desa tahap I telah ditransfer ke kas desa", "Dana Desa tahap I belum ditransfer ke kas desa", "Pemerintah desa membatalkan penyaluran BLT Desa", "Kepala Desa sedang dinas luar"], "answer": 1, "explanation": "Kaidah Modus Tollens: Jika P maka Q. Negasi Q (~Q). Maka kesimpulannya Negasi P (~P), yaitu Dana Desa tahap I belum ditransfer ke kas desa.", "source": "Logika Matematika Modus Tollens"}, {"id": 391, "category": "Logika dan penalaran", "difficulty": "sulit", "question": "Lima orang perangkat desa (Ali, Budi, Citra, Dedi, dan Eka) bertugas piket pelayanan desa dari Senin hingga Jumat. Aturan penugasan:\n1. Budi bertugas tepat satu hari sebelum Citra.\n2. Ali bertugas pada hari Rabu.\n3. Dedi bertugas pada hari pertama (Senin).\nSiapakah yang bertugas piket pada hari Jumat?", "options": ["Budi", "Citra", "Eka", "Dedi"], "answer": 1, "explanation": "Senin: Dedi. Rabu: Ali. Tersisa Selasa, Kamis, Jumat. Budi tepat sebelum Citra, sehingga pasangan berurutan (Budi, Citra) hanya bisa di Kamis dan Jumat. Hari Selasa diisi Eka. Maka yang piket hari Jumat adalah Citra.", "source": "Penalaran Analitis Urutan Logis"}, {"id": 392, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Dari 100 kepala keluarga di Dusun Krajan, tercatat 60 KK menerima bantuan beras, 45 KK menerima bantuan bibit pertanian, dan 20 KK menerima kedua jenis bantuan tersebut. Berapakah jumlah KK yang sama sekali tidak menerima kedua bantuan tersebut?", "options": ["10 KK", "15 KK", "20 KK", "25 KK"], "answer": 1, "explanation": "Jumlah KK penerima bantuan = 60 + 45 - 20 = 85 KK. KK yang tidak menerima kedua bantuan = 100 - 85 = 15 KK.", "source": "Diagram Venn Teori Himpunan"}, {"id": 393, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Premis 1: Warga yang mengurus surat keterangan usaha wajib membawa surat pengantar RT atau surat bukti kepemilikan tempat usaha.\nPremis 2: Pak Joko tidak membawa surat pengantar RT.\nKesimpulan yang sah adalah...", "options": ["Pak Joko tidak boleh mengurus surat keterangan usaha", "Pak Joko wajib membawa surat bukti kepemilikan tempat usaha", "Pak Joko harus membayar denda administrasi", "Pak Joko dapat langsung meminta tanda tangan Kades"], "answer": 1, "explanation": "Silogisme Disjungtif (P atau Q. Tidak P. Maka Q). Karena Pak Joko tidak membawa surat RT, ia wajib membawa bukti tempat usaha.", "source": "Silogisme Disjungtif"}, {"id": 394, "category": "Pengetahuan umum", "difficulty": "sedang", "question": "Pada masa keemasan Kerajaan Singasari dan Majapahit abad ke-13 hingga ke-15, wilayah Kabupaten Tuban memegang peranan sangat penting dalam percaturan ekonomi Nusantara sebagai...", "options": ["Bandar pelabuhan niaga maritim internasional utama tempat bersandarnya kapal dagang mancanegara (Tiongkok, Arab, dan Gujarat)", "Pusat penempaan senjata keris utama kerajaan di pedalaman", "Lumbung padi utama pegunungan kapur", "Pusat pemerintahan istana Majapahit"], "answer": 0, "explanation": "Tuban merupakan pelabuhan utama Kerajaan Majapahit (kambang putih) di pesisir utara Jawa Timur, menjadi pintu gerbang perdagangan maritim internasional rempah-rempah dan keramik sutra.", "source": "Sejarah Maritim Nusantara; Ensiklopedia Sejarah Tuban"}, {"id": 395, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Kawasan perbukitan kapur (karst) di wilayah barat Kabupaten Tuban menjadi lokasi beroperasinya salah satu industri manufaktur strategis nasional terbesar di Indonesia, yaitu...", "options": ["Industri Pabrik Semen (PT Semen Indonesia / SIG Pabrik Tuban)", "Pabrik Peleburan Timah", "Pabrik Kertas Tisu", "Kawasan Industri Perakitan Pesawat Terbang"], "answer": 0, "explanation": "Kabupaten Tuban memiliki deposit batu gamping/kapur melimpah yang menopang kompleks industri pabrik semen PT Semen Indonesia (Persero) Tbk di wilayah Kerek dan Merakurak.", "source": "Dinas Perindustrian dan Perdagangan Kabupaten Tuban"}, {"id": 396, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Di sebelah barat, wilayah Kabupaten Tuban berbatasan langsung dengan kabupaten yang termasuk wilayah Provinsi Jawa Tengah, yaitu...", "options": ["Kabupaten Rembang", "Kabupaten Bojonegoro", "Kabupaten Blora", "Kabupaten Lamongan"], "answer": 0, "explanation": "Batas wilayah Kabupaten Tuban di sebelah barat berbatasan langsung dengan Kabupaten Rembang (Provinsi Jawa Tengah).", "source": "Profil Geografis Kabupaten Tuban"}, {"id": 397, "category": "Pengetahuan umum", "difficulty": "sedang", "question": "Salah satu hidangan kuliner tradisional khas pesisir dan pedesaan Kabupaten Tuban yang terkenal bercita rasa sangat pedas dan menggunakan kuah santan bumbu rempah kuning adalah...", "options": ["Rajungan Pedas dan Becek Mentok khas Tuban", "Rawon Daging Surabaya", "Gudeg Nangka Manis", "Rujak Cingur Petis"], "answer": 0, "explanation": "Rajungan Pedas dan Becek Mentok adalah kuliner khas legendaris Kabupaten Tuban yang bercita rasa pedas gurih kaya rempah khas pesisir laut Jawa.", "source": "Pariwisata dan Kuliner Khas Kabupaten Tuban"}, {"id": 398, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Ketika staf pelayanan desa sedang mengetik dokumen dan tiba-tiba aplikasi pengolah kata macet/membeku (keterangan 'Not Responding'), kombinasi tombol cepat untuk membuka Task Manager guna menutup paksa aplikasi yang macet adalah...", "options": ["Ctrl + Shift + Esc (atau Ctrl + Alt + Del)", "Ctrl + Alt + Tab", "Alt + Shift + Enter", "Windows + Spasi"], "answer": 0, "explanation": "Kombinasi tombol `Ctrl + Shift + Esc` (atau `Ctrl + Alt + Del`) langsung membuka Windows Task Manager. Di Task Manager, pengguna dapat memilih aplikasi yang bermasalah lalu mengklik 'End Task' untuk menutup paksa aplikasi yang membeku tanpa harus merestart paksa komputer.", "source": "Troubleshooting Sistem Operasi Windows & Perawatan Komputer Kantor"}, {"id": 399, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Komponen perangkat keras komputer yang berfungsi sebagai memori penyimpanan data kerja sementara saat komputer menyala dan seluruh datanya akan hilang saat komputer dimatikan (bersifat volatile) adalah...", "options": ["RAM (Random Access Memory)", "ROM (Read-Only Memory)", "Harddisk Eksternal", "Flashdisk"], "answer": 0, "explanation": "RAM (Random Access Memory) adalah memori kerja sementara komputer berkecepatan tinggi yang menyimpan data dan instruksi yang sedang diproses oleh prosesor. Jika komputer mati, data dalam RAM otomatis hilang (volatile).", "source": "Dasar Arsitektur Komputer & Perangkat Keras TIK"}, {"id": 400, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Demi menjaga keamanan dan kerahasiaan data kependudukan warga di komputer pelayanan desa saat staf harus meninggalkan meja kerja sementara waktu, kombinasi tombol cepat pada keyboard untuk mengunci layar monitor seketika adalah...", "options": ["Windows + L", "Windows + D", "Alt + F4", "Ctrl + Alt + P"], "answer": 0, "explanation": "Kombinasi tombol `Windows + L` (Lock) berfungsi langsung mengunci komputer seketika sehingga siapa pun yang ingin menggunakan komputer harus memasukkan kata sandi (password) terlebih dahulu. Ini praktik keamanan standar saat meninggalkan meja kerja.", "source": "Standar Keamanan Informasi & Pintasan Keyboard Windows"}, {"id": 401, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan UU No. 3 Tahun 2024 tentang Perubahan Kedua atas UU No. 6 Tahun 2014, mekanisme transfer Dana Desa bersumber dari APBN disalurkan secara langsung ke...", "options": ["Rekening Kas Pribadi Kepala Desa", "Rekening Kas Desa (RKD) pada bank yang ditunjuk", "Rekening Kas Pengurus Lembaga Adat Desa", "Rekening Kas BUMDes"], "answer": 1, "explanation": "UU No. 3 Tahun 2024 dan regulasi keuangan negara menegaskan bahwa Dana Desa dari APBN disalurkan langsung dari Rekening Kas Umum Negara (RKUN) ke Rekening Kas Desa (RKD) untuk efisiensi dan transparansi.", "source": "UU No. 3 Tahun 2024 Pasal 72 ayat (1) huruf b"}, {"id": 402, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Dalam struktur organisasi Pemerintah Desa, pimpinan Sekretariat Desa yang bertugas memimpin urusan ketatausahaan, keuangan, dan perencanaan adalah...", "options": ["Kepala Seksi Pemerintahan", "Sekretaris Desa", "Kepala Dusun", "Ketua BPD"], "answer": 1, "explanation": "Permendagri No. 84 Tahun 2015 Pasal 7 menegaskan bahwa Sekretaris Desa berkedudukan sebagai pimpinan sekretariat desa dan bertugas membantu Kepala Desa dalam bidang administrasi pemerintahan.", "source": "Permendagri No. 84 Tahun 2015 Pasal 7"}, {"id": 403, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 84 Tahun 2015, apabila pemerintah desa membutuhkan staf pembantu perangkat desa, siapakah yang berwenang mengangkat staf tersebut?", "options": ["Camat atas persetujuan Bupati", "Kepala Desa dengan Keputusan Kepala Desa", "Ketua BPD atas usulan warga", "Sekretaris Daerah Kabupaten"], "answer": 1, "explanation": "Permendagri No. 84 Tahun 2015 Pasal 13 menyebutkan bahwa dalam hal diperlukan, Kepala Desa dapat mengangkat staf pembantu perangkat desa sesuai kemampuan keuangan desa dengan Keputusan Kepala Desa.", "source": "Permendagri No. 84 Tahun 2015 Pasal 13"}, {"id": 404, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 67 Tahun 2017 Pasal 2, pengisian jabatan Perangkat Desa yang lowong dapat dilakukan melalui 2 (dua) cara, yaitu...", "options": ["Mutasi jabatan antarperangkat desa dan penjaringan/penyaringan calon perangkat desa", "Penunjukan langsung oleh Camat dan lelang jabatan", "Pemilihan suara langsung warga dan undian terbuka", "Pengangkatan otomatis keluarga kepala desa dan tes wawancara BPD"], "answer": 0, "explanation": "Permendagri No. 67 Tahun 2017 Pasal 2 ayat (1) menyatakan pengisian jabatan perangkat desa yang kosong dapat dilakukan melalui mutasi jabatan antarperangkat desa di lingkungan pemdes atau penjaringan dan penyaringan calon perangkat desa.", "source": "Permendagri No. 67 Tahun 2017 Pasal 2"}, {"id": 405, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sulit", "question": "Berdasarkan Permendagri No. 67 Tahun 2017 Pasal 7, perangkat desa yang berstatus diberhentikan sementara diberikan penghasilan tetap sebesar...", "options": ["100% dari penghasilan tetap setiap bulan", "75% dari penghasilan tetap setiap bulan", "50% dari penghasilan tetap setiap bulan", "Tidak diberikan penghasilan sama sekali (0%)"], "answer": 2, "explanation": "Permendagri No. 67 Tahun 2017 Pasal 7 ayat (1) mengatur bahwa perangkat desa yang diberhentikan sementara diberikan penghasilan tetap sebesar 50% (lima puluh persen) dari penghasilan tetap yang diterimanya setiap bulan.", "source": "Permendagri No. 67 Tahun 2017 Pasal 7 ayat (1)"}, {"id": 406, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Jika perangkat desa yang diberhentikan sementara diputus bebas atau tidak bersalah oleh pengadilan dengan putusan berkekuatan hukum tetap, kewajiban Kepala Desa adalah...", "options": ["Memberikan uang pesangon lalu memberhentikannya", "Merehabilitasi dan mengembalikan jabatannya sebagai perangkat desa", "Menurunkan jabatannya menjadi tenaga honorer lepas", "Menyerahkan keputusannya kepada BPD"], "answer": 1, "explanation": "Permendagri No. 67 Tahun 2017 Pasal 7 ayat (3) menegaskan bahwa perangkat desa yang diberhentikan sementara dan diputus bebas oleh pengadilan wajib direhabilitasi dan dikembalikan pada jabatannya semula.", "source": "Permendagri No. 67 Tahun 2017 Pasal 7 ayat (3)"}, {"id": 407, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Menurut UU No. 6 Tahun 2014 Pasal 48, unsur Perangkat Desa terdiri atas...", "options": ["Sekretariat Desa, Pelaksana Teknis, dan Pelaksana Kewilayahan", "Kepala Desa, BPD, dan RT/RW", "Sekretaris Desa, Bendahara Desa, dan Petugas Linmas", "Camat, Lurah, dan Kepala Lingkungan"], "answer": 0, "explanation": "UU No. 6 Tahun 2014 Pasal 48 menegaskan perangkat desa terdiri atas: a. Sekretariat Desa (Kaur), b. Pelaksana Teknis (Kasi), dan c. Pelaksana Kewilayahan (Kepala Dusun).", "source": "UU No. 6 Tahun 2014 Pasal 48"}, {"id": 408, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Pencatatan kas harian, pengelolaan buku bank desa, penatausahaan bukti belanja APB Desa, dan verifikasi kuitansi belanja desa merupakan fungsi pokok dari...", "options": ["Kepala Seksi Pelayanan", "Kepala Urusan Keuangan", "Kepala Urusan Perencanaan", "Kepala Dusun"], "answer": 1, "explanation": "Permendagri No. 84 Tahun 2015 Pasal 8 ayat (3) menjelaskan bahwa Kepala Urusan Keuangan bertugas melaksanakan penatausahaan keuangan, penerimaan kas, bukti pengeluaran kas, dan buku kas.", "source": "Permendagri No. 84 Tahun 2015 Pasal 8"}, {"id": 409, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Pelaksanaan administrasi kependudukan (KK, KTP, mutasi warga), pembinaan ketenteraman ketertiban, dan fasilitasi pemilihan RT/RW merupakan tugas pokok...", "options": ["Kepala Seksi Pemerintahan", "Kepala Urusan Tata Usaha dan Umum", "Kepala Seksi Kesejahteraan", "Sekretaris Desa"], "answer": 0, "explanation": "Permendagri No. 84 Tahun 2015 Pasal 9 ayat (2) menyatakan Kepala Seksi Pemerintahan bertugas menyusun rancangan regulasi, pembinaan ketenteraman ketertiban, administrasi kependudukan, dan pembinaan kelembagaan masyarakat.", "source": "Permendagri No. 84 Tahun 2015 Pasal 9"}, {"id": 410, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Pengelolaan program Posyandu, percepatan penurunan stunting desa, dan pembangunan gedung PAUD desa secara teknis diampu oleh...", "options": ["Kepala Seksi Kesejahteraan", "Kepala Urusan Umum", "Kepala Seksi Keamanan", "Kepala Dusun"], "answer": 0, "explanation": "Permendagri No. 84 Tahun 2015 Pasal 10 menyebutkan Kepala Seksi Kesejahteraan mengampu bidang pelaksanaan pembangunan sarana prasarana desa, kesehatan, dan pendidikan perdesaan.", "source": "Permendagri No. 84 Tahun 2015 Pasal 10"}, {"id": 411, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Pelayanan pencatatan pengantar nikah, talak, cerai, dan rujuk (NTCR), pelestarian seni budaya tradisional desa, dan pembinaan karang taruna diampu oleh...", "options": ["Kepala Seksi Pelayanan", "Kepala Urusan Keuangan", "Kepala Urusan Perencanaan", "Sekretaris Desa"], "answer": 0, "explanation": "Permendagri No. 84 Tahun 2015 Pasal 11 mengatur Kepala Seksi Pelayanan bertugas melaksanakan pelayanan sosial keagamaan, kebudayaan, pencatatan sipil sosial, dan kepemudaan.", "source": "Permendagri No. 84 Tahun 2015 Pasal 11"}, {"id": 412, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 83 Tahun 2015, anggota Tim Penjaringan dan Penyaringan Calon Perangkat Desa yang dibentuk Kepala Desa berasal dari...", "options": ["Perangkat desa, pengurus lembaga kemasyarakatan desa (LKD), dan tokoh masyarakat desa", "Aparatur sipil negara dari kantor kecamatan saja", "Pengurus partai politik tingkat ranting", "Anggota BPD yang sedang aktif"], "answer": 0, "explanation": "Permendagri No. 83 Tahun 2015 Pasal 4 menjelaskan Tim Seleksi terdiri atas unsur perangkat desa, pengurus kelembagaan kemasyarakatan, dan tokoh masyarakat desa.", "source": "Permendagri No. 83 Tahun 2015 Pasal 4"}, {"id": 413, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sulit", "question": "Berdasarkan Permendagri No. 83 Tahun 2015 jo. Permendagri No. 67 Tahun 2017, berapa orang calon perangkat desa yang hasil penyaringannya dikonsultasikan oleh Kepala Desa kepada Camat?", "options": ["Hanya 1 orang dengan nilai tertinggi", "Paling sedikit 2 (dua) orang calon", "Seluruh peserta seleksi tanpa terkecuali", "Minimal 5 orang peserta terbaik"], "answer": 1, "explanation": "Permendagri No. 83 Tahun 2015 Pasal 4 ayat (3) menetapkan bahwa Kepala Desa mengonsultasikan paling sedikit 2 (dua) orang calon perangkat desa hasil seleksi kepada Camat.", "source": "Permendagri No. 83 Tahun 2015 Pasal 4 ayat (3)"}, {"id": 414, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan Perda Kabupaten Tuban No. 2 Tahun 2016 jo. No. 16 Tahun 2021, batas waktu pelantikan perangkat desa terpilih setelah terbitnya Keputusan Kepala Desa adalah...", "options": ["Paling lambat 7 hari kerja", "Paling lambat 14 hari kalender", "Paling lambat 30 hari kalender", "Paling lambat 60 hari kalender"], "answer": 2, "explanation": "Perda Kab. Tuban No. 2/2016 jo. 16/2021 Pasal 14 mengatur bahwa pelantikan perangkat desa dilaksanakan paling lambat 30 (tiga puluh) hari kalender sejak ditetapkannya Keputusan Kepala Desa.", "source": "Perda Kab. Tuban No. 2/2016 jo. No. 16/2021 Pasal 14"}, {"id": 415, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "mudah", "question": "Berdasarkan UU No. 6 Tahun 2014 Pasal 26 ayat (2) huruf c, pemegang kekuasaan pengelolaan keuangan dan aset desa adalah...", "options": ["Ketua BPD", "Kepala Desa", "Sekretaris Desa", "Kaur Keuangan"], "answer": 1, "explanation": "Kepala Desa adalah Pemegang Kekuasaan Pengelolaan Keuangan Desa (PKPKD) dan mewakili Pemerintah Desa dalam kepemilikan aset desa.", "source": "UU No. 6 Tahun 2014 Pasal 26 ayat (2) huruf c"}, {"id": 416, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Sanksi administratif apakah yang dapat diberikan kepada Kepala Desa jika tidak menyampaikan LPPD atau LKPPD dalam batas waktu yang ditentukan undang-undang?", "options": ["Denda uang tunai Rp100.000.000", "Teguran lisan, teguran tertulis, hingga pemberhentian sementara oleh bupati", "Hukuman kurungan langsung dari BPD", "Penghapusan nomor register desa"], "answer": 1, "explanation": "UU No. 6 Tahun 2014 Pasal 28 mengatur bahwa Kepala Desa yang tidak memenuhi kewajiban menyampaikan LPPD/LKPPD dikenai sanksi administratif berupa teguran lisan, tertulis, hingga pemberhentian sementara.", "source": "UU No. 6 Tahun 2014 Pasal 28"}, {"id": 417, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Berdasarkan PP No. 43 Tahun 2014 jo. PP No. 11 Tahun 2019, Alokasi Dana Desa (ADD) yang dialokasikan Pemerintah Kabupaten paling sedikit adalah...", "options": ["5% dari dana perimbangan yang diterima kabupaten setelah dikurangi DAK", "10% dari dana perimbangan yang diterima kabupaten setelah dikurangi DAK", "15% dari total Pendapatan Asli Daerah (PAD)", "20% dari APBD kabupaten"], "answer": 1, "explanation": "PP No. 43/2014 Pasal 96 ayat (1) menegaskan Pemerintah Daerah Kabupaten mengalokasikan Alokasi Dana Desa (ADD) dalam APBD paling sedikit 10% dari dana perimbangan setelah dikurangi DAK.", "source": "PP No. 43 Tahun 2014 Pasal 96 ayat (1)"}, {"id": 418, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Menurut UU No. 3 Tahun 2024, dalam menjalankan tugas dan kewajiban kedinasannya, Kepala Desa dan Perangkat Desa berhak memperoleh...", "options": ["Perlindungan hukum atas pelaksanaan tugas kedinasan", "Kekebalan hukum mutlak dari segala tindak pidana", "Hak veto terhadap putusan pengadilan negeri", "Hak monopoli atas seluruh usaha perdagangan di desa"], "answer": 0, "explanation": "UU No. 3 Tahun 2024 menyisipkan ketentuan hak memperoleh perlindungan hukum bagi aparatur desa sepanjang tindakan kedinasan yang diambil sesuai dengan ketentuan peraturan perundang-undangan.", "source": "UU No. 3 Tahun 2024 Pasal 26 & Pasal 50A"}, {"id": 419, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sulit", "question": "Berdasarkan Permendagri No. 83 Tahun 2015, Kepala Desa membentuk Tim Seleksi Penjaringan dan Penyaringan Perangkat Desa paling lambat...", "options": ["1 minggu setelah kekosongan", "1 bulan setelah kekosongan", "2 bulan setelah kekosongan jabatan perangkat desa", "6 bulan setelah kekosongan"], "answer": 2, "explanation": "Permendagri No. 83 Tahun 2015 Pasal 4 ayat (1) menetapkan bahwa Kepala Desa membentuk Tim Seleksi paling lambat 2 (dua) bulan setelah jabatan Perangkat Desa dinyatakan kosong.", "source": "Permendagri No. 83 Tahun 2015 Pasal 4 ayat (1)"}, {"id": 420, "category": "Pemerintahan desa, struktur organisasi, tugas dan fungsi perangkat desa", "difficulty": "sedang", "question": "Pembagian wilayah desa ke dalam beberapa dusun didasarkan atas pertimbangan...", "options": ["Jumlah perolehan suara pemilukada", "Kondisi geografis, jumlah penduduk, dan rentang kendali pelayanan pemerintahan", "Permintaan kelompok arisan warga setempat", "Jumlah gedung pertokoan di wilayah desa"], "answer": 1, "explanation": "Permendagri No. 84 Tahun 2015 mengatur pembentukan dusun (wilayah kerja Kasun) didasarkan pada faktor geografis, luas wilayah, jumlah penduduk, dan efektivitas rentang kendali pelayanan.", "source": "Permendagri No. 84 Tahun 2015 Pasal 12"}, {"id": 421, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "mudah", "question": "Di dalam hierarki peraturan perundang-undangan menurut UU No. 12 Tahun 2011 Pasal 7 ayat (1), Ketetapan MPR menempati urutan...", "options": ["Di atas UUD 1945", "Di bawah UUD 1945 dan di atas Undang-Undang/Perppu", "Setara dengan Peraturan Pemerintah", "Di bawah Peraturan Presiden"], "answer": 1, "explanation": "Urutan hierarki perundang-undangan: 1. UUD 1945, 2. Tap MPR, 3. UU/Perppu, 4. PP, 5. Perpres, 6. Perda Provinsi, 7. Perda Kabupaten/Kota.", "source": "UU No. 12 Tahun 2011 Pasal 7 ayat (1)"}, {"id": 422, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Menurut UU No. 12 Tahun 2011 Pasal 15, materi muatan tentang sanksi pidana hanya boleh dimuat di dalam...", "options": ["Undang-Undang, Peraturan Daerah Provinsi, dan Peraturan Daerah Kabupaten/Kota", "Peraturan Desa dan Peraturan Kepala Desa", "Peraturan Pemerintah dan Keputusan Camat", "Seluruh jenis peraturan perundang-undangan"], "answer": 0, "explanation": "UU No. 12 Tahun 2011 Pasal 15 menegaskan materi muatan mengenai ketentuan pidana hanya dapat dimuat dalam Undang-Undang dan Peraturan Daerah (Perda). Peraturan Desa tidak berwenang memuat ancaman sanksi pidana kurungan.", "source": "UU No. 12 Tahun 2011 Pasal 15"}, {"id": 423, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Peraturan yang ditetapkan oleh dua Kepala Desa atau lebih dalam rangka kerja sama antardesa (misal pengelolaan sumber mata air bersama) disebut...", "options": ["Peraturan Desa Bersama (Permakades)", "Peraturan Gabungan Camat", "Peraturan Wilayah Dusun", "Keputusan Bersama RT/RW"], "answer": 0, "explanation": "Permendagri No. 111 Tahun 2014 Pasal 2 mengatur Peraturan Bersama Kepala Desa (Permakades) adalah peraturan yang ditetapkan oleh dua atau lebih Kepala Desa dalam rangka kerja sama antardesa.", "source": "Permendagri No. 111 Tahun 2014 Pasal 2"}, {"id": 424, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "mudah", "question": "Berdasarkan UU No. 6 Tahun 2014 Pasal 70, hak apakah yang dimiliki oleh masyarakat desa dalam pembentukan Peraturan Desa?", "options": ["Berhak memveto secara sepihak isi Perdes", "Berhak memberikan masukan secara lisan atau tertulis dalam penyiapan atau pembahasan rancangan Perdes", "Berhak membubarkan tim penyusun rancangan Perdes", "Berhak mengesahkan Perdes tanpa keterlibatan BPD"], "answer": 1, "explanation": "UU No. 6 Tahun 2014 Pasal 70 menjamin hak masyarakat desa untuk memberikan masukan secara lisan atau tertulis dalam penyiapan atau pembahasan rancangan Perdes.", "source": "UU No. 6 Tahun 2014 Pasal 70"}, {"id": 425, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Asas dalam pembentukan regulasi yang memperhitungkan bahwa peraturan yang dibuat dapat berlaku efektif secara filosofis, yuridis, dan sosiologis di masyarakat disebut...", "options": ["Asas dapat dilaksanakan", "Asas kelembagaan yang tepat", "Asas kejelasan rumusan", "Asas keterbukaan"], "answer": 0, "explanation": "UU No. 12 Tahun 2011 Pasal 5 huruf d menjelaskan asas 'dapat dilaksanakan' berarti setiap pembentukan peraturan harus memperhitungkan efektivitas peraturan di dalam masyarakat.", "source": "UU No. 12 Tahun 2011 Pasal 5 huruf d"}, {"id": 426, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Asas 'kedayagunaan dan kehasilgunaan' dalam pembentukan peraturan perundang-undangan (Pasal 5 huruf e UU 12/2011) mengandung makna bahwa...", "options": ["Peraturan dibuat sesering mungkin untuk menyerap anggaran", "Peraturan dibuat karena memang benar-benar dibutuhkan dan bermanfaat dalam mengatur kehidupan masyarakat", "Peraturan harus disalin persis dari peraturan daerah lain", "Peraturan harus menguntungkan pihak pemerintah semata"], "answer": 1, "explanation": "Asas kedayagunaan dan kehasilgunaan menyatakan bahwa setiap peraturan perundang-undangan dibuat karena memang benar-benar dibutuhkan dan bermanfaat dalam mengatur kehidupan bermasyarakat, berbangsa, dan bernegara.", "source": "UU No. 12 Tahun 2011 Pasal 5 huruf e"}, {"id": 427, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "mudah", "question": "Setelah Peraturan Desa diundangkan dalam Lembaran Desa, Pemerintah Desa wajib melakukan sosialisasi kepada...", "options": ["Aparatur kecamatan saja", "Masyarakat desa agar mengetahui dan melaksanakannya", "Pengurus partai politik", "Media cetak nasional"], "answer": 1, "explanation": "Permendagri No. 111 Tahun 2014 mewajibkan sosialisasi Perdes kepada seluruh masyarakat desa agar tercipta ketaatan hukum.", "source": "Permendagri No. 111 Tahun 2014"}, {"id": 428, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Asas hukum yang menyatakan bahwa peraturan hukum yang lebih tinggi mengesampingkan peraturan hukum yang lebih rendah disebut asas...", "options": ["Lex superior derogat legi inferiori", "Lex posterior derogat legi priori", "Lex specialis derogat legi generali", "Pacta sunt servanda"], "answer": 0, "explanation": "Asas Lex Superior Derogat Legi Inferiori adalah prinsip hukum bahwa aturan yang lebih tinggi kedudukannya mengesampingkan aturan yang lebih rendah.", "source": "Prinsip Hukum Perundang-undangan Indonesia"}, {"id": 429, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Asas hukum yang menyatakan bahwa peraturan yang baru mengesampingkan peraturan lama yang sederajat mengenai materi yang sama disebut asas...", "options": ["Lex superior derogat legi inferiori", "Lex posterior derogat legi priori", "Lex specialis derogat legi generali", "Presumption of innocence"], "answer": 1, "explanation": "Asas Lex Posterior Derogat Legi Priori berarti peraturan perundang-undangan baru mengesampingkan peraturan perundang-undangan lama yang mengatur hal yang sama.", "source": "Prinsip Hukum Perundang-undangan Indonesia"}, {"id": 430, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Asas hukum yang menyatakan bahwa norma hukum yang bersifat khusus mengesampingkan norma hukum yang bersifat umum disebut asas...", "options": ["Lex superior derogat legi inferiori", "Lex posterior derogat legi priori", "Lex specialis derogat legi generali", "Equality before the law"], "answer": 2, "explanation": "Asas Lex Specialis Derogat Legi Generali menyatakan bahwa aturan hukum khusus mengesampingkan aturan hukum umum.", "source": "Prinsip Hukum Perundang-undangan Indonesia"}, {"id": 431, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Berdasarkan UU No. 30 Tahun 2014 tentang Administrasi Pemerintahan, Asas Kecermatan menuntut pejabat pemerintahan desa untuk...", "options": ["Menandatangani surat tanpa membaca isinya demi kecepatan pelayanan", "Meneliti seluruh dokumen, fakta hukum, dan bukti secara teliti sebelum menetapkan keputusan", "Menolak seluruh permohonan warga yang tidak dikenal", "Meminta bayaran tambahan atas pemeriksaan dokumen"], "answer": 1, "explanation": "Asas Kecermatan (UU 30/2014 Pasal 10 ayat 1 huruf d) mengharuskan pejabat pemerintah meneliti semua fakta yang relevan dan memasukkan semua aspek yang relevan dalam pertimbangan sebelum menerbitkan keputusan.", "source": "UU No. 30 Tahun 2014 Pasal 10 ayat (1) huruf d"}, {"id": 432, "category": "Peraturan perundang-undangan dan tata kelola pemerintahan", "difficulty": "sedang", "question": "Berdasarkan UU No. 30 Tahun 2014, Keputusan Tata Usaha Negara Desa (Keputusan Kepala Desa) memiliki ciri-ciri pokok...", "options": ["Konkret, individual, dan final", "Abstrak, umum, dan sementara", "Rahasia, sepihak, dan tidak dapat digugat", "Lisan, fleksibel, dan tanpa nomor registrasi"], "answer": 0, "explanation": "Keputusan administrasi pemerintahan bersifat konkret (objeknya nyata), individual (subjeknya tertentu), dan final (sudah definitif dan menimbulkan akibat hukum).", "source": "UU No. 30 Tahun 2014 tentang Administrasi Pemerintahan"}, {"id": 433, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Sikap warga desa yang tidak memaksakan agama atau kepercayaannya kepada tetangga yang berbeda keyakinan merupakan butir pengamalan sila ke-...", "options": ["Sila Pertama", "Sila Kedua", "Sila Ketiga", "Sila Keempat"], "answer": 0, "explanation": "Tidak memaksakan suatu agama dan kepercayaan terhadap Tuhan Yang Maha Esa kepada orang lain adalah butir Sila ke-1 Pancasila.", "source": "Ketetapan MPR No. I/MPR/2003 Butir Sila 1"}, {"id": 434, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Mengembangkan sikap tenggang rasa (tepa salira) dalam pergaulan hidup bermasyarakat di dusun merupakan wujud pengamalan sila ke-...", "options": ["Pertama", "Kedua", "Ketiga", "Kelima"], "answer": 1, "explanation": "Mengembangkan sikap tenggang rasa dan tepa salira merupakan butir pengamalan Sila ke-2 Pancasila: Kemanusiaan yang Adil dan Beradab.", "source": "Ketetapan MPR No. I/MPR/2003 Butir Sila 2"}, {"id": 435, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Pemerintah Desa menggalakkan pemakaian produk kerajinan batik gedog khas Tuban dan olahan pangan lokal warga. Hal ini mencerminkan pengamalan Pancasila sila ke-...", "options": ["Pertama", "Kedua", "Ketiga", "Keempat"], "answer": 2, "explanation": "Bangga sebagai bangsa Indonesia dan cinta tanah air melalui pengutamaan produk lokal adalah perwujudan Sila ke-3: Persatuan Indonesia.", "source": "Ketetapan MPR No. I/MPR/2003 Butir Sila 3"}, {"id": 436, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Menerima dan melaksanakan hasil keputusan musyawarah desa dengan itikad baik dan rasa tanggung jawab moral kepada Tuhan Yang Maha Esa merupakan pengamalan sila ke-...", "options": ["Kedua", "Ketiga", "Keempat", "Kelima"], "answer": 2, "explanation": "Dengan itikad baik dan rasa tanggung jawab menerima dan melaksanakan hasil keputusan musyawarah merupakan butir pokok Sila ke-4 Pancasila.", "source": "Ketetapan MPR No. I/MPR/2003 Butir Sila 4"}, {"id": 437, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Seorang perangkat desa yang mengutamakan kesederhanaan, tidak bergaya hidup mewah, dan tidak memamerkan kekayaan di media sosial mengamalkan nilai sila ke-...", "options": ["Kedua", "Ketiga", "Keempat", "Kelima"], "answer": 3, "explanation": "Tidak bersikap boros dan tidak bergaya hidup mewah merupakan butir pengamalan Sila ke-5 Pancasila: Keadilan Sosial bagi Seluruh Rakyat Indonesia.", "source": "Ketetapan MPR No. I/MPR/2003 Butir Sila 5"}, {"id": 438, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Pasal 28D ayat (1) UUD 1945 menegaskan bahwa setiap orang berhak atas...", "options": ["Bantuan modal usaha cuma-cuma", "Pengakuan, jaminan, perlindungan, dan kepastian hukum yang adil serta perlakuan yang sama di hadapan hukum", "Pembebasan dari seluruh kewajiban membayar pajak", "Jabatan di struktur pemerintahan tanpa melalui seleksi"], "answer": 1, "explanation": "Pasal 28D ayat (1) UUD 1945 berbunyi: 'Setiap orang berhak atas pengakuan, jaminan, perlindungan, dan kepastian hukum yang adil serta perlakuan yang sama dihadapan hukum'.", "source": "UUD NRI 1945 Pasal 28D ayat (1)"}, {"id": 439, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "sedang", "question": "Berdasarkan Pasal 30 ayat (2) UUD 1945, usaha pertahanan dan keamanan negara dilaksanakan melalui sistem pertahanan dan keamanan rakyat semesta dengan kedudukan TNI dan Polri sebagai...", "options": ["Kekuatan utama", "Kekuatan pendukung", "Satu-satunya komponen", "Penonton pasif"], "answer": 0, "explanation": "Pasal 30 ayat (2) UUD 1945 menyebutkan usaha pertahanan dan keamanan negara dilaksanakan melalui Sishankamrata dengan Tentara Nasional Indonesia dan Kepolisian Negara RI sebagai kekuatan utama, dan rakyat sebagai kekuatan pendukung.", "source": "UUD NRI 1945 Pasal 30 ayat (2)"}, {"id": 440, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Penyediaan sarana belajar Pos PAUD dan beasiswa bagi anak tidak mampu di desa merupakan implementasi amanat konstitusi Pasal 31 ayat (1) UUD 1945 yang berbunyi...", "options": ["Setiap warga negara berhak mendapat pendidikan", "Negara memajukan kebudayaan nasional", "Pemerintah memajukan ilmu pengetahuan dan teknologi", "Fakir miskin dipelihara oleh negara"], "answer": 0, "explanation": "Pasal 31 ayat (1) UUD 1945 berbunyi: 'Setiap warga negara berhak mendapat pendidikan'.", "source": "UUD NRI 1945 Pasal 31 ayat (1)"}, {"id": 441, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Berdasarkan Pasal 33 ayat (1) UUD 1945, sistem perekonomian nasional Indonesia disusun sebagai usaha bersama berdasar atas asas...", "options": ["Persaingan bebas kapitalistik", "Kekeluargaan", "Monopoli pemerintah semata", "Konglomerasi swasta"], "answer": 1, "explanation": "Pasal 33 ayat (1) UUD 1945 menyatakan: 'Perekonomian disusun sebagai usaha bersama berdasar atas asas kekeluargaan'. Asas ini menjiwai pembentukan Koperasi dan BUMDes.", "source": "UUD NRI 1945 Pasal 33 ayat (1)"}, {"id": 442, "category": "Pancasila, UUD 1945, dan wawasan kebangsaan", "difficulty": "mudah", "question": "Jumlah bulu pada sayap burung Garuda Pancasila berjumlah 17 helai, pada ekor 8 helai, pada pangkal ekor 19 helai, dan pada leher 45 helai. Kombinasi angka tersebut melambangkan...", "options": ["Jumlah pasal dalam Undang-Undang Dasar 1945", "Tanggal Proklamasi Kemerdekaan Republik Indonesia (17 Agustus 1945)", "Jumlah pahlawan nasional yang menandatangani teks proklamasi", "Jumlah kementerian koordinator era kabinet pertama"], "answer": 1, "explanation": "Konfigurasi jumlah bulu lambang Garuda Pancasila melambangkan momentum bersejarah Proklamasi Kemerdekaan RI yaitu tanggal 17 Agustus 1945 (17-8-1945).", "source": "UU No. 24 Tahun 2009 tentang Bendera, Bahasa, dan Lambang Negara"}, {"id": 443, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Buku administrasi umum desa yang khusus mencatat luas, lokasi, status perolehan, dan nama pemegang hak sewa atas tanah milik pemerintah desa adalah...", "options": ["Buku Tanah Kas Desa", "Buku Kas Umum", "Buku Ekspedisi", "Buku Rencana Anggaran Biaya"], "answer": 0, "explanation": "Permendagri No. 47 Tahun 2016 mengatur Buku Tanah Kas Desa sebagai register resmi untuk mencatat status, asal-usul, luas, dan pemanfaatan tanah bengkok/kas desa.", "source": "Permendagri No. 47 Tahun 2016"}, {"id": 444, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Buku administrasi umum yang digunakan untuk mencatat nomor urut, nomor keputusan, tanggal penetapan, dan perihal Keputusan Kepala Desa adalah...", "options": ["Buku Data Peraturan Desa", "Buku Data Keputusan Kepala Desa", "Buku Register Surat Keterangan", "Buku Lembaran Daerah"], "answer": 1, "explanation": "Permendagri No. 47 Tahun 2016 mengatur Buku Data Keputusan Kepala Desa untuk membukukan seluruh Surat Keputusan (SK) yang diterbitkan Kepala Desa.", "source": "Permendagri No. 47 Tahun 2016"}, {"id": 445, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Warga pendatang yang berdomisili sementara di suatu desa untuk keperluan kerja proyek tanpa pindah KTP dicatatkan oleh perangkat desa ke dalam...", "options": ["Buku Data Induk Penduduk", "Buku Data Penduduk Sementara", "Buku Inventaris Desa", "Buku Agenda Rahasia"], "answer": 1, "explanation": "Buku Data Penduduk Sementara digunakan untuk mencatat setiap warga yang berdomisili di desa tetapi tidak memiliki KTP-el desa setempat.", "source": "Permendagri No. 47 Tahun 2016 Lampiran Administrasi Kependudukan"}, {"id": 446, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Buku administrasi pembangunan desa yang mencatat nama, jenis kelamin, keahlian, dan bidang tugas tenaga penggerak swadaya masyarakat adalah...", "options": ["Buku Rencana Kerja Pembangunan", "Buku Kader Pemberdayaan Masyarakat Desa (KPMD)", "Buku Inventarisasi Hasil Pembangunan", "Buku Kas Pembantu Kegiatan"], "answer": 1, "explanation": "Permendagri No. 47 Tahun 2016 mengatur Buku Kader Pemberdayaan Masyarakat untuk mencatat identitas dan peran kader pendamping pembangunan desa.", "source": "Permendagri No. 47 Tahun 2016"}, {"id": 447, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Pada naskah dinas resmi yang ditandatangani oleh Kepala Desa, penulisan nama pejabat penandatangan yang tepat adalah...", "options": ["Nama lengkap dengan gelar akademis dan tanpa mencantumkan NIP (kecuali Kades PNS)", "Nama lengkap disertai nomor rekening bank", "Hanya paraf kecil tanpa nama terang", "Nama samaran atau julukan warga"], "answer": 0, "explanation": "Format baku tanda tangan Kepala Desa mencantumkan nama jabatan di atas tanda tangan, nama lengkap pejabat (ditambah gelar bila ada), dan tidak mencantumkan NIP karena Kades merupakan jabatan politis/bukan PNS (kecuali Kades penjabat/Pj. PNS).", "source": "Permendagri No. 1 Tahun 2023 tentang Tata Naskah Dinas"}, {"id": 448, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Cap dinas (stempel) resmi Pemerintah Desa dibubuhkan pada bagian...", "options": ["Pojok kanan atas surat mengenai perangko", "Menyentuh bagian kiri tanda tangan pejabat penandatangan naskah dinas", "Tepat di tengah teks isi surat", "Halaman belakang amplop surat saja"], "answer": 1, "explanation": "Sesuai kaidah tata naskah dinas, cap dinas dibubuhkan di sebelah kiri menyinggung sedikit bagian tanda tangan pejabat penandatangan.", "source": "Permendagri No. 1 Tahun 2023 tentang Tata Naskah Dinas"}, {"id": 449, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Bagian penutup amar putusan pada Surat Keputusan (SK) Kepala Desa yang memuat tanggal berlakunya keputusan tersebut biasanya dirumuskan pada diktum...", "options": ["Menimbang", "Mengingat", "MEMUTUSKAN: KESATU / KEDUA / KETIGA", "Lampiran Tabel"], "answer": 2, "explanation": "Amar keputusan dan klausul mulai berlakunya keputusan dirumuskan dalam Diktum 'MEMUTUSKAN: Menetapkan...' (misal Diktum KETIGA: Keputusan ini mulai berlaku pada tanggal ditetapkan).", "source": "Tata Naskah Dinas Keputusan Kepala Desa"}, {"id": 450, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Dalam pelaksanaan pemusnahan arsip dinas kantor desa yang telah melewati batas retensi dan tidak memiliki nilai guna, dokumen legalitas yang wajib dibuat adalah...", "options": ["Berita Acara Pemusnahan Arsip dan Daftar Pertelaan Arsip yang Dimusnahkan", "Kuitansi pembayaran biaya pembakaran berkas", "Surat peringatan kepada mantan pegawai", "Peraturan Desa tentang Pembakaran Sampah Kantor"], "answer": 0, "explanation": "UU No. 43 Tahun 2009 Pasal 66 mewajibkan setiap pemusnahan arsip disertai Berita Acara Pemusnahan Arsip dan daftar pertelaan arsip serta disaksikan minimal 2 orang saksi bidang hukum/pengawasan.", "source": "UU No. 43 Tahun 2009 tentang Kearsipan Pasal 66"}, {"id": 451, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "mudah", "question": "Surat dinas yang diterbitkan oleh Kepala Desa untuk menerangkan status domisili, usaha, atau keadaan belum menikah warga disebut...", "options": ["Surat Perintah Tugas", "Surat Keterangan Desa (SKD)", "Nota Dinas", "Lembar Disposisi"], "answer": 1, "explanation": "Surat Keterangan Desa adalah naskah dinas yang memuat keterangan resmi mengenai suatu fakta atau keadaan seseorang/barang yang diketahui pemerintah desa.", "source": "Pedoman Tata Naskah Dinas Kemendagri"}, {"id": 452, "category": "Administrasi pemerintahan, surat-menyurat, dan pengarsipan", "difficulty": "sedang", "question": "Naskah dinas yang berisi pelimpahan wewenang dari Kepala Desa kepada Sekretaris Desa untuk menandatangani surat-surat tertentu selama Kepala Desa menjalankan dinas luar kota disebut...", "options": ["Surat Kuasa / Surat Pelimpahan Kewenangan", "Surat Edaran", "Surat Perjanjian Kerja Bersama", "Surat Pengantar"], "answer": 0, "explanation": "Surat Kuasa Kedinasan / Surat Pelimpahan Wewenang adalah naskah dinas resmi untuk melimpahkan wewenang tertentu kepada pejabat bawahan.", "source": "Tata Naskah Dinas Kemendagri"}, {"id": 453, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 20 Tahun 2018, dokumen yang memuat perkiraan penerimaan kas dan kebutuhan penarikan dana belanja per bulan atau triwulan adalah...", "options": ["Rencana Kerja Pemerintah Desa (RKP Desa)", "Rencana Anggaran Kas Desa (RAK Desa)", "Buku Bank Kas Desa", "Laporan Keterangan Penyelenggaraan Pemdes"], "answer": 1, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 38 mengatur bahwa Rencana Anggaran Kas (RAK) Desa disusun oleh Kaur Keuangan untuk mengendalikan arus kas masuk dan arus kas keluar setiap periode.", "source": "Permendagri No. 20 Tahun 2018 Pasal 38"}, {"id": 454, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Dokumen Pelaksanaan Anggaran (DPA) yang memuat rencana kegiatan dan rincian belanja disusun oleh...", "options": ["Kepala Seksi dan Kepala Urusan selaku Pelaksana Kegiatan Anggaran (PKA)", "Ketua BPD bersama Camat", "Tenaga Ahli Pemberdayaan Masyarakat Kabupaten", "Pengurus Karang Taruna"], "answer": 0, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 35 menyebutkan Kaur dan Kasi selaku PKA menyusun DPA paling lambat 6 hari kerja setelah Perdes APB Desa ditetapkan.", "source": "Permendagri No. 20 Tahun 2018 Pasal 35"}, {"id": 455, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 20 Tahun 2018, buku pembantu yang digunakan oleh Kaur Keuangan (Bendahara Desa) untuk mencatat seluruh transaksi penerimaan dan pengeluaran yang dilakukan melalui rekening perbankan kas desa adalah...", "options": ["Buku Pembantu Pajak", "Buku Pembantu Bank", "Buku Kas Pembantu Panjar", "Buku Inventaris Hasil Pembangunan"], "answer": 1, "explanation": "Buku Pembantu Bank merupakan buku pembantu dalam penatausahaan keuangan desa yang digunakan untuk mencatat seluruh mutasi debet dan kredit pada Rekening Kas Desa (RKD) secara tertib.", "source": "Permendagri No. 20 Tahun 2018 Lampiran Penatausahaan Keuangan Desa"}, {"id": 456, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Kepala Desa wajib menyampaikan Laporan Pertanggungjawaban (LPJ) Realisasi Pelaksanaan APB Desa kepada Bupati/Wali Kota melalui Camat setiap akhir tahun anggaran, paling lambat pada...", "options": ["1 bulan setelah akhir tahun anggaran (akhir Januari)", "3 bulan setelah akhir tahun anggaran (akhir Maret)", "6 bulan setelah akhir tahun anggaran (akhir Juni)", "Akhir tahun anggaran berjalan (31 Desember)"], "answer": 1, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 70 ayat (1) mengatur bahwa Kepala Desa menyampaikan laporan pertanggungjawaban realisasi pelaksanaan APB Desa kepada Bupati/Wali Kota melalui Camat paling lambat 3 (tiga) bulan setelah akhir tahun anggaran berkenaan yang ditetapkan dengan Peraturan Desa.", "source": "Permendagri No. 20 Tahun 2018 Pasal 70 ayat (1)"}, {"id": 457, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sulit", "question": "Berdasarkan Permendagri No. 1 Tahun 2016, pemanfaatan aset desa berupa tanah melalui skema Bangun Guna Serah (BGS) dapat dilakukan paling lama untuk jangka waktu...", "options": ["5 tahun", "10 tahun", "20 tahun", "50 tahun"], "answer": 2, "explanation": "Permendagri No. 1 Tahun 2016 Pasal 14 ayat (3) mengatur bahwa jangka waktu Bangun Guna Serah (BGS) dan Bangun Serah Guna (BSG) paling lama 20 (dua puluh) tahun dan dapat diperpanjang.", "source": "Permendagri No. 1 Tahun 2016 Pasal 14 ayat (3)"}, {"id": 458, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 1 Tahun 2016, pemanfaatan aset desa berupa Pinjam Pakai barang milik desa dapat dilakukan antar...", "options": ["Pemerintah Desa dengan perusahaan swasta multinasional untuk bisnis", "Pemerintah Desa dengan Pemerintah Desa lain atau Lembaga Kemasyarakatan Desa tanpa imbalan uang", "Kepala Desa dengan anggota keluarganya untuk kepentingan pribadi", "Pemerintah Desa dengan pengurus partai politik untuk kampanye"], "answer": 1, "explanation": "Permendagri No. 1 Tahun 2016 Pasal 12 menjelaskan Pinjam Pakai aset desa dilakukan antara Pemdes dengan Pemda/Pemdes lain atau Lembaga Kemasyarakatan Desa untuk kepentingan umum tanpa memungut imbalan.", "source": "Permendagri No. 1 Tahun 2016 Pasal 12"}, {"id": 459, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "mudah", "question": "Semua penerimaan dan pengeluaran desa dalam rangka pelaksanaan APB Desa wajib dilakukan melalui...", "options": ["Rekening Kas Desa (RKD) pada bank pemerintah yang ditunjuk", "Dompet digital pribadi Kaur Keuangan", "Kotak brankas rahasia di rumah Kepala Desa", "Rekening giro pengurus BPD"], "answer": 0, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 14 menegaskan seluruh transaksi keuangan desa wajib disalurkan melalui Rekening Kas Desa (RKD).", "source": "Permendagri No. 20 Tahun 2018 Pasal 14"}, {"id": 460, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Berdasarkan Peraturan LKPP No. 12 Tahun 2019 tentang Pedoman Pengadaan Barang/Jasa di Desa, bentuk dokumen bukti perjanjian pengadaan barang/jasa melalui Penyedia yang bernilai di atas Rp50.000.000,00 sampai dengan Rp200.000.000,00 adalah...", "options": ["Bukti Pembelian / Nota Kontan", "Kuitansi bermeterai", "Surat Perjanjian Kerja (SPK)", "Surat Perjanjian (Kontrak formal)"], "answer": 2, "explanation": "Perka LKPP No. 12 Tahun 2019 mengatur bentuk bukti transaksi: Bukti pembelian (s.d. Rp10 jt), Kuitansi (s.d. Rp50 jt), Surat Perjanjian Kerja/SPK (di atas Rp50 jt s.d. Rp200 jt), dan Surat Perjanjian Kontrak (di atas Rp200 jt).", "source": "Peraturan LKPP No. 12 Tahun 2019 tentang Pengadaan Barang/Jasa di Desa"}, {"id": 461, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "mudah", "question": "Kelompok pendapatan desa yang bersumber dari Bagi Hasil Pajak Daerah dan Retribusi Daerah (BHPR) Kabupaten termasuk dalam kelompok...", "options": ["Pendapatan Asli Desa (PADes)", "Pendapatan Transfer", "Pendapatan Lain-lain", "Penerimaan Pembiayaan"], "answer": 1, "explanation": "Permendagri No. 20 Tahun 2018 Pasal 11 menyatakan kelompok Pendapatan Transfer terdiri dari: Dana Desa, ADD, Bagi Hasil Pajak dan Retribusi Daerah (BHPR), serta Bantuan Keuangan.", "source": "Permendagri No. 20 Tahun 2018 Pasal 11"}, {"id": 462, "category": "Keuangan desa, APB Desa, dan aset desa", "difficulty": "sedang", "question": "Bendahara Desa wajib memungut Pajak Penghasilan (PPh) Pasal 22 sebesar 1,5% atas transaksi belanja barang jika nilai transaksi...", "options": ["Di atas Rp1.000.000,00 tidak termasuk PPN", "Di atas Rp2.000.000,00 tidak termasuk PPN", "Di atas Rp5.000.000,00 termasuk PPN", "Di atas Rp10.000.000,00 termasuk PPN"], "answer": 1, "explanation": "Sesuai ketentuan perpajakan bendahara instansi pemerintah, pemungutan PPh Pasal 22 dikenakan atas belanja pengadaan barang dengan nilai di atas Rp2.000.000,00 tidak termasuk PPN (PMK No. 231/PMK.03/2019).", "source": "PMK No. 231/PMK.03/2019 tentang Pemungutan Pajak oleh Bendahara"}, {"id": 463, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Dalam tahapan penyusunan Rencana Kerja Pemerintah Desa (RKP Desa), tujuan dilakukannya pencermatan ulang terhadap dokumen RPJM Desa adalah...", "options": ["Mengubah visi dan misi Kepala Desa yang telah ditetapkan sebelumnya", "Menyelaraskan rencana program tahunan dengan arah kebijakan pembangunan 8 tahun serta mengevaluasi program yang belum terlaksana di tahun sebelumnya", "Menghapus program pemberdayaan masyarakat agar anggaran fokus pada kantor desa", "Mengganti susunan pengurus BPD dan lembaga desa"], "answer": 1, "explanation": "Pencermatan ulang RPJM Desa dalam penyusunan RKP Desa bertujuan untuk menyelaraskan program kegiatan prioritas tahun berjalan dengan dokumen perencanaan jangka menengah (RPJMDes) serta meninjau kegiatan luncuran yang belum terealisasi pada tahun sebelumnya.", "source": "Permendesa PDTT No. 21 Tahun 2020 tentang Pedoman Umum Pembangunan dan Pemberdayaan Masyarakat Desa"}, {"id": 464, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Dalam Musrenbangdes pembahasan rancangan RKP Desa, keterlibatan kelompok perempuan, kelompok disabilitas, dan warga miskin dijamin regulasi untuk mewujudkan prinsip...", "options": ["Pembangunan eksklusif elit desa", "Pembangunan desa yang partisipatif dan inklusif", "Pengurangan peran pemerintah desa", "Peniadaan kewenangan BPD"], "answer": 1, "explanation": "Pembangunan inklusif memastikan semua lapisan masyarakat, khususnya kelompok rentan dan marginal, memiliki hak bersuara dan terakomodasi kebutuhannya dalam perencanaan desa.", "source": "Permendesa PDTT No. 21 Tahun 2020"}, {"id": 465, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "SDGs Desa Tujuan ke-5 yaitu 'Keterlibatan Perempuan Desa' mengamanatkan bahwa dalam kelembagaan desa dan musyawarah desa...", "options": ["Perempuan dilarang mencalonkan diri menjadi kepala desa", "Keterwakilan perempuan sekurang-kurangnya 30% dalam pengambilan keputusan pembangunan desa", "Hanya kaum pria yang boleh mengelola BUMDes", "Perempuan hanya diperkenankan menjadi staf administrasi tanpa hak suara"], "answer": 1, "explanation": "Tujuan ke-5 SDGs Desa mendorong kesetaraan gender dan keterlibatan aktif perempuan minimal 30% di berbagai forum musyawarah desa dan kepengurusan kelembagaan desa.", "source": "Permendesa PDTT No. 21 Tahun 2020 tentang SDGs Desa"}, {"id": 466, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "mudah", "question": "Upaya Pemerintah Desa menyediakan sarana air bersih melalui program HIPPAM (Himpunan Penduduk Pemakai Air Minum) dan jamban sehat warga sejalan dengan SDGs Desa tujuan ke-...", "options": ["Ke-2: Desa Tanpa Kelaparan", "Ke-6: Desa Layak Air Bersih dan Sanitasi", "Ke-7: Desa Berenergi Bersih", "Ke-13: Tanggap Perubahan Iklim"], "answer": 1, "explanation": "SDGs Desa tujuan ke-6 adalah 'Desa Layak Air Bersih dan Sanitasi' yang menargetkan akses air minum aman dan sanitasi yang layak bagi seluruh warga desa.", "source": "Permendesa PDTT No. 21 Tahun 2020 tentang SDGs Desa"}, {"id": 467, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Berdasarkan PP No. 11 Tahun 2021, modal awal pendirian BUMDes bersumber dari APB Desa melalui mekanisme...", "options": ["Pinjaman bank komersial berbunga tinggi", "Penyertaan modal desa yang ditetapkan dengan Peraturan Desa", "Iuran wajib seluruh kepala keluarga di desa", "Pungutan liar sewa lahan perumahan warga"], "answer": 1, "explanation": "PP No. 11 Tahun 2021 Pasal 39 menyebutkan bahwa modal awal BUMDes bersumber dari APB Desa melalui pos penyertaan modal desa yang ditetapkan dengan Peraturan Desa.", "source": "PP No. 11 Tahun 2021 Pasal 39"}, {"id": 468, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Apabila beberapa desa di suatu kawasan kecamatan ingin mendirikan usaha pariwisata terpadu bersama, kelembagaan ekonomi yang tepat dibentuk adalah...", "options": ["BUMDes Bersama (BUMDesma)", "Koperasi Simpan Pinjam Swasta", "Perseroan Terbatas Milik Camat", "Yayasan Amal Lingkungan"], "answer": 0, "explanation": "PP No. 11 Tahun 2021 mengatur pendirian BUMDes Bersama (BUMDesma) yang didirikan oleh 2 (dua) desa atau lebih dalam rangka kerja sama antardesa.", "source": "PP No. 11 Tahun 2021 Pasal 7"}, {"id": 469, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "mudah", "question": "Berdasarkan Permendagri No. 18 Tahun 2018, pengurus Lembaga Kemasyarakatan Desa (LKD) seperti Ketua RT, RW, dan PKK dilarang...", "options": ["Mengadakan kegiatan gotong royong warga", "Menjadi pengurus atau berafiliasi dengan partai politik", "Menghadiri musyawarah perencanaan desa", "Mengikuti pelatihan peningkatan kapasitas kader"], "answer": 1, "explanation": "Permendagri No. 18 Tahun 2018 Pasal 8 ayat (5) tegas melarang pengurus LKD merangkap jabatan pada LKD lainnya dan dilarang menjadi anggota partai politik.", "source": "Permendagri No. 18 Tahun 2018 Pasal 8 ayat (5)"}, {"id": 470, "category": "Pembangunan desa, perencanaan, dan pemberdayaan masyarakat", "difficulty": "sedang", "question": "Tahapan siklus pembangunan desa yang benar dan berurutan sesuai regulasi adalah...", "options": ["Pelaksanaan kegiatan - Perencanaan - Pengawasan - Evaluasi", "Perencanaan - Penganggaran - Pelaksanaan - Pertanggungjawaban/Evaluasi", "Penganggaran - Evaluasi - Perencanaan - Pelaksanaan", "Pertanggungjawaban - Pelaksanaan - Perencanaan - Penganggaran"], "answer": 1, "explanation": "Siklus tata kelola pembangunan desa berurutan: Perencanaan (RPJM/RKP Desa) -> Penganggaran (APB Desa) -> Pelaksanaan Kegiatan -> Pertanggungjawaban dan Evaluasi.", "source": "Permendagri No. 114 Tahun 2014 & Permendesa 21/2020"}, {"id": 471, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "mudah", "question": "Berdasarkan UU No. 6 Tahun 2014 Pasal 55 huruf a, BPD berwenang bersama Kepala Desa untuk...", "options": ["Membahas dan menyepakati Rancangan Peraturan Desa", "Menetapkan besaran gaji PNS di kantor kecamatan", "Mengadili perkara pidana warga desa di pengadilan", "Menjual aset tanah kas desa secara bebas"], "answer": 0, "explanation": "Fungsi legislasi BPD adalah membahas dan menyepakati rancangan Peraturan Desa (Perdes) bersama Kepala Desa.", "source": "UU No. 6 Tahun 2014 Pasal 55 huruf a"}, {"id": 472, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Berdasarkan UU No. 6 Tahun 2014 Pasal 61 huruf a, BPD berhak meminta keterangan kepada Pemerintah Desa mengenai...", "options": ["Kehidupan rumah tangga pribadi perangkat desa", "Penyelenggaraan pemerintahan desa dan pengelolaan keuangan desa", "Daftar kekayaan pribadi warga desa yang bukan pejabat", "Hasil pemeriksaan kesehatan dokter warga desa"], "answer": 1, "explanation": "BPD berhak meminta keterangan tertulis atau lisan dari Pemerintah Desa terkait penyelenggaraan pemerintahan desa dalam rangka fungsi pengawasan.", "source": "UU No. 6 Tahun 2014 Pasal 61 huruf a"}, {"id": 473, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "sedang", "question": "Berdasarkan Permendagri No. 110 Tahun 2016, rapat BPD dinyatakan kuorum dan sah untuk mengambil keputusan jika dihadiri oleh paling sedikit...", "options": ["1/2 dari jumlah anggota BPD", "2/3 dari jumlah anggota BPD", "3/4 dari jumlah anggota BPD", "Seluruh anggota BPD (100%)"], "answer": 1, "explanation": "Permendagri No. 110 Tahun 2016 Pasal 40 mengatur bahwa rapat BPD dinyatakan sah apabila dihadiri oleh paling sedikit 2/3 (dua pertiga) dari jumlah anggota BPD.", "source": "Permendagri No. 110 Tahun 2016 Pasal 40"}, {"id": 474, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "mudah", "question": "Dalam pengambilan keputusan di Musyawarah Desa, apabila upaya musyawarah mufakat tidak tercapai setelah diusahakan berulang kali, maka keputusan dapat diambil melalui...", "options": ["Penunjukan sepihak oleh Camat", "Pemungutan suara terbanyak (voting)", "Adu kekuatan fisik antarpendukung", "Pengundian koin uang logam"], "answer": 1, "explanation": "Apabila musyawarah untuk mufakat tidak tercapai, keputusan diambil berdasarkan pemungutan suara terbanyak (voting) secara demokratis.", "source": "Permendagri No. 110 Tahun 2016"}, {"id": 475, "category": "BPD, kelembagaan desa, dan musyawarah", "difficulty": "mudah", "question": "Tunjangan dan operasional pimpinan serta anggota BPD bersumber dari...", "options": ["Anggaran Pendapatan dan Belanja Desa (APB Desa)", "Sumbangan sukarela bulanan warga miskin", "Hasil pemotongan bantuan sosial PKH", "Pinjaman online atas nama desa"], "answer": 0, "explanation": "PP No. 11 Tahun 2019 dan Permendagri 110/2016 menetapkan tunjangan kedudukan dan biaya operasional BPD dianggarkan resmi dalam APB Desa (bersumber dari ADD).", "source": "PP No. 11 Tahun 2019 Pasal 100"}, {"id": 476, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Manakah deretan kata serapan berikut yang seluruhnya baku sesuai Ejaan Bahasa Indonesia yang Disempurnakan (EYD V)?", "options": ["Analisa, sistim, kwalitas", "Analisis, sistem, kualitas", "Analisis, sistim, kwalitas", "Analisa, sistem, kualitas"], "answer": 1, "explanation": "Bentuk baku yang tepat menurut EYD V dan KBBI adalah 'analisis' (bukan analisa), 'sistem' (bukan sistim), dan 'kualitas' (bukan kwalitas).", "source": "EYD Edisi V & KBBI Daring"}, {"id": 477, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Berdasarkan kaidah EYD V tentang penulisan bilangan, manakah penulisan kalimat yang tepat?", "options": ["Rapat desa itu dihadiri oleh 3 orang narasumber ahli.", "Rapat desa itu dihadiri oleh tiga orang narasumber ahli.", "Rapat desa itu dihadiri oleh 3 (tiga) orang narasumber ahli.", "Rapat desa itu dihadiri oleh ke-3 orang narasumber ahli."], "answer": 1, "explanation": "Bilangan dalam teks yang dapat dinyatakan dengan satu atau dua kata ditulis dengan huruf ('tiga orang'), kecuali jika dipakai berurutan seperti dalam perincian naskah dinas formal.", "source": "EYD Edisi V Penulisan Bilangan dan Angka"}, {"id": 478, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Penulisan singkatan resmi nama peraturan perundang-undangan negara yang tepat adalah...", "options": ["U.U.D. 1945 dan P.E.R.D.E.S.", "UUD 1945 dan PERDES", "uud 1945 dan perdes", "Uud 1945 dan PerDes"], "answer": 1, "explanation": "Singkatan nama resmi lembaga pemerintahan dan dokumen resmi negara terdiri atas huruf kapital tanpa tanda titik di antaranya (misal: UUD, UU, PP, PERDES).", "source": "EYD Edisi V Penulisan Singkatan dan Akronim"}, {"id": 479, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Cermati kalimat penutup surat dinas berikut: 'Demikian surat permohonan ini, atas perhatian dan bantuannya kami haturkan beribu-ribu terima kasih.' Perbaikan kalimat tersebut agar efektif dan lugas adalah...", "options": ["Demikian surat ini kami sampaikan, atas perhatian Bapak/Ibu kami haturkan banyak-banyak terima kasih.", "Demikian surat permohonan ini disampaikan. Atas perhatian Saudara, kami ucapkan terima kasih.", "Demikianlah surat kami sampaikan, kami ucapkan ribuan terima kasih yang mendalam.", "Atas perhatiannya kami haturkan banyak terima kasih."], "answer": 1, "explanation": "Kalimat penutup surat dinas yang efektif harus hemat kata, lugas, dan santun. Bentuk 'kami ucapkan terima kasih' baku dan tidak berlebihan (tanpa 'beribu-ribu' atau 'banyak-banyak').", "source": "Pedoman Penulisan Surat Dinas Baku Bahasa Indonesia"}, {"id": 480, "category": "Bahasa Indonesia", "difficulty": "sedang", "question": "Penggunaan huruf miring (italics) yang benar dalam naskah surat dinas pemerintahan adalah...", "options": ["Kepala Desa menjabat secara *ex-officio* sebagai Penasihat BUMDes.", "Kepala Desa menjabat secara EX-OFFICIO sebagai Penasihat BUMDes.", "Kepala Desa menjabat secara 'ex-officio' sebagai Penasihat BUMDes.", "Kepala Desa menjabat secara ex-officio sebagai Penasihat BUMDes."], "answer": 0, "explanation": "Huruf miring dipakai untuk menuliskan kata atau ungkapan dalam bahasa daerah atau bahasa asing yang belum diserap ke dalam bahasa Indonesia (seperti istilah Latin 'ex-officio'). Pilihan lain salah karena dicetak tegak biasa tanpa miring, menggunakan huruf kapital seluruhnya, atau sekadar diapit tanda petik.", "source": "EYD Edisi V Penggunaan Huruf Miring"}, {"id": 481, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Manakah penulisan kata depan 'di' dan awalan 'di-' berikut yang seluruhnya tepat?", "options": ["Surat itu ditanda tangani di balai desa.", "Surat itu ditandatangani dibalai desa.", "Surat itu ditandatangani di balai desa.", "Surat itu di tandatangani di-balai desa."], "answer": 2, "explanation": "Awalan 'di-' pada kata kerja pasif ditulis serangkai ('ditandatangani'), sedangkan kata depan 'di' yang menunjukkan tempat ditulis terpisah ('di balai desa').", "source": "EYD Edisi V Penulisan Kata Depan"}, {"id": 482, "category": "Bahasa Indonesia", "difficulty": "mudah", "question": "Pilihlah pasangan kata baku yang tepat sesuai kaidah EYD V!", "options": ["Standarisasi dan komoditi", "Standardisasi dan komoditas", "Standarisasi dan komoditas", "Standardisasi dan komoditi"], "answer": 1, "explanation": "Bentuk kata serapan yang baku adalah 'standardisasi' (imbuhan -isasi dari standard) dan 'komoditas' (bukan komoditi).", "source": "EYD Edisi V & KBBI Daring"}, {"id": 483, "category": "Matematika dan numerik", "difficulty": "mudah", "question": "Total pagu Belanja Desa dalam APB Desa adalah Rp1.500.000.000,00. Jika anggaran yang dialokasikan untuk Bidang Pelaksanaan Pembangunan Desa adalah Rp600.000.000,00, berapa persentase anggaran pembangunan tersebut terhadap total belanja desa?", "options": ["35%", "40%", "45%", "50%"], "answer": 1, "explanation": "Persentase = (Rp600.000.000,00 / Rp1.500.000.000,00) x 100% = 4/10 x 100% = 40%.", "source": "Aritmetika Sosial Persentase Anggaran"}, {"id": 484, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Pemerintah Desa memberikan honorarium narasumber pelatihan aparatur desa sebesar Rp2.000.000,00 kepada seorang narasumber profesional (non-PNS dan ber-NPWP). Jika tarif PPh Pasal 21 adalah 5%, berapakah uang honor bersih yang diterima narasumber tersebut?", "options": ["Rp1.800.000,00", "Rp1.900.000,00", "Rp1.950.000,00", "Rp1.980.000,00"], "answer": 1, "explanation": "Potongan PPh 21 = 5% x Rp2.000.000,00 = Rp100.000,00. Honor bersih = Rp2.000.000,00 - Rp100.000,00 = Rp1.900.000,00.", "source": "Perhitungan Pajak Penghasilan PPh 21"}, {"id": 485, "category": "Matematika dan numerik", "difficulty": "mudah", "question": "Sebidang tanah lapangan olahraga milik desa memiliki luas 1,2 hektar. Berapakah luas tanah tersebut jika dikonversikan ke dalam satuan are?", "options": ["12 are", "120 are", "1.200 are", "12.000 are"], "answer": 1, "explanation": "1 hektar (ha) = 100 are (1 are = 100 m²). Maka 1,2 hektar = 1,2 x 100 = 120 are.", "source": "Konversi Satuan Ukuran Luas"}, {"id": 486, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Perangkat desa mengantarkan berkas LPPD ke kantor kecamatan berjarak 10 km dengan sepeda motor berkecepatan rata-rata 40 km/jam. Berapa menit waktu yang dibutuhkan untuk tiba di kantor kecamatan?", "options": ["10 menit", "15 menit", "20 menit", "25 menit"], "answer": 1, "explanation": "Waktu tempuh = Jarak / Kecepatan = 10 km / 40 km/jam = 0,25 jam. Dikonversi ke menit: 0,25 x 60 menit = 15 menit.", "source": "Perhitungan Waktu, Kecepatan, dan Jarak"}, {"id": 487, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Rekening kas desa di bank daerah memiliki saldo rata-rata mengendap sebesar Rp300.000.000,00. Bank memberikan bunga jasa giro bersih 0,3% per bulan setelah dipotong pajak. Berapakah pendapatan jasa giro yang masuk ke kas desa pada bulan tersebut?", "options": ["Rp600.000,00", "Rp900.000,00", "Rp1.200.000,00", "Rp1.500.000,00"], "answer": 1, "explanation": "Jasa giro = 0,3% x Rp300.000.000,00 = 0,003 x 300.000.000 = Rp900.000,00.", "source": "Aritmetika Keuangan Perbankan"}, {"id": 488, "category": "Matematika dan numerik", "difficulty": "sedang", "question": "Program bantuan material bedah rumah (RTLH) desa disalurkan secara bertahap dengan pola barisan aritmetika: Tahap 1 sebesar Rp5.000.000,00; Tahap 2 sebesar Rp7.500.000,00; Tahap 3 sebesar Rp10.000.000,00. Berapakah nilai bantuan yang disalurkan pada Tahap ke-5?", "options": ["Rp12.500.000,00", "Rp15.000.000,00", "Rp17.500.000,00", "Rp20.000.000,00"], "answer": 1, "explanation": "Suku pertama (a) = 5.000.000, beda (b) = 2.500.000. Suku ke-5 (U5) = a + (5 - 1)b = 5.000.000 + 4 x 2.500.000 = 5.000.000 + 10.000.000 = Rp15.000.000,00.", "source": "Barisan dan Deret Aritmetika"}, {"id": 489, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Premis 1: Semua pengelola keuangan desa wajib menandatangani pakta integritas pencegahan korupsi.\nPremis 2: Sebagian staf pembantu umum desa bukan pengelola keuangan desa.\nKesimpulan yang sah adalah...", "options": ["Semua staf pembantu umum wajib menandatangani pakta integritas", "Sebagian staf pembantu umum desa tidak wajib menandatangani pakta integritas pencegahan korupsi pengelola keuangan", "Tidak ada staf pembantu umum yang boleh bertugas di kantor desa", "Semua pengelola keuangan adalah staf pembantu umum"], "answer": 1, "explanation": "Silogisme kategorial: Karena sebagian staf bukan pengelola keuangan, maka sebagian staf tersebut tidak terkena kewajiban pakta integritas khusus pengelola keuangan desa.", "source": "Silogisme Kategorial Logika Deduktif"}, {"id": 490, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Premis 1: Jika suatu desa berstatus Desa Mandiri dalam Indeks Desa Membangun (IDM), maka desa tersebut berhak menerima alokasi afirmasi Dana Desa.\nPremis 2: Desa Sukamaju berstatus Desa Mandiri dalam IDM.\nKesimpulan yang benar menurut kaidah logika Modus Ponens adalah...", "options": ["Desa Sukamaju tidak menerima alokasi afirmasi Dana Desa", "Desa Sukamaju berhak menerima alokasi afirmasi Dana Desa", "Desa Sukamaju harus menurunkan statusnya", "Semua desa di kecamatan menerima alokasi afirmasi"], "answer": 1, "explanation": "Kaidah Modus Ponens: Jika P maka Q. P terjadi. Maka kesimpulannya Q (Desa Sukamaju berhak menerima alokasi afirmasi Dana Desa).", "source": "Logika Matematika Modus Ponens"}, {"id": 491, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Premis 1: Jika dokumen RKP Desa disepakati tepat waktu sebelum akhir September, maka APB Desa dapat ditetapkan sebelum 31 Desember.\nPremis 2: Jika APB Desa dapat ditetapkan sebelum 31 Desember, maka pencairan Siltap perangkat desa awal tahun tidak mengalami penundaan.\nKesimpulan yang sah menurut silogisme hipotetis adalah...", "options": ["Jika dokumen RKP Desa disepakati tepat waktu sebelum akhir September, maka pencairan Siltap perangkat desa awal tahun tidak mengalami penundaan", "Pencairan Siltap pasti tertunda meskipun RKP Desa tepat waktu", "APB Desa tidak perlu ditetapkan sebelum 31 Desember", "Siltap perangkat desa ditiadakan jika RKP Desa terlambat"], "answer": 0, "explanation": "Silogisme Hipotetis Rantai: Jika P maka Q. Jika Q maka R. Maka kesimpulannya Jika P maka R.", "source": "Silogisme Hipotetis Logika Proposisional"}, {"id": 492, "category": "Logika dan penalaran", "difficulty": "sulit", "question": "Dalam rapat desa, 5 orang pejabat duduk berderet menghadap warga: Kepala Desa, Sekdes, Ketua BPD, Camat, dan Kasun. Aturan duduk:\n1. Camat duduk tepat di tengah (kursi nomor 3).\n2. Kepala Desa duduk di sebelah kanan Camat.\n3. Kasun duduk di ujung paling kiri (kursi nomor 1).\n4. Sekdes duduk di antara Kasun dan Camat.\nSiapakah yang duduk di kursi paling kanan (kursi nomor 5)?", "options": ["Ketua BPD", "Kepala Desa", "Sekdes", "Kasun"], "answer": 0, "explanation": "Urutan kursi 1 sampai 5 dari kiri ke kanan:\nKursi 1: Kasun.\nKursi 3: Camat.\nKursi 2: Sekdes (di antara Kasun dan Camat).\nKursi 4: Kepala Desa (sebelah kanan Camat).\nMaka kursi nomor 5 diisi oleh Ketua BPD.", "source": "Penalaran Posisi Ruang dan Urutan Logis"}, {"id": 493, "category": "Logika dan penalaran", "difficulty": "sedang", "question": "Dari 80 peternak penerima bibit ternak di desa, 50 orang memelihara sapi, 40 orang memelihara kambing, dan 15 orang memelihara sapi sekaligus kambing. Berapakah jumlah peternak yang tidak memelihara sapi maupun kambing?", "options": ["5 orang", "10 orang", "15 orang", "20 orang"], "answer": 0, "explanation": "Total peternak yang memelihara sapi atau kambing = 50 + 40 - 15 = 75 orang. Maka yang tidak memelihara keduanya = 80 - 75 = 5 orang.", "source": "Diagram Venn Teori Himpunan"}, {"id": 494, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Kabupaten Tuban dikenal luas dengan sebutan atau julukan sebagai...", "options": ["Bumi Blambangan", "Bumi Minak Jinggo", "Bumi Wali", "Bumi Arema"], "answer": 2, "explanation": "Kabupaten Tuban dijuluki sebagai 'Bumi Wali' karena banyaknya makam para wali dan ulama penyebar agama Islam terkemuka di tanah Jawa yang berada di wilayah Tuban.", "source": "Profil Identitas Daerah Kabupaten Tuban"}, {"id": 495, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Komoditas buah hortikultura unggulan nasional khas Kabupaten Tuban yang memiliki cita rasa manis seperti madu, berdaging buah tebal, dan telah resmi bersertifikat varietas unggul nasional dari Kementerian Pertanian RI adalah...", "options": ["Durian Montong", "Belimbing Tasikmadu", "Salak Pondoh", "Jeruk Nipis Bancar"], "answer": 1, "explanation": "Belimbing Tasikmadu adalah varietas buah unggulan khas Kabupaten Tuban (sentra budidaya di Desa Tasikmadu, Kecamatan Palang) yang telah dilepas secara nasional oleh Kementerian Pertanian karena keunggulan rasa manis madu, aroma harum, dan ukuran buahnya yang besar.", "source": "Profil Potensi Pertanian dan Hortikultura Kabupaten Tuban"}, {"id": 496, "category": "Pengetahuan umum", "difficulty": "mudah", "question": "Dalam aspek kesiapsiagaan mitigasi bencana alam di wilayah Kabupaten Tuban, potensi kerawanan bencana musiman yang sering melanda desa-desa dataran rendah di sepanjang hilir Daerah Aliran Sungai (DAS) Bengawan Solo saat puncak musim hujan adalah...", "options": ["Banjir luapan air sungai (banjir genangan)", "Gempa bumi tektonik berkekuatan tinggi", "Erupsi gunung berapi aktif", "Tsunami gelombang pasang tinggi"], "answer": 0, "explanation": "Wilayah Kabupaten Tuban bagian timur dan selatan yang dilintasi hilir Sungai Bengawan Solo (seperti Kecamatan Rengel, Soko, Plumpang, dan Widang) secara periodik menghadapi ancaman banjir luapan Bengawan Solo saat musim penghujan, sehingga memerlukan kesiapsiagaan aparatur desa dalam mitigasi dan evakuasi.", "source": "Profil Geografis & BPBD Kabupaten Tuban"}, {"id": 497, "category": "Pengetahuan umum", "difficulty": "sedang", "question": "Kementerian Desa PDTT mengembangkan konsep pembangunan berbasis data terpadu yang melokalisasi 17 Tujuan Pembangunan Berkelanjutan (SDGs) global PBB dengan menambahkan 1 tujuan khas kearifan lokal Indonesia (tujuan ke-18), yaitu...", "options": ["Pemanfaatan kecerdasan buatan serba digital di pelosok desa", "Kelembagaan Desa Dinamis dan Budaya Desa Adaptif", "Industrialisasi pabrik multinasional di kawasan pedesaan", "Swastanisasi pengelolaan seluruh tanah kas desa"], "answer": 1, "explanation": "SDGs Desa mengadaptasi 17 tujuan pembangunan berkelanjutan global dari PBB dan menambahkan tujuan ke-18, yaitu 'Kelembagaan Desa Dinamis dan Budaya Desa Adaptif' untuk mempertahankan kearifan lokal, tradisi gotong royong, dan kelembagaan adat di desa.", "source": "Permendesa PDTT No. 21 Tahun 2020 tentang SDGs Desa"}, {"id": 498, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Dalam pengelolaan administrasi kantor modern, format berkas digital standar yang digunakan secara berurutan untuk dokumen pengolah kata yang dapat diedit, lembar kerja hitung/tabel, dan dokumen arsip final yang tata letaknya terkunci portabel adalah...", "options": [".mp3, .avi, dan .jpg", ".docx, .xlsx, dan .pdf", ".exe, .zip, dan .html", ".txt, .bmp, dan .apk"], "answer": 1, "explanation": "Ekstensi berkas standar perkantoran adalah: .docx untuk dokumen pengolah kata (Microsoft Word), .xlsx untuk lembar sebar/spreadsheet (Microsoft Excel), dan .pdf (Portable Document Format) untuk dokumen final terarsip yang tidak mudah bergeser formatnya.", "source": "Standar Operasional Komputer Administrasi Perkantoran"}, {"id": 499, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Pada sistem operasi komputer Windows, kombinasi tombol keyboard yang digunakan untuk menghapus file/berkas secara langsung dan permanen tanpa memindahkannya terlebih dahulu ke tempat penampungan sampah sementara (Recycle Bin) adalah...", "options": ["Ctrl + Delete", "Shift + Delete", "Alt + Delete", "Windows + Delete"], "answer": 1, "explanation": "Menekan Shift + Delete akan menghapus berkas terpilih secara langsung dari media penyimpanan secara permanen (bypassing Recycle Bin), sedangkan tombol Delete biasa hanya memindahkan berkas ke Recycle Bin.", "source": "Dasar Sistem Operasi Microsoft Windows"}, {"id": 500, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Berdasarkan Undang-Undang No. 25 Tahun 2009 tentang Pelayanan Publik, prinsip penyelenggaraan pelayanan di kantor desa yang melarang diskriminasi berdasarkan suku, ras, agama, golongan, status gender, atau latar belakang politik disebut...", "options": ["Asas Partisipatif", "Asas Non-Diskriminatif", "Asas Keterbukaan", "Asas Akuntabilitas"], "answer": 1, "explanation": "UU No. 25 Tahun 2009 Pasal 4 huruf g menegaskan Asas Tidak Diskriminatif, yaitu perlakuan yang tidak membedakan jenis kelamin, suku, agama, ras, status sosial, maupun pandangan politik dalam pelayanan publik.", "source": "UU No. 25 Tahun 2009 tentang Pelayanan Publik Pasal 4 huruf g"}, {"id": 501, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Pengurusan jenazah seorang muslim (memandikan, mengafani, menyalatkan, dan menguburkan) dalam hukum fikih Islam berstatus...", "options": ["Fardhu 'ain bagi seluruh penduduk desa tanpa terkecuali", "Fardhu kifayah, yaitu kewajiban yang gugur bagi warga lain apabila telah dilaksanakan oleh sebagian orang", "Sunnah muakkadah yang dianjurkan bagi perangkat desa saja", "Mubah tergantung kesepakatan musyawarah warga rukun tetangga"], "answer": 1, "explanation": "Hukum mengurus jenazah muslim (memandikan, mengafani, menyalatkan, dan memakamkan) adalah Fardhu Kifayah. Artinya, kewajiban ini dibebankan kepada umat/masyarakat secara kolektif; jika sudah ada sebagian warga (seperti modin dan keluarga) yang melaksanakannya dengan baik, maka gugurlah dosa seluruh warga lainnya di wilayah tersebut.", "source": "Kitab Fathul Qarib al-Mujib & Fikih Islam Sulaiman Rasjid, Bab Tajhiz al-Janaiz"}, {"id": 502, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Dalam pelaksanaan sholat jenazah, urutan bacaan yang dibaca setelah Takbir Kedua adalah...", "options": ["Membaca Surat Al-Fatihah", "Membaca doa pengampunan khusus untuk jenazah (Allahummaghfir lahu/laha)", "Membaca shalawat kepada Nabi Muhammad SAW", "Membaca doa untuk keluarga yang ditinggalkan lalu salam"], "answer": 2, "explanation": "Rukun sholat jenazah terdiri dari 4 takbir tanpa ruku dan sujud: Takbir 1 membaca Surat Al-Fatihah; Takbir 2 membaca Shalawat kepada Nabi Muhammad SAW (minimal: Allahumma shalli 'ala sayyidina Muhammad); Takbir 3 membaca doa bagi jenazah (Allahummaghfir lahu...); Takbir 4 membaca doa penutup (Allahumma la tahrimna ajrahu...) disusul salam.", "source": "Fikih Praktis Ibadah Jenazah Kemenag RI & Kitab Matan Taqrib Fiqih Syafi'i"}, {"id": 503, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Ketika menjadi imam sholat jenazah untuk jenazah laki-laki, posisi berdiri imam yang sesuai dengan sunnah Rasulullah SAW adalah...", "options": ["Sejajar dengan bagian kepala atau dada jenazah", "Sejajar dengan bagian perut atau pinggang jenazah", "Sejajar dengan kedua lutut jenazah", "Sejajar dengan ujung kedua telapak kaki jenazah"], "answer": 0, "explanation": "Berdasarkan hadits riwayat Abu Daud dan Tirmidzi dari Anas bin Malik dan Samurah bin Jundub, sunnah posisi imam saat menyalatkan jenazah laki-laki adalah berdiri lurus searah kepala/dada jenazah. Sedangkan jika jenazah perempuan, posisi imam berdiri searah bagian tengah tubuh (pinggang/perut) jenazah.", "source": "HR. Abu Daud No. 3194 & Tirmidzi No. 1034, Bab Posisi Imam Sholat Jenazah"}, {"id": 504, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Berapakah jumlah lapisan kain kafan yang disunnahkan untuk membungkus jenazah laki-laki muslim?", "options": ["1 lapis kain sarung", "3 lapis kain kafan putih bersih", "5 lapis kain kafan bersusun", "7 lapis kain kafan berwarna hijau"], "answer": 1, "explanation": "Berdasarkan hadits riwayat Bukhari dan Muslim dari Ummul Mukminin Aisyah RA, jenazah laki-laki disunnahkan dikafani dengan 3 lapis kain putih tanpa gamis dan sorban. Sementara untuk jenazah perempuan disunnahkan 5 lapis (kain basahan/sarung, baju kurung, kerudung, dan 2 lembar kain penutup seluruh tubuh).", "source": "HR. Bukhari No. 1264 & Muslim No. 941; Fiqih Jenazah Kemenag RI"}, {"id": 505, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sulit", "question": "Seorang warga desa meninggal dunia dalam musibah kecelakaan perahu di laut dan jasadnya belum ditemukan setelah operasi pencarian resmi SAR ditutup. Tindakan ibadah yang dilaksanakan oleh warga desa bersama modin/tokoh agama adalah...", "options": ["Melaksanakan sholat khusuf di balai desa", "Melaksanakan sholat gaib berjamaah untuk mendoakan almarhum", "Membuat nisan kosong tanpa doa jenazah", "Mengganti kewajiban sholat dengan membayar fidyah 1 sha' beras"], "answer": 1, "explanation": "Bila seorang muslim wafat di tempat yang jauh atau jenazahnya tidak berada di hadapan jamaah (misal hilang di perairan/musibah bencana alam setelah pencarian dinyatakan selesai), disyariatkan melaksanakan Sholat Gaib sebagaimana Rasulullah SAW menyalatkan jenazah Raja Najasyi (Ash-hamah) di Madinah saat wafat di Habasyah.", "source": "HR. Bukhari No. 1318 & Muslim No. 951; Keputusan Bahtsul Masail NU & Tarjih Muhammadiyah"}, {"id": 506, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Berikut ini pihak yang paling berhak dan utama memandikan jenazah laki-laki dewasa yang wafat di desa secara syar'i adalah...", "options": ["Kasi Pelayanan bersama Kepala Desa", "Istri atau kerabat laki-laki terdekat yang paham tata cara memandikan dan amanah menjaga aib jenazah", "Tetangga laki-laki yang berusia paling tua di lingkungan RT", "Bidan desa atau tenaga kesehatan puskesmas pembantu"], "answer": 1, "explanation": "Dalam syariat Islam, pihak yang paling utama memandikan jenazah adalah istri almarhum atau anggota keluarga laki-laki terdekat (ayah, anak kandung, saudara laki-laki) yang memahami tata cara bersuci/thaharah serta terpercaya (amanah) untuk menutup aib fisik almarhum, didampingi oleh petugas rohani (modin/amil).", "source": "Kitab Al-Majmu' Syarah al-Muhadzdzab Imam An-Nawawi, Juz 5"}, {"id": 507, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Saat proses pemakaman jenazah muslim di tempat pemakaman umum (TPU) desa, posisi jenazah di dalam liang lahad diletakkan dengan cara...", "options": ["Terlentang membujur ke arah barat dengan mata memandang ke atas", "Dimiringkan ke sisi lambung kanan menghadap arah kiblat dan tali kain kafan dilepas", "Duduk menghadap pintu masuk pemakaman", "Tengkurap dengan kepala menghadap ke timur"], "answer": 1, "explanation": "Sunnah dan rukun dalam penguburan jenazah muslim adalah meletakkan jenazah miring di atas lambung kanan menghadap ke arah kiblat. Tali pengikat kafan pada bagian kepala dan tubuh dilepas, serta pipi kanan disentuhkan ke tanah/lahad.", "source": "Fathul Mu'in Hamisy I'anatut Thalibin, Bab Ahkam al-Janaiz"}, {"id": 508, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Bagaimanakah ketentuan syariat Islam terhadap orang yang meninggal dunia dalam keadaan mati syahid di medan perang membela negara/agama?", "options": ["Wajib dimandikan tujuh kali dan dikafani lima lapis", "Tidak dimandikan dan tidak dishalatkan, melainkan langsung dimakamkan bersama pakaian yang dikenakannya", "Hanya dishalatkan tanpa perlu dikubur di liang lahad", "Cukup ditayamumkan oleh modin lalu dishalatkan seperti jenazah biasa"], "answer": 1, "explanation": "Jenazah muslim yang wafat sebagai Syahid Ma'rakah (syahid medan perang membela kebenaran/negara) memiliki kekhususan syariat: tidak dimandikan dan tidak dishalatkan, melainkan langsung dimakamkan dengan pakaian yang berlumuran darah yang melekat di tubuhnya sebagai saksi kemuliaan di hari kiamat.", "source": "HR. Bukhari No. 1343 tentang Syuhada Perang Uhud; Kitab Al-Umm Imam Asy-Syafi'i"}, {"id": 509, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Tujuan utama anjuran ber-ta'ziyah (melayat) ke rumah duka keluarga warga desa yang sedang tertimpa musibah kematian adalah...", "options": ["Menuntut pembagian warisan tanah kas desa secepatnya", "Menghibur dan menguatkan hati keluarga yang berduka (tasliyah), mendoakan jenazah, serta membantu meringankan beban mereka", "Mengadakan pesta perayaan perpisahan warga", "Meminta pertanggungjawaban panitia rukun kematian tingkat dusun"], "answer": 1, "explanation": "Ta'ziyah secara bahasa bermakna tasliyah (menghibur). Tujuannya adalah meringankan duka nestapa keluarga yang ditinggalkan, menasihati agar bersabar dan ridha terhadap takdir Allah SWT, mendoakan ampunan bagi si mayit, serta dianjurkan membuatkan makanan bagi keluarga duka (sebagaimana hadits riwayat Abu Daud: 'Buatkanlah makanan untuk keluarga Ja'far').", "source": "HR. Abu Daud No. 3132 & Tirmidzi No. 998; Kitab Riyadhus Shalihin Imam An-Nawawi"}, {"id": 510, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Sebelum proses pemakaman jenazah selesai dan keluarga duka meninggalkan area pemakaman, perangkat desa atau tokoh agama setempat biasanya menyampaikan pengumuman terkait hak adami si mayit, yaitu...", "options": ["Menyita rumah almarhum untuk kas rukun tetangga", "Meminta permohonan maaf dan mengimbau siapa pun yang memiliki urusan piutang/tanggungan dengan almarhum agar menghubungi ahli warisnya", "Membacakan riwayat slip gaji almarhum selama bekerja", "Menginstruksikan seluruh pelayat membayar iuran wajib pemakaman tunai"], "answer": 1, "explanation": "Hak adami (utang piutang dan sengketa antarmanusia) merupakan tanggungan yang sangat berat bagi orang yang telah meninggal dunia. Perangkat desa/modin bertugas mengumumkan kepada warga agar memaafkan kesalahan almarhum dan meminta pihak yang memiliki sangkutan hak/piutang segera menyelesaikan bersama ahli waris almarhum secara musyawarah.", "source": "HR. Tirmidzi No. 1078 ('Jiwa seorang mukmin terkatung-katung karena utangnya sampai dilunasi'); Norma Adat Desa Muslim"}, {"id": 511, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Besaran takaran Zakat Fitrah per jiwa bagi umat Islam di Indonesia yang dibayarkan berupa makanan pokok beras adalah setara dengan...", "options": ["1 mud atau sekitar 0,6 kg beras", "1 sha' atau setara dengan 2,5 kg / 3,5 liter beras berkualitas baik", "5 wasaq atau sekitar 653 kg gabah kering panen", "10 liter beras ketan putih"], "answer": 1, "explanation": "Kewajiban zakat fitrah adalah 1 sha' makanan pokok (kurma, gandum, atau beras di Indonesia). Berdasarkan Keputusan Komisi Fatwa MUI dan Surat Keputusan Ketua BAZNAS, 1 sha' beras setara dengan 2,5 kg atau 3,5 liter beras per jiwa yang dikonsumsi sehari-hari.", "source": "SK Ketua BAZNAS No. 10 Tahun 2024 & Fatwa MUI tentang Standar Ukuran Zakat Fitrah"}, {"id": 512, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Waktu terbaik (afdhal) untuk membayarkan Zakat Fitrah kepada panitia amil/UPZ desa adalah...", "options": ["Pada awal bulan Sya'ban sebelum memasuki bulan puasa", "Mulai terbit fajar tanggal 1 Syawal hingga sebelum dimulainya Sholat Idul Fitri", "Setelah sholat Idul Fitri pada siang hari hari raya", "Pada tanggal 10 Dzulhijjah bersamaan dengan penyembelihan hewan qurban"], "answer": 1, "explanation": "Waktu afdhal pembayaran zakat fitrah adalah sejak terbit fajar 1 Syawal hingga sebelum pelaksanaan Sholat Idul Fitri. Bila dibayarkan setelah sholat Idul Fitri selesai tanpa uzur syar'i, pembayarannya dihukumi sedekah biasa dan tidak terhitung sebagai zakat fitrah yang sempurna.", "source": "HR. Abu Daud No. 1609 & Ibnu Majah No. 1827; Fiqih Syafi'iyah"}, {"id": 513, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Berdasarkan Al-Qur'an Surat At-Taubah ayat 60, siapakah yang berhak menerima penyaluran zakat (asnaf delapan)?", "options": ["Perangkat desa, BPD, pengurus RT, dan anggota linmas", "Fakir, miskin, amil, muallaf, riqab (hamba sahaya), gharimin (orang berutang), fisabilillah, dan ibnu sabil (musafir)", "Keluarga kepala desa, donatur masjid, dan aparat keamanan kecamatan", "Penyelenggara lelang tanah kas desa dan kontraktor pembangunan balai desa"], "answer": 1, "explanation": "Surat At-Taubah ayat 60 secara tegas menetapkan 8 golongan mustahiq zakat (Asnaf Tsamaniyah): 1. Fakir, 2. Miskin, 3. Amil zakat, 4. Muallaf, 5. Riqab, 6. Gharimin, 7. Fisabilillah, dan 8. Ibnu Sabil. Zakat tidak boleh dialokasikan di luar 8 asnaf ini.", "source": "Al-Qur'an Surat At-Taubah Ayat 60 & UU No. 23 Tahun 2011 tentang Pengelolaan Zakat"}, {"id": 514, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sulit", "question": "Seorang petani di desa memanen padi dari sawah tadah hujan (mengandalkan air hujan alami tanpa biaya bahan bakar pompa/irigasi). Berapakah persentase zakat hasil pertanian yang wajib dikeluarkannya bila panennya telah mencapai nisab 5 wasaq (sekitar 653 kg gabah kering)?", "options": ["2,5% dari total penjualan gabah", "5% dari hasil panen kotor", "10% dari total hasil panen padi", "20% dari keuntungan bersih setelah dikurangi modal"], "answer": 2, "explanation": "Berdasarkan hadits Rasulullah SAW riwayat Bukhari: hasil tanaman pertanian yang diairi dengan air hujan alami/mata air (tanpa biaya) wajib dikeluarkan zakatnya sebesar 10% (sepersepuluh). Sedangkan jika diairi menggunakan sarana irigasi berbiaya (pompa air/diesel/genset), zakatnya adalah 5% (seperdua puluh).", "source": "HR. Bukhari No. 1483 & Kitab Bidayatul Mujtahid Ibnu Rusyd"}, {"id": 515, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Berdasarkan UU Nomor 41 Tahun 2004 tentang Wakaf, apakah status hukum tanah wakaf yang diperuntukkan bagi masjid, pemakaman, atau madrasah di desa?", "options": ["Dapat diperjualbelikan oleh ahli waris wakif jika kas keluarga menipis", "Dapat disita oleh pengadilan untuk melunasi utang pribadi nadzir", "Kekal manfaatnya untuk kepentingan umum dan dilarang keras untuk dijual, diwariskan, dihibahkan, ditukar, atau disita", "Otomatis beralih menjadi tanah bengkok Kepala Desa"], "answer": 2, "explanation": "Pasal 40 UU No. 41 Tahun 2004 tentang Wakaf menegaskan bahwa harta benda wakaf dilarang: a. dijadikan jaminan; b. disita; c. dihibahkan; d. dijual; e. diwariskan; f. ditukar; atau g. dialihkan dalam bentuk pengalihan hak lainnya. Pelanggaran atas pasal ini memiliki konsekuensi pidana.", "source": "UU No. 41 Tahun 2004 tentang Wakaf Pasal 40 & PP No. 42 Tahun 2006"}, {"id": 516, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Pejabat yang berwenang membuat Akta Ikrar Wakaf (AIW) untuk legalitas tanah wakaf di wilayah perdesaan adalah...", "options": ["Kepala Seksi Pelayanan dan Sekretaris BPD", "Pejabat Pembuat Akta Ikrar Wakaf (PPAIW), yang dijabat oleh Kepala Kantor Urusan Agama (KUA) Kecamatan setempat", "Ketua Lembaga Pemberdayaan Masyarakat (LPM)", "Pengurus Karang Taruna Desa"], "answer": 1, "explanation": "Menurut UU No. 41 Tahun 2004 dan PMA No. 73 Tahun 2013, ikrar wakaf wajib dituangkan dalam Akta Ikrar Wakaf (AIW) di hadapan PPAIW (Pejabat Pembuat Akta Ikrar Wakaf), yaitu Kepala Kantor Urusan Agama (KUA) kecamatan setempat, disaksikan oleh minimal 2 orang saksi.", "source": "UU No. 41 Tahun 2004 Pasal 37 jo. Peraturan Menteri Agama No. 73 Tahun 2013"}, {"id": 517, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Pihak yang ditunjuk oleh wakif untuk menerima, memelihara, dan mengelola harta benda wakaf di desa (seperti takmir masjid desa) disebut...", "options": ["Mauquf 'alaih", "Nadzir", "Musytari", "Murtahin"], "answer": 1, "explanation": "Dalam rukun wakaf terdapat 4 unsur: 1. Wakif (pihak yang mewakafkan), 2. Mauquf bih (harta yang diwakafkan), 3. Mauquf 'alaih (pihak penerima manfaat/peruntukan wakaf), dan 4. Nadzir (pihak yang menerima amanah memelihara dan mengelola harta benda wakaf).", "source": "UU No. 41 Tahun 2004 tentang Wakaf Pasal 6 & Fiqih Muamalah Kontemporer"}, {"id": 518, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Tradisi sedekah bumi atau tasyakuran desa yang rutin diselenggarakan oleh masyarakat pedesaan Jawa (seperti di Kabupaten Tuban) menurut kacamata dakwah Islam yang moderat dimaknai sebagai...", "options": ["Upacara peribadatan syirik yang wajib dilarang keras oleh kepala desa", "Sarana bersyukur kepada Allah SWT atas limpahan rezeki hasil bumi, mempererat silaturahmi antarwarga, dan sedekah makanan yang diisi doa bersama", "Ajang pesta pemborosan anggaran kas desa", "Kewajiban konstitusi negara yang mengikat secara hukum pidana"], "answer": 1, "explanation": "Pendekatan dakwah kultural para Walisongo (termasuk Sunan Bonang) mentransformasikan tradisi sedekah bumi menjadi sarana syukur kepada Allah SWT (Rabbul 'Alamin), mempererat kerukunan/silaturahmi, berbagi sedekah makanan kepada sesama, dan tahlil/doa bersama untuk keselamatan desa dari bencana.", "source": "Pedoman Dakwah Kultural MUI & Sejarah Akulturasi Islam Nusantara"}, {"id": 519, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Dalam struktur perangkat desa di Jawa Timur, tugas pelayanan sosial keagamaan, pengurusan jenazah, pembinaan nikah, dan doa desa secara tradisional diemban oleh perangkat atau staf pembantu yang dikenal dengan sebutan...", "options": ["Bayan atau Jogoboyo", "Modin (Kasi Pelayanan / Urusan Kesra)", "Ulu-ulu atau Kamituwo", "Pamong Tani Desa"], "answer": 1, "explanation": "Secara kultural dan sosiologis di Jawa, 'Modin' (Lebe/Kaum) adalah sebutan untuk perangkat desa yang mengurusi urusan keagamaan, pernikahan, kematian (rohani), dan sosial kemasyarakatan. Dalam nomenklatur modern Permendagri No. 84/2015, tugas ini diintegrasikan ke dalam fungsi Kepala Seksi Pelayanan.", "source": "Permendagri No. 84 Tahun 2015 Pasal 9 ayat (4) & Sosiologi Hukum Desa Tuban"}, {"id": 520, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Berdasarkan Undang-Undang Nomor 16 Tahun 2019 tentang Perubahan atas UU No. 1 Tahun 1974 tentang Perkawinan, batas usia minimal perkawinan bagi pria dan wanita adalah...", "options": ["Pria 18 tahun dan wanita 16 tahun", "Pria dan wanita sama-sama minimal berusia 19 tahun", "Pria 21 tahun dan wanita 18 tahun", "Pria 20 tahun dan wanita 17 tahun"], "answer": 1, "explanation": "Pasal 7 ayat (1) UU No. 16 Tahun 2019 mengubah batas usia perkawinan, yaitu perkawinan hanya diizinkan apabila pria dan wanita sudah mencapai usia 19 (sembilan belas) tahun. Perangkat desa bertugas melakukan edukasi guna mencegah perkawinan usia anak di desa.", "source": "UU No. 16 Tahun 2019 tentang Perubahan atas UU No. 1 Tahun 1974 tentang Perkawinan Pasal 7"}, {"id": 521, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Rukun nikah dalam hukum syariat Islam yang wajib dipenuhi agar akad perkawinan sah terdiri atas...", "options": ["Calon mempelai pria, calon mempelai wanita, wali nikah, dua orang saksi laki-laki yang adil, serta ijab dan kabul", "Kepala desa, ketua BPD, saksi satu orang, mahar berupa mobil, dan pesta resepsi", "Penghulu KUA, camat, surat perjanjian pranikah, dan seragam dinas", "Undangan minimal 100 orang warga RT, tumpeng, dan hiburan rakyat"], "answer": 0, "explanation": "Rukun nikah menurut Kompilasi Hukum Islam (KHI) Pasal 14 dan jumhur ulama mazhab Syafi'i ada 5: 1. Calon mempelai pria, 2. Calon mempelai wanita, 3. Wali nikah dari pihak wanita, 4. Dua orang saksi laki-laki yang adil dan baligh, 5. Ijab dan Kabul (shighat akad).", "source": "Instruksi Presiden No. 1 Tahun 1991 tentang Kompilasi Hukum Islam (KHI) Pasal 14"}, {"id": 522, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sulit", "question": "Jika seorang ayah kandung dari calon mempelai wanita telah meninggal dunia, siapakah urutan wali nasab berikutnya yang paling berhak menjadi wali nikah?", "options": ["Paman kandung dari pihak ibu", "Kakek kandung dari pihak ayah (ayah dari ayah) atau saudara laki-laki kandung (seayah seibu)", "Tetangga tertua yang dituakan di rukun tetangga", "Suami dari saudara perempuan calon pengantin wanita"], "answer": 1, "explanation": "Urutan prioritas wali nasab dalam KHI Pasal 21 dan fikih Syafi'i: 1. Ayah kandung, 2. Kakek (ayah dari ayah) ke atas, 3. Saudara laki-laki kandung seayah seibu, 4. Saudara laki-laki seayah, 5. Anak laki-laki dari saudara kandung, 6. Paman (saudara ayah), dst. Kerabat dari pihak ibu bukan merupakan wali nasab pernikahan.", "source": "Kompilasi Hukum Islam (KHI) Pasal 21 & Kitab Fathul Qarib al-Mujib"}, {"id": 523, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Pernikahan yang dilaksanakan hanya secara agama/adat tanpa dicatatkan pada Kantor Urusan Agama (KUA) atau Kantor Catatan Sipil sering disebut nikah siri. Mengapa perangkat desa berkewajiban mengedukasi warga agar mencatatkan pernikahan secara resmi?", "options": ["Agar pemerintah desa mendapat komisi retribusi dari KUA", "Untuk menjamin kepastian hukum hak keperdataan istri dan anak (seperti akta kelahiran, hak nafkah, dan hak waris)", "Karena nikah resmi membebaskan warga dari kewajiban gotong royong", "Agar seluruh mas kawin diserahkan ke kas rukun kampung"], "answer": 1, "explanation": "Pencatatan perkawinan (UU No. 1/1974 Pasal 2 ayat 2) sangat krusial untuk melindungi hak-hak hukum perempuan dan anak. Tanpa akta nikah resmi, anak akan kesulitan mendapatkan akta kelahiran berkekuatan hukum penuh, hak nafkah, perwalian hukum, serta pembagian hak waris bila terjadi perceraian atau kematian.", "source": "UU No. 1 Tahun 1974 Pasal 2 ayat (2) & Putusan MK No. 46/PUU-VIII/2010"}, {"id": 524, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Dalam administrasi desa, dokumen surat pengantar yang diterbitkan oleh pemerintah desa (Kasi Pelayanan/Sekdes) untuk warga yang hendak melangsungkan pernikahan di KUA dikenal sebagai model formulir...", "options": ["Surat Keterangan Kematian (Model A)", "Surat Pengantar Perkawinan (Model N1) dan Permohonan Kehendak Nikah", "Surat Pernyataan Bebas Narkoba", "Surat Izin Usaha Perdagangan (SIUP)"], "answer": 1, "explanation": "Berdasarkan Peraturan Menteri Agama No. 20 Tahun 2019 tentang Pencatatan Pernikahan, calon pengantin wajib melampirkan Surat Pengantar Perkawinan dari Kepala Desa/Lurah (Formulir Model N1, N2, N4) sebagai bukti status kependudukan dan persetujuan kehendak nikah.", "source": "PMA No. 20 Tahun 2019 tentang Pencatatan Pernikahan Pasal 4 & Permendagri No. 47/2016"}, {"id": 525, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Apabila calon mempelai wanita tidak memiliki wali nasab sama sekali atau walinya 'adhol' (enggan menikahkan tanpa alasan syar'i setelah diputus oleh Pengadilan Agama), maka akad nikah dilaksanakan dengan perwalian dari...", "options": ["Wali Hakim (Kepala KUA atas pelimpahan kewenangan Menteri Agama)", "Kepala Seksi Pemerintahan Desa", "Ketua RT setempat", "Calon mertua laki-laki"], "answer": 0, "explanation": "KHI Pasal 23 mengatur bahwa bila wali nasab tidak ada, gaib, atau berstatus adhal (enggan) berdasarkan penetapan/putusan Pengadilan Agama, maka hak perwalian berpindah kepada Wali Hakim (Sultan/Menteri Agama yang didelegasikan kepada Kepala KUA Kecamatan setempat).", "source": "Kompilasi Hukum Islam (KHI) Pasal 23 & PMA No. 20 Tahun 2019"}, {"id": 526, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Harta yang diperoleh suami dan istri secara bersama-sama selama ikatan perkawinan berlangsung dalam hukum Islam di Indonesia dan perundang-undangan dikenal sebagai...", "options": ["Harta bawaan masing-masing", "Harta bersama (gono-gini)", "Harta pusaka tinggi adat", "Harta hibah wasiat wajibah"], "answer": 1, "explanation": "Menurut Pasal 35 UU No. 1/1974 dan KHI Pasal 85, harta benda yang diperoleh selama perkawinan menjadi harta bersama (harta gono-gini). Sedangkan harta bawaan masing-masing suami atau istri sebelum menikah dan harta hibah/warisan tetap di bawah penguasaan masing-masing.", "source": "UU No. 1 Tahun 1974 Pasal 35 & Kompilasi Hukum Islam (KHI) Bab XIII"}, {"id": 527, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Prinsip dasar 'Moderasi Beragama' (Wasathiyah) yang digaungkan oleh Kementerian Agama dan harus ditegakkan di lingkungan desa mencakup 4 pilar utama, yaitu...", "options": ["Komitmen kebangsaan, toleransi, anti-kekerasan, dan akomodatif terhadap kebudayaan lokal", "Keseragaman keyakinan, pemusatan tempat ibadah, asimilasi etnis paksa, dan kepatuhan mutlak", "Penghapusan ritual adat, privatisasi agama total, penutupan forum dialog, dan sentralisme kas", "Pemisahan wilayah mukim berdasarkan suku, pemungutan pajak keyakinan, dan peradilan adat tertutup"], "answer": 0, "explanation": "Empat indikator utama Moderasi Beragama menurut Kemenag RI: 1. Komitmen kebangsaan (penerimaan Pancasila & UUD 1945), 2. Toleransi (menghormati perbedaan keyakinan), 3. Anti-kekerasan (menolak ekstremisme/radikalisme), dan 4. Akomodatif terhadap kebudayaan lokal yang selaras dengan nilai agama.", "source": "Buku Moderasi Beragama Kementerian Agama RI (2019) & Perpres No. 58 Tahun 2023"}, {"id": 528, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Landasan Al-Qur'an yang menegaskan bahwa keragaman manusia diciptakan bersuku-suku dan berbangsa-bangsa agar saling mengenal dan bekerja sama terdapat dalam...", "options": ["Surat Al-Baqarah ayat 282", "Surat Al-Hujurat ayat 13", "Surat Al-Ikhlas ayat 1-4", "Surat Al-Fil ayat 1-5"], "answer": 1, "explanation": "Surat Al-Hujurat ayat 13 menyatakan: 'Wahai manusia! Sungguh, Kami telah menciptakan kamu dari seorang laki-laki dan seorang perempuan, kemudian Kami jadikan kamu berbangsa-bangsa dan bersuku-suku agar kamu saling mengenal (li ta'arafu). Sungguh, yang paling mulia di antara kamu di sisi Allah ialah orang yang paling bertakwa.'", "source": "Al-Qur'an Surat Al-Hujurat Ayat 13 & Tafsir Al-Misbah Quraish Shihab"}, {"id": 529, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Surat Al-Kafirun ayat terakhir yang berbunyi 'Lakum diinukum waliyadiin' (Untukmu agamamu, dan untukku agamaku) merupakan panduan fundamental umat beragama dalam hal...", "options": ["Mencampuradukkan ritual peribadatan antaragama demi kompromi politik", "Menjaga kemurnian akidah pribadi tanpa menghina, mencela, atau memaksakan keyakinan kepada pemeluk agama lain (toleransi beragama)", "Melarang umat lain bermukim di desa yang mayoritas muslim", "Membatasi hak warga non-muslim dalam mendapatkan pelayanan surat kependudukan"], "answer": 1, "explanation": "Surat Al-Kafirun mengajarkan batasan toleransi: dalam hal akidah dan ibadah mahdhah tidak boleh ada kompromi/sinkretisme, namun dalam muamalah dan relasi sosial kemasyarakatan wajib menjunjung tinggi saling menghormati, tidak memaksakan kehendak, dan menjaga kedamaian antarumat beragama.", "source": "Al-Qur'an Surat Al-Kafirun Ayat 6 & Tafsir Ibnu Katsir"}, {"id": 530, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sulit", "question": "Dokumen konstitusi tertulis pertama dalam sejarah peradaban Islam yang digagas oleh Nabi Muhammad SAW untuk menyatukan masyarakat majemuk Madinah (kaum muslimin Muhajirin, Anshar, serta kaum Yahudi dan Nasrani) dalam satu kesatuan bangsa dikenal sebagai...", "options": ["Perjanjian Hudaibiyah", "Piagam Madinah (Mitsaq al-Madinah)", "Fathu Makkah", "Bai'at 'Aqabah Pertama"], "answer": 1, "explanation": "Piagam Madinah (Mitsaq al-Madinah) tahun 622 M adalah piagam konstitusional pertama di dunia yang menjamin kebebasan beragama, kesetaraan hak dan kewajiban warga negara, persatuan mempertahankan wilayah, serta penegakan keadilan tanpa diskriminasi bagi masyarakat Madinah yang majemuk.", "source": "Sirah Nabawiyah Ibnu Hisyam & Tarikh Thabari, Bab Konstitusi Madinah"}, {"id": 531, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Peraturan Bersama Menteri Agama dan Menteri Dalam Negeri (PBM) Nomor 9 dan Nomor 8 Tahun 2006 mengatur tentang pedoman pelaksanaan tugas kepala daerah/perangkat dalam hal...", "options": ["Pemilihan kepala desa serentak", "Pemeliharaan kerukunan umat beragama, pemberdayaan Forum Kerukunan Umat Beragama (FKUB), dan pendirian rumah ibadat", "Pengelolaan aset tanah kas desa untuk perkebunan sawit", "Penataan pos bantuan hukum terpadu tingkat kecamatan"], "answer": 1, "explanation": "PBM No. 9 dan 8 Tahun 2006 merupakan regulasi kunci yang mewajibkan kepala daerah dan jajaran pemerintahan hingga tingkat desa menjaga kerukunan umat beragama, memfasilitasi FKUB, serta mengatur persyaratan teknis dan administratif pendirian rumah ibadat demi ketenteraman bersama.", "source": "Peraturan Bersama Menteri Agama dan Menteri Dalam Negeri No. 9 dan 8 Tahun 2006"}, {"id": 532, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Sikap 'Tasamuh' dalam konsep ukhuwah Islamiyah dan kemasyarakatan perdesaan mengandung makna...", "options": ["Sikap acuh tak acuh terhadap kebersihan lingkungan", "Sikap tenggang rasa, lapang dada, dan saling menghormati perbedaan latar belakang keyakinan maupun suku", "Sikap memaksakan pendapat kelompok sendiri dalam musdes", "Sikap mengutamakan kepentingan pribadi di atas kepentingan umum"], "answer": 1, "explanation": "Tasamuh berarti toleransi, kelapangan dada, dan tenggang rasa. Sikap tasamuh menjadi modal sosial paling berharga bagi masyarakat desa di Indonesia dalam merajut kerukunan, mencegah polarisasi, dan menjaga keharmonisan antarwarga.", "source": "Pedoman Moderasi Beragama Kemenag RI & Risalah Ahlussunnah wal Jama'ah"}, {"id": 533, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Tiga pilar persaudaraan (Tri Ukhuwah) yang diajarkan oleh ulama Indonesia (seperti KH. Achmad Siddiq) untuk menjaga keutuhan Negara Kesatuan Republik Indonesia adalah...", "options": ["Ukhuwah Islamiyah (persaudaraan seagama), Ukhuwah Wathaniyah (persaudaraan sebangsa setanah air), dan Ukhuwah Insaniyah/Basyariyah (persaudaraan sesama manusia)", "Ukhuwah partai, ukhuwah ormas, dan ukhuwah marga", "Ukhuwah niaga, ukhuwah profesi, dan ukhuwah dinas", "Ukhuwah sekuler, ukhuwah liberal, dan ukhuwah feodal"], "answer": 0, "explanation": "Tri Ukhuwah adalah konsep agung harmoni sosial: 1. Ukhuwah Islamiyah (persaudaraan sesama muslim), 2. Ukhuwah Wathaniyah (persaudaraan sebangsa melintasi sekat agama/suku), dan 3. Ukhuwah Insaniyah/Basyariyah (persaudaraan universal sesama umat manusia).", "source": "Konsep Tri Ukhuwah Muktamar NU Ke-27 Situbondo (1984) & Pemikiran Gus Dur"}, {"id": 534, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Jika terjadi perselisihan atau kesalahpahaman antarkelompok warga di desa akibat isu keagamaan di media sosial, langkah preventif terbaik yang wajib diambil perangkat desa adalah...", "options": ["Membiarkan perselisihan membesar agar warga terbiasa berkonflik", "Mengadakan dialog tabayyun (klarifikasi/mediasi) secara persuasif bersama BPD, Babinsa, Bhabinkamtibmas, dan tokoh agama setempat", "Mendukung salah satu pihak yang paling banyak memberikan suara saat pilkades", "Mengusir pihak minoritas dari lingkungan desa"], "answer": 1, "explanation": "Prinsip Tabayyun (klarifikasi fakta) sesuai Al-Qur'an Surat Al-Hujurat ayat 6 merupakan metode islami yang dipadukan dengan kearifan musyawarah desa. Perangkat desa bersama Tiga Pilar (Kepala Desa, Babinsa, Bhabinkamtibmas) dan tokoh agama wajib memediasi secara netral dan adil demi ketenteraman umum.", "source": "Al-Qur'an Surat Al-Hujurat Ayat 6 & Pedoman Penanganan Konflik Sosial Permendagri No. 42/2015"}, {"id": 535, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Empat sifat mulia Nabi Muhammad SAW yang wajib dijadikan teladan etika kepemimpinan moral oleh seorang perangkat desa adalah...", "options": ["Siddiq (jujur), Amanah (dapat dipercaya), Tabligh (transparan/menyampaikan), dan Fathonah (cerdas/bijaksana)", "Kadzib, Khianat, Kitman, dan Baladah", "Egois, Ambisius, Otoriter, dan Tertutup", "Riya', Sum'ah, 'Ujub, dan Takabbur"], "answer": 0, "explanation": "Empat sifat wajib bagi Rasulullah SAW: 1. Siddiq (integritas, berkata dan berbuat benar), 2. Amanah (dapat dipercaya mengelola aset dan uang desa), 3. Tabligh (transparan dalam informasi publik desa), 4. Fathonah (cerdas mencari solusi permasalahan masyarakat). Lawan sifat ini adalah sifat mustahil bagi rasul.", "source": "Aqidatul Awam Syaikh Ahmad al-Marzuqi & Etika Kepemimpinan Pelayanan Publik"}, {"id": 536, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Hadits Nabi Muhammad SAW yang menegaskan bahwa 'Kullukum ra'in wa kullukum mas'ulun 'an ra'iyyatihi' mengandung makna mendalam bahwa...", "options": ["Setiap orang boleh berbuat sesuka hatinya tanpa aturan", "Setiap kalian adalah pemimpin dan setiap pemimpin pasti akan dimintai pertanggungjawaban atas kepemimpinannya di hadapan Allah SWT", "Hanya kepala desa yang akan ditanya pertanggungjawabannya di akhirat", "Perangkat desa tidak memiliki beban moral terhadap warga"], "answer": 1, "explanation": "Hadits riwayat Bukhari dan Muslim: 'Kullukum ra'in wa kullukum mas'ulun 'an ra'iyyatihi...'. Pemimpin masyarakat bertanggung jawab atas rakyatnya, kepala keluarga bertanggung jawab atas keluarganya, dan setiap pemegang amanah akan dimintai hisab atas kewajibannya.", "source": "HR. Bukhari No. 893 & HR. Muslim No. 1829"}, {"id": 537, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Hukum menerima suap, uang pelicin, atau gratifikasi terselubung (risywah) bagi seorang perangkat desa dalam pelayanan administrasi warga adalah...", "options": ["Halal karena dianggap sebagai tanda ucapan terima kasih warga", "Haram mutlak dan dilaknat oleh Allah SWT serta Rasul-Nya", "Makruh bila nilainya di bawah seratus ribu rupiah", "Mubah bila disetor ke kas pengurus karang taruna"], "answer": 1, "explanation": "Rasulullah SAW bersabda: 'La'natu Allahi 'ala ar-rasyi wal murtasyi' (Laknat Allah atas orang yang menyuap dan orang yang menerima suap). Dalam administrasi negara hal ini dikategorikan pungli/gratifikasi/tindak pidana korupsi yang melanggar UU No. 20/2001.", "source": "HR. Abu Daud No. 3580 & Tirmidzi No. 1337; Fatwa MUI No. 4/Munas VI/MUI/2000"}, {"id": 538, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Bagaimanakah sikap seorang perangkat desa yang beriman ketika mendapati perbedaan pilihan politik atau perselisihan pendapat dalam musyawarah rencana pembangunan desa?", "options": ["Menyerang pribadi peserta yang berbeda pandangan", "Mengedepankan adab musyawarah (syura), menghargai pendapat orang lain, dan berlapang dada menerima keputusan mufakat bersama", "Memboikot musyawarah desa", "Memutuskan sepihak tanpa melibatkan BPD dan warga"], "answer": 1, "explanation": "Al-Qur'an Surat Asy-Syura ayat 38 memuji orang-orang yang menyelesaikan urusan mereka secara musyawarah ('wa amruhum syura bainahum'). Sikap lapang dada dan menghormati hasil mufakat adalah perwujudan akhlakul karimah seorang pelayan masyarakat.", "source": "Al-Qur'an Surat Asy-Syura Ayat 38 & Surat Ali 'Imran Ayat 159"}, {"id": 539, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sulit", "question": "Dalam kisah sahabat Umar bin Khattab RA saat menjadi Khalifah, beliau mematikan lampu minyak milik negara dan menggantinya dengan lampu minyak miliknya sendiri ketika berbincang tentang urusan pribadi dengan putranya. Hikmah utama kisah ini bagi penyelenggara keuangan desa adalah...", "options": ["Pentingnya hidup dalam kegelapan agar hemat listrik", "Ketegasan dalam memisahkan fasilitas/keuangan dinas negara dari kepentingan pribadi dan keluarga (kehati-hatian atas harta publik)", "Larangan membeli minyak lampu di pasar desa", "Keharusan memotong anggaran alat tulis kantor desa"], "answer": 1, "explanation": "Keteladanan Khalifah Umar bin Khattab RA tersebut merupakan pelajaran tertinggi tentang integritas birokrasi: tidak menyalahgunakan satu sen pun uang atau fasilitas milik masyarakat/desa untuk urusan dan kepentingan pribadi keluarga.", "source": "Kitab Manaqib Amirul Mukminin Umar bin Khattab Ibnul Jauzi & Tarikh Khulafa As-Suyuthi"}, {"id": 540, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Prinsip amar ma'ruf nahi munkar dalam kehidupan bermasyarakat di desa wajib dijalankan dengan cara...", "options": ["Tindakan main hakim sendiri dan merusak fasilitas warga", "Hikmah, teladan yang baik (mau'izhah hasanah), dialog santun, serta koordinasi dengan aparat penegak hukum yang berwenang", "Membentuk kelompok milisi liar di tingkat RT", "Menyebarkan ujaran kebencian di pengeras suara masjid"], "answer": 1, "explanation": "Al-Qur'an Surat An-Nahl ayat 125 menegaskan: 'Serulah (manusia) kepada jalan Tuhanmu dengan hikmah dan pengajaran yang baik, dan berdebatlah dengan mereka dengan cara yang baik.' Nahi munkar tidak boleh dilakukan dengan cara yang menimbulkan kemungkaran baru yang lebih besar.", "source": "Al-Qur'an Surat An-Nahl Ayat 125 & Fiqih Dakwah Syekh Jum'ah Amin"}, {"id": 541, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Seorang perangkat desa yang mengemban tugas mengelola Dana Bantuan Sosial (Bansos) bagi warga miskin desa namun menyunat atau memotong bantuan tersebut untuk keuntungan pribadinya, dalam pandangan agama dikategorikan sebagai tindakan...", "options": ["Ijtihad yang diperbolehkan demi kelancaran operasional", "Khianat atas amanah dan memakan harta anak yatim/fakir miskin secara batil yang diancam azab pedih", "Urusan perdata ringan yang cukup ditegur secara lisan", "Amalan sedekah paksa"], "answer": 1, "explanation": "Memotong bansos fakir miskin adalah bentuk Ghulul (pengkhianatan terhadap amanah publik) dan memakan harta sesama secara zalim (Surat An-Nisa ayat 29). Di akhirat pelakunya akan memikul sendiri beban kezalimannya di hadapan Allah SWT.", "source": "Al-Qur'an Surat An-Nisa Ayat 29 & Surat Ali 'Imran Ayat 161 (Bab Ghulul)"}, {"id": 542, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Penerapan nilai 'Jujur dan Terpercaya' (Siddiq dan Amanah) oleh seorang Sekretaris Desa tecermin secara konkret dalam tindakan...", "options": ["Menyembunyikan buku ekspedisi agar tidak dibaca oleh BPD", "Mencatat seluruh surat masuk, surat keluar, dan realisasi anggaran belanja desa sesuai fakta riil tanpa manipulasi laporan kuitansi", "Menandatangani kuitansi kosong yang disodorkan pihak ketiga", "Mengganti tanggal keputusan kepala desa agar tidak kedaluwarsa"], "answer": 1, "explanation": "Integritas moral perangkat desa dibuktikan dengan kesesuaian antara fakta lapangan dan catatan administrasi (jujur), serta tidak merekayasa nota kuitansi atau memalsukan dokumen demi keuntungan diri sendiri atau kelompok.", "source": "Permendagri No. 47 Tahun 2016 tentang Administrasi Desa & Kode Etik Pamong Desa"}, {"id": 543, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Salah satu tokoh Walisongo yang berdakwah di pesisir utara Jawa Timur dan makam keramatnya berada di Kelurahan Kutorejo, Kabupaten Tuban (sebelah barat Masjid Agung Tuban) adalah...", "options": ["Sunan Kudus (Ja'far Shadiq)", "Sunan Bonang (Raden Makhdum Ibrahim)", "Sunan Muria (Raden Umar Said)", "Sunan Gunung Jati (Syarif Hidayatullah)"], "answer": 1, "explanation": "Sunan Bonang memiliki nama asli Raden Makhdum Ibrahim, putra dari Sunan Ampel dan Nyai Ageng Manila. Makam beliau terletak di jantung Kota Tuban (Kelurahan Kutorejo), menjadikan Kabupaten Tuban termasyhur dengan sebutan 'Bumi Wali'.", "source": "Babad Tuban & Sejarah Walisongo Agus Sunyoto (Atlas Walisongo)"}, {"id": 544, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Karya sastra suluk legendaris gubahan Sunan Bonang yang memuat wejangan tasawuf mendalam tentang makrifatullah dan pengendalian hawa nafsu adalah...", "options": ["Serat Centhini", "Suluk Wijil", "Kitab Sutasoma", "Babad Tanah Jawi"], "answer": 1, "explanation": "Suluk Wijil adalah karya sastra mistik/tasawuf fenomenal karangan Sunan Bonang yang menceritakan dialog spiritual Sunan Bonang dengan Wijil, seorang bekas abdi dalem Majapahit, berisi ajaran tasawuf falsafi yang disajikan dengan bahasa Jawa yang santun dan filosofis.", "source": "Atlas Walisongo Agus Sunyoto & Naskah Manuskrip Suluk Wijil Koleksi Perpustakaan Nasional"}, {"id": 545, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Dalam menyampaikan dakwah Islam kepada masyarakat Jawa pada masanya, Sunan Bonang sangat bijaksana memanfaatkan media seni budaya, salah satunya dengan...", "options": ["Mewajibkan warga menghafal naskah dalam bahasa Arab tanpa terjemah", "Menggubah instrumen gamelan bonang (gong kecil berkoleksi nada khas) dan tembang Tombo Ati untuk memikat hati masyarakat", "Merobohkan candi peninggalan kerajaan kuno", "Melarang seluruh bentuk tembang dan karawitan Jawa"], "answer": 1, "explanation": "Sunan Bonang memodifikasi alat musik gamelan Jawa dengan menambahkan instrumen 'bonang' (gong perunggu kecil berpencon) yang menghasilkan alunan nada mistis-meditatif, serta menggubah tembang Tombo Ati (Obat Hati) yang sarat muatan zikir, sholat malam, tadarus, dan pergaulan orang saleh.", "source": "Ensiklopedi Islam Nusantara & Sejarah Kebudayaan Islam Kemenag RI"}, {"id": 546, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Falsafah dakwah 'Moh Limo' (menolak 5 perkara maksiat: Moh Main, Moh Ngombe, Moh Madat, Moh Maling, Moh Madon) yang sangat berpengaruh dalam membersihkan moral masyarakat desa digagas oleh tokoh Walisongo, yaitu...", "options": ["Sunan Kalijaga", "Sunan Ampel (Raden Rahmat)", "Sunan Giri", "Sunan Muria"], "answer": 1, "explanation": "Sunan Ampel (Raden Rahmat), ayahanda dari Sunan Bonang dan Sunan Drajat, meletakkan dasar ajaran moral 'Moh Limo': 1. Moh Main (tidak berjudi), 2. Moh Ngombe (tidak minum arak/mabuk), 3. Moh Madat (tidak memakai candu/narkoba), 4. Moh Maling (tidak mencuri/korupsi), 5. Moh Madon (tidak berzina).", "source": "Babad Ampel Denta & Atlas Walisongo"}, {"id": 547, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Sunan Drajat (Raden Qasim), adik kandung Sunan Bonang yang berdakwah di pesisir Lamongan (bersebelahan dengan Tuban), terkenal dengan 'Catur Piwulang' (empat ajaran luhur) untuk pemberdayaan masyarakat miskin. Ajaran 'Wenehono teken marang wong kang wuto' bermakna...", "options": ["Berilah tongkat petunjuk kepada orang yang buta (berilah ilmu bimbingan kepada mereka yang bodoh/tersesat)", "Berilah makanan kepada orang yang kenyang", "Berilah pakaian mewah kepada pejabat desa", "Berilah payung hanya kepada keluarga bangsawan"], "answer": 0, "explanation": "Catur Piwulang Sunan Drajat: 1. Wenehono teken marang wong kang wuto (berilah petunjuk/ilmu pada yang buta), 2. Wenehono mangan marang wong kang luwe (berilah makan pada yang lapar), 3. Wenehono busana marang wong kang wudo (berilah pakaian/martabat pada yang telanjang), 4. Wenehono payung marang wong kang kodanan (berilah perlindungan pada yang kehujanan).", "source": "Manuskrip Sunan Drajat Museum Drajat Lamongan & Sejarah Islam Pesisir Jawa Timur"}, {"id": 548, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Metode dakwah para Walisongo di Nusantara yang memadukan ajaran Islam dengan kearifan adat lokal tanpa kekerasan dikenal dalam istilah sejarah kebudayaan sebagai...", "options": ["Invasi militer feodal", "Akulturasi budaya dan asimilasi damai (inkulturasi dakwah)", "Kolonisasi administratif", "Westernisasi nilai perdesaan"], "answer": 1, "explanation": "Pendekatan dakwah Walisongo adalah akulturasi damai: nilai-nilai tauhid dan syariat dimasukkan secara halus ke dalam adat istiadat, wayang, tembang, arsitektur masjid (atap tumpang meru), dan tradisi desa tanpa menghancurkan kearifan lokal yang sudah mengakar.", "source": "Buku Menengok Dinamika Islam Nusantara Prof. Azyumardi Azra & Atlas Walisongo"}, {"id": 549, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "mudah", "question": "Mengapa Kabupaten Tuban dijuluki sebagai 'Bumi Wali' atau 'Kota Wali'?", "options": ["Karena di Kabupaten Tuban terdapat makam salah satu Walisongo utama yaitu Sunan Bonang, serta makam banyak waliyullah/wali penyebar Islam terkemuka seperti Syekh Subakir, Syekh Maulana Ishaq, dan Sunan Bejagung", "Karena seluruh kepala desa di Kabupaten Tuban bergelar wali nikah", "Karena Kabupaten Tuban merupakan penghasil minyak goreng terbesar", "Karena hukum adat di Tuban menggantikan hukum positif Indonesia"], "answer": 0, "explanation": "Tuban bergelar 'Bumi Wali' karena posisinya sebagai pelabuhan utama kerajaan Majapahit kuno yang menjadi pintu gerbang masuknya para juru dakwah Islam, ditandai dengan makam Sunan Bonang di pusat kota, Makam Sunan Bejagung (Syekh Asy'ari), Makam Syekh Maulana Ishaq di pesisir, serta puluhan makam auliya lainnya.", "source": "Profil Pariwisata Religi Kabupaten Tuban & Sejarah Tuban Bumi Wali Disparbudpora"}, {"id": 550, "category": "Pendidikan agama dan moderasi beragama", "difficulty": "sedang", "question": "Nilai keteladanan terbesar dari para wali penyebar agama Islam di tanah Jawa yang patut diteladani oleh seluruh jajaran perangkat desa dalam memimpin warga perdesaan adalah...", "options": ["Mengejar kekayaan materi dan tanah bengkok seluas-luasnya", "Keikhlasan melayani, kesederhanaan hidup, keadilan sosial bagi kaum lemah, serta keteduhan dalam mengayomi seluruh lapisan masyarakat tanpa diskriminasi", "Mewajibkan warga desa menyetor upeti bulanan", "Menutup akses desa bagi warga dari luar daerah"], "answer": 1, "explanation": "Para Walisongo meneladankan kepemimpinan kenabian (khidmah lil ummah): mereka merakyat, melayani masyarakat dengan tulus, membela kaum papa (mustadh'afin), hidup bersahaja, serta membawa kedamaian dan ketenteraman bagi seluruh warga desa.", "source": "Atlas Walisongo Agus Sunyoto & Refleksi Nilai Kepemimpinan Luhur Nusantara"}, {"id": 551, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Dalam penyusunan Buku Profil Desa atau Laporan Pertanggungjawaban APBDes yang akan dijilid bolak-balik, fitur pengaturan margin pada aplikasi pengolah kata yang tepat untuk memberi ruang ekstra penjilidan di bagian dalam halaman adalah...", "options": ["Orientation Landscape", "Gutter Margin / Mirror Margins", "Columns Two with Line Between", "Hanging Indent 1.5 cm"], "answer": 1, "explanation": "Gutter margin memberikan ruang tambahan pada sisi margin penjilidan (biasanya sisi kiri untuk halaman ganjil dan sisi kanan untuk halaman genap pada cetak bolak-balik / Mirror Margins) agar teks tidak terpotong atau tertutup lem/staples saat dokumen resmi desa dijilid.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Modul Pengolah Kata)"}, {"id": 552, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Pada pembuatan Kop Surat resmi Pemerintah Desa di Microsoft Word, cara yang paling rapi dan standar untuk membuat garis pemisah tebal ganda (double line) di bawah identitas kop surat adalah...", "options": ["Menekan tombol garis bawah (underscore) berulang-ulang sampai ujung kertas", "Menggunakan fitur Shapes garis bebas ditarik manual dengan tetikus (mouse)", "Menggunakan fitur 'Borders and Shading' pada menu Home/Paragraph lalu memilih garis Bottom Border", "Membuat tabel 10 baris lalu mewarnai salah satu sel dengan warna hitam pekat"], "answer": 2, "explanation": "Cara resmi dan rapi membuat garis kop surat adalah menggunakan fitur 'Borders and Shading' pada paragraf kop, lalu memilih garis tebal atau ganda pada posisi Bottom Border. Menggambar manual dengan Shapes rentan bergeser saat dibuka di komputer lain, dan mengetik underscore manual menghasilkan garis yang tidak rata.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Tata Naskah Dinas)"}, {"id": 553, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Ketika menyusun dokumen RKP Desa yang memuat halaman sampul tanpa nomor, kata pengantar bernomor romawi kecil (i, ii), dan isi materi bernomor angka biasa (1, 2, 3), fitur pemutus halaman yang wajib digunakan adalah...", "options": ["Page Break biasa (Ctrl + Enter)", "Section Break (Next Page)", "Line Break (Shift + Enter)", "Column Break"], "answer": 1, "explanation": "Section Break (Next Page) membagi dokumen menjadi beberapa seksi independen sehingga pengaturan tata letak, orientasi (portrait/landscape), dan format nomor halaman (romawi vs angka Arab, serta 'Unlink from Previous') dapat berbeda antar-bagian dokumen.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Modul Pengolah Kata)"}, {"id": 554, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Surat keputusan kepala desa dan administrasi desa di Indonesia umumnya dicetak menggunakan kertas ukuran Folio / F4. Ukuran lebar dan tinggi standar untuk kertas Folio/F4 pada pengaturan 'Custom Page Size' adalah...", "options": ["21,0 cm x 29,7 cm", "21,5 cm x 33,0 cm (8,5 x 13 inci)", "21,59 cm x 35,56 cm (Legal)", "14,8 cm x 21,0 cm (A5)"], "answer": 1, "explanation": "Ukuran standar kertas Folio / F4 (HVS Folio) di Indonesia adalah lebar 21,5 cm dan tinggi 33,0 cm (atau 8,5 x 13 inci). Pilihan Legal memiliki panjang 35,56 cm (lebih panjang 2,5 cm dari F4), sehingga jika memilih format Legal pada kertas F4, bagian bawah dokumen akan terpotong saat dicetak.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Pengaturan Kertas Dokumen)"}, {"id": 555, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Perangkat keras penyimpanan data generasi baru yang menggunakan chip memori flash tanpa komponen mekanis berputar, menghasilkan kecepatan baca-tulis jauh lebih tinggi dan tahan guncangan dibandingkan harddisk konvensional (HDD) adalah...", "options": ["Floppy Disk", "SSD (Solid State Drive)", "CD-ROM", "Pita Kaset Magnetik"], "answer": 1, "explanation": "SSD (Solid State Drive) adalah media penyimpanan sekunder berbasis chip semikonduktor flash yang bekerja secara elektrik tanpa piringan mekanis berputar seperti HDD konvensional, memberikan kecepatan booting sistem dan akses file kantor desa yang jauh lebih cepat serta tahan benturan.", "source": "Standar Kompetensi Komputer Perangkat Desa (Perangkat Keras Penyimpanan)"}, {"id": 556, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Kaidah tata naskah dinas pemerintah mengharuskan badan paragraf surat atau peraturan desa memiliki perataan teks yang rapi di sisi kiri dan sisi kanan. Perataan teks ini disebut...", "options": ["Align Left (Rata Kiri)", "Center (Rata Tengah)", "Align Right (Rata Kanan)", "Justify (Rata Kanan-Kiri)"], "answer": 3, "explanation": "Perataan teks Justify (Ctrl + J) menghasilkan naskah yang rata pada batas margin kiri dan margin kanan secara simetris, sehingga dokumen dinas terlihat formal, tertib, dan profesional sesuai Peraturan Menteri Dalam Negeri tentang Tata Naskah Dinas.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Format Tata Naskah)"}, {"id": 557, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sulit", "question": "Dalam proses pembahasan bersama draf rancangan Peraturan Desa antara Kepala Desa dan BPD, fitur aplikasi pengolah kata yang berfungsi merekam setiap perubahan kalimat, pencoretan, atau usulan penambahan teks oleh para pihak disebut...", "options": ["Word Count", "Track Changes (Review)", "Macro Recorder", "Hyphenation"], "answer": 1, "explanation": "Fitur Track Changes (di bawah tab Review) memungkinkan seluruh suntingan, penambahan kata, penghapusan klausa, dan komentar terekam dengan penanda warna berbeda, memudahkan tim legal atau pimpinan desa meninjau usulan perubahan sebelum draf disahkan menjadi Perdes final.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Review Regulasi Desa)"}, {"id": 558, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Saat membuat tabel Register Penduduk Desa yang memanjang hingga 5 halaman, staf desa ingin agar judul kolom (No, NIK, Nama, Alamat) otomatis muncul di baris paling atas pada setiap halaman berikutnya. Fitur yang harus diaktifkan adalah...", "options": ["Ketik ulang judul tabel secara manual di awal setiap halaman", "Split Cells pada menu layout tabel", "Repeat Header Rows pada tab Table Tools > Layout", "Merge and Center baris pertama"], "answer": 2, "explanation": "Fitur 'Repeat Header Rows' memastikan baris kepala tabel (header) otomatis diulang di bagian atas setiap halaman berikutnya saat tabel memotong batas halaman (page break). Ini mencegah kesalahan pembacaan kolom data penduduk tanpa perlu mengetik manual.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Pengelolaan Tabel)"}, {"id": 559, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Fungsi matematika dasar pada lembar kerja Excel yang digunakan untuk menjumlahkan seluruh nilai realisasi belanja bidang pembangunan desa dari sel D5 sampai sel D25 adalah...", "options": ["=TOTAL(D5:D25)", "=SUM(D5:D25)", "=PLUS(D5:D25)", "=ADD(D5:D25)"], "answer": 1, "explanation": "Fungsi =SUM(number1, [number2], ...) adalah formula standar Excel untuk menjumlahkan sekumpulan angka dalam rentang sel (range) tertentu, dalam contoh ini =SUM(D5:D25).", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Formula Spreadsheet)"}, {"id": 560, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Untuk menghitung rata-rata pendapatan per kepala keluarga warga prasejahtera dari data sel E2 sampai E50, formula yang benar adalah...", "options": ["=MEAN(E2:E50)", "=AVERAGE(E2:E50)", "=RATARATA(E2:E50)", "=MEDIAN(E2:E50)"], "answer": 1, "explanation": "Fungsi =AVERAGE(range) digunakan untuk menghitung nilai rata-rata hitung (arithmetic mean) dari sekumpulan nilai dalam sel numerik.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Formula Spreadsheet)"}, {"id": 561, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Kaur Perencanaan ingin membuat status otomatis penerima bantuan: jika penghasilan di sel C2 kurang dari atau sama dengan 1.500.000 maka berstatus 'Penerima BLT', jika lebih besar berstatus 'Bukan Penerima'. Penulisan rumus IF yang tepat adalah...", "options": ["=IF(C2 <= 1500000; 'Penerima BLT'; 'Bukan Penerima')", "=IF(C2 <= 1500000, \"Penerima BLT\", \"Bukan Penerima\")", "=CHECK(C2 <= 1500000; Penerima BLT; Bukan Penerima)", "=CONDITION(C2; 1500000; \"Penerima BLT\"; \"Bukan\")"], "answer": 1, "explanation": "Struktur baku fungsi IF adalah =IF(logical_test, [value_if_true], [value_if_false]). Teks keterangan wajib diapit tanda petik dua ganda (\"), dan pemisah argumen menggunakan koma atau titik koma sesuai konfigurasi regional sistem.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Formula Logika Excel)"}, {"id": 562, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Fungsi spreadsheet yang digunakan untuk menghitung banyaknya warga yang berstatus pekerjaan 'Petani' dari kolom pekerjaan (C2:C100) adalah...", "options": ["=COUNT(C2:C100)", "=COUNTIF(C2:C100, \"Petani\")", "=SUMIF(C2:C100, \"Petani\")", "=COUNTA(C2:C100, \"Petani\")"], "answer": 1, "explanation": "=COUNTIF(range, criteria) menghitung jumlah sel yang memenuhi kriteria tertentu (dalam hal ini sel yang bernilai teks \"Petani\"). Fungsi COUNT hanya menghitung angka, sedangkan SUMIF menjumlahkan nilai angka bersyarat.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Formula Statistik Excel)"}, {"id": 563, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sulit", "question": "Kasi Pemerintahan ingin mencari nama warga secara otomatis pada tabel master kependudukan berdasarkan input NIK. Jika NIK dicari pada kolom pertama tabel referensi A2:D500 dan Nama Warga berada di kolom ke-2, rumus pencarian vertikal yang tepat adalah...", "options": ["=HLOOKUP(F2, A2:D500, 2, FALSE)", "=VLOOKUP(F2, A2:D500, 2, FALSE)", "=SEARCH(F2, A2:D500, 2)", "=FIND(F2, A2:D500, Nama)"], "answer": 1, "explanation": "Fungsi =VLOOKUP(lookup_value, table_array, col_index_num, [range_lookup]) mencari nilai kunci (NIK di F2) pada kolom paling kiri tabel (A2:D500), lalu mengembalikan nilai pada kolom indeks ke-2 (Nama Warga). Parameter FALSE digunakan untuk pencarian nilai persis (exact match).", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Formula VLOOKUP)"}, {"id": 564, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Simbol yang digunakan dalam formula Excel untuk mengunci alamat sel agar baris dan kolomnya tidak berubah saat formula disalin (di-copy) ke sel lain (referensi absolut) adalah...", "options": ["Tanda Persen (%)", "Tanda Dolar ($)", "Tanda Bintang (*)", "Tanda Pagar (#)"], "answer": 1, "explanation": "Tanda dolar ($), misalnya $A$1, mengunci sel secara absolut baik baris maupun kolomnya sehingga nilainya tetap merujuk pada sel tersebut saat ditarik/disalin ke sel lain. Menekan tombol F4 pada keyboard dapat menambahkan tanda dolar secara otomatis.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Referensi Absolut)"}, {"id": 565, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Saat hendak memaparkan materi Musrenbangdes di balai desa menggunakan proyektor LCD dari laptop, jenis kabel dan port antarmuka standar modern yang dapat mentransmisikan sinyal video definisi tinggi (HD) sekaligus audio suara secara bersamaan melalui satu kabel adalah...", "options": ["VGA (Video Graphics Array)", "HDMI (High-Definition Multimedia Interface)", "Kabel RCA Kuning", "Port Serial COM1"], "answer": 1, "explanation": "HDMI (High-Definition Multimedia Interface) adalah antarmuka digital standar modern yang mengirimkan sinyal video resolusi tinggi beserta sinyal audio digital secara simultan dalam satu kabel, menggantikan kabel analog VGA yang hanya membawa sinyal gambar tanpa suara.", "source": "Standar Perangkat Komputer dan Audio Visual Modern"}, {"id": 566, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Untuk membatasi agar staf pendaftaran hanya dapat menginput pilihan nama dusun yang sah (misalnya: Dusun Krajan, Dusun Mulyo, Dusun Rejo) melalui menu pilihan tarik-turun (dropdown), fitur Excel yang digunakan adalah...", "options": ["Conditional Formatting", "Data Validation dengan kriteria 'List'", "AutoFilter", "Text to Columns"], "answer": 1, "explanation": "Data Validation (menu Data > Data Validation) dengan kriteria 'List' memungkinkan pembuat formulir membatasi isian sel hanya pada daftar pilihan yang ditentukan dalam bentuk dropdown list, mencegah salah ketik nama wilayah administratif.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Validasi Data)"}, {"id": 567, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Untuk menyaring daftar pemilih pilkades agar hanya menampilkan warga yang bertempat tinggal di RT 02 RW 01, tombol perintah pada tab Data yang harus diaktifkan adalah...", "options": ["Filter (berlogo corong penyaring)", "Sort A to Z", "Consolidate", "Remove Duplicates"], "answer": 0, "explanation": "Perintah Filter (ikon corong pada tab Data atau Ctrl+Shift+L) memunculkan tombol panah pada kepala kolom untuk menyaring data berdasarkan kriteria tertentu (misal hanya mencentang RT 02 RW 01).", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Filter Data)"}, {"id": 568, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Ketika staf desa membuka beberapa program sekaligus (seperti Siskeudes, Word, Excel, dan Browser) di komputer, tombol pintasan (keyboard shortcut) yang paling cepat dan praktis untuk berpindah-pindah antarjendela aplikasi yang sedang aktif adalah...", "options": ["Ctrl + Alt + Del", "Alt + Tab", "Ctrl + Shift + Esc", "Windows + E"], "answer": 1, "explanation": "Menekan kombinasi Alt + Tab pada keyboard menampilkan jendela peralihan cepat (Task Switcher) untuk beralih secara langsung dari satu aplikasi aktif ke aplikasi lainnya tanpa perlu mengklik ikon aplikasi di taskbar dengan mouse.", "source": "Navigasi Cepat Sistem Operasi Windows"}, {"id": 569, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Berdasarkan Peraturan Menteri Komunikasi dan Informatika RI, nama domain internet tingkat kedua resmi yang khusus dialokasikan dan digunakan untuk situs web resmi instansi pemerintahan desa di Indonesia adalah...", "options": [".com", ".desa.go.id atau .desa.id", ".org", ".co.id"], "answer": 1, "explanation": "Sesuai regulasi domain instansi pemerintah Republik Indonesia (Permenkominfo), domain resmi bagi entitas pemerintahan desa adalah .desa.go.id (dan pengelolaan domain desa .desa.id), guna memastikan keabsahan dan kredibilitas informasi resmi desa bagi publik.", "source": "Permenkominfo tentang Tata Kelola Nama Domain Instansi Pemerintah"}, {"id": 570, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Dalam penggunaan komputer sehari-hari, perbedaan mendasar antara Peramban Web (Web Browser) seperti Google Chrome atau Microsoft Edge dengan Mesin Pencari (Search Engine) seperti Google Search atau Bing adalah...", "options": ["Web browser adalah perangkat keras sedangkan mesin pencari adalah monitor layar", "Web browser adalah aplikasi perangkat lunak untuk membuka dan menjelajah situs web di internet, sedangkan mesin pencari adalah layanan berbasis web untuk mencari informasi atau tautan situs", "Mesin pencari adalah jenis kabel jaringan sedangkan web browser adalah printer", "Tidak ada perbedaan, keduanya adalah sistem operasi komputer"], "answer": 1, "explanation": "Web Browser (Chrome, Firefox, Edge) adalah aplikasi/program yang diinstal di komputer pengguna untuk mengakses dan merender kode halaman web, sedangkan Search Engine (Google, Bing) adalah program/layanan web yang mengindeks dan mencari informasi di seluruh penjuru internet berdasarkan kata kunci tertentu.", "source": "Konsep Dasar Teknologi Informasi & Internet"}, {"id": 571, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Untuk mewujudkan tata kelola kearsipan digital desa yang tertib dan mudah dicari kembali, pola penamaan berkas dokumen SK Kepala Desa yang paling tepat dan baku adalah...", "options": ["sk baru fix banget.docx", "dokumen1_final(2).pdf", "2026_SK-Kades_No-05_Pengangkatan-Kaur-Keuangan.pdf", "SK KADES TERBARU REVISI OK.doc"], "answer": 2, "explanation": "Standar penamaan file digital arsip kedinasan harus memuat unsur: Tahun, Jenis Dokumen/Instansi, Nomor Surat, dan Ringkasan Isi Dokumen tanpa spasi berantakan, serta disimpan dalam format PDF non-editable. Contoh: 2026_SK-Kades_No-05_Pengangkatan-Kaur-Keuangan.pdf.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Manajemen Kearsipan Digital)"}, {"id": 572, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Alasan utama mengapa dokumen resmi Pemerintah Desa (seperti Perdes, Peraturan Bersama Kades, dan Surat Edaran) harus dikonversi ke format PDF sebelum didistribusikan kepada publik atau via WhatsApp adalah...", "options": ["Format PDF hanya bisa dibuka di komputer server kecamatan", "Format PDF mempertahankan tata letak (layout), font, tanda tangan, dan tidak mudah diedit sembarangan di berbagai perangkat", "Format PDF otomatis menghapus cap stempel desa sehingga aman", "Format PDF membuat ukuran file menjadi lebih besar 100 kali lipat"], "answer": 1, "explanation": "Format PDF (Portable Document Format) dirancang agar tampilan dokumen (tata letak, jenis font, garis, tabel, dan tanda tangan) tampil konsisten di semua jenis komputer dan ponsel cerdas serta tidak mudah diubah-ubah secara tidak sah.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Format Dokumen Standar)"}, {"id": 573, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Saat akan mengirimkan 15 berkas lampiran persyaratan verifikasi calon perangkat desa melalui pos elektronik (email), tindakan teknis terbaik agar berkas tidak tercecer dan hemat ukuran transmisi adalah...", "options": ["Mengirim 15 email terpisah masing-masing satu lampiran", "Memasukkan seluruh berkas ke dalam satu folder lalu mengompresinya menjadi berkas arsip (.ZIP atau .RAR)", "Memfoto layar komputer menggunakan kamera ponsel lalu mengirim gambarnya", "Menghapus lampiran-lampiran yang dirasa kurang penting"], "answer": 1, "explanation": "Mengompresi berkas ke dalam format ZIP/RAR menggabungkan banyak file menjadi satu paket utuh serta memperkecil ukuran data transmisi (kompresi lossless), sehingga pengiriman melalui email dinas menjadi praktis dan rapi.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Pengelolaan Berkas Digital)"}, {"id": 574, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Di kantor desa yang memiliki beberapa komputer staf dan printer bersama, sistem jaringan komputer lokal yang menghubungkan perangkat-perangkat tersebut dalam satu ruangan kantor dinamakan...", "options": ["LAN (Local Area Network)", "WAN (Wide Area Network)", "MAN (Metropolitan Area Network)", "VPN (Virtual Private Network)"], "answer": 0, "explanation": "LAN (Local Area Network) adalah jaringan komputer yang mencakup wilayah geografis terbatas seperti ruangan kantor, balai desa, atau satu gedung perkantoran, memungkinkan berbagi file data dan perangkat printer bersama.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Jaringan Komputer Dasar)"}, {"id": 575, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Demi keamanan sistem administrasi dan server desa, kebijakan pengaturan jaringan nirkabel (Wi-Fi) di Balai Desa yang paling tepat adalah...", "options": ["Membuat satu jaringan Wi-Fi tanpa password agar semua warga bebas memakainya", "Memisahkan jaringan Wi-Fi untuk Pelayanan Administrasi Desa dengan Wi-Fi Publik/Tamu (Guest Network)", "Mematikan Wi-Fi selamanya dan hanya memakai disket untuk bertukar data", "Menyamakan password router Wi-Fi dengan tanggal lahir Kepala Desa"], "answer": 1, "explanation": "Memisahkan jaringan (segregasi jaringan) antara Wi-Fi internal staf pelayanan dengan Wi-Fi publik warga/tamu (Guest Network) mencegah pihak luar mengakses komputer administrasi, printer dinas, data kependudukan, atau menyebarkan malware.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Keamanan Jaringan Kantor)"}, {"id": 576, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Saat mengirim surat elektronik (email) dinas kepada Camat mengenai laporan realisasi bansos, bagian 'Subject' pada formulir email wajib diisi dengan...", "options": ["Dikosongkan saja agar terlihat misterius", "Kata 'HALO' atau 'TOLONG DIBACA'", "Judul yang ringkas, jelas, dan memuat perihal surat (misal: 'Laporan Realisasi Penyaluran BLT-DD Tahap I Desa Sukamaju')", "Menyalin seluruh isi badan surat ke kolom subject"], "answer": 2, "explanation": "Kolom Subject adalah judul atau perihal surat elektronik. Pengisian subject yang jelas, informatif, dan formal memudahkan penerima mengenali isi pesan dinas dan mengarsipkannya dengan tepat.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Etika Komunikasi Digital)"}, {"id": 577, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Pada formulir pengiriman email kedinasan, fungsi kolom BCC (Blind Carbon Copy) adalah...", "options": ["Mengirim email utama kepada penerima surat", "Mengirim tembusan surat di mana alamat penerima tembusan tersebut tidak terlihat oleh penerima lainnya", "Menghapus email secara otomatis setelah 24 jam", "Mengubah format teks email menjadi sandi rahasia"], "answer": 1, "explanation": "BCC (Blind Carbon Copy) digunakan untuk mengirim tembusan tanpa memperlihatkan alamat email penerima BCC tersebut kepada penerima lain (baik To maupun CC). Ini penting saat mengirim pemberitahuan massal untuk melindungi privasi alamat email warga.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Komunikasi Email Kedinasan)"}, {"id": 578, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Seorang staf desa menerima pesan WhatsApp atau email yang mengatasnamakan Bank Jatim atau Kementerian Desa dengan tautan (link) untuk 'Verifikasi Akun Siskeudes'. Setelah diklik, muncul halaman login palsu yang meminta kata sandi. Modus kejahatan siber ini disebut...", "options": ["Phishing", "Defragmentasi", "Overclocking", "Troubleshooting"], "answer": 0, "explanation": "Phishing adalah bentuk penipuan rekayasa sosial (social engineering) di mana pelaku menyamar sebagai entitas terpercaya untuk mencuri informasi sensitif seperti username, kata sandi, kode OTP, atau informasi rekening perbankan melalui situs atau tautan palsu.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Kesadaran Keamanan Siber)"}, {"id": 579, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Standar pembuatan kata sandi (password) yang kuat dan aman untuk akun Sistem Keuangan Desa (Siskeudes) atau email kedinasan desa adalah...", "options": ["Menggunakan angka berurutan seperti '12345678'", "Menggunakan nama desa diikuti angka 'desaku2026'", "Kombinasi minimal 8-12 karakter yang memuat huruf besar, huruf kecil, angka, dan simbol khusus unik", "Menggunakan tanggal lahir anak kepala desa"], "answer": 2, "explanation": "Password kuat harus memadukan huruf kapital, huruf kecil, angka, dan karakter khusus/simbol (misal: !@#$%), memiliki panjang minimal 8-12 karakter, serta tidak menggunakan data pribadi yang mudah ditebak untuk mencegah serangan brute force.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Manajemen Kredensial)"}, {"id": 580, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Untuk melindungi database kependudukan dan keuangan desa dari ancaman virus Ransomware (pengunci data) atau kerusakan harddisk fisik, strategi pencadangan (backup) data terbaik adalah...", "options": ["Tidak perlu backup jika sudah memakai antivirus gratisan", "Menerapkan aturan backup 3-2-1: menyimpan minimal 3 salinan data, pada 2 media penyimpanan berbeda (harddisk internal & eksternal), dan 1 salinan disimpan di tempat terpisah/cloud", "Menyalin file ke folder yang sama di desktop komputer", "Mencetak seluruh isi database ke kertas setiap sore hari"], "answer": 1, "explanation": "Aturan backup 3-2-1 adalah standar industri manajemen kontinuitas data: 3 salinan data, 2 jenis media berbeda (misal: harddisk kantor dan harddisk eksternal offline), serta 1 salinan disimpan off-site (di luar lokasi/cloud tersandikan) guna mengantisipasi bencana fisik maupun ransomware.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Strategi Pencadangan Data)"}, {"id": 581, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Berdasarkan Undang-Undang Nomor 27 Tahun 2022 tentang Perlindungan Data Pribadi (UU PDP), tindakan perangkat desa mengunggah foto Kartu Keluarga dan KTP warga yang memuat NIK secara terbuka ke grup media sosial Facebook desa adalah...", "options": ["Tindakan terpuji demi transparansi total informasi desa", "Pelanggaran hukum terhadap pelindungan data pribadi spesifik/spesifik warga yang dapat dikenai sanksi pidana dan administratif", "Boleh dilakukan asalkan disukai oleh kepala dusun", "Kewajiban rutin bulanan yang diatur dalam Permendagri"], "answer": 1, "explanation": "Pasal dalam UU No. 27 Tahun 2022 (UU PDP) menegaskan bahwa NIK dan data kependudukan adalah data pribadi yang wajib dilindungi kerahasiaannya. Mengunggah data kependudukan tanpa izin pemilik dan tanpa hak ke ruang publik melanggar hukum dan membahayakan warga dari kejahatan pinjaman online ilegal atau pencurian identitas.", "source": "Latihan Buatan — UU No. 27 Tahun 2022 tentang Pelindungan Data Pribadi & Etika Layanan"}, {"id": 582, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Ketika printer kantor desa mengalami 'Paper Jam' (kertas tersangkut di dalam roller printer), tindakan pertama yang benar untuk mengatasinya adalah...", "options": ["Menarik paksa kertas ke arah berlawanan sekuat tenaga menggunakan obeng", "Mematikan printer terlebih dahulu, membuka penutup roller, lalu menarik kertas tersangkut secara perlahan searah jalur keluar kertas", "Menyiram roller printer dengan air hangat", "Menekan tombol cetak 20 kali berturut-turut"], "answer": 1, "explanation": "Penanganan paper jam harus diawali dengan mematikan daya printer, membuka penutup akses roller, lalu menarik kertas perlahan searah alur jalannya kertas agar gir atau sensor penarik kertas tidak patah atau rusak.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Pemeliharaan Perangkat Keras)"}, {"id": 583, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Perangkat keras tambahan yang berfungsi sebagai penyimpan daya cadangan sementara agar komputer server/kerja desa tidak langsung mati saat listrik PLN padam mendadak disebut...", "options": ["Modem", "UPS (Uninterruptible Power Supply)", "Scanner", "Motherboard"], "answer": 1, "explanation": "UPS (Uninterruptible Power Supply) menyediakan cadangan daya baterai sementara ketika arus listrik utama terputus, memberikan waktu bagi operator desa untuk menyimpan dokumen dan mematikan (shut down) komputer secara aman.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Perangkat Keras Komputer)"}, {"id": 584, "category": "Komputer dasar dan pelayanan publik", "difficulty": "sedang", "question": "Aplikasi resmi berbasis komputer yang dikembangkan bersama oleh Kemendagri dan BPKP untuk membantu pemerintah desa dalam perencanaan, penganggaran, penatausahaan, dan pelaporan keuangan desa secara akuntabel dinamakan...", "options": ["SISKEUDES (Sistem Keuangan Desa)", "DAPODIK (Data Pokok Pendidikan)", "SIMDA Barang Milik Daerah", "E-KTP Mobile Client"], "answer": 0, "explanation": "SISKEUDES (Sistem Keuangan Desa) adalah aplikasi resmi yang dikembangkan oleh BPKP bersama Kemendagri guna memfasilitasi tata kelola keuangan desa sesuai ketentuan Permendagri No. 20 Tahun 2018.", "source": "Latihan Buatan — Petunjuk Teknis SISKEUDES Kemendagri & BPKP RI"}, {"id": 585, "category": "Komputer dasar dan pelayanan publik", "difficulty": "mudah", "question": "Dalam etika berkomunikasi digital (netiket) pelayanan desa, penggunaan HURUF KAPITAL SEMUA (ALL CAPS) dalam pesan obrolan atau surat elektronik sebaiknya dihindari karena...", "options": ["Membuat ukuran file email menjadi terlalu besar", "Dapat dipersepsikan oleh pembaca sebagai teriakan, kemarahan, atau nada bicara yang tidak sopan", "Dilarang oleh sistem operasi Windows", "Membuat tinta printer cepat habis saat dicetak"], "answer": 1, "explanation": "Dalam konvensi netiket digital, mengetik teks seluruhnya dengan huruf besar/kapital dianggap setara dengan berteriak atau bersikap agresif/marah, sehingga tidak pantas digunakan dalam komunikasi resmi pelayanan masyarakat.", "source": "Latihan Buatan — Standar Kompetensi Komputer Perangkat Desa (Etika Netiket Digital)"}];
window.MASTER_QUESTIONS = window.__MASTER_QUESTIONS__;
